  AvgCommunicate_100438_Content_13 = {Text = "!?"},
  AvgCommunicate_100438_Content_14 = {
    Text = "Boleh ya? Boleh ya?"
  },
  AvgCommunicate_100438_Content_15 = {
    Text = "Model gratis, membantumu mengejar seni yang paling sempurna! Di mana lagi kamu bisa menemukan model yang sekooperatif ini?"
  },
  AvgCommunicate_100438_Content_16 = {
    Text = "……Ada benarnya juga."
  },
  AvgCommunicate_100438_Content_17 = {
