  },
  AvgCommunicate_100438_Content_2 = {
    Text = "Kelas master melukis yang kuajar sendiri, semua peralatan lukis koleksiku bisa kamu gunakan sesukamu, tertarik tidak?"
  },
  AvgCommunicate_100438_Content_3 = {
    Text = "Ada hal sebaik ini?"
