  AvgCommunicate_100438_Content_4 = {
    Text = "Sangat tertarik!"
  },
  AvgCommunicate_100438_Content_5 = {
    Text = "Sebagai pelukis hebat dan pengajar berpengalaman, ketulusan selalu menjadi sifatku yang paling menonjol. Tapi tolong pahami, setiap penciptaan seni yang indah membutuhkan percikan inspirasi..."
  },
  AvgCommunicate_100438_Content_6 = {
    Text = "Sebagai imbalan atas pengajaran ini, maukah kamu menjadi model untuk lukisanku?"
  },
  AvgCommunicate_100438_Content_7 = {
    Text = "Sudah kuduga..."
  },
  AvgCommunicate_100438_Content_8 = {
    Text = "Boleh ya? Boleh ya?"
  },
  AvgCommunicate_100438_Content_9 = {
    Text = "Kelas master gratis, ruang studio gratis, peralatan lukis gratis, semuanya gratis!"
  },
  AvgCommunicate_100438_Option_3 = {
    Text = "Ada hal sebaik ini?"
  },
  AvgCommunicate_100438_Option_4 = {
