  },
  AvgCommunicate_100439_Content_1 = {
    Text = "Aku nyatakan bahwa stiker ekspresi adalah seni terhebat di era baru!"
  },
  AvgCommunicate_100439_Content_10 = {
    Text = "Kalau begitu, bisakah kamu memperkenalkan aku kepada seniman yang membuat stiker ekspresi ini?"
  },
  AvgCommunicate_100439_Content_11 = {
    Text = "Tentu saja bisa."
  },
  AvgCommunicate_100439_Content_2 = {
    Text = "Kamu serius?"
  },
  AvgCommunicate_100439_Content_3 = {
    Text = "Tentu saja! Aku selalu serius dalam menghadapi seni."
  },
  AvgCommunicate_100439_Content_8 = {
    Text = "Jangan spam lagi. Aku setuju dengan pendapatmu."
  },
  AvgCommunicate_100439_Content_9 = {
    Text = "Bagus sekali! Aku tahu kamu pasti bisa memahami seni di mataku, memang pantas disebut Penjaga Rahasia."
  },
  AvgCommunicate_100440_Content_1 = {
    Text = "Malam ini suasananya pas, saatnya menjalankan misi rahasia kita!"
  },
  AvgCommunicate_100440_Content_10 = {
    Text = "Jelaskan dengan jelas, apa rencanamu? Hati-hati aku adukan ke Dulesain."
  },
  AvgCommunicate_100440_Content_11 = {
    Text = "Aku cuma ingin menyelinap ke dapur untuk mengambil beberapa bahan makanan, dan soal rekan seni... aku tidak akan mengkhianati Shan."
  },
  AvgCommunicate_100440_Content_12 = {Text = "Gawat."},
  AvgCommunicate_100440_Content_13 = {
    Text = "...Semudah itu sudah membongkar semuanya."
  },
  AvgCommunicate_100440_Content_14 = {
    Text = "Kamu sudah lupa akibat terakhir kali mencuri bahan makanan dari dapur untuk dijadikan model?"
  },
  AvgCommunicate_100440_Content_15 = {
    Text = "Terakhir kali ya terakhir kali... Kali ini aku sengaja memilih hari Festival Roh, dan ada Shan yang membantuku, pasti tidak masalah."
  },
  AvgCommunicate_100440_Content_16 = {
    Text = "Jangan beritahu Dulceigne, boleh?"
  },
  AvgCommunicate_100440_Content_17 = {
    Text = "Ini adalah kolaborasi yang sudah lama kunantikan, aku ingin Shan mengapresiasi seniku..."
  },
  AvgCommunicate_100440_Content_18 = {
    Text = "...Baiklah. Ingat tunjukkan hasil jadinya padaku."
  },
  AvgCommunicate_100440_Content_2 = {
    Text = "Apa yang kamu bicarakan?"
  },
  AvgCommunicate_100440_Content_3 = {
    Text = "Apa yang kamu bicarakan?"
  },
  AvgCommunicate_100440_Content_4 = {
    Text = "Bukankah kita sudah janjian? Di hari Festival Roh, Dulesain pasti akan pergi ke pesta dansa dulu, ini kesempatan kita!"
  },
  AvgCommunicate_100440_Content_5 = {
    Text = "??? Kamu salah kirim pesan ya?"
