  AvgCommunicate_100440_Content_6 = {
    Text = "Eh... tunggu..."
  },
  AvgCommunicate_100440_Content_7 = {
    Text = "Maaf, seharusnya pesan ini dikirim ke rekan seniku, anggap saja kamu tidak pernah menerimanya."
  },
  AvgCommunicate_100440_Content_8 = {
    Text = "Rekan seni... jangan-jangan..."
  },
  AvgCommunicate_100440_Content_9 = {
    Text = "Rekan seni... jangan-jangan..."
  },
  AvgCommunicate_100440_Option_2 = {
    Text = "Misi rahasia?"
  },
  AvgCommunicate_100440_Option_3 = {
    Text = "Ini seni baru apalagi?"
  },
  AvgCommunicate_100440_Option_8 = {
    Text = "Siapa rekan senimu?"
  },
  AvgCommunicate_121371_Content_1 = {
    Text = "Aku melihatnya, tanpa beban, sungguh sulit dipahami."
  },
  AvgCommunicate_121371_Content_2 = {
    Text = "Kesukaannya terhadap benda-benda juga polos sampai terasa absurd."
  },
  AvgCommunicate_121371_Content_3 = {
    Text = "...Murphy memberitahuku, boneka baru dan gaun yang ingin dia ikuti undiannya musim ini, satu pun tidak berhasil didapatkan."
  },
  AvgCommunicate_121371_Content_4 = {
    Text = "Semua nomor undian sudah dibeli orang lebih dulu, siapa ya, sungguh sulit ditebak."
  },
  AvgCommunicate_121371_Content_5 = {
    Text = "Sebagai orang yang telah menanggung lebih lama, mendapatkan sedikit kompensasi adalah hal yang wajar."
  },
  AvgCommunicate_121371_Content_6 = {
    Text = "...Misalnya mendapatkan cukup banyak warisan Keturunan Laut, sehingga kamu bisa berbuat sesukamu dengan uang?"
  },
  AvgCommunicate_121371_Content_7 = {Text = "Heh."},
  AvgCommunicate_121371_Content_8 = {
    Text = "Meskipun aku harus mengakui, pilihan dan keberuntungannya sebelumnya, mungkin sedikit lebih baik dariku."
  },
  AvgCommunicate_121371_Content_9 = {
    Text = "Tapi dia harus paham, perlawanan terhadap takdir tidak selalu bisa berhasil setiap kali."
  },
  AvgCommunicate_121372_Content_1 = {
    Text = "Lancang! Tidak sopan! Tidak bisa dimaafkan!"
  },
  AvgCommunicate_121372_Content_10 = {
    Text = "Aku akan..."
  },
  AvgCommunicate_121372_Content_11 = {
    Text = "Kamu akan..."
  },
  AvgCommunicate_121372_Content_12 = {
    Text = "Para siswa yang lewat dan berhenti untuk mengelus kucing hampir menyebabkan kemacetan fenomenal di gedung sekolah bersama kucing-kucing itu. Sungguh bakat yang mengagumkan."
  },
  AvgCommunicate_121372_Content_13 = {
    Text = "Aku akan segera menyelamatkanmu."
  },
  AvgCommunicate_121372_Content_2 = {Text = "Ada apa?"},
  AvgCommunicate_121372_Content_3 = {
    Text = "Sungguh tidak masuk akal! Kenapa Misage membiarkan makhluk seperti ini masuk ke asrama!"
  },
  AvgCommunicate_121372_Content_4 = {
    Text = "Tunggu, aku mendengar seseorang menjerit di gedung asrama, apakah itu kamu?"
  },
  AvgCommunicate_121372_Content_5 = {
    Text = "Kenapa ada begitu banyak kucing berkumpul di depan pintu!?"
  },
  AvgCommunicate_121372_Content_6 = {
    Text = "Makhluk-makhluk kecil jahat dan licik ini mengikutiku sejak aku muncul, pasti ada konspirasi, mereka mau mencelakai sang Putri!"
  },
  AvgCommunicate_121372_Content_7 = {
    Text = "...Menurutku makhluk jahat yang ingin mencelakai seseorang seharusnya, tidak akan berbaring di lantai sambil memperlihatkan perutnya."
  },
  AvgCommunicate_121372_Content_8 = {
    Text = "Kucing-kucing itu tampaknya menyukaimu dengan cara yang luar biasa tidak biasa."
  },
  AvgCommunicate_121372_Content_9 = {
    Text = "Omong kosong! Atas nama kedudukanku sebagai Putri, aku memerintahkanmu untuk segera mengusir mereka, kalau tidak, aku akan, aku akan..."
  },
  AvgCommunicate_121372_Option_10 = {Text = "Aku akan"},
  AvgCommunicate_121372_Option_11 = {Text = "Kamu akan"},
  AvgCommunicate_121375_Content_1 = {
    Text = "Aku tahu apa yang ingin kamu katakan. Mereka melakukannya secara sukarela."
  },
  AvgCommunicate_121375_Content_10 = {
    Text = "Mengingat ketulusanmu... Putri ini bisa memberimu kehormatan itu."
  },
  AvgCommunicate_121375_Content_11 = {
    Text = "Kalau begitu, aku ingin melihat sekotak tart raspberry mentega segar."
  },
  AvgCommunicate_121375_Content_12 = {
    Text = "Kau punya waktu seperempat jam."
  },
  AvgCommunicate_121375_Content_13 = {
    Text = "Ini bukan termasuk \"benar-benar diperlukan\", kan?!"
  },
  AvgCommunicate_121375_Content_14 = {Text = "Hm?"},
  AvgCommunicate_121375_Content_15 = {
    Text = "……Baiklah, aku mengerti. Kalau aku tidak mau, banyak ikan lain yang mau."
  },
  AvgCommunicate_121375_Content_16 = {
    Text = "Aku pergi sekarang, jangan sampai ada lebih banyak kepala ikan muncul di Missage."
  },
  AvgCommunicate_121375_Content_2 = {
    Text = "Meskipun aku tidak tahu bagaimana kamu menghubungi Mereka, tapi kamu tidak bisa terus membiarkan Keturunan Laut muncul di Misager untuk menjalankan tugas, mengantre, bahkan mengerjakan PR untukmu."
  },
  AvgCommunicate_121375_Content_3 = {
    Text = "Kamu tahu berapa banyak guru dan siswa yang mengeluh buku PR mereka jadi lengket-lengket?"
  },
  AvgCommunicate_121375_Content_4 = {
    Text = "Mereka hanyalah semut-semut yang mengejar dan memaksa untuk mengabdi padaku."
  },
  AvgCommunicate_121375_Content_5 = {
    Text = "Aku benci Mereka merampas kebebasanku, tapi soal menikmati layanan — aku tidak pernah keberatan."
  },
  AvgCommunicate_121375_Content_6 = {
    Text = "Jadi, kenapa tidak memanfaatkan yang tidak berguna?"
