  AvgCommunicate_123720_Content_14 = {
    Text = "@2<AvgCommunicateConfuseColor.Light> ……kamu sekar@1<AvgCommunicateConfuseColor.Light> bisa ke sini tidak@2<AvgCommunicateConfuseColor.Light> ?"
  },
  AvgCommunicate_123720_Content_15 = {
    Text = "Komunikatornya sepert@1<AvgCommunicateConfuseColor.Light> rusak karena kupukul……"
  },
  AvgCommunicate_123720_Content_16 = {
