  },
  AvgCommunicate_123720_Content_17 = {
    Text = "Tunggu, jangan bilang kamu benar-benar \"berkelahi\" dengan komunikatornya?!"
  },
  AvgCommunicate_123720_Content_18 = {
    Text = "Kamu tahu@2<AvgCommunicateConfuseColor.Light> , perangkat elektronik yang rusak cukup dipukul@1<AvgCommunicateConfuseColor.Light> -pukul saja bisa diperbaiki@1<AvgCommunicateConfuseColor.Light> ."
  },
  AvgCommunicate_123720_Content_19 = {
    Text = "Pokoknya, kamu ke sini@2<AvgCommunicateConfuseColor.Light> dulu. Aku tidak mau menulis ulang@2<AvgCommunicateConfuseColor.Light> laporan, kata-kata membosankan itu cukup diucapkan@1<AvgCommunicateConfuseColor.Light> sekali saja@1<AvgCommunicateConfuseColor.Light> ."
  },
  AvgCommunicate_123720_Content_2 = {
    Text = "Mana laporannya? Aku tidak melihatnya……"
  },
  AvgCommunicate_123720_Content_3 = {
