  AvgCommunicate_123720_Content_5 = {
    Text = "Apakah laporan itu mencantumkan masalah penempatan lanjutan Perhimpunan Fajar Bintang?"
  },
  AvgCommunicate_123720_Content_6 = {
    Text = "Tentu saja. Tahta Suci Kehidupan mengambil alih pekerjaan penempatan selanjutnya, para \"yang tak berdosa\" akan ditampung oleh lembaga terkait dan perlahan diintegrasikan ke masyarakat."
  },
  AvgCommunicate_123720_Content_7 = {
    Text = "\"Yang berdosa\" akan ditempatkan di gereja untuk melakukan kerja sosial, berusaha berbuat baik untuk menebus dosa mereka."
  },
  AvgCommunicate_123720_Content_8 = {
    Text = "Aku cukup suka dengan akhir seperti ini. Bagaimanapun, mereka hanyalah orang-orang malang yang dibikin gila oleh dunia mengerikan ini."
  },
  AvgCommunicate_123720_Content_9 = {
