  AvgCommunicate_123720_Option_2 = {
    Text = "Mana laporannya?"
  },
  AvgCommunicate_123720_Option_5 = {
    Text = "Apakah laporan itu mencantumkan masalah penempatan lanjutan Perhimpunan Fajar Bintang?"
  },
  AvgCommunicate_123720_Option_9 = {
