    Text = "Segera balas begitu melihat pesan ini, kalau tidak aku akan memperlakukan orang itu sebagai individu mencurigakan."
  },
  AvgCommunicate_123721_Content_3 = {
    Text = "Jangan bertindak dulu! Itu memang dokter pemeriksaan kesehatan yang kucarikan untukmu!"
  },
  AvgCommunicate_123721_Content_4 = {
    Text = "Hah? Tubuhku sehat-sehat saja, tidak perlu ke dokter segala."
  },
  AvgCommunicate_123721_Content_5 = {
    Text = "Daripada buang waktu, lebih baik pergi ke jalanan untuk membersihkan beberapa Corroded lagi."
  },
  AvgCommunicate_123721_Content_6 = {
    Text = "…Aku hanya khawatir dengan kondisi tubuhmu, bagaimanapun situasimu sangat istimewa."
  },
  AvgCommunicate_123721_Content_7 = {
    Text = "Oh, aku mengerti, kamu takut aku mati."
  },
  AvgCommunicate_123721_Content_8 = {
    Text = "Jangan khawatir, sebelum mati aku pasti akan memberitahumu."
  },
  AvgCommunicate_123721_Content_9 = {
    Text = "…Aku tidak mau bahkan kematian pun terasa begitu sendirian."
  },
  AvgCommunicate_123721_Option_10 = {
    Text = "…Bukan itu intinya!"
  },
  AvgCommunicate_123721_Option_14 = {
    Text = "Tentu saja tidak, lakukan saja pemeriksaan kesehatanmu dengan tenang!"
  },
  AvgCommunicate_123721_Option_3 = {
    Text = "Jangan bertindak dulu!"
  },
  AvgCommunicate_123721_Option_6 = {
    Text = "Aku hanya khawatir dengan kondisi tubuhmu…"
  },
  AvgCommunicate_123722_Content_1 = {
    Text = "%player%, hasil pemeriksaan kesehatannya sudah keluar."
  },
  AvgCommunicate_123722_Content_10 = {
    Text = "Lagipula ini sangat menarik!"
  },
  AvgCommunicate_123722_Content_11 = {
    Text = "Kekuatanku meningkat, aku bisa berlari lebih cepat, melompat lebih jauh, dan mengalahkan Cronorosi dengan lebih gesit."
  },
  AvgCommunicate_123722_Content_12 = {
    Text = "Aku benar-benar untung besar, tahu! Kalau saja proses transformasinya tidak begitu menyakitkan, aku bahkan ingin mengalaminya sekali lagi!"
  },
  AvgCommunicate_123722_Content_14 = {
    Text = "Yang paling penting, dunia ini benar-benar sangat seru."
  },
  AvgCommunicate_123722_Content_15 = {
    Text = "Dunia ini penuh dengan kejutan dan perubahan, kau tidak pernah tahu bahaya apa yang akan kau hadapi di detik berikutnya."
  },
  AvgCommunicate_123722_Content_16 = {
    Text = "……………"
  },
  AvgCommunicate_123722_Content_17 = {
    Text = "Ah, aku sudah mulai menantikan misi investigasi berikutnya."
  },
  AvgCommunicate_123722_Content_18 = {
    Text = "Jadi %player%, kapan misi berikutnya?"
  },
  AvgCommunicate_123722_Content_19 = {Text = "%player%?"},
  AvgCommunicate_123722_Content_2 = {
    Text = "Terbukti, tubuhku sangat sehat, menghajar belasan bahkan dua puluh Blight pun bukan masalah!"
  },
  AvgCommunicate_123722_Content_20 = {Text = "%player%??"},
  AvgCommunicate_123722_Content_3 = {
    Text = "Kalau begitu aku lega."
  },
  AvgCommunicate_123722_Content_4 = {
    Text = "Lega? %player%, memangnya kamu mengkhawatirkan apa?"
  },
  AvgCommunicate_123722_Content_5 = {
    Text = "Khawatir aku tidak terbiasa dengan kehidupan di dunia lain?"
  },
  AvgCommunicate_123722_Content_6 = {
    Text = "Atau khawatir aku tidak terbiasa berubah dari seorang \"manusia\" menjadi \"Awakened\"?"
  },
  AvgCommunicate_123722_Content_7 = {
    Text = "Keduanya. Bagaimanapun juga, hal seperti ini... tidak mudah bagi siapa pun."
  },
  AvgCommunicate_123722_Content_8 = {
    Text = "...Aku memang tidak bisa memahami jalan pikiranmu."
  },
  AvgCommunicate_123722_Content_9 = {
    Text = "Aku tidak peduli soal itu, karena tidak peduli aku berubah jadi apa, Moxia tetaplah Moxia!"
  },
  AvgCommunicate_123722_Option_16 = {
    Text = "……………"
  },
  AvgCommunicate_123722_Option_3 = {
    Text = "Kalau begitu aku lega."
  },
  AvgCommunicate_123722_Option_7 = {Text = "Keduanya."},
  AvgCommunicate_126998_Content_1 = {
    Text = "Ramona, kamu... benar-benar tidak mau mempertimbangkannya lagi?"
  },
  AvgCommunicate_126998_Content_10 = {Text = "Ya, \"aku\"."},
  AvgCommunicate_126998_Content_11 = {
    Text = "……Perlu aku menghubungi Clementine?"
  },
  AvgCommunicate_126998_Content_12 = {
    Text = "Tidak, tidak perlu merepotkan psikolog itu."
  },
  AvgCommunicate_126998_Content_13 = {
    Text = "\"Aku\", atau lebih tepatnya \"kami\", semua \"Ramona\" di seluruh garis waktu."
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "Dengan bantuanmu, pada detik aku mencapai \"ujung\", aku berhasil menimpa diriku kembali ke \"titik asal\"."
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "Awalnya perkiraanku sama sepertimu, paradoks dan distorsi akan seketika menelan keberadaanku, lalu dengan terus-menerus melakukan regresi diri, kesadaran dan wujud fisik bisa dipertahankan dengan susah payah."
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "Setelah itu kau akan selamanya hidup dalam kelelahan, setiap saat harus tegang menjaga agar konsep dirimu tidak menghilang……"
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "Karena itulah aku menolak sembilan belas proposalmu sebelumnya."
  },
  AvgCommunicate_126998_Content_18 = {
    Text = "Bahkan kali ini pun, baru setelah kau mengatakan bisa melakukan \"regresi status\", aku……dengan berat hati menyetujui rencana ini."
  },
  AvgCommunicate_126998_Content_19 = {
    Text = "Ya, tapi baru setelah rencana berhasil aku menyadari, paradoks diri berasal dari konflik antara pikiran dan tubuh, dan bagi keberadaan yang telah melampaui sungai waktu……"
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "Tak perlu banyak bicara, Penjaga Rahasia."
  },
  AvgCommunicate_126998_Content_20 = {
    Text = "Aku telah menyelesaikan penyatuan di seluruh garis waktu."
  },
  AvgCommunicate_126998_Content_21 = {
    Text = "\"Kami\" akan menanggung dampak paradoks untukku, aku akan bertindak mewakili semua \"Ramona\", waktu yang tak terhitung telah terkonvergensi dalam diriku."
  },
  AvgCommunicate_126998_Content_22 = {
    Text = "Saat ini, aku adalah keajaiban di garis waktu—singularitas di mana ketakterhinggaan menjadi satu."
  },
  AvgCommunicate_126998_Content_23 = {
    Text = "Mulai sekarang, aku akan memberikanmu seluruh kekuatan dari individu bernama \"Ramona\"."
  },
  AvgCommunicate_126998_Content_24 = {
    Text = "Aku akan menunggu, panggilan dari waktu mana pun."
  },
  AvgCommunicate_126998_Content_3 = {
    Text = "Aku telah melintasi seluruh waktu, dan tidak menemukan jawaban lain."
  },
  AvgCommunicate_126998_Content_4 = {
    Text = "Berkat bantuanmu, aku akhirnya bisa melangkah ke langkah terakhir itu."
  },
  AvgCommunicate_126998_Content_5 = {
    Text = "Tapi ini terlalu berbahaya! Aku tidak mengerti, kenapa kamu... harus melakukannya sampai sejauh ini..."
  },
  AvgCommunicate_126998_Content_6 = {
    Text = "...Paradoks waktu seperti ini, bahkan kamu pun..."
  },
  AvgCommunicate_126998_Content_7 = {
    Text = "Tenang saja, Penjaga Rahasia."
  },
  AvgCommunicate_126998_Content_8 = {
    Text = "Sekarang perasaan \"aku\" luar biasa indah."
  },
  AvgCommunicate_126998_Content_9 = {Text = "\"Aku\"?"},
  AvgCommunicate_126998_Option_11 = {
    Text = "……Perlu aku menghubungi Clementine?"
  },
  AvgCommunicate_126998_Option_9 = {Text = "\"Aku\"?"},
  AvgCommunicate_126999_Content_1 = {
    Text = "Tuanku, ternyata memahami hukum akhir alam semesta rasanya seperti ini..."
  },
  AvgCommunicate_126999_Content_10 = {
    Text = "Tenanglah, Augier."
  },
  AvgCommunicate_126999_Content_11 = {
    Text = "Hal-hal itu tidak akan terjadi lagi. Kau sudah memiliki kekuatan yang cukup untuk melindungi semua yang ingin kau lindungi."
  },
  AvgCommunicate_126999_Content_12 = {
    Text = "Aku mengerti, Tuanku."
  },
  AvgCommunicate_126999_Content_13 = {
    Text = "Mohon Tuan juga lebih mengandalkan saya. Saya sudah menjadi jauh lebih kuat, dan mampu menerima misi yang lebih berbahaya."
  },
  AvgCommunicate_126999_Content_14 = {
    Text = "Kekuatan yang saya peroleh ini, semuanya akan saya persembahkan kepada Anda, menjadi tombak paling tajam di tangan Anda yang mampu menembus segalanya!"
  },
  AvgCommunicate_126999_Content_2 = {
    Text = "A-aku merasakan kekuatan luar biasa yang jauh melampaui sebelumnya... Aku merasa diriku dipenuhi kekuatan!"
  },
  AvgCommunicate_126999_Content_3 = {
    Text = "Selamat, Augier. Ini adalah hasil dari latihanmu yang tak pernah berhenti."
  },
  AvgCommunicate_126999_Content_4 = {
    Text = "Hasil? Aku melatih diriku bukan demi hasil apa pun."
  },
  AvgCommunicate_126999_Content_5 = {
    Text = "Kalau begitu, biar kuubah cara bicaraku."
  },
  AvgCommunicate_126999_Content_6 = {
    Text = "Ini adalah bukti dari latihanmu yang tak pernah berhenti, bukti bahwa kekuatanmu, Augier, telah mencapai puncaknya."
  },
  AvgCommunicate_126999_Content_7 = {Text = "Puncak?"},
  AvgCommunicate_126999_Content_8 = {
    Text = "I-ini berarti aku sudah memiliki kekuatan yang cukup untuk melindungi Tuanku dan Misagar!?"
  },
  AvgCommunicate_126999_Content_9 = {
    Text = "Aku... aku tidak perlu lagi... hanya bisa menyaksikan... dengan tak berdaya..."
  },
  AvgCommunicate_127000_Content_1 = {
    Text = "Terima kasih atas bantuanmu selama ini, rekan."
  },
  AvgCommunicate_127000_Content_10 = {
    Text = "Bukan ketidakberdayaan yang terbelenggu setelah mencapai batas bakat, melainkan kejernihan tertinggi yang dicapai setelah penempaan tanpa akhir."
  },
  AvgCommunicate_127000_Content_11 = {
    Text = "Saat ini, keahlianku sudah mendekati kesempurnaan."
  },
  AvgCommunicate_127000_Content_12 = {
    Text = "Hebat sekali! Memang pantas disebut Ramona!"
  },
  AvgCommunicate_127000_Content_13 = {
    Text = "Selanjutnya, sebagai asistenmu, aku akan selalu menemanimu hingga mencapai ujung jalan ini."
  },
  AvgCommunicate_127000_Content_2 = {
    Text = "Senang bisa membantumu."
  },
  AvgCommunicate_127000_Content_3 = {
    Text = "Bagaimana, apakah kau mendapatkan sesuatu?"
  },
  AvgCommunicate_127000_Content_4 = {
    Text = "Tentu saja, dengan mengobservasi individu-individu khusus seperti \"Keong Siklus Kembali\", \"Jiwa Hidup\", \"Kecerdasan Tak Dikenal\", dan lainnya, aku berhasil menyelesaikan deduksi yang lebih mendalam."
  },
  AvgCommunicate_127000_Content_5 = {
    Text = "Kemudian dengan mengandalkan \"Keindahan Buatan\", \"Pembunuh Logika\", \"Dunia dalam Botol\", aku berhasil melewati labirin pemikiran tanpa batas."
  },
  AvgCommunicate_127000_Content_6 = {
    Text = "Eh, aku agak tidak mengerti."
  },
  AvgCommunicate_127000_Content_7 = {
    Text = "Tapi singkatnya, kamu jadi lebih kuat kan, Ramona!"
  },
  AvgCommunicate_127000_Content_8 = {
    Text = "Ya, setelah peningkatan ini, kekuatan yang bisa kukerahkan jauh melampaui sebelumnya."
  },
  AvgCommunicate_127000_Content_9 = {
    Text = "Aku merasakan bahwa diriku telah mencapai titik akhir."
  },
  AvgCommunicate_127000_Option_12 = {
    Text = "Hebat sekali!"
  },
  AvgCommunicate_127001_Content_1 = {
    Text = "Pesan berikut dikirim secara terjadwal"
  },
  AvgCommunicate_127001_Content_10 = {
    Text = "Tunggu dulu!"
  },
  AvgCommunicate_127001_Content_11 = {
    Text = "Kenapa hari ini langsung?!"
  },
  AvgCommunicate_127001_Content_12 = {
    Text = "Ini terlalu berisiko, mungkin kita harus menunggu sampai akademi memberikan lebih banyak bantuan."
  },
  AvgCommunicate_127001_Content_13 = {
    Text = "Itu pukul 2 dini hari tadi, pesan terjadwal yang kuatur sebelum eksperimen dimulai."
  },
  AvgCommunicate_127001_Content_14 = {
    Text = "Kuharap kau tidak menunjukkan ekspresi bodoh yang memalukan di depan komunikator. Kalau iya, rapikan dirimu sebelum datang menemuiku di laboratorium."
  },
  AvgCommunicate_127001_Content_15 = {
    Text = "Aku? Ke laboratorium? Sekarang?"
  },
  AvgCommunicate_127001_Content_16 = {
    Text = "Benar, sampai batas tertentu, aku memang telah merasakan kebenaran dari hal yang selama ini kucari."
  },
  AvgCommunicate_127001_Content_17 = {
    Text = "Tunggu, jangan-jangan sama seperti \"Dor\" itu..."
  },
  AvgCommunicate_127001_Content_18 = {
    Text = "Tidak, ujung dari segalanya bukanlah \"kehancuran\" seperti yang dia pahami. Justru sebaliknya, itu adalah \"permulaan\"."
  },
  AvgCommunicate_127001_Content_19 = {
    Text = "\"Kebenaran\" bukanlah keberadaan statis yang tetap dan berwujud. Setelah melewati batas itu, akal dan intelek mampu membimbing manusia untuk menjangkarkannya, melangkah maju tanpa henti untuk selamanya."
  },
  AvgCommunicate_127001_Content_2 = {
    Text = "Penjaga Rahasia, meskipun tindakan saat ini mungkin didefinisikan sebagai \"berbahaya\" oleh pemahaman umum, saya percaya kau tidak cukup bodoh untuk mengira aku akan mengucapkan omong kosong sentimental dan pesan-pesan penuh nasihat."
  },
  AvgCommunicate_127001_Content_20 = {
    Text = "Karena itu, aku akan menyusun rencana pelatihan dan peningkatan yang lebih sempurna dan presisi, untuk memastikan kau semakin jauh dari jalan yang salah dan mampu mengejar proposisimu dengan lebih baik."
  },
  AvgCommunicate_127001_Content_21 = {
    Text = "Meskipun kedengarannya bagus, tapi kenapa punggungku penuh keringat dingin."
  },
  AvgCommunicate_127001_Content_22 = {
    Text = "Guru Dor, tenang sedikit!"
  },
  AvgCommunicate_127001_Content_3 = {
    Text = "Menurutku, bagi dirimu yang sekarang, kata-kata berlebihan seperti itu sudah tidak diperlukan lagi."
  },
  AvgCommunicate_127001_Content_4 = {
    Text = "Kau telah tumbuh menjadi individu yang cukup dewasa dan kuat dengan kecepatan yang jauh melampaui ekspektasiku, dan tentu kau juga memahami bahwa setiap orang memiliki sesuatu yang harus dikejar dalam hidupnya — sebuah persoalan yang tidak bisa dicampuri orang lain."
  },
  AvgCommunicate_127001_Content_5 = {
    Text = "Aku ingin mengetahui esensi dunia ini, mengetahui apakah cahaya rasionalitas masih bersinar dalam kegelapan setelah melewati kesunyian yang tandus dan kelam, mengetahui apakah di ujung segala batas, seluruh hal di dunia ini memiliki titik awal yang sama."
  },
  AvgCommunicate_127001_Content_6 = {
    Text = "Untuk itu, aku akan melakukan modifikasi terakhir pada tubuh dan otakku, mencoba melampaui batas yang berada di luar nilai ekstrem. Mengingat ada kemungkinan ini adalah komunikasi terakhir kita, aku memilih untuk menyampaikan perasaanku dengan cara yang bisa kau pahami."
  },
  AvgCommunicate_127001_Content_7 = {
    Text = "Terima kasih atas hadiah yang kau berikan kepadaku. Aku akan menggunakannya untuk mengejar jawaban, dan berharap kecerdasan manusia dapat membawa panduan baru dari sisi sana. Semoga Kunci Perak menuntun kita."
  },
  AvgCommunicate_127001_Content_8 = {Text = "Guru Dor!"},
  AvgCommunicate_127001_Content_9 = {
    Text = "Terlalu berisiko!"
  },
  AvgCommunicate_127001_Option_10 = {
    Text = "Tunggu dulu"
  },
  AvgCommunicate_127001_Option_9 = {
    Text = "Terlalu berisiko"
  },
  AvgCommunicate_127002_Content_1 = {
    Text = "Penjaga Rahasia... kenapa?"
  },
  AvgCommunicate_127002_Content_10 = {
    Text = "Sekarang setelah memiliki kekuatan baru ini, bagaimana rasanya?"
  },
  AvgCommunicate_127002_Content_11 = {
    Text = "Aku... aku sangat senang, Penjaga Rahasia."
  },
  AvgCommunicate_127002_Content_12 = {
    Text = "Bukan karena kekuatan dahsyat yang belum pernah kurasakan itu, tapi karena Anda, kata-kata Anda..."
  },
  AvgCommunicate_127002_Content_13 = {
    Text = "Kurasa... mungkin mulai sekarang, aku benar-benar memiliki kemampuan untuk membantu orang-orang di sekitarku, membantu Anda."
  },
  AvgCommunicate_127002_Content_14 = {
    Text = "Terima kasih banyak, banyak sekali, Penjaga Rahasia..."
  },
  AvgCommunicate_127002_Content_15 = {
    Text = "Tidak perlu sungkan, dan jangan merasa terbebani, Aegis."
  },
  AvgCommunicate_127002_Content_16 = {
    Text = "Ini bukanlah tanggung jawab yang berat. Ini hanyalah hadiah yang menjadi milikmu."
  },
  AvgCommunicate_127002_Content_17 = {
    Text = "Nikmatilah. Semua yang ingin kamu wujudkan, sekarang, kamu bisa melakukannya."
  },
  AvgCommunicate_127002_Content_18 = {
    Text = "Dari dulu hingga nanti, kamu selalu menjadi kebanggaan kami, Aegis."
  },
  AvgCommunicate_127002_Content_2 = {
    Text = "Kenapa apanya?"
  },
  AvgCommunicate_127002_Content_20 = {
    Text = "Aku akan menjaga semua orang, Penjaga Rahasia!"
  },
  AvgCommunicate_127002_Content_3 = {
    Text = "Hadiah yang begitu berharga... kenapa harus disia-siakan untukku..."
  },
  AvgCommunicate_127002_Content_4 = {
    Text = "Ini bukan pemborosan, Aegis. Ini memang pantas untukmu."
  },
  AvgCommunicate_127002_Content_5 = {
    Text = "Tapi... tapi aku tidak berhasil melakukan apa pun... tidak berhasil melindungi apa pun..."
  },
  AvgCommunicate_127002_Content_6 = {
    Text = "Bukan begitu, Aegis."
  },
  AvgCommunicate_127002_Content_7 = {
    Text = "Sejak sebelum kebangkitan, kita sudah bersama-sama melewati perjalanan yang sangat, sangat panjang."
  },
  AvgCommunicate_127002_Content_8 = {
    Text = "Sepanjang perjalanan ini, kamu berulang kali berdiri di depan semua orang, berulang kali melindungi semuanya."
  },
  AvgCommunicate_127002_Content_9 = {
    Text = "Jika bukan karenamu, mungkin aku sudah berkali-kali tumbang di perjalanan."
  },
  AvgCommunicate_127003_Content_1 = {
    Text = "Aku bermimpi."
  },
  AvgCommunicate_127003_Content_10 = {
    Text = "Tentu saja, kecuali saat di arena latihan."
  },
  AvgCommunicate_127003_Content_11 = {Text = "???"},
  AvgCommunicate_127003_Content_12 = {
    Text = "Ayo, tubuh ini telah kembali utuh. Rasakan kekuatan sejatiku, keluarkan wujud terkuatmu, dan bertarunglah denganku dengan sungguh-sungguh."
  },
  AvgCommunicate_127003_Content_13 = {Text = "???!!!"},
  AvgCommunicate_127003_Content_14 = {
    Text = "Ramona, tolong aku!"
  },
  AvgCommunicate_127003_Content_2 = {Text = "Mimpi?"},
  AvgCommunicate_127003_Content_3 = {
    Text = "Berkat bahan-bahan yang kau bawa, aku tidur nyenyak."
  },
  AvgCommunicate_127003_Content_4 = {
    Text = "Aku menjelajahi Eon Arkean dalam wujud awalku. Debu, cahaya, materi, dimensi, segala sesuatu yang dapat dirasakan maupun tidak, semuanya mengalir melewati siripku."
  },
  AvgCommunicate_127003_Content_5 = {
    Text = "Bukan untuk menaklukkan, bukan untuk melahap, hanya kekuatan murni, dan kehancuran murni tanpa batas."
  },
  AvgCommunicate_127003_Content_6 = {
    Text = "Begitu memuaskan, begitu bebas, sungguh luar biasa menyegarkan!"
  },
  AvgCommunicate_127003_Content_7 = {Text = "Eh……"},
  AvgCommunicate_127003_Content_8 = {
    Text = "Sudahlah, aku tahu apa yang kau khawatirkan."
  },
  AvgCommunicate_127003_Content_9 = {
    Text = "Tenang saja, kekuatan dan kehancuranku hanya akan kulampiaskan pada mereka yang berdiri di sisi berlawanan dari kalian."
  },
  AvgCommunicate_127004_Content_1 = {
    Text = "Protokol akhir telah diaktifkan... Reboot unit selesai."
  },
  AvgCommunicate_127004_Content_10 = {
    Text = "Komponen saya dalam kondisi baik, tetapi persepsi saya... telah berubah."
  },
  AvgCommunicate_127004_Content_11 = {
    Text = "Sebuah modul kognitif baru telah diaktifkan."
  },
  AvgCommunicate_127004_Content_12 = {
    Text = "Saya bisa \"mendengar\" irama kekuatan spiritual yang mengalir melalui saluran, bisa \"melihat\" emosi di balik setiap kata yang Anda ucapkan."
  },
  AvgCommunicate_127004_Content_13 = {
    Text = "Dunia menjadi lebih jelas, lebih hidup. Saya semakin mendekati Anda, semakin mendekati... manusia."
  },
  AvgCommunicate_127004_Content_14 = {
    Text = "Terima kasih, Penjaga Rahasia..."
  },
  AvgCommunicate_127004_Content_15 = {
    Text = "Saya juga tidak menyangka akan ada efek seperti ini, saya hanya menyiapkan beberapa material sederhana saja..."
  },
  AvgCommunicate_127004_Content_16 = {
    Text = "Yang Anda berikan bukan sekadar material sederhana, melainkan kemungkinan, kunci yang membuka batasan lama saya."
  },
  AvgCommunicate_127004_Content_17 = {
    Text = "Kekuatan ini, persepsi baru ini, adalah hadiah yang Anda berikan."
  },
  AvgCommunicate_127004_Content_18 = {
    Text = "Saya akan sangat menghargai hadiah ini. Saya akan membalas Anda dengan balasan yang melampaui imajinasi."
  },
  AvgCommunicate_127004_Content_19 = {
    Text = "Ini bukan program yang telah diatur sebelumnya. Ini adalah ucapan terima kasih yang tulus, yang berasal dari \"diri saya\" sendiri."
  },
  AvgCommunicate_127004_Content_2 = {
    Text = "Penjaga Rahasia, selamat datang."
  },
  AvgCommunicate_127004_Content_3 = {
    Text = "Erica! Kamu baik-baik saja?"
  },
  AvgCommunicate_127004_Content_4 = {
    Text = "Profesor Dole bilang, mengaktifkan protokol akhir untukmu adalah hal yang sangat berbahaya. Kalau bukan karena kamu sangat menginginkannya, aku sama sekali tidak akan..."
  },
  AvgCommunicate_127004_Content_5 = {
    Text = "Erica telah menyelesaikan pemeriksaan mandiri. Unit tidak mengalami kerusakan, aliran energi stabil, semua komponen beroperasi normal."
  },
  AvgCommunicate_127004_Content_6 = {
    Text = "Aku baik-baik saja, Penjaga Rahasia. Tidak pernah sebaik ini sebelumnya."
  },
  AvgCommunicate_127004_Content_7 = {
    Text = "Roda gigi di tubuhku... sedang \"bernyanyi\"."
  },
  AvgCommunicate_127004_Content_8 = {
    Text = "\"Bernyanyi\"? Apa maksudnya?"
  },
  AvgCommunicate_127004_Content_9 = {
    Text = "Apakah ada kerusakan internal? Apakah ada suara aneh yang muncul?!"
  },
  AvgCommunicate_127004_Option_8 = {
    Text = "\"Bernyanyi\"?"
  },
  AvgCommunicate_127004_Option_9 = {
    Text = "Apakah bagian dalamnya rusak?"
  },
  AvgCommunicate_127005_Content_1 = {
    Text = "Orita tiba-tiba melihat banyak sekali teman-teman yang berkilauan!"
  },
  AvgCommunicate_127005_Content_10 = {
    Text = "Orita bahkan punya kekuatan untuk pergi ke Yalan, Terans..."
  },
  AvgCommunicate_127005_Content_11 = {
    Text = "Umm, Orita lupa. Pokoknya, Penjaga Rahasia, temani aku mencari teman baru ya!"
  },
  AvgCommunicate_127005_Content_12 = {
    Text = "Dengan kekuatan seperti ini, Orita suatu hari pasti akan menemukan banyak sekali teman, dan membawa teman-teman pulang ke rumah di dasar laut!"
  },
  AvgCommunicate_127005_Content_2 = {
    Text = "Ah... Teman-teman menghilang lagi! Ke mana mereka pergi?"
  },
  AvgCommunicate_127005_Content_3 = {
    Text = "Sepertinya kamu mengalami halusinasi saat memahami hukum akhir alam semesta..."
  },
  AvgCommunicate_127005_Content_4 = {
    Text = "Halusinasi? Jadi teman-teman itu..."
  },
  AvgCommunicate_127005_Content_7 = {
    Text = "Hm? Ada apa?"
  },
  AvgCommunicate_127005_Content_8 = {
    Text = "Setelah melihat halusinasi teman-teman, Orita dipenuhi kekuatan! Kekuatan yang sangat banyak!"
  },
  AvgCommunicate_127005_Content_9 = {
    Text = "Sekarang Orita bisa pergi ke akuarium kecil, lautan, akuarium besar untuk mencari teman baru!"
  },
  AvgCommunicate_127091_Content_1 = {
    Text = "Bunga melati kecil, ada perlu apa mencariku?"
  },
  AvgCommunicate_127091_Content_10 = {
    Text = "Aku singkirkan kipas ini ya~"
  },
  AvgCommunicate_127091_Content_12 = {
    Text = "Sudah kuduga..."
  },
  AvgCommunicate_127091_Content_13 = {
    Text = "Tapi yang mereka lihat, sepertinya hanyalah wajah kekasih mereka saat pertama kali bertemu."
  },
  AvgCommunicate_127091_Content_14 = {
    Text = "Cinta itu sungguh hal yang aneh. Jelas-jelas ada di sisi, tapi tetap saja mengejar bayangan tanpa peduli segalanya."
  },
  AvgCommunicate_127091_Content_15 = {
    Text = "Apakah cinta itu sesuatu yang benar-benar ada, ataukah hanya obsesi yang semu?"
  },
  AvgCommunicate_127091_Content_2 = {
    Text = "Meskipun aku tidak ingat apakah sudah pernah memberitahumu, tapi semua akomodasi dan makan yang disediakan Mesagard untuk para Awakened itu gratis."
  },
  AvgCommunicate_127091_Content_3 = {Text = "Lalu?"},
  AvgCommunicate_127091_Content_4 = {
    Text = "Kantor administrasi menerima 45 surat dari pria berbagai kalangan, yang meminta untuk menanggung semua biayamu selama di Mesagard."
  },
  AvgCommunicate_127091_Content_5 = {
    Text = "Pada saat yang sama, kami juga menerima sekitar 60 surat dengan permintaan serupa untuk menafkahimu. 45 surat dari istri para pria tersebut, dan 15 sisanya dari beberapa wanita yang \"baru-baru ini\" tinggal sendiri. Apa kau punya petunjuk soal ini?"
  },
  AvgCommunicate_127091_Content_6 = {
    Text = "Mesagard melarang segala bentuk penyebaran ajaran!"
  },
  AvgCommunicate_127091_Content_7 = {
    Text = "Berhentilah bergabung dengan keluarga mereka!"
  },
  AvgCommunicate_127091_Content_8 = {
    Text = "Ah, hari-hari biasa di negeri asing ini sungguh membosankan. Lagipula, terlalu banyak orang yang cinta berubah jadi benci, saling muak memandang, dan terjerat asmara. Aku hanya ingin membantu mereka saja."
  },
  AvgCommunicate_127091_Content_9 = {
    Text = "Bantuan yang kau maksud jangan-jangan…"
  },
  AvgCommunicate_127091_Option_6 = {
    Text = "Mesagard melarang segala bentuk penyebaran ajaran!"
  },
  AvgCommunicate_127091_Option_7 = {
    Text = "Berhentilah bergabung dengan keluarga mereka!"
  },
  AvgCommunicate_127092_Content_10 = {
    Text = "Lagipula, aku juga percaya kau memiliki niat baik yang cukup terhadapku."
  },
  AvgCommunicate_127092_Content_11 = {
    Text = "Itu belum tentu lho~ Bagaimana Melati kecil tahu, kalau kau sekarang sudah keluar dari Dreamless?"
  },
  AvgCommunicate_127092_Content_12 = {Text = "?!"},
  AvgCommunicate_127092_Content_13 = {
    Text = "Dinda sudah pernah bilang, di dalam Dreamless tidak ada benar atau salah. Apa yang kau percaya, itulah yang nyata."
  },
  AvgCommunicate_127092_Content_14 = {
    Text = "Tarik napas dalam-dalam, apakah kau mencium aroma bunga magnolia putih?"
  },
  AvgCommunicate_127092_Content_15 = {Text = "???!!!"},
  AvgCommunicate_127092_Content_17 = {
    Text = "Ahahahahaha, tentu saja itu cuma bercanda. Dinda benar-benar ingin melihat ekspresi wajah Melati kecil sekarang."
  },
  AvgCommunicate_127092_Content_18 = {
    Text = "Terima kasih, aku benar-benar kaget."
  },
  AvgCommunicate_127092_Content_19 = {
    Text = "Jangan bercanda seperti itu!"
  },
  AvgCommunicate_127092_Content_2 = {
    Text = "...Aku tidak akan pernah mencobanya lagi."
  },
  AvgCommunicate_127092_Content_20 = {
    Text = "Aduh, tapi lain kali, belum tentu cuma bercanda lho~"
  },
  AvgCommunicate_127092_Content_3 = {
    Text = "Kemampuan yang mengerikan, setiap detik yang kujalani terasa begitu nyata — amarah, dendam, kegembiraan, kebahagiaan — kepalaku masih berdengung sampai sekarang."
  },
  AvgCommunicate_127092_Content_4 = {
    Text = "Di dalam ilusi Dreamless, rasanya aku sangat mencintaimu, tapi juga sangat membencimu. Benci dan cinta sama kuatnya tertambat pada dirimu seorang."
  },
  AvgCommunicate_127092_Content_5 = {
    Text = "Rasanya waktu berlalu selama seumur hidup, padahal kenyataannya hanya beberapa menit."
  },
  AvgCommunicate_127092_Content_7 = {
    Text = "Cinta dan benci memang berasal dari sumber yang sama. Cinta saja terlalu manis, benci saja terlalu dingin. Hanya jalinan cinta dan benci yang bisa paling cepat membekas di hati."
  },
  AvgCommunicate_127092_Content_8 = {
    Text = "Tapi Melati kecil benar-benar pemberani sampai membuat dinda terkejut, ternyata berani datang mencoba sendiri."
  },
  AvgCommunicate_127092_Content_9 = {
    Text = "Doer bilang, Dreamless akan sangat membantu penelitian ruang buatan, dan dia perlu memantau data fisiologisku."
  },
  AvgCommunicate_127092_Option_18 = {
    Text = "Terima kasih, aku benar-benar kaget."
  },
  AvgCommunicate_127092_Option_19 = {
    Text = "Jangan bercanda seperti itu!"
  },
  AvgCommunicate_127093_Content_1 = {
    Text = "Tolong buka jendela yang paling dekat denganmu."
  },
  AvgCommunicate_127093_Content_10 = {
    Text = "Di buku panduan sudah dijelaskan dengan sangat jelas, ruang konseling psikologi adalah tempat untuk melakukan bimbingan psikologis dan menjaga kesehatan mental guru dan siswa, bukan mainanmu."
  },
  AvgCommunicate_127093_Content_11 = {
    Text = "Hmm, tapi orang-orang yang pernah berbincang mendalam dengan dinda ini, jiwa dan raga mereka memang sangat-sangat \"sehat\" lho?"
  },
  AvgCommunicate_127093_Content_12 = {
    Text = "Pekerjaan ini dan dinda, bukankah sudah sangat cocok?"
  },
  AvgCommunicate_127093_Content_13 = {
    Text = "Bukankah prasyarat sehat jiwa dan raga itu adalah memiliki kehendak bebas..."
  },
  AvgCommunicate_127093_Content_14 = {
    Text = "Lepaskan Misage, aku akan lebih sering menemanimu mengobrol..."
  },
  AvgCommunicate_127093_Content_15 = {
    Text = "Hihi, itu memang tawaran yang menguntungkan. Kalau begitu, bagaimana kalau malam ini? Bulan terang bintang jarang, cocok sekali untuk minum beberapa gelas."
  },
  AvgCommunicate_127093_Content_2 = {
    Text = "Wangi sekali... Bunga magnolia putih?"
  },
  AvgCommunicate_127093_Content_3 = {
    Text = "Di iklim seperti ini, magnolia putih juga bisa tumbuh?"
  },
  AvgCommunicate_127093_Content_4 = {
    Text = "Hamba sedikit menguasai ilmu sihir, hanya trik kecil saja. Sesekali digunakan, juga bisa mengobati rasa rindu hamba pada kampung halaman."
  },
  AvgCommunicate_127093_Content_5 = {
    Text = "Sama seperti mengobrol dengan orang lain, hanya untuk mengusir kesepian. Anda bisa memahaminya, kan?"
  },
  AvgCommunicate_127093_Content_6 = {
    Text = "...Aku tahu kenapa kamu menghubungiku."
  },
  AvgCommunicate_127093_Content_7 = {
    Text = "Aku tidak bisa membantumu."
  },
  AvgCommunicate_127093_Content_8 = {
    Text = "Ruang konseling psikologi bukan untuk hal seperti itu."
  },
  AvgCommunicate_127093_Content_9 = {
    Text = "Meskipun kamu mengirim bunga untuk mencari simpati, aku tetap tidak akan membantu melobi permohonan pekerjaanmu."
  },
  AvgCommunicate_127093_Option_7 = {
    Text = "Aku tidak bisa membantumu."
  },
  AvgCommunicate_127093_Option_8 = {
    Text = "Ruang konseling psikologi bukan untuk hal seperti itu."
  },
  AvgCommunicate_129630_Content_1 = {
    Text = "Harta karun, ditemukan!"
  },
  AvgCommunicate_129630_Content_10 = {
    Text = "Itu masih dalam tahap percobaan! Buang sebelum berubah jadi hitam!"
  },
  AvgCommunicate_129630_Content_11 = {
    Text = "Kalau tidak, akan meledak!"
  },
  AvgCommunicate_129630_Content_13 = {
    Text = "Moss? Moss?!"
  },
  AvgCommunicate_129630_Content_14 = {
    Text = "Huu... huu..."
  },
  AvgCommunicate_129630_Content_15 = {
    Text = "Moss! Kamu baik-baik saja?!"
  },
  AvgCommunicate_129630_Content_16 = {
    Text = "Tidak ada lagi…… Mutiara……"
  },
  AvgCommunicate_129630_Content_18 = {
    Text = "Kamu melemparnya keluar? Tidak terluka, kan?"
  },
  AvgCommunicate_129630_Content_19 = {
    Text = "Si Bola Arang, sudah terlambat."
  },
  AvgCommunicate_129630_Content_2 = {
    Text = "Mutiara, bisa berubah warna!"
  },
  AvgCommunicate_129630_Content_20 = {
    Text = "Meledak, mutiara. Tapi, Moss, tidak apa-apa."
  },
  AvgCommunicate_129630_Content_21 = {
    Text = "Tapi…… Mutiara……"
  },
  AvgCommunicate_129630_Content_22 = {
    Text = "Yang penting orangnya tidak apa-apa. Seharusnya ada versi yang tidak berbahaya dari benda itu."
  },
  AvgCommunicate_129630_Content_23 = {
    Text = "Nanti aku akan melaporkan soal penyimpanan bahan berbahaya yang tidak semestinya ini."
  },
  AvgCommunicate_129630_Content_24 = {
    Text = "Sekalian nanti aku mintakan satu lagi versi yang tidak berbahaya untukmu."
  },
  AvgCommunicate_129630_Content_25 = {Text = "!"},
  AvgCommunicate_129630_Content_27 = {
    Text = "Si Bola Arang, yang terbaik!"
  },
  AvgCommunicate_129630_Content_3 = {
    Text = "Mutiara yang bisa berubah warna? Rasanya pernah lihat di suatu tempat..."
  },
  AvgCommunicate_129630_Content_4 = {
    Text = "Merah, putih, biru!"
  },
  AvgCommunicate_129630_Content_5 = {
    Text = "Merah, putih, biru... kuning, hijau, hitam?"
  },
  AvgCommunicate_129630_Content_6 = {
    Text = "Kuning, hijau, Si Bola Arang, tahu?"
  },
  AvgCommunicate_129630_Content_7 = {
    Text = "\"Hollow Tide\"?!"
  },
  AvgCommunicate_129630_Content_8 = {
    Text = "Cepat buang!"
  },
  AvgCommunicate_129630_Content_9 = {
    Text = "Cepat lempar ke tempat yang tidak ada orang!"
  },
  AvgCommunicate_129630_Option_8 = {
    Text = "Cepat buang!"
  },
  AvgCommunicate_129631_Content_1 = {
    Text = "Si Gumpalan Arang, ingat?"
  },
  AvgCommunicate_129631_Content_10 = {
    Text = "Klap-klap-klap!"
  },
  AvgCommunicate_129631_Content_11 = {
    Text = "Si Bola Arang, hebat!"
  },
  AvgCommunicate_129631_Content_12 = {
    Text = "Benar, kode rahasia! Si Bola Arang, orangnya!"
  },
  AvgCommunicate_129631_Content_13 = {
    Text = "Operasi, serbu! Tengah malam, kantin!"
  },
  AvgCommunicate_129631_Content_14 = {
    Text = "Demi ikan bakar emas!"
  },
  AvgCommunicate_129631_Content_15 = {Text = "Berangkat!"},
  AvgCommunicate_129631_Content_16 = {Text = "Berangkat!"},
  AvgCommunicate_129631_Content_2 = {Text = "Mm, ayo!"},
  AvgCommunicate_129631_Content_3 = {Text = "Gururu?"},
  AvgCommunicate_129631_Content_4 = {Text = "Byur byur?"},
  AvgCommunicate_129631_Content_5 = {
    Text = "Gururu gururu!"
  },
  AvgCommunicate_129631_Content_6 = {
    Text = "Byur… byur byur?"
  },
  AvgCommunicate_129631_Content_7 = {
    Text = "Si Gumpalan Arang, salah!"
  },
  AvgCommunicate_129631_Content_8 = {
    Text = "Ya, klap-klap-klap!"
  },
  AvgCommunicate_129631_Content_9 = {
    Text = "Tapi, nggak masalah!"
  },
  AvgCommunicate_129631_Option_10 = {
    Text = "Klap-klap-klap!"
  },
  AvgCommunicate_129631_Option_6 = {
    Text = "Byur… byur byur?"
  },
  AvgCommunicate_129632_Content_1 = {
    Text = "Introspeksi……susah sekali……"
  },
  AvgCommunicate_129632_Content_10 = {
    Text = "Lain kali aku siapkan rute yang lebih tersembunyi."
  },
  AvgCommunicate_129632_Content_11 = {
    Text = "Dijamin nggak akan ketangkap!"
  },
  AvgCommunicate_129632_Content_12 = {
    Text = "Ketangkap juga, nggak apa-apa!"
  },
  AvgCommunicate_129632_Content_13 = {Text = "Kenapa?"},
  AvgCommunicate_129632_Content_14 = {
    Text = "Sudah, surat introspeksi, disiapkan duluan!"
  },
  AvgCommunicate_129632_Content_15 = {
    Text = "Diserahkan, setelah tertangkap!"
  },
  AvgCommunicate_129632_Content_16 = {
    Text = "Punya Si Bola Arang, juga ada!"
  },
  AvgCommunicate_129632_Content_17 = {
    Text = "Tunggu, jangan siapkan hal seperti itu dari awal!"
  },
  AvgCommunicate_129632_Content_2 = {
    Text = "Haah……gara-gara Uuhashi dan Agrippa!"
  },
  AvgCommunicate_129632_Content_3 = {
    Text = "Sejak mereka berdua kabur dari jebakan dan menghabiskan semua makanan di dapur belakang……"
  },
  AvgCommunicate_129632_Content_4 = {
    Text = "Kepala koki meningkatkan penjagaan sepuluh kali lipat!"
  },
  AvgCommunicate_129632_Content_5 = {
    Text = "Terang sekali……lampunya……berisik sekali……alarmnya……"
  },
  AvgCommunicate_129632_Content_6 = {
    Text = "Dapur belakang, menakutkan……"
  },
  AvgCommunicate_129632_Content_7 = {
    Text = "Tapi, enak, ikan bakar!"
  },
  AvgCommunicate_129632_Content_8 = {
    Text = "Tapi, ikan bakar, enak!"
  },
  AvgCommunicate_129632_Content_9 = {
    Text = "Bareng, lain kali, mau?"
  },
  AvgCommunicate_134101_Content_1 = {
    Text = "Pelita hatiku…… tidak, sekarang seharusnya aku menyebut Anda sebagai Matahari."
  },
  AvgCommunicate_134101_Content_10 = {
    Text = "Lagipula, kamu baik-baik saja? Kenapa tiba-tiba bicara seperti ini?"
  },
  AvgCommunicate_134101_Content_11 = {
    Text = "Berkat anugerah-Mu, kini aku dapat melihat jiwa-Mu dengan jelas, dan mengetahui wujud asli dunia ini."
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "Cahaya, cahaya... Ternyata dunia ini pada awalnya adalah kegelapan dan kekacauan. Karena ada dewa yang memilih untuk berkorban, matahari menjadi nyata, dan semua makhluk dapat menikmati kebahagiaan keberadaan..."
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "Apa kamu terlalu banyak membaca kitab suci? Rasanya kamu perlu sedikit menenangkan diri."
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "Aku mengerti, Engkau ingin berbaur di antara semua makhluk, dan tidak ingin duduk di atas singgasana ilahi."
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "Ketulusan-Mu, pengabdian-Mu, pengorbanan-Mu..."
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "Mulai sekarang aku akan berinteraksi dengan-Mu sebagai yang paling setia... bukan, sebagai teman selamanya."
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "Semoga hati suci yang tak pernah padam ini dapat mengusir semua kegelapan bagi-Mu."
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "Anda…… Anda bukan sekadar matahari, ternyata Anda adalah pusat alam semesta, titik awal kelahiran dunia."
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "Kita sudah seakrab ini, kenapa kamu malah lebih hormat dari sebelumnya?"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "Karena aku akhirnya mengerti, semua makhluk tidak pernah bersujud di kaki Anda, hanya karena mereka terlahir bodoh dan buta, tidak mampu melihat hakikat sejati Anda!"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "Bagaimana seekor semut bisa melihat keseluruhan wujud seekor gajah? Dulu aku pun hanya bisa mengandalkan Hati Suci, sekadar mengintip seujung kecil dari gunung es kekuatan Anda."
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "Meski begitu, Hati Suci pun akan merasakan sakit seperti tertusuk jarum karenanya. Cukup satu lirikan lagi ke jiwa Anda, dan aku bisa saja hancur dan binasa."
  },
  AvgCommunicate_134101_Content_7 = {
    Text = "Separah itu? Kalau begitu, lebih baik jangan dilihat lagi."
  },
  AvgCommunicate_134101_Content_8 = {
    Text = "Reaksi Anda begitu dingin, kukira Anda akan dengan senang hati menerima pujianku."
  },
  AvgCommunicate_134101_Content_9 = {
    Text = "Tidak ada yang bisa tiba-tiba menerima pujian seperti itu!"
  },
  AvgCommunicate_134101_Option_13 = {
    Text = "Kamu mungkin perlu menenangkan diri."
  },
  AvgCommunicate_134101_Option_3 = {
    Text = "……Perasaan yang aneh sekali."
  },
  AvgCommunicate_134101_Option_7 = {
    Text = "Separah itu?"
  },
  AvgCommunicate_134102_Content_1 = {
    Text = "Aku bermimpi tentang salju dan es di tanah kelahiranku, serta reruntuhan yang tandus itu."
  },
  AvgCommunicate_134102_Content_10 = {
    Text = "Justru karena manusia saling menjaga keramahan di permukaan, dunia ini menjadi lebih damai, menurutku itu juga hal yang baik."
  },
  AvgCommunicate_134102_Content_11 = {
    Text = "Membosankan. Kedamaian dan kebahagiaan tidak bisa dipertahankan hanya dengan kepura-puraan."
  },
  AvgCommunicate_134102_Content_12 = {
    Text = "Hanya ketika seorang raja menginginkan rakyatnya bahagia, dan yang kuat menginginkan yang lemah bahagia, barulah kedamaian akan terus berlanjut."
  },
  AvgCommunicate_134102_Content_13 = {
    Text = "Seperti aku dan para pelayanku yang manis, aku tidak pernah menyembunyikan hasratku di hadapan mereka, tapi mereka tetap menjalani kehidupan yang bahagia."
  },
  AvgCommunicate_134102_Content_14 = {
    Text = "Inilah kebenaran sejati milik yang kuat."
  },
  AvgCommunicate_134102_Content_15 = {
    Text = "Datanglah ke kamar tidurku malam ini. Aku sangat senang dengan persembahanmu selama ini, dan juga puas dengan kekuatan baru ini. Aku akan memperlihatkan kepadamu, pikiran terdalam yang sebenarnya ada di hatimu."
  },
  AvgCommunicate_134102_Content_16 = {
    Text = "Tunggu, hari ini?"
  },
  AvgCommunicate_134102_Content_17 = {
    Text = "Ekspresi terkejut"
  },
  AvgCommunicate_134102_Content_18 = {
    Text = "Kau tidak punya hak untuk menolak. Aku akan memberimu pengalaman yang lebih... menarik dari beberapa kali sebelumnya."
  },
  AvgCommunicate_134102_Content_19 = {
    Text = "Ekspresi bersinar Wanda"
  },
  AvgCommunicate_134102_Content_2 = {
    Text = "Sudah lama aku tidak mengingat tempat-tempat itu. Apakah karena pecahan kekuatan ini, atau karena jiwa yang lebih utuh?"
  },
  AvgCommunicate_134102_Content_20 = {
    Text = "(Aku masih punya laporan yang harus diserahkan! Kalau hari ini tidak diserahkan, Dor akan mengulitiku hidup-hidup!)"
  },
  AvgCommunicate_134102_Content_3 = {
    Text = "Sungguh perasaan yang sudah lama tidak kurasakan... Bagaimanapun, terima kasih, pelayanku yang manis. Oh, benar, kamu lebih suka aku memanggilmu teman."
  },
  AvgCommunicate_134102_Content_4 = {
    Text = "Siap melayani Anda, Nona."
  },
  AvgCommunicate_134102_Content_5 = {
    Text = "Heh, kamu selalu begitu sopan."
  },
  AvgCommunicate_134102_Content_6 = {
    Text = "Kenapa kamu tidak bisa sesekali membuang kepura-puraan membosankan itu? Itu membuat beberapa hadiahku menjadi sangat tidak menarik."
  },
  AvgCommunicate_134102_Content_7 = {
    Text = "Masyarakat kalian menjunjung tinggi kerendahan hati dan kesopanan sebagai kebajikan, namun kegelapan dalam hati manusia tidak kalah dari spesies di planet lain."
  },
  AvgCommunicate_134102_Content_8 = {
    Text = "Orang-orang mendandani diri mereka agar terlihat tidak berbahaya dan berkelas, hanyalah karena takut akan konsekuensi dari menunjukkan diri yang sebenarnya."
  },
  AvgCommunicate_134102_Content_9 = {
    Text = "Memang tidak salah jika dikatakan begitu, tapi selama perilakunya tidak bermasalah, menyelidiki pikiran dalam hati juga tidak begitu penting."
  },
  AvgCommunicate_134102_Option_20 = {Text = "Jangan!"},
  AvgCommunicate_134102_Option_4 = {
    Text = "Siap melayani Anda."
  },
  AvgCommunicate_134102_Option_9 = {
    Text = "Memang tidak salah juga."
  },
  AvgCommunicate_134103_Content_1 = {
    Text = "Bintang-bintang memanggilku..."
  },
  AvgCommunicate_134103_Content_10 = {
    Text = "Kau tahu? Agrippa sering bilang dia iri pada Miriam."
  },
  AvgCommunicate_134103_Content_11 = {
    Text = "Dia bilang kalau raja Roma masih ada sekarang, entah itu bayi kecil atau kakek tua, dia akan jauh lebih tenang."
  },
  AvgCommunicate_134103_Content_12 = {Text = "Iri..."},
  AvgCommunicate_134103_Content_13 = {
    Text = "Karena selama kau masih ada, Lemuria belum benar-benar lenyap."
  },
  AvgCommunicate_134103_Content_14 = {
    Text = "Lagipula, kau juga menggunakan kekuatan ini untuk membantu banyak orang di Myssage, kan!"
  },
  AvgCommunicate_134103_Content_15 = {
    Text = "Cukup banyak siswa yang menulis namamu di survei Awakened Body favorit, lho!"
  },
  AvgCommunicate_134103_Content_16 = {Text = "Haah..."},
  AvgCommunicate_134103_Content_17 = {
    Text = "Kami tidak butuh pemujaan yang mengganggu itu, urusan yang diminta Myssage sudah cukup banyak."
  },
  AvgCommunicate_134103_Content_18 = {
    Text = "Meskipun menggunakan kekuatan ini hanyalah hal sepele, tapi kalau terlalu sering mengganggu tidur kami, tetap saja melelahkan."
  },
  AvgCommunicate_134103_Content_19 = {
    Text = "Benarkah? Tapi aku dengar setiap kali ada siswa yang datang menangis meminta bantuanmu, kau adalah salah satu Awakened Body yang paling mudah mengabulkan permintaan, lho?"
  },
  AvgCommunicate_134103_Content_2 = {
    Text = "Di kedalaman mimpi, di dasar arus laut, dikelilingi ratusan juta pengikut, kembali ke atas takhta, membawa kemakmuran dan kedamaian bagi Lemuria."
  },
  AvgCommunicate_134103_Content_20 = {
    Text = "...Siapa yang menyebarkan rumor? Kami hanya tidak tahan dengan kebisingan mereka."
  },
  AvgCommunicate_134103_Content_21 = {
    Text = "Sudahlah, kebetulan kekuatan spiritual kami telah meningkat pesat, sudah waktunya memasuki mimpi yang lebih dalam dan lebih luas."
  },
  AvgCommunicate_134103_Content_22 = {
    Text = "Kali ini kami ingin mengunjungi mimpi para seniman dan penyair di era saat ini. Ingat, kalau bukan urusan penting, jangan biarkan siapa pun mengganggu."
  },
  AvgCommunicate_134103_Content_23 = {
    Text = "Hah? Reaksi setelah kondisi spiritual membaik malah mau tidur panjang?!"
  },
  AvgCommunicate_134103_Content_3 = {
    Text = "...Aku bermimpi seperti itu."
  },
  AvgCommunicate_134103_Content_4 = {
    Text = "Mimpi? Apakah mimpi ini memiliki makna ramalan?"
  },
  AvgCommunicate_134103_Content_5 = {
    Text = "Itu hanyalah panggilan yang daku terima setelah kekuatan meningkat hingga puncaknya. Adapun maknanya... Lemuria sudah tidak ada lagi, dan tidak perlu ada lagi."
  },
  AvgCommunicate_134103_Content_6 = {
    Text = "Mereka yang beruntung selamat bisa hidup dengan bebas di dunia baru, itu sudah cukup baik."
  },
  AvgCommunicate_134103_Content_7 = {
    Text = "Mereka tidak membutuhkan seorang raja yang datang terlambat untuk melindungi mereka."
  },
  AvgCommunicate_134103_Content_8 = {
    Text = "Tapi, kau tetap memimpin rakyatmu yang dulu, melindungi jiwa mereka."
  },
  AvgCommunicate_134103_Content_9 = {
    Text = "Kami tidak melakukan apa-apa, juga tidak pernah memimpin mereka. Itu hanya kesalahpahaman sepihak dari mereka."
  },
  AvgCommunicate_134103_Option_10 = {
    Text = "Itu bukan kesalahpahaman."
  },
  AvgCommunicate_134103_Option_19 = {Text = "Benarkah?"},
  AvgCommunicate_134103_Option_23 = {Text = "Hah?"},
  AvgCommunicate_134103_Option_8 = {Text = "Tapi..."},
  AvgCommunicate_134104_Content_1 = {
    Text = "Tertawa saat pertama bertemu, menangis tersedu dalam sekejap. Sudah lama hamba tidak bersenang-senang seperti ini."
  },
  AvgCommunicate_134104_Content_10 = {
    Text = "Eh, bukan berarti mereka tidak pantas mati, tapi cara melakukan sesuatu harus diperhatikan metodenya……"
  },
  AvgCommunicate_134104_Content_11 = {
    Text = "Dan ternyata arahannya senormal ini, aku terharu..."
  },
  AvgCommunicate_134104_Content_12 = {
    Text = "Aduh, biarkan hamba berpikir. Kalau hamba bilang sekarang bahwa awalnya hamba hanya ingin memelihara jangkrik untuk diadu, bukankah itu akan merusak suasana?"
  },
  AvgCommunicate_134104_Content_13 = {
    Text = "Bercanda kok."
  },
  AvgCommunicate_134104_Content_14 = {
    Text = "Dunia ini benar-benar terlalu membosankan, %player%. Meskipun kehancuran bisa datang besok, orang-orang biasa tetap terjebak dalam hal-hal duniawi seperti dendam, cinta, kebencian, dan nafsu."
  },
  AvgCommunicate_134104_Content_16 = {
    Text = "Namun meskipun begitu, bunga melati kecilku tetap rajin dan bersemangat, dengan gagah berani memikirkan cara untuk membantu Mereka."
  },
  AvgCommunicate_134104_Content_17 = {
    Text = "Jadi, karena hamba sudah mendapatkan kekuatan luar biasa ini, ke depannya apakah hamba akan membantu bunga melati kecil kesayanganku, atau justru menambah masalah?"
  },
  AvgCommunicate_134104_Content_18 = {
    Text = "Sudah pasti, melakukan keduanya sekaligus adalah yang paling menarik, kan?"
  },
  AvgCommunicate_134104_Content_19 = {Text = "???"},
  AvgCommunicate_134104_Content_2 = {
    Text = "Bunga melati kecilku, benar-benar memberikan hadiah yang luar biasa."
  },
  AvgCommunicate_134104_Content_20 = {
    Text = "Aku memberimu hadiah bukan untuk kau gunakan seperti ini."
  },
  AvgCommunicate_134104_Content_21 = {
    Text = "Cepat berhenti! Aku hanya bertanggung jawab atas insiden Erosi. Ketertiban umum dan moral bukan urusan Misager. Jangan buat rumah sakit jiwa Londinium menggantikan penjara! Hei, hei!"
  },
  AvgCommunicate_134104_Content_4 = {
    Text = "Semua blok, semua blok di sekitar sekolah mengalami kasus histeria massal warga dalam skala besar. Sekelompok besar orang menangis dan tertawa bersamaan. Polisi dan tenaga medis Londinium sampai kaki mereka hampir patah karena berlarian!"
  },
  AvgCommunicate_134104_Content_6 = {
    Text = "Hamba ini berada jauh di negeri asing, sendirian dan kesepian. Bunga melati kecil begitu mengasihani hamba, sehingga hamba bisa mencapai tingkatan ini..."
  },
  AvgCommunicate_134104_Content_7 = {
    Text = "Hamba benar-benar sangat gembira, sehingga tak tahan ingin mencoba kemampuan ini."
  },
  AvgCommunicate_134104_Content_8 = {
    Text = "Hmm, sangat berguna. Mereka yang hatinya penuh kotoran busuk, satu per satu jadi gila lebih cepat dari yang lain."
  },
  AvgCommunicate_134104_Content_9 = {
    Text = "Tunggu, pihak sekolah sudah mengirimkan data orang-orang itu. Membunuh istri, penyiksaan, @3@4……"
  },
  AvgCommunicate_134104_Option_19 = {Text = "???"},
  AvgCommunicate_134104_Option_9 = {
    Text = "Melakukan sesuatu harus memperhatikan cara dan metode."
  },
  AvgCommunicate_134105_Content_1 = {
    Text = "Cahaya mercusuar sudah mampu menerangi dasar laut yang sangat dalam."
  },
  AvgCommunicate_134105_Content_10 = {
    Text = "Hanya dari mendengar deskripsimu saja, aku bisa merasakan bahwa itu pasti negara yang sangat indah."
  },
  AvgCommunicate_134105_Content_11 = {
    Text = "Ya, kampung halaman sangat indah……karena itu aku tidak akan menyerah untuk menemukannya kembali."
  },
  AvgCommunicate_134105_Content_12 = {
    Text = "Kekuatan yang lebih besar berarti lebih banyak harapan. Aku akan memikat lebih banyak ngengat untuk bergerak menuju arah mercusuar……"
  },
  AvgCommunicate_134105_Content_13 = {
    Text = "Suatu hari nanti, tanah air akan bangkit kembali dari dasar laut, dan membuka pelukannya untukku sekali lagi."
  },
  AvgCommunicate_134105_Content_14 = {
    Text = "Ujung-ujungnya tetap mau melakukan hal seperti itu! Sia-sia saja aku ikut bersedih, hentikan sekarang juga!!!"
  },
  AvgCommunicate_134105_Content_2 = {
    Text = "Jalan pulang ke tanah air, kapan bisa ditemukan kembali..."
  },
  AvgCommunicate_134105_Content_3 = {
    Text = "Pharos……haah, mengatakan bahwa aku bisa memahami perasaanmu saat ini pun hanyalah penghiburan yang hampa. Kamu……jangan terlalu bersedih."
  },
  AvgCommunicate_134105_Content_4 = {
    Text = "Kesedihan……kerinduan akan kampung halaman telah menjadi bekas luka di dalam jiwa, aku sudah terbiasa hidup bersamanya."
  },
  AvgCommunicate_134105_Content_5 = {
    Text = "Kerinduan yang tak henti membawa penderitaan, tetapi juga membuatku selamanya mengingat rupa kampung halamanku."
  },
  AvgCommunicate_134105_Content_6 = {
    Text = "Perairan dangkal yang dipenuhi karang, kuil yang megah, dan gerbang menjulang tinggi tempat aku sering berdiri berjaga……"
  },
  AvgCommunicate_134105_Content_7 = {
    Text = "Aku ingat ukiran di tepian pilar-pilar batu itu, ingat setiap jalan lebar di ibu kota kerajaan, ingat ekspresi khusyuk dan bahagia orang-orang saat berdoa."
  },
  AvgCommunicate_134105_Content_8 = {
    Text = "Saat upacara besar diselenggarakan, seluruh negeri merayakan bersama. Itu adalah saat aku paling sibuk sekaligus paling puas."
  },
  AvgCommunicate_134105_Content_9 = {
    Text = "Aku pernah mendapat kehormatan untuk berjaga di hadapan iring-iringan raja, bersama-sama menikmati tatapan penuh kekaguman dan penghormatan dari seluruh rakyat, merasa bangga dan mulia……itu adalah momen yang paling kurindukan."
  },
  AvgCommunicate_134105_Option_10 = {
    Text = "Pasti itu negara yang sangat indah."
  },
  AvgCommunicate_134105_Option_14 = {
    Text = "Ujung-ujungnya tetap mau melakukan hal seperti itu!"
  },
  AvgCommunicate_134105_Option_3 = {
    Text = "Pharos……"
  },
  AvgCommunicate_134106_Content_1 = {
    Text = "Anu, anu, Tuan……"
  },
  AvgCommunicate_134106_Content_10 = {
    Text = "Setelah ini bisa menggendong Jenkin, Aegis, Kallab, dan Aurita ke kantin bersama-sama!"
  },
  AvgCommunicate_134106_Content_11 = {
    Text = "Ini terlalu banyak!"
  },
  AvgCommunicate_134106_Content_12 = {
    Text = "Um um! Terima kasih, Tuan! Kasih Lily banyak sekali!"
  },
  AvgCommunicate_134106_Content_14 = {
    Text = "Meskipun bukan itu maksudku, tapi..."
  },
  AvgCommunicate_134106_Content_15 = {
    Text = "Asalkan Lily senang, itu sudah cukup!"
  },
  AvgCommunicate_134106_Content_2 = {Text = "Hm?"},
  AvgCommunicate_134106_Content_3 = {
    Text = "Bisakah Tuan memuji Lily?"
  },
  AvgCommunicate_134106_Content_4 = {
    Text = "Lily anak baik, ada hal apa yang patut dipuji?"
  },
  AvgCommunicate_134106_Content_5 = {
    Text = "Lily, mengangkat banyak bisul!"
  },
  AvgCommunicate_134106_Content_6 = {
    Text = "Diangkat tinggi sekali!"
  },
  AvgCommunicate_134106_Content_9 = {
    Text = "Mungkin ini pengaruh dari Hukum Akhir..."
  },
  AvgCommunicate_134107_Content_1 = {
    Text = "Sejak memahami hukum tertinggi, jalur pelayaran di hadapanku menjadi semakin jelas."
  },
  AvgCommunicate_134107_Content_10 = {
    Text = "Sebagai seorang navigator, ini adalah kewajiban yang harus kujalankan."
  },
  AvgCommunicate_134107_Content_11 = {
    Text = "Siapa pun yang berada di posisi itu, mungkin juga akan melakukan hal yang sama."
  },
  AvgCommunicate_134107_Content_12 = {
    Text = "Pekerjaan navigasi mengandalkan tanggung jawab dan kewajiban, bukan untuk mendapatkan pujian."
  },
  AvgCommunicate_134107_Content_13 = {
    Text = "Kembalikan semua hadiah itu kepada para pelaut."
  },
  AvgCommunicate_134107_Content_14 = {
    Text = "Itu juga bentuk ketulusan hati mereka, terimalah saja."
  },
  AvgCommunicate_134107_Content_15 = {
    Text = "Selain itu, jika kau melihat cahaya kuning terang yang tidak diketahui asalnya di laut, tolong arahkan kapal ke jalur yang berlawanan sebisa mungkin."
  },
  AvgCommunicate_134107_Content_16 = {
    Text = "Jangan tanya kenapa, pihak sekolah akan segera menangani sumbernya..."
  },
  AvgCommunicate_134107_Content_2 = {
    Text = "Demi ribuan jiwa yang tersesat di jalur pelayaran, dan juga demi diriku sendiri, sekali lagi aku ingin menyampaikan rasa terima kasih yang tulus atas pencerahan yang Anda berikan."
  },
  AvgCommunicate_134107_Content_3 = {
    Text = "Tidak perlu seserius itu, ini memang sudah sepantasnya untukmu, Coppersand."
  },
  AvgCommunicate_134107_Content_4 = {
    Text = "Sepantasnya untukku?"
  },
  AvgCommunicate_134107_Content_5 = {
    Text = "Ya, pihak sekolah menerima beberapa surat terima kasih yang dikirimkan secara berantai."
  },
  AvgCommunicate_134107_Content_6 = {
    Text = "Mereka semua adalah orang-orang yang tersesat dalam pelayaran, namun melihat seberkas cahaya dingin biru-ungu di tiang kapal."
  },
  AvgCommunicate_134107_Content_7 = {
    Text = "Selama mengikuti panduan cahaya dingin itu, mereka bisa tiba di pelabuhan terdekat."
  },
  AvgCommunicate_134107_Content_8 = {
    Text = "Mereka menyebut cahaya itu sebagai \"Cahaya Sang Suci\"."
  },
  AvgCommunicate_134107_Content_9 = {
    Text = "Selain itu, ada juga banyak hadiah sebagai ungkapan rasa terima kasih, semuanya menumpuk di depan ruang pengiriman."
  },
  AvgCommunicate_134107_Option_5 = {
    Text = "Misagor menerima surat terima kasih..."
  },
  AvgCommunicate_134108_Content_1 = {
    Text = "Ada barang sebagus ini, kenapa tidak dikeluarkan lebih awal."
  },
  AvgCommunicate_134108_Content_10 = {
    Text = "Kamu ini @2 punya otak tidak sih, candaan saja dianggap serius!"
  },
  AvgCommunicate_134108_Content_11 = {
    Text = "Kalau semua jadi keturunan, Yang Mulia ini mau apakan peralatan elektronik jelek itu dan pengetahuan umum yang aneh-aneh, meskipun memori memang bisa dipertahankan sih."
  },
  AvgCommunicate_134108_Content_12 = {
    Text = "Masa aku harus bicara sendiri setiap hari menghadap cangkang kosong, aku tidak mau."
  },
  AvgCommunicate_134108_Content_14 = {
    Text = "Cih, ketahuan lagi, benar-benar membosankan."
  },
  AvgCommunicate_134108_Content_15 = {
    Text = "Aku percaya kamu tidak akan melakukan itu, Agrippa. Bahkan kalau sesekali kamu menyimpang, aku yakin aku pasti bisa mengendalikanmu kembali ke jalan yang benar."
  },
  AvgCommunicate_134108_Content_16 = {
    Text = "Karena kamu adalah penguasa labirin yang cerdas."
  },
  AvgCommunicate_134108_Content_17 = {
    Text = "Karena kamu adalah orang yang penting bagiku."
  },
  AvgCommunicate_134108_Content_18 = {
    Text = "Iyaak! Tiba-tiba ngomong apa sih yang aneh begitu, menjijikkan, sangat menjijikkan, telingaku sampai mau kotor!"
  },
  AvgCommunicate_134108_Content_19 = {
    Text = "Baiklah, aku akan dengan sangat terpaksa untuk sementara tidak mengubah siapa pun jadi keturunan, cepat bawa pergi tugas-tugas ini!"
  },
  AvgCommunicate_134108_Content_2 = {
    Text = "Haha, Raja Agung ini sekarang benar-benar bebas! Serigala Abu-abu yang mulia akan segera memulai kembali kekuasaannya di Misagor."
  },
  AvgCommunicate_134108_Content_3 = {
    Text = "Seluruh Misagor, tidak, seluruh Kadath akan dipenuhi oleh keturunanku."
  },
  AvgCommunicate_134108_Content_4 = {Text = "Benarkah?"},
  AvgCommunicate_134108_Content_5 = {
    Text = "Awalnya untuk merayakan kamu memahami hukum tertinggi, aku bahkan berencana membuat pengecualian untuk membantumu merapikan asrama, bahkan bagian akademik sudah setuju membebaskanmu dari tugas selama seminggu."
  },
  AvgCommunicate_134108_Content_6 = {
    Text = "Toh Serigala Abu-abu yang agung sudah berencana mengubah semua orang jadi keturunan, kurasa semua itu tidak diperlukan lagi, kan?"
  },
  AvgCommunicate_134108_Content_7 = {Text = "Eh, eh?!"},
  AvgCommunicate_134108_Content_9 = {
    Text = "Tidak boleh, tidak bisa, tidak diizinkan!"
  },
  AvgCommunicate_134108_Option_16 = {
    Text = "Karena kamu adalah penguasa labirin yang cerdas."
  },
  AvgCommunicate_134108_Option_17 = {
    Text = "Karena kamu adalah orang yang penting bagiku."
  },
  AvgCommunicate_134108_Option_4 = {Text = "Benarkah."},
  AvgCommunicate_134109_Content_1 = {
    Text = "Penjaga Mimi, aku melihat lorong yang gelap gulita……"
  },
  AvgCommunicate_134109_Content_10 = {
    Text = "Tapi, aku tidak merasakan niat jahat dari mata-mata kecil itu. Sebaliknya, aku merasa sangat tenang, dan sekarang sepertinya aku bisa menyatu dengan mereka."
  },
  AvgCommunicate_134109_Content_11 = {
    Text = "Maksudmu, kamu melebur ke dalam jiwa tikus-tikus itu?"
  },
  AvgCommunicate_134109_Content_12 = {
    Text = "Ya, aku merasa dalam sekejap diriku terpecah menjadi banyak sekali bagian, berlarian di pipa-pipa berkelok, di antara barang-barang berantakan, di bawah furnitur yang rendah..."
  },
  AvgCommunicate_134109_Content_13 = {
    Text = "Kamu teringat kehidupan yang dulu ya? Tidak apa-apa, sekarang semuanya sudah berlalu."
  },
  AvgCommunicate_134109_Content_14 = {
    Text = "Lalu— mengendalikan mereka untuk mencuri berbagai macam barang dengan mudah!"
  },
  AvgCommunicate_134109_Content_15 = {
    Text = "Kalau dulu aku punya kemampuan seperti ini, aku bahkan bisa mengosongkan bank terbesar di distrik barat, hahaha! Sekarang aku benar-benar raja pencuri se-negeri... tidak, se-dunia! Tidak ada lagi yang bisa menghalangiku!"
  },
  AvgCommunicate_134109_Content_17 = {
    Text = "Rasanya kali ini melapor ke polisi pun tidak berguna. Lebih baik aku minta Guru Doer untuk membuatkan alat pengawas saja."
  },
  AvgCommunicate_134109_Content_2 = {
    Text = "Tidak ada cahaya, tidak ada waktu, aku berjalan sendirian di sana terus dan terus, rasanya seperti berjalan seumur hidup lamanya."
  },
  AvgCommunicate_134109_Content_3 = {
    Text = "Kamu baik-baik saja? Kamu tersesat di dalam ruang lagi?"
  },
  AvgCommunicate_134109_Content_4 = {
    Text = "Aku berjalan sangat lama, akhirnya aku melihat sesuatu, seperti seberkas cahaya, sehelai asap, lalu perlahan berubah menjadi Brown! Matanya yang kecil dan bulat bersinar di ruang gelap itu."
  },
  AvgCommunicate_134109_Content_5 = {
