  AvgCommunicate_134110_Content_4 = {
    Text = "Tidak, tidak, lebih banyak teknologi @2manusia, pengetahuan, jiwa yang lebih kuat, semuanya tidak berguna, tidak berguna lagi! Aku tetap tidak bisa bermigrasi lagi!"
