  },
  AvgCommunicate_134110_Content_6 = {
    Text = "Aku tidak mau menjadi lebih kuat lagi, aku mau kabur, aku mau lari sejauh-jauhnya. Tapi kalau seluruh dunia ini hitam, semua cahaya itu palsu, lalu aku bisa pergi ke mana..."
