  },
  AvgCommunicate_134111_Content_2 = {
    Text = "Para pengikut memang pernah memuji dengan kata-kata berlebihan seperti menutupi langit dan menghalangi matahari, tapi aku tahu, yang pernah kumiliki hanyalah sepasang sayap yang sangat biasa."
  },
  AvgCommunicate_134111_Content_20 = {
    Text = "Tentu saja! Suatu kehormatan bagiku, Penyelamat."
  },
  AvgCommunicate_134111_Content_21 = {
    Text = "Sudah sepakat, aku akan segera minta Erika membuatkan keranjang angkut khusus!"
  },
  AvgCommunicate_134111_Content_22 = {
    Text = "Jangan pernah lagi berpikir untuk memberikan sayapmu kepada orang lain, siapa pun itu tidak boleh."
  },
  AvgCommunicate_134111_Content_3 = {
