  AvgCommunicate_134114_Content_4 = {
    Text = "Liz……apakah kamu masih mengenang kebakaran waktu itu?"
  },
  AvgCommunicate_134114_Content_5 = {
    Text = "Kebencianku sudah perlahan terbakar habis dalam api, tapi, aku tidak berhak memaafkan kebakaran itu atas nama orang lain."
  },
  AvgCommunicate_134114_Content_6 = {
    Text = "Aku tidak pernah menyesal, dan tidak akan lari dari wajah-wajah di dalam api itu."
  },
  AvgCommunicate_134114_Content_7 = {
    Text = "Setelah datang ke sini, kamu memberiku kehidupan baru. Aku sudah tidak membutuhkan panggung megah apa pun, tapi jika ada kamu sebagai penonton, kurasa, aku masih akan merasa bahagia saat menari."
