  },
  AvgCommunicate_134115_Content_11 = {
    Text = "Kau bisa melihat semua itu, aku turut bahagia untukmu, Myriam!"
  },
  AvgCommunicate_134115_Content_12 = {
    Text = "Tentu saja, aku akan tetap mempersembahkan segalanya demi turunnya Kerajaan Tuhan."
  },
  AvgCommunicate_134115_Content_13 = {
    Text = "Tapi aku kini mengerti... Kerajaan Tuhan bukanlah hanya dua keadaan antara turun sepenuhnya atau lenyap sepenuhnya."
  },
  AvgCommunicate_134115_Content_14 = {
    Text = "Saat kita berdoa demi turunnya Kerajaan Tuhan, sebagian dari Kerajaan Tuhan telah hadir di sisi kita."
  },
  AvgCommunicate_134115_Content_15 = {
    Text = "Terima kasih, Penjaga Rahasia. Kaulah yang memberiku kekuatan baru."
  },
  AvgCommunicate_134115_Content_16 = {
    Text = "Yang kulihat adalah bukti keberadaan abadi Kerajaan Tuhan!"
