  AvgCommunicate_134115_Content_2 = {
    Text = "Apa yang kau lihat?"
  },
  AvgCommunicate_134115_Content_3 = {
    Text = "Kerajaan Tuhan... benar... itu adalah siluet Kerajaan Tuhan!"
