  AvgCommunicate_134116_Content_3 = {
    Text = "Bagaimana mengatakannya ya, kira-kira begini, pikiran-pikiran biasa bagiku seperti buku harian yang terbuka lebar, membosankan dan terlihat jelas semuanya. Agak membosankan, sih."
