  AvgCommunicate_134116_Content_5 = {
    Text = "Tidak sehebat itu, kok. Lagipula, di dunia ini masih banyak orang yang mentalnya tangguh dan keras kepala, berusaha membungkus hati mereka berlapis-lapis agar tidak mudah diketahui orang lain."
  },
  AvgCommunicate_134116_Content_6 = {
    Text = "Dan juga ada keberadaan yang selalu misterius sepertimu."
  },
  AvgCommunicate_134116_Content_7 = {
    Text = "Tidak perlu tegang. Mendapatkan jawaban ujian lebih dulu itu sama tidak serunya dengan mengetahui akhir cerita lebih dulu atau menemukan pelaku pembunuhan sebelum waktunya."
  },
  AvgCommunicate_134116_Content_8 = {
    Text = "Aku sangat menikmati proses membimbing, menduga, dan mengupas kepompong yang membungkus jiwa ini sedikit demi sedikit."
  },
  AvgCommunicate_134116_Content_9 = {
    Text = "Tanpa permainan saling berbalas seperti ini, apa bedanya dengan dokter gadungan yang mendiagnosis secara kasar dan langsung memotong bagian otak seseorang?"
  },
  AvgCommunicate_134116_Option_10 = {Text = "Eh……"},
  AvgCommunicate_134116_Option_12 = {Text = "?!!"},
  AvgCommunicate_134116_Option_2 = {
    Text = "Rasa seperti apa?"
  },
  AvgCommunicate_134116_Option_4 = {Text = "Apa?!"},
  AvgCommunicate_134117_Content_1 = {
    Text = "Rima dalam syair itu menjadi semakin mendalam dan penuh perasaan."
  },
  AvgCommunicate_134117_Content_10 = {
    Text = "Aku bisa membawamu masuk ke dunia puisi, menjelajahinya bersama."
  },
  AvgCommunicate_134117_Content_12 = {
    Text = "Ini seperti sihir kata-kata, hebat sekali!"
  },
  AvgCommunicate_134117_Content_13 = {
    Text = "Kalau begitu, aku ingin merasakan ilusi pensiun, kaya raya, dan makanan tak terbatas. Bisa bawa aku ke sana?"
  },
  AvgCommunicate_134117_Content_14 = {
    Text = "I-ini... seharusnya, seharusnya bisa! Tolong beri aku waktu sebentar, aku perlu memikirkannya dengan baik..."
  },
  AvgCommunicate_134117_Content_2 = {
    Text = "Sekarang, aku bisa melihat emosi yang bergejolak dalam irama senandung itu, serta kekuatan yang terpancar di balik setiap kiasan."
  },
  AvgCommunicate_134117_Content_3 = {
    Text = "Meskipun aku tidak sepenuhnya mengerti, tapi kedengarannya seperti pemandangan yang sangat indah."
  },
  AvgCommunicate_134117_Content_4 = {
    Text = "Ya, puisi adalah kunci untuk mengeksplorasi keindahan. Puisi mampu mengungkap hukum universal dunia dan meniru wajah asli kehidupan."
  },
  AvgCommunicate_134117_Content_5 = {
    Text = "Dalam puisi, kita menemukan jati diri, menemukan kebijaksanaan sejarah dan filsafat, serta menemukan tempat tinggal yang murni bagi jiwa."
  },
  AvgCommunicate_134117_Content_6 = {
    Text = "Ah, tanpa sadar aku sudah mulai berceloteh sendiri, maaf ya..."
  },
  AvgCommunicate_134117_Content_7 = {
    Text = "Tidak apa-apa, aku suka melihatmu begitu antusias saat membicarakan puisi, sangat mempesona!"
  },
  AvgCommunicate_134117_Content_8 = {
    Text = "Te-terima kasih, Penjaga Rahasia. Singkatnya, sekarang aku bisa meminjam lebih banyak kekuatan dari dunia itu melalui bait-bait puisi, menciptakan sebuah ilusi puitis yang sempurna."
  },
  AvgCommunicate_134117_Content_9 = {
    Text = "Entah kau ingin menikmati ketenangan, gairah, atau kesedihan, ingin mengejar aroma bunga, arus laut, atau awan."
  },
  AvgCommunicate_134117_Option_12 = {
    Text = "Seperti sihir kata-kata saja."
  },
  AvgCommunicate_134117_Option_3 = {
    Text = "Kedengarannya indah."
  },
  AvgCommunicate_134117_Option_7 = {
    Text = "Tidak apa-apa."
  },
  AvgCommunicate_134118_Content_1 = {
    Text = "Ternyata kamu memberikan sesuatu yang begitu berharga untuk Nona ini, kamu..."
  },
  AvgCommunicate_134118_Content_10 = {
    Text = "Tapi, membuat sebanyak itu bisa kamu habiskan? Sebelumnya ada koki yang mengadu bahwa kamu menghabiskan semua stok mentega dan keju, dan akulah yang mengeluarkan uang untuk mengganti persediaan dapur."
  },
  AvgCommunicate_134118_Content_11 = {
    Text = "Wah, siapa yang diam-diam mengadu di sini? Jangan sampai kutangkap dia!"
  },
  AvgCommunicate_134118_Content_12 = {
    Text = "Soal kue, urusan seorang lady jangan kamu campuri! Sebanyak apa pun yang kubuat, aku bisa menghabiskan semuanya!"
  },
  AvgCommunicate_134118_Content_13 = {
    Text = "Kalau tidak habis, kamu datang saja dan makan bersama!"
  },
  AvgCommunicate_134118_Content_14 = {
    Text = "A-aku juga harus makan? Aku bisa mati kekenyangan, lalu jadi gemuk di usia muda!"
  },
  AvgCommunicate_134118_Content_15 = {
    Text = "Jangan banyak omong, dari tadi bicara panjang lebar, belum menyebut soal hadiahmu. Nona ini akan bermurah hati menyisihkan satu bagian kue buatan tangan untukmu mulai sekarang."
  },
  AvgCommunicate_134118_Content_16 = {
    Text = "Bersyukurlah, ini adalah karya pembuat kue jenius yang orang lain ingin beli pun tak bisa!"
  },
  AvgCommunicate_134118_Content_17 = {
    Text = "Jadi... toko kue ini pada akhirnya tetap produksi sendiri, konsumsi sendiri ya!"
  },
  AvgCommunicate_134118_Content_2 = {
    Text = "Hmph, lumayan juga."
  },
  AvgCommunicate_134118_Content_3 = {
    Text = "Sekarang Nona ini bisa memutar sepuluh, tidak, seratus Voidwalker sekaligus seperti gasing! Tidak perlu lagi ada yang menyelamatkanku!"
  },
  AvgCommunicate_134118_Content_4 = {
    Text = "Nona Besar hebat!"
  },
  AvgCommunicate_134118_Content_5 = {
    Text = "Meskipun kehidupan sekarang sudah tidak perlu was-was lagi, tapi soal kekuatan, tentu saja semakin banyak semakin terasa aman."
  },
  AvgCommunicate_134118_Content_6 = {
    Text = "Orang yang tinjunya lebih besar tidak akan pernah rugi!"
  },
  AvgCommunicate_134118_Content_7 = {
    Text = "Tapi, kekuatan sehebat ini, sayang sekali kalau hanya dipakai untuk bekerja buat Messagger... Aha, ada ide!"
  },
  AvgCommunicate_134118_Content_8 = {
    Text = "Karena begitu banyak tentakel bisa bekerja secara mandiri, lebih baik aku buka toko kue sendiri saja. Dengan satu orang merangkap delapan posisi, bukankah aku bisa menikmati kebebasan kue kecil selamanya!"
  },
  AvgCommunicate_134118_Content_9 = {
    Text = "Bisa dipakai begitu juga?"
  },
  AvgCommunicate_134118_Option_14 = {
    Text = "Aku juga harus makan?"
  },
  AvgCommunicate_134118_Option_17 = {Text = "Jadi..."},
  AvgCommunicate_134118_Option_4 = {
    Text = "Murphy hebat!"
  },
  AvgCommunicate_134118_Option_9 = {
    Text = "Bisa dipakai begitu juga?"
  },
  AvgCommunicate_134119_Content_1 = {
    Text = "Hahahaha... Hahahahaha!"
  },
  AvgCommunicate_134119_Content_10 = {
    Text = "Di bawah kekuatan absolut, penaklukan hanyalah sebuah permainan panjang."
  },
  AvgCommunicate_134119_Content_11 = {
    Text = "Asal kamu senang..."
  },
  AvgCommunicate_134119_Content_12 = {
    Text = "Waktu akan membawakan kabar kemenanganku kepadamu. Saat itu tiba, sebagai pahlawan utama kerajaan baruku, aku akan menyisihkan tanah paling subur sebagai wilayah jajahanmu."
  },
  AvgCommunicate_134119_Content_13 = {
    Text = "Atau... kau lebih menyukai kota Londinium yang kelabu ini?"
  },
  AvgCommunicate_134119_Content_2 = {
    Text = "Jangan-jangan kamu dimabukkan oleh kekuatan dan tiba-tiba jadi gila?"
  },
  AvgCommunicate_134119_Content_3 = {
    Text = "Hmph, sebagai penyumbang kekuatan terbesarku, aku bisa memaafkan kekurangajaranmu yang kecil itu."
  },
  AvgCommunicate_134119_Content_4 = {
    Text = "Ah… saat yang telah lama kutunggu-tunggu, rasa manis yang begitu familiar, sensasi Darah yang menggelora!"
  },
  AvgCommunicate_134119_Content_5 = {
    Text = "Sekarang aku bisa dengan mudah mengangkat gunung es dan membelah jurang laut."
  },
  AvgCommunicate_134119_Content_6 = {
    Text = "Kepala suku mana pun, pejuang terkuat Pengarung Laut sekalipun, tak akan mampu bertahan satu ronde melawanku. Wanita gila itu pun tak bisa lagi menekanku."
  },
  AvgCommunicate_134119_Content_7 = {
    Text = "Segera, aku akan menaklukkan lautan, lalu menaklukkan semua daratan! Hahahahaha!"
  },
  AvgCommunicate_134119_Content_8 = {
    Text = "......Percaya diri itu bagus, tapi jangan terlalu narsis! Ini sudah level delusi, tahu!"
  },
  AvgCommunicate_134119_Content_9 = {
    Text = "Kamu tidak tahu apa-apa tentang kekuatan raksasa, nak."
  },
  AvgCommunicate_134119_Option_11 = {
    Text = "Asal kamu senang..."
  },
  AvgCommunicate_134119_Option_2 = {
    Text = "Kamu kerasukan?"
  },
  AvgCommunicate_134120_Content_1 = {
    Text = "Nyanyianku, sudah berbeda dari sebelumnya."
  },
  AvgCommunicate_134120_Content_10 = {
    Text = "Mm, pasti akan kulakukan!"
  },
  AvgCommunicate_134120_Content_11 = {
    Text = "Oh iya, Penjaga Rahasia, berkat nasihatmu sebelumnya, aku menerima kerja sama dengan perusahaan musik. Sekarang album pertamaku sudah resmi dirilis, dan katanya penjualannya sangat bagus di pasaran."
  },
  AvgCommunicate_134120_Content_12 = {
    Text = "Itu hal yang bagus! Selamat, selamat! Berapa banyak yang terjual?"
  },
  AvgCommunicate_134120_Content_13 = {
    Text = "Sepertinya... terjual seratus ribu keping. Tapi aku juga tidak membutuhkan mata uang planet ini. Karena tidak ada cara lain untuk membalas kebaikanmu, bagaimana kalau pendapatan dari album ini kuberikan saja kepadamu?"
  },
  AvgCommunicate_134120_Content_14 = {Text = "Horeee!!!"},
  AvgCommunicate_134120_Content_2 = {
    Text = "Penjaga Rahasia, setelah kamu membantuku memahami hukum terakhir, nyanyianku sepertinya beresonansi secara menakjubkan dengan Aether."
  },
  AvgCommunicate_134120_Content_3 = {
    Text = "Kedengarannya kamu jadi lebih kuat, Feint pasti juga akan senang!"
  },
  AvgCommunicate_134120_Content_4 = {
    Text = "Bagaimana aku bisa membalas kebaikanmu, Penjaga Rahasia? Bisa bertemu kembali dengan kakak saja sudah merupakan kebahagiaan yang dulu tak pernah bisa kuraih, dan kamu bahkan memberiku harta seindah ini."
  },
  AvgCommunicate_134120_Content_5 = {
    Text = "Sekarang aku tak punya apa-apa, dan aku juga bukan lagi bintang yang dipuja orang. Satu-satunya yang bisa kuberikan sebagai balasan adalah... izinkan aku menyanyikan sebuah lagu untukmu."
  },
  AvgCommunicate_134120_Content_6 = {
    Text = "Tinkter, kamu sudah menemukan jalanmu sendiri. Jika kamu bersedia mewujudkan keinginanku..."
  },
  AvgCommunicate_134120_Content_7 = {
    Text = "Bernyanyilah dengan bebas, untuk dirimu sendiri, dan juga untukku."
  },
  AvgCommunicate_134120_Content_8 = {
    Text = "Bukan untuk menyenangkan siapa pun, bukan untuk memenuhi tuntutan siapa pun, tapi hanya untuk kebahagiaanmu sendiri."
  },
  AvgCommunicate_134120_Content_9 = {
    Text = "Kebahagiaanku... sendiri."
  },
  AvgCommunicate_134120_Option_12 = {
    Text = "Itu hal yang bagus."
  },
  AvgCommunicate_134120_Option_14 = {Text = "?!!"},
  AvgCommunicate_134120_Option_3 = {
    Text = "Bagus sekali."
  },
  AvgCommunicate_134120_Option_6 = {
    Text = "Pernahkah kamu berpikir"
  },
  AvgCommunicate_134180_Content_1 = {
    Text = "Angin mengembangkan layar, burung-burung terbang berbaris di sisi kita……"
  },
  AvgCommunicate_134180_Content_10 = {
    Text = "Aku ingin, bersamamu, bersama Kapten, bersama semua orang, terus berlayar di lautan selamanya."
  },
  AvgCommunicate_134180_Content_11 = {
    Text = "Bersama mengalami hari cerah, hari hujan, bersama berlayar ke berbagai pelabuhan, berlabuh di negara-negara yang berbeda."
  },
  AvgCommunicate_134180_Content_12 = {
    Text = "Bersama memancing, memanggang ikan……hmm, kita juga bisa mengambil kerang dari lambung kapal, lalu merebusnya dengan anggur merah."
  },
  AvgCommunicate_134180_Content_13 = {
    Text = "Ayo pergi saat liburan berikutnya."
  },
  AvgCommunicate_134180_Content_14 = {
    Text = "Aku sudah lama memikirkannya, berlayar……adalah saat aku paling bahagia."
  },
  AvgCommunicate_134180_Content_15 = {
    Text = "Aku akan membuat semua orang menghindari setiap badai, dan terus berlayar dengan bahagia bersama."
  },
  AvgCommunicate_134180_Content_16 = {
    Text = "Kedengarannya memang sangat indah, tapi kalau terus-terusan berlayar tanpa henti, selain Yang Terbangkitkan dari Ranah Laut Dalam, semua orang pasti akan mabuk laut!"
  },
  AvgCommunicate_134180_Content_2 = {
    Text = "Aku melihat haluan kapal membelah ombak, aku mendengar para pelaut menyanyikan lagu laut, aku merasakan bisikan angin dan hujan."
  },
  AvgCommunicate_134180_Content_3 = {
    Text = "Aku bisa melihat lebih jelas sekarang, jalur menuju perairan yang cerah dan tenang itu."
  },
  AvgCommunicate_134180_Content_4 = {
    Text = "Selamat untukmu! Celeste!"
  },
  AvgCommunicate_134180_Content_5 = {
    Text = "Sekarang, mungkin aku benar-benar bisa mewujudkan harapan semua orang, membuat kapal-kapal yang kulindungi tiba dengan selamat di seberang."
  },
  AvgCommunicate_134180_Content_6 = {
    Text = "Aku tidak akan mengecewakan semua orang lagi."
  },
  AvgCommunicate_134180_Content_7 = {
    Text = "Lalu, bagaimana dengan keinginanmu? Sudahkah kamu memikirkan keinginanmu sendiri?"
  },
  AvgCommunicate_134180_Content_8 = {
    Text = "Keinginanku……"
  },
  AvgCommunicate_134180_Content_9 = {
    Text = "Aku sudah memikirkannya."
  },
  AvgCommunicate_134180_Option_13 = {
    Text = "Ayo pergi saat liburan berikutnya."
  },
  AvgCommunicate_134180_Option_16 = {
    Text = "Kedengarannya sangat indah."
  },
  AvgCommunicate_134180_Option_4 = {
    Text = "Selamat untukmu"
  },
  AvgCommunicate_134180_Option_7 = {
    Text = "Lalu bagaimana denganmu?"
  },
  AvgCommunicate_134181_Content_1 = {
    Text = "Ah……panggilan lautan, begitu lembut, begitu hangat."
  },
  AvgCommunicate_134181_Content_10 = {
    Text = "Apakah perilaku kasar Rogers yang meninggalkan trauma padamu, atau kamu menganggapku sebagai seniman yang miskin ide dan malas seperti itu?"
  },
  AvgCommunicate_134181_Content_11 = {
    Text = "Mengasah keterampilan berkarya tidak bisa mengambil jalan pintas apa pun. Patung-patungku, tentu saja semuanya dipahat oleh tanganku sendiri, satu pahatan demi satu pahatan."
  },
  AvgCommunicate_134181_Content_12 = {
    Text = "Tenang saja, tidak akan menggunakan sehelai rambutmu pun."
  },
  AvgCommunicate_134181_Content_13 = {
    Text = "Haha……mungkin karena keterampilan memahatmu terlalu hebat. Setiap kali melihat karyamu, aku selalu merasa seperti melihat orang hidup."
  },
  AvgCommunicate_134181_Content_14 = {
    Text = "Hmm……kalau begitu, sekarang setelah kekuatanku mencapai puncaknya, mungkin aku benar-benar bisa membuat patung yang bisa hidup lho."
  },
  AvgCommunicate_134181_Content_15 = {
    Text = "Di saat larut malam yang sunyi, di luar jangkauan pandanganmu, bola mata patung itu akan perlahan berputar, sudut bibirnya akan sedikit terangkat……"
  },
  AvgCommunicate_134181_Content_16 = {
    Text = "Setelah aku menyelesaikan karya terbaruku, aku akan mengirim satu patung untuk diletakkan di samping tempat tidurmu, mengawasimu untukku. Bagaimana?"
  },
  AvgCommunicate_134181_Content_17 = {
    Text = "Aku tidak akan berani tidur seumur hidupku!!!"
  },
  AvgCommunicate_134181_Content_18 = {
    Text = "Aku cuma bercanda."
  },
  AvgCommunicate_134181_Content_19 = {
    Text = "Ternyata, kamu benar-benar takut dengan cerita hantu sesederhana itu, sungguh menggemaskan."
  },
  AvgCommunicate_134181_Content_2 = {
    Text = "Kamu pasti juga mendengarnya, kan?"
  },
  AvgCommunicate_134181_Content_3 = {
    Text = "Lautan mengundang kita, mereka menunggu kita……untuk pergi bersama ke istana putih bersih di dasar laut."
  },
  AvgCommunicate_134181_Content_4 = {
    Text = "Siapa? Sepertinya telingaku sudah tuli, aku tidak mendengar apa-apa."
  },
  AvgCommunicate_134181_Content_5 = {
    Text = "Kalau begitu, ini adalah ciuman Muse yang hanya milikku seorang. Keindahan lautan kini telah menyatu dengan jiwaku."
  },
  AvgCommunicate_134181_Content_6 = {
    Text = "Kamu selalu membawa lebih banyak inspirasi untuk karyaku. Aku benar-benar semakin menyukaimu."
  },
  AvgCommunicate_134181_Content_7 = {
    Text = "Mau mempertimbangkan untuk menjadi asisten tetapku? Kamu tidak perlu melakukan apa-apa, cukup datang ke studioku setiap hari untuk duduk sebentar, minum secangkir teh, dan mengobrol."
  },
  AvgCommunicate_134181_Content_8 = {
    Text = "Meskipun aku sangat tersanjung dengan kebaikanmu, tapi……apakah aku akan bangun tidur dan mendapati diriku sudah berubah menjadi patung batu?"
  },
  AvgCommunicate_134181_Content_9 = {
    Text = "Hehe, jadi begitu caramu memandangku?"
  },
  AvgCommunicate_134181_Option_13 = {
    Text = "Keahlianmu terlalu hebat."
  },
  AvgCommunicate_134181_Option_17 = {Text = "Jangan!!!"},
  AvgCommunicate_134181_Option_4 = {
    Text = "Aku tidak mendengarnya."
  },
  AvgCommunicate_134181_Option_8 = {
    Text = "Apa aku akan dijadikan patung?"
  },
  AvgCommunicate_134187_Content_1 = {
    Text = "Anak anjing, bagaimana kabarmu belakangan ini?"
  },
  AvgCommunicate_134187_Content_10 = {
    Text = "Jangan bertindak gegabah, bagaimanapun juga, Black Pool akan mengekangmu dengan erat."
  },
  AvgCommunicate_134187_Content_11 = {
    Text = "Kalian sama sekali tidak tahu kekuatan seperti apa yang bisa diberikan pengetahuan kepadaku."
  },
  AvgCommunicate_134187_Content_12 = {
    Text = "Aku sangat puas dengan hadiah ini. Jadi, murid tersayangku, aku juga ingin memberimu sebuah hadiah."
  },
  AvgCommunicate_134187_Content_13 = {Text = "...?"},
  AvgCommunicate_134187_Content_14 = {
    Text = "Terkalah, tebak sejauh mana aku bisa melangkah sekarang."
  },
  AvgCommunicate_134187_Content_15 = {
    Text = "Menebak apakah cara pembatasan kalian yang arogan itu benar-benar bisa berhasil atau tidak."
  },
  AvgCommunicate_134187_Content_16 = {
    Text = "Menebak apakah kebenaran yang telah kuintip itu, setelah aku memperoleh kekuatan ini, akan benar-benar tertanam dalam kognisi kalian semua."
  },
  AvgCommunicate_134187_Content_17 = {
    Text = "Ini adalah PR terpenting setelah pelajaran lho. Segera, segera, aku akan datang untuk memeriksanya sendiri."
  },
  AvgCommunicate_134187_Content_2 = {
    Text = "Nyalimu benar-benar besar sampai membuatku terkejut, berani sekali mengirimkan hadiah sekelas ini."
  },
  AvgCommunicate_134187_Content_3 = {
    Text = "Kalau kubilang ada kecelakaan serius saat mengangkut material langka, kau percaya tidak……"
  },
  AvgCommunicate_134187_Content_5 = {
    Text = "Kau meremehkanku, dan juga meremehkan Misage."
  },
  AvgCommunicate_134187_Content_6 = {
    Text = "Kami bersedia membiarkan setiap Awakened menyentuh batas itu, karena kami akan mencoba segala cara untuk menghentikan kehancuran."
  },
  AvgCommunicate_134187_Content_7 = {
    Text = "Inilah……perbedaan terbesar antara Guru Dor itu, serta kami, dengan dirimu. Meskipun kehancuran sudah ditakdirkan, kami tidak akan tunduk padanya."
  },
  AvgCommunicate_134187_Content_8 = {
    Text = "Haah, kenapa aku tidak menyadari sebelumnya, sistem pendidikan Misage ternyata bisa menghasilkan orang bodoh."
  },
  AvgCommunicate_134187_Content_9 = {
    Text = "Untungnya, dia bodoh sampai menyedihkan, sampai-sampai sulit menahan diri untuk tidak merasa sayang."
  },
  AvgCommunicate_134187_Option_13 = {Text = "...?"},
  AvgCommunicate_134187_Option_3 = {
    Text = "Itu kecelakaan."
  },
  AvgCommunicate_134187_Option_5 = {
    Text = "Itu tanda perhatian."
  },
  AvgCommunicate_134188_Content_1 = {
    Text = "Hukum, hebat sekali! Duar—! Bum—! Blaar—!"
  },
  AvgCommunicate_134188_Content_11 = {
    Text = "Kalau begitu, biaya perbaikan sekolah bulan ini seharusnya bisa turun drastis……"
  },
  AvgCommunicate_134188_Content_12 = {
    Text = "PR jahat, muncul, Moss, hajar!"
  },
  AvgCommunicate_134188_Content_13 = {
    Text = "Tidak, tidak boleh menganggap PR juga sebagai musuh!"
  },
  AvgCommunicate_134188_Content_14 = {
    Text = "Moss, Moss?"
  },
  AvgCommunicate_134188_Content_16 = {
    Text = "Penjaga Rahasia, aku Nodira. Tenang saja, Moss sudah ditahan, PR dan ruang kelas semuanya aman."
  },
  AvgCommunicate_134188_Content_17 = {
    Text = "Syukurlah……"
  },
  AvgCommunicate_134188_Content_18 = {
    Text = "Nodira, aku, Misage, dan Moss akan selalu membutuhkanmu selamanya."
  },
  AvgCommunicate_134188_Content_2 = {
    Text = "Ingat baik-baik Peraturan Missaeger edisi khusus Morth pasal pertama, dalam kondisi apa pun tidak diperbolehkan mengarahkan senjata pemusnah apa pun ke siapa pun di Missaeger."
  },
  AvgCommunicate_134188_Content_5 = {
    Text = "%player%, tenang, Morth, kendali, bisa!"
  },
  AvgCommunicate_134188_Content_6 = {
    Text = "Morth, tahan, pusaran."
  },
  AvgCommunicate_134188_Content_7 = {
    Text = "Morth, teman, peluk."
  },
  AvgCommunicate_134188_Content_8 = {
    Text = "Morth, musuh, duar—! Bum—! Blaar—!"
  },
  AvgCommunicate_134188_Option_2 = {
    Text = "Keselamatan yang utama."
  },
  AvgCommunicate_134189_Content_1 = {
    Text = "Kita adalah rekan seperjuangan, jadi, aku tidak akan mengucapkan terima kasih."
  },
  AvgCommunicate_134189_Content_2 = {
    Text = "Senjataku sudah diasah hingga setajam mungkin, cukup tajam untuk menyayat tenggorokan seorang pemilik budak dalam sekejap."
  },
  AvgCommunicate_134189_Content_3 = {
    Text = "Makna perlawanan, makna pembalasan, makna pertempuran, hingga kini aku masih terus merenungkannya."
  },
  AvgCommunicate_134189_Content_4 = {
    Text = "Mungkin aku akan terus merenungkannya sepanjang hidupku, hingga hari di mana aku tak lagi mampu berdiri."
  },
  AvgCommunicate_134189_Content_5 = {
    Text = "Setidaknya, aku tidak akan lagi merasa bimbang."
  },
  AvgCommunicate_134189_Content_6 = {
    Text = "Untuk rekan seperjuanganku."
  },
  AvgCommunicate_134189_Content_7 = {
    Text = "Untuk rekan seperjuangan, kalianlah yang membebaskanku, yang membuatku melangkah maju dengan teguh."
  },
  AvgCommunicate_134189_Content_8 = {
    Text = "Saat kalian membutuhkanku, aku akan selalu mempercayakan punggungku dan bertempur berdampingan dengan kalian."
  },
  AvgCommunicate_134189_Content_9 = {
    Text = "Mari terus bertempur bersama, demi hal-hal yang layak dibalaskan, dan juga demi menikmati momen pertempuran yang membebaskan."
  },
  AvgCommunicate_134189_Option_6 = {
    Text = "Untuk rekan seperjuangan."
  },
  AvgCommunicate_134201_Content_1 = {
    Text = "Keeper, saya sudah mengajukan permohonan ke bagian akademik, saya akan absen dari latihan selama tiga hari ke depan."
  },
  AvgCommunicate_134201_Content_10 = {
    Text = "Tapi, setelah saya melampaui batas itu, saya akhirnya mengerti."
  },
  AvgCommunicate_134201_Content_11 = {Text = "Apa?"},
  AvgCommunicate_134201_Content_13 = {
    Text = "Akulah pedang sang perintis. Justru karena aku selalu berjalan di jalan ini, aku bisa mengenal kalian semua, mengenalmu."
  },
  AvgCommunicate_134201_Content_14 = {
    Text = "Tujuan yang kukejar membuatku tak pernah sendirian. Mungkin kita tak akan pernah sampai, tapi selama kita terus bertahan, aku bisa membuat dunia yang ideal dan adil itu semakin dekat, sedikit lagi, sedikit lagi."
  },
  AvgCommunicate_134201_Content_15 = {
    Text = "Dengan diriku sebagai pedang, hingga mencapai utopia di mana semua orang bisa hidup dalam cahaya."
  },
  AvgCommunicate_134201_Content_16 = {
    Text = "Visi yang begitu agung, Instruktur Elva! Saya akan mendukungmu tanpa syarat!"
  },
  AvgCommunicate_134201_Content_17 = {
    Text = "Bagus sekali. Kalau begitu, saya akan menggunakan tiga hari ini untuk mengembangkan program latihan yang lebih ketat dan menantang."
  },
  AvgCommunicate_134201_Content_18 = {
    Text = "Kamu akan menjadi orang pertama yang mencobanya. Tenang saja, saya akan menemani latihan sepanjang waktu, meningkatkan kemampuan bersama semua orang."
  },
  AvgCommunicate_134201_Content_19 = {
    Text = "Tunggu, soal ini kurasa kita bisa diskusikan lagi..."
  },
  AvgCommunicate_134201_Content_2 = {
    Text = "Apakah ada masalah dengan materinya? Kamu baik-baik saja? Perlu bantuan?"
  },
  AvgCommunicate_134201_Content_3 = {
    Text = "Tidak, justru sebaliknya, semuanya berjalan lancar. Saya mengalami peningkatan yang berbeda dari sebelumnya."
  },
  AvgCommunicate_134201_Content_4 = {
    Text = "Saya agak kurang mengerti..."
  },
  AvgCommunicate_134201_Content_5 = {
    Text = "Saya... setelah meninggalkan militer, pernah terombang-ambing untuk waktu yang sangat lama."
  },
  AvgCommunicate_134201_Content_6 = {
    Text = "Saya tidak tahu untuk apa saya harus bertarung. Satu-satunya hal yang bisa saya ikuti adalah keadilan yang bahkan saya sendiri tidak tahu apakah pada akhirnya bisa tercapai."
  },
  AvgCommunicate_134201_Content_7 = {
    Text = "Saya berharap bisa berdiri di pihak yang lemah, di pihak yang tak mampu bersuara, di pihak yang diperlakukan tidak adil."
  },
  AvgCommunicate_134201_Content_8 = {
    Text = "Tapi saya juga sangat sadar, tidak peduli seberapa kuat saya menjadi, selalu ada hal-hal yang di luar kemampuan saya. Seperti meskipun waktu bisa diputar kembali, saya tetap tidak bisa mencegah kehancuran Yalan."
  },
  AvgCommunicate_134201_Content_9 = {
    Text = "Instruktur Elva..."
  },
  AvgCommunicate_134201_Option_2 = {Text = "Ada apa?"},
  AvgCommunicate_134202_Content_1 = {
    Text = "Terima kasih sudah menyerahkan sesuatu yang begitu berharga kepadaku, %player%."
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "Kurasa ini mungkin memberitahuku bahwa, selain meninggalkan jejak dalam ingatan, dunia juga bisa dijelajahi dengan langkah kaki."
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "Jika tak bisa menyimpannya, maka terus, terus melangkah maju. Dunia dan kalian semua akan mengingatnya untukku."
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "Bahkan aku pun jadi ikut bersemangat..."
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "Aku akan menjadi penjelajah terhebat, ahli mekanik paling handal. %player%, aku ingin secara resmi mengundangmu."
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "Saat tiba hari di mana semuanya telah terselesaikan, mari bertualang bersamaku, menciptakan lebih banyak kenangan berharga di dunia ini."
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "Mungkin hari itu masih jauh, atau mungkin sudah besok."
  },
  AvgCommunicate_134202_Content_16 = {
    Text = "Undangan ini berlaku selamanya, aku pasti akan mengingatnya."
  },
  AvgCommunicate_134202_Content_2 = {
    Text = "Aku butuh waktu sangat lama untuk mencernanya, dan sekarang... semua itu membuatku merasa seolah aku kembali menjadi utuh."
  },
  AvgCommunicate_134202_Content_3 = {
    Text = "Jadi, sekarang kamu tidak akan melupakan hal-hal lagi?"
  },
  AvgCommunicate_134202_Content_4 = {
    Text = "Hmm, coba kuingat-ingat..."
  },
  AvgCommunicate_134202_Content_5 = {
    Text = "Haha, tetap tidak bisa mengingat!"
  },
  AvgCommunicate_134202_Content_6 = {
    Text = "Kenapa nadanya bangga begitu!"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "Karena, meskipun mungkin masih akan melupakan banyak hal, baik dulu maupun sekarang, %player% akan selalu mengingatkanku dan membantuku mengingat."
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "Siapa aku, di mana aku, apa yang harus kulakukan, orang-orang yang paling kupercaya akan memberitahuku."
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "Mungkin karena itulah, setelah memahami hukum tertinggi, meskipun daya ingatku tidak membaik, aku merasa seluruh dunia seperti peta yang luas, terbentang di hadapanku."
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "Daya ingatmu jadi lebih baik?"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "Dulu aku mengira, hanya dengan berperan sebagai penonton, aku bisa merasakan kesenangan dari hal yang tak terduga."
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "Meskipun aku tidak sepenuhnya mengerti… tapi kedengarannya itu hal yang baik?"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "Sejak aku meninggalkan pintu gerbang itu, ini adalah keberuntungan terbesar yang pernah kujumpai."
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "Penjaga Rahasia, ini adalah kejutan tak terduga yang Anda berikan kepadaku."
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "Takdir tidak pernah mengecewakan mereka yang dermawan."
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "Aku tak bisa menyentuh benang takdirmu, tetapi saat kau berjuang melawan takdir, roda pintalkku akan selalu berputar untukmu."
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "Sudah sangat lama... sangat lama, aku tidak merasakan perasaan seperti ini..."
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "Rasa seperti apa?"
  },
  AvgCommunicate_134208_Content_4 = {Text = "Baru."},
  AvgCommunicate_134208_Content_5 = {
    Text = "Kuncup bunga tumbuh dalam keheningan, kata-kata terjalin di atas kertas, awan mengalir lembut tertiup angin…"
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "Dan tentu saja manusia— tangan yang terentang, air mata yang jatuh, detak jantung yang bagai genderang perang atau rintik hujan…"
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "Aku melihat lebih banyak dari sebelumnya, tetapi pandanganku kini lebih rendah dari sebelumnya."
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "Pandanganku tak lagi terpaku di langit, Penjaga Rahasia. Ia telah turun, mendarat di setiap jalanan, di sisi setiap pejalan kaki."
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "Diriku yang sekarang tidak perlu lagi berpura-pura. Aku bisa benar-benar hadir, sebagai seorang individu."
  },
  AvgCommunicate_134208_Option_10 = {
    Text = "Kedengarannya hal yang baik?"
  },
  AvgCommunicate_134208_Option_3 = {
    Text = "Rasa seperti apa?"
  },
  AvgCommunicate_134242_Content_1 = {
    Text = "Teks sementara"
  },
  AvgCommunicate_134245_Content_1 = {
    Text = "Rasanya ini barang yang sangat berharga, tidak apa-apa diberikan ke Saya?"
  },
  AvgCommunicate_134245_Content_12 = {
    Text = "Ternyata dunia ini juga memiliki sisi yang indah ya, meskipun agak berbeda dari dunia yang ada dalam ingatanku."
  },
  AvgCommunicate_134245_Content_13 = {
    Text = "Cara pembentukannya, logika pergerakannya, Saya sudah sepenuhnya bisa memahaminya."
  },
  AvgCommunicate_134245_Content_14 = {
    Text = "Jadi, untuk Tulis Ulang dunia ini menjadi dunia yang ada dalam ingatanku, mungkin sekarang aku bisa melakukannya dengan sangat mudah."
  },
  AvgCommunicate_134245_Content_16 = {
    Text = "Meskipun tahu kamu bercanda, tolong jangan pernah melakukan hal seperti itu."
  },
  AvgCommunicate_134245_Content_18 = {
    Text = "Kenapa tiba-tiba diam, itu bercanda kan? Jangan diam di saat seperti ini!"
  },
  AvgCommunicate_134245_Content_19 = {
    Text = "Itu, tadi aku hanya keluar sebentar, mengamati semua orang dari sudut pandang baru..."
  },
  AvgCommunicate_134245_Content_2 = {
    Text = "Aku percaya pada Saya, jadi tidak apa-apa."
  },
  AvgCommunicate_134245_Content_20 = {
    Text = "Saat orang-orang yang kukenal dan memperlakukan Saya dengan baik masih hidup dengan baik, rasanya seperti ini."
  },
  AvgCommunicate_134245_Content_21 = {
    Text = "Tidak bisa bilang di mana yang tidak beres tapi entah kenapa merasa pasti ada sesuatu yang tidak beres."
  },
  AvgCommunicate_134245_Content_22 = {
    Text = "Dan sekarang di wajahmu pasti muncul lagi Ekspresi nakal yang berhasil itu!"
  },
  AvgCommunicate_134245_Content_23 = {
    Text = "Jangan khawatir, akan hidup berdampingan dengan baik bersama semua orang di dunia ini."
  },
  AvgCommunicate_134245_Content_24 = {
    Text = "Hmm… tapi dunia yang ada dalam ingatan Saya mungkin lebih menarik. Bagaimana kalau kita semua pergi melihatnya bersama? Sekarang seharusnya bisa dilakukan lho!"
  },
  AvgCommunicate_134245_Content_25 = {
    Text = "Kalimat itu justru lebih menakutkan!"
  },
  AvgCommunicate_134245_Content_3 = {
    Text = "Jika bisa membantumu memahami dunia ini dengan lebih baik, penelitian tentang \"bagaimana menghentikan Pelarutan\" juga pasti akan sangat terbantu."
  },
  AvgCommunicate_134245_Content_4 = {
    Text = "Bagaimanapun, kamu memang sangat hebat dalam hal belajar dan meneliti..."
  },
  AvgCommunicate_134245_Content_5 = {
    Text = "Sebenarnya ini semacam kebetulan dalam pasokan... tapi sekarang menyesal juga sudah terlambat kan?"
  },
  AvgCommunicate_134245_Content_6 = {
    Text = "Eh? Kalau begitu apakah perlu dikembalikan, agak bingung juga."
  },
  AvgCommunicate_134245_Content_7 = {
    Text = "Eh? Bisa dikembalikan ya."
  },
  AvgCommunicate_134245_Content_8 = {
    Text = "Hmm, biarkan Saya berpikir dulu..."
  },
  AvgCommunicate_134245_Content_9 = {
    Text = "Jawabannya adalah — tidak mau."
  },
  AvgCommunicate_134245_Option_2 = {
    Text = "Tidak masalah"
  },
  AvgCommunicate_134245_Option_5 = {Text = "Kebetulan"},
  AvgCommunicate_134246_Content_1 = {
    Text = "Caraboo yang terkasih, tersayang, dan luar biasa~"
  },
  AvgCommunicate_134246_Content_10 = {
    Text = "Biarkan aku periksa."
  },
  AvgCommunicate_134246_Content_11 = {
    Text = "Biarkan aku periksa data fluktuasi Indeks gnostik-mu."
  },
  AvgCommunicate_134246_Content_12 = {
    Text = "Luar biasa, kali ini kamu benar-benar tidak berbohong."
  },
  AvgCommunicate_134246_Content_13 = {
    Text = "Hehe, sekarang percaya pada Caraboo kecil yang malang kan~"
  },
  AvgCommunicate_134246_Content_14 = {
    Text = "Demi Caraboo bisa menghasilkan keuntungan berlipat ganda bagi Tuan di masa depan, mohon Tuan terus berinvestasi besar-besaran padaku!"
  },
  AvgCommunicate_134246_Content_15 = {
    Text = "Asalkan ada delapan lagi, tidak, lima Mencerahkan saja! Aku pasti bisa membuat Anda kagum lagi!"
  },
  AvgCommunicate_134246_Content_16 = {
    Text = "Tidak mungkin."
  },
  AvgCommunicate_134246_Content_17 = {
    Text = "Jangan bohong."
  },
  AvgCommunicate_134246_Content_18 = {
    Text = "Profesor Doll pernah memberitahuku, eksplorasi Mencerahkan sudah mencapai puncaknya, dalam seratus tahun pun sulit untuk ada terobosan lagi."
  },
  AvgCommunicate_134246_Content_19 = {
    Text = "Setelah memahami hukum tertinggi, seorang Awakener tidak dapat lagi memperdalam kepribadiannya."
  },
  AvgCommunicate_134246_Content_2 = {
    Text = "Tiba-tiba begitu manis, ada apa lagi yang kamu butuhkan?"
  },
  AvgCommunicate_134246_Content_21 = {
    Text = "Haha, pasti aku tidak sengaja membuat kesalahan di suatu tempat!"
  },
  AvgCommunicate_134246_Content_22 = {
    Text = "Tolong putar balik memori percakapan ke enam baris sebelumnya, semoga harimu menyenangkan!"
  },
  AvgCommunicate_134246_Content_3 = {
    Text = "Aduh, lihat apa yang Anda katakan, memangnya saya orang yang tidak pernah datang tanpa keperluan."
  },
  AvgCommunicate_134246_Content_4 = {
    Text = "Kamu memang seperti itu..."
  },
  AvgCommunicate_134246_Content_5 = {
    Text = "Huhu, aku sangat sedih, Tuan salah paham padaku terlalu dalam."
  },
  AvgCommunicate_134246_Content_6 = {
    Text = "Kedatanganku kali ini, justru untuk menyampaikan kabar baik kepada Anda!"
  },
  AvgCommunicate_134246_Content_7 = {
    Text = "Investasi Anda telah menghasilkan hasil yang super, super luar biasa."
  },
  AvgCommunicate_134246_Content_8 = {
    Text = "Lihat, aku sekarang sudah berbeda dari dulu, benar-benar berubah total~"
  },
  AvgCommunicate_134246_Content_9 = {Text = "Benarkah?"},
  AvgCommunicate_134246_Option_10 = {
    Text = "Biarkan aku periksa"
  },
  AvgCommunicate_134246_Option_16 = {
    Text = "Tidak mungkin"
  },
  AvgCommunicate_134246_Option_17 = {
    Text = "Jangan bohong"
  },
  AvgCommunicate_134246_Option_9 = {Text = "Benarkah?"},
  AvgCommunicate_134247_Content_1 = {
    Text = "Teks sementara"
  },
  AvgCommunicate_134249_Content_1 = {
    Text = "Penjaga Rahasia…"
  },
  AvgCommunicate_134249_Content_10 = {
    Text = "Uuu…… perasaan itu datang lagi. Tiba-tiba aku merasa panas, dan haus. Di perut, di dalam perutku,"
  },
  AvgCommunicate_134249_Content_11 = {
    Text = "Penjaga Rahasia, apakah aku sakit? Perutku terasa lembek, jantungku juga terasa lembek, semuanya terasa lembek, aku tidak bisa membedakan, rasanya seperti mau meleleh……"
  },
  AvgCommunicate_134249_Content_12 = {
    Text = "Tarik napas dalam-dalam, Rheya, kamu tidak akan meleleh."
  },
  AvgCommunicate_134249_Content_13 = {
    Text = "Ini adalah reaksi normal manusia dalam hubungan intim, tidak perlu minum obat…… juga tidak perlu mengambil cambuk!"
  },
  AvgCommunicate_134249_Content_14 = {
    Text = "Eh? Cambuk juga tidak perlu? Kecewa sekali."
  },
  AvgCommunicate_134249_Content_16 = {
    Text = "……Ehm, kalau kamu benar-benar membutuhkannya, mungkin pergi cari Pandiya……"
  },
  AvgCommunicate_134249_Content_17 = {Text = "Hehe."},
  AvgCommunicate_134249_Content_18 = {
    Text = "Penjaga Rahasia, mulai sekarang aku akan berusaha untuk tidak berjongkok di depan pintu Anda lagi."
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "Tapi…… bisakah Anda sesekali meninggalkan satu pintu terbuka untukku di malam hari? Jendela juga boleh."
  },
  AvgCommunicate_134249_Content_2 = {
    Text = "Daging dan darah kakak semakin menyatu dengan tubuhku dibanding sebelumnya. Mereka bernapas dengan tenang di bawah kulit, tidak lagi terus-terusan berteriak ingin merobek tubuhku."
  },
  AvgCommunicate_134249_Content_20 = {
    Text = "Aku tidak akan masuk, hanya dengan mengetahui ada jalan yang bisa menuju ke Anda kapan saja, aku bisa tidur lebih tenang."
  },
  AvgCommunicate_134249_Content_3 = {
    Text = "Rasa haus akan darah juga tidak lagi semenyakitkan dulu. Dulu rasanya seperti ada sesuatu yang tersangkut di tenggorokan, kalau tidak minum akan tercekik. Sekarang sepertinya... dia mau menungguku sebentar."
  },
  AvgCommunicate_134249_Content_4 = {
    Text = "Itu berita yang sangat bagus."
  },
  AvgCommunicate_134249_Content_5 = {
    Text = "Malam di sekolah sangat sunyi. Air mancur bergemericik."
  },
  AvgCommunicate_134249_Content_6 = {
    Text = "Penjaga Rahasia, Anda memberiku begitu banyak harta berharga, apakah aku layak?"
  },
  AvgCommunicate_134249_Content_7 = {
    Text = "Tentu saja layak."
  },
  AvgCommunicate_134249_Content_8 = {
    Text = "...Anda selalu menjawab dengan sangat cepat."
  },
  AvgCommunicate_134249_Content_9 = {
    Text = "Rheya, kamu sudah banyak membantu kami, ini sudah seharusnya kulakukan."
  },
  AvgCommunicate_134250_Content_1 = {
    Text = "Kau tidak tahu akhir dari memelihara seekor binatang buas?"
  },
  AvgCommunicate_134250_Content_10 = {
    Text = "Aku sering berpikir, apakah kamu benar-benar seperti yang terlihat di permukaan, atau..."
  },
  AvgCommunicate_134250_Content_11 = {
    Text = "Sebenarnya kamu selama ini berakting, sama seperti para pemilik budak itu."
  },
  AvgCommunicate_134250_Content_12 = {
    Text = "Menurutmu? Aku tidak pandai berakting, juga tidak pandai berbohong."
  },
  AvgCommunicate_134250_Content_13 = {
    Text = "Kamu bisa mengikuti perasaanmu sendiri. Aku tidak akan membujukmu, juga tidak akan memaksamu melakukan apa pun."
  },
  AvgCommunicate_134250_Content_14 = {
    Text = "Seperti yang dirimu yang lain pernah katakan, kita adalah teman, adalah rekan seperjuangan."
  },
  AvgCommunicate_134250_Content_15 = {
    Text = "Tch, jangan samakan aku dengan si lemah itu."
  },
  AvgCommunicate_134250_Content_16 = {
    Text = "Aku sudah muak dengan pengkhianatan, aku sama sekali tidak butuh teman."
  },
  AvgCommunicate_134250_Content_17 = {
    Text = "Lagipula, aku juga tidak menginginkan janji apa pun darimu."
  },
  AvgCommunicate_134250_Content_18 = {
    Text = "Kamu cukup memberiku lebih banyak kekuatan saja."
  },
  AvgCommunicate_134250_Content_19 = {
    Text = "Dan aku, akan membantumu membalas dendam kepada musuh-musuhmu."
  },
  AvgCommunicate_134250_Content_2 = {
    Text = "Binatang buas yang tumbuh dewasa akan mematahkan rantainya, rawr— dan menggigit putus tenggorokan pemeliharanya."
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "Sampai hari di mana kamu benar-benar mengkhianatiku... meskipun kamu lari ke ujung dunia sekalipun, aku akan mengejarmu dan menggigit putus tenggorokanmu."
  },
  AvgCommunicate_134250_Content_3 = {
    Text = "Sekarang ikatan antara kau dan aku, di mataku lebih rapuh dari rantai besi."
  },
  AvgCommunicate_134250_Content_4 = {
    Text = "Kau tidak takut?"
  },
  AvgCommunicate_134250_Content_5 = {
    Text = "Kau bebas, ikatan kita bukan untuk membatasimu."
  },
  AvgCommunicate_134250_Content_6 = {
    Text = "Aku tidak perlu merasa takut."
  },
  AvgCommunicate_134250_Content_8 = {
    Text = "Cih, kata-kata manis."
  },
  AvgCommunicate_134250_Content_9 = {
    Text = "Tapi, aku sudah mengamatimu selama ini, dan belum pernah melihatmu menunjukkan celah sedikit pun."
  },
  AvgCommunicate_134250_Option_12 = {Text = "Menurutmu?"},
  AvgCommunicate_134250_Option_5 = {Text = "Kau bebas"},
  AvgCommunicate_134263_Content_1 = {
    Text = "Penjaga Rahasia!!"
  },
  AvgCommunicate_134263_Content_10 = {
    Text = "Tentu saja, aku tidak pernah meragukan bahwa kamu akan menjadi lebih kuat."
  },
  AvgCommunicate_134263_Content_12 = {
    Text = "Kamu ini orangnya benar-benar aneh."
  },
  AvgCommunicate_134263_Content_13 = {
    Text = "Di saat seperti ini, bukankah seharusnya kamu bilang sesuatu seperti \"Tuh kan, aku tidak salah menilaimu\" atau \"Sudah kuduga, kamu tidak mengecewakan harapanku\"?"
  },
  AvgCommunicate_134263_Content_14 = {
    Text = "Kenapa kamu bisa setenang itu?"
  },
  AvgCommunicate_134263_Content_16 = {
    Text = "Eh... karena kamu sudah berusaha sekeras itu, menjadi kuat itu sudah sewajarnya, apa yang perlu dikomentari."
  },
  AvgCommunicate_134263_Content_17 = {
    Text = "50 yang kamu kembalikan dua tahun lalu, dan 54 yang kamu kembalikan tahun lalu, semuanya masih kusimpan."
  },
  AvgCommunicate_134263_Content_18 = {
    Text = "Disimpan buat apa... pakai saja."
  },
  AvgCommunicate_134263_Content_19 = {
    Text = "Sudahlah, jangan bahas itu, masih ada urusan penting."
  },
  AvgCommunicate_134263_Content_2 = {
    Text = "Garis-garis itu memanas, kekuatan laut dalam mengalir di bawah kulit, jauh lebih jelas dari sebelumnya!"
  },
  AvgCommunicate_134263_Content_20 = {
    Text = "Cepat ke tepi danau, aku menunggumu di sini."
  },
  AvgCommunicate_134263_Content_21 = {Text = "Ada apa?"},
  AvgCommunicate_134263_Content_22 = {
    Text = "Datang saja, nanti kamu juga tahu."
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "Baiklah... kalau begitu tunggu aku sebentar. Sekarang di luar sedang hujan, aku harus kembali ke asrama dulu untuk ambil payung."
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "Jangan berlama-lama, rencana kita selanjutnya tidak butuh payung."
  },
  AvgCommunicate_134263_Content_25 = {
    Text = "Kamu tidak akan kehujanan, sayap membranku cukup besar."
  },
  AvgCommunicate_134263_Content_3 = {
    Text = "Kau tahu rasanya seperti apa?!"
  },
  AvgCommunicate_134263_Content_4 = {
    Text = "Pokoknya sangat luar biasa, sulit diungkapkan dengan kata-kata, kalian manusia mungkin sulit memahaminya."
  },
  AvgCommunicate_134263_Content_5 = {
    Text = "……Caecus, kamu baik-baik saja?"
  },
  AvgCommunicate_134263_Content_6 = {
    Text = "Tentu saja aku baik, tidak pernah sebaik ini sebelumnya."
  },
  AvgCommunicate_134263_Content_7 = {
    Text = "Sudah kubilang sejak dulu, investasimu tidak akan sia-sia, garis keturunanku tidak akan menipuku."
  },
  AvgCommunicate_134263_Content_8 = {Text = "Aku tahu."},
  AvgCommunicate_134263_Content_9 = {
    Text = "……Itu saja?"
  },
  AvgCommunicate_134264_Content_1 = {
    Text = "Mohon ampuni saya, utusan yang pucat, saya kurang siap untuk ini, sepertinya telah menimbulkan sedikit keterkejutan."
  },
  AvgCommunicate_134264_Content_10 = {
    Text = "Setiap kali memikirkan hal ini, kedamaian dalam hatiku jauh melampaui penderitaan ragawi."
  },
  AvgCommunicate_134264_Content_11 = {
    Text = "Aku mengerti, mungkin aku tidak memiliki pemikiran semulia itu. Tapi demi kamu, demi teman-temanku."
  },
  AvgCommunicate_134264_Content_12 = {
    Text = "Selama bisa mencapai dunia yang ideal dan damai itu, apa pun itu, aku akan berusaha melakukannya."
  },
  AvgCommunicate_134264_Content_13 = {
    Text = "Terima kasih, utusan yang pucat."
  },
  AvgCommunicate_134264_Content_14 = {
    Text = "Semoga segala penderitaan pada akhirnya akan terurai, semoga kita senantiasa berjalan berdampingan."
  },
  AvgCommunicate_134264_Content_15 = {
    Text = "Semoga perlindungan Sang Ayah juga turun atas segala yang kamu hargai."
  },
  AvgCommunicate_134264_Content_2 = {
    Text = "Huh…… Syukurlah kamu baik-baik saja, aku tidak menyangka pemahaman akan hukum alam akan membawa efek seperti ini."
  },
  AvgCommunicate_134264_Content_3 = {
    Text = "Tidak perlu mengkhawatirkanku, inilah misi yang membawaku datang ke dunia ini."
  },
  AvgCommunicate_134264_Content_4 = {
    Text = "Sebelum melangkah menuju puncak, sebelum Sang Ayah menyingkapkan misteri yang tak terukur ini kepadaku, aku sudah mempersembahkan diri pada jalan ini."
  },
  AvgCommunicate_134264_Content_5 = {
    Text = "Menghimpun penderitaan semua makhluk dalam satu tubuh, membimbing segala sesuatu menuju tanah suci tanpa noda di mana penderitaan tak lagi ada — ini bukanlah beban. Ini adalah anugerah yang diberikan Sang Ayah kepadaku."
  },
  AvgCommunicate_134264_Content_6 = {
    Text = "Aku selalu merasa kamu menanggung terlalu banyak. Penderitaan orang lain memang terurai, tapi harganya……"
  },
  AvgCommunicate_134264_Content_7 = {
    Text = "Api pucatku, kamu memiliki hati yang lembut."
  },
  AvgCommunicate_134264_Content_8 = {
    Text = "Namun tenanglah. Penderitaan ragawi bagiku, ibarat duri bagi tanah — semakin dalam ia menusuk, semakin kokoh aku berakar."
  },
  AvgCommunicate_134264_Content_9 = {
    Text = "Jika di dunia ini masih ada satu orang yang menderita, Dia tidak akan sendirian. Jika masih ada satu orang yang belum terbebas dari lautan penderitaan, aku tidak akan mencapai seberang lebih dulu darinya."
  },
  AvgCommunicate_134264_Option_11 = {
    Text = "Aku mengerti"
  },
  AvgCommunicate_134264_Option_6 = {Text = "Tapi……"},
  AvgCommunicate_134265_Content_1 = {
    Text = "Hahaha, puas, puas!"
  },
  AvgCommunicate_134265_Content_10 = {
    Text = "Coba tanya anak buahku, mereka sudah mengenalku bertahun-tahun, kapan pernah melihatku melakukan hal seperti itu!"
  },
  AvgCommunicate_134265_Content_11 = {
    Text = "Aduh, sekarang kekuatanku makin dahsyat, lain kali harus lebih hati-hati supaya tidak membuatmu kepanasan."
  },
  AvgCommunicate_134265_Content_12 = {
    Text = "Apa... ternyata itu kau? Kalau begitu, beberapa kali pakaianku terganti, itu juga ulahmu?"
  },
  AvgCommunicate_134265_Content_13 = {
    Text = "Iya, pakaianmu kotor terkena tumpahan minuman dan makanan, masa kubiarkan kau masuk selimut dalam keadaan kotor."
  },
  AvgCommunicate_134265_Content_14 = {
    Text = "Terima kasih, Katigula."
  },
  AvgCommunicate_134265_Content_15 = {
    Text = "Tapi lain kali bisa tidak langsung bangunkan aku saja..."
  },
  AvgCommunicate_134265_Content_16 = {
    Text = "Wah, malu ya? Tidak apa-apa, hubungan kita kan sudah sedekat apa."
  },
  AvgCommunicate_134265_Content_17 = {
    Text = "Jangan bilang cuma ganti baju, bahkan kalau harus menembus lautan api dan mendaki gunung pedang demimu, itu sama sekali bukan masalah!"
  },
  AvgCommunicate_134265_Content_18 = {
    Text = "Paling-paling, lain kali biar kau yang gantikan bajuku sekali, impas kan."
  },
  AvgCommunicate_134265_Content_19 = {
    Text = "...Semuanya tidak masuk akal sampai-sampai orang benar-benar tidak tahu harus membalas apa!"
  },
  AvgCommunicate_134265_Content_2 = {
    Text = "Perasaan menyegarkan yang belum pernah ada sebelumnya, sekarang, akulah sang Matahari!"
  },
  AvgCommunicate_134265_Content_3 = {
    Text = "Nak, aku benar-benar semakin kagum padamu."
  },
  AvgCommunicate_134265_Content_4 = {
    Text = "Baru tahu sekarang? Kehebatanku masih banyak lagi, lho."
  },
  AvgCommunicate_134265_Content_5 = {
    Text = "Oh? Sepertinya selama ini kami semua menganggapmu anak kecil, ternyata memang kurang tepat ya."
  },
  AvgCommunicate_134265_Content_6 = {
    Text = "Hmm... mulai sekarang, harus memanggilmu 'si besar' baru pas."
  },
  AvgCommunicate_134265_Content_7 = {
    Text = "'Si besar' itu apa-apaan! Kau menggodaku dengan wajah serius lagi, kan?"
  },
  AvgCommunicate_134265_Content_8 = {
    Text = "Hahaha, mau bagaimana lagi, setiap kali keluar minum kau selalu yang pertama tumbang."
  },
  AvgCommunicate_134265_Content_9 = {
    Text = "Jadi aku harus menggendongmu kembali ke asrama setiap kali, melepas sepatumu, menyelimutimu, dan mengelap wajahmu."
  },
  AvgCommunicate_134265_Option_12 = {
    Text = "Ternyata itu kau?"
  },
  AvgCommunicate_134265_Option_7 = {Text = "?!"},
  AvgCommunicate_134267_Content_1 = {
    Text = "%player%, musikku telah menjadi lebih sempurna."
  },
  AvgCommunicate_134267_Content_10 = {
    Text = "Musikku bagaikan mesin yang berjalan presisi, dan itu pernah menjadikanku bagian dari orkestra paling ternama. Tentu saja, aku pernah bangga karenanya."
  },
  AvgCommunicate_134267_Content_11 = {
    Text = "Dia berbeda, dia tidak cocok untuk bermain bersama. Musiknya hanya cocok bersinar sendirian di langit, bagaikan matahari atau bulan."
  },
  AvgCommunicate_134267_Content_12 = {
    Text = "Aku selalu memperhatikannya, mengejarnya, hanya saja aku telah kehilangan kesempatan untuk berkomunikasi dengannya selamanya."
  },
  AvgCommunicate_134267_Content_13 = {
    Text = "Tapi... permainan yang kini telah mencapai kesempurnaan mutlak, mungkin inilah jawaban terbaik yang bisa aku persembahkan setelah mengejarnya seumur hidup."
  },
  AvgCommunicate_134267_Content_14 = {
    Text = "Sangat mengharukan...... Ternyata kamu punya masa lalu seperti itu, kisah musisi legendaris yang saling menginspirasi dan penuh semangat......"
  },
  AvgCommunicate_134267_Content_15 = {
    Text = "Hmm, itu hanya ungkapan perasaan yang biasa saja, sebenarnya tidak seheboh itu."
  },
  AvgCommunicate_134267_Content_16 = {
    Text = "Bagaimanapun juga, yang paling ingin kukatakan adalah, terima kasih, %player%."
  },
  AvgCommunicate_134267_Content_17 = {
    Text = "Mulai sekarang, izinkan aku terus memainkan seruling untukmu, menemanimu terlelap setiap malam."
  },
  AvgCommunicate_134267_Content_2 = {
    Text = "Tanpa bimbinganmu, aku mungkin tidak akan pernah bisa melampaui langkah terakhir ini, mengkalibrasi kesalahan kecil yang dulu mustahil dikalibrasi oleh manusia."
  },
  AvgCommunicate_134267_Content_3 = {
    Text = "Ketukan yang sempurna, nada yang tanpa cela, semuanya terdengar begitu indah..."
  },
  AvgCommunicate_134267_Content_4 = {
    Text = "Benar! Aku belum pernah mendengar permainan yang begitu menyejukkan hati!"
  },
  AvgCommunicate_134267_Content_5 = {
    Text = "Ini adalah hasil resonansi antara musik dan perhitungan, instrumen dan tubuh manusia, otak dan otot."
  },
  AvgCommunicate_134267_Content_6 = {
    Text = "Akhirnya aku membuktikan bahwa di ujung jalan yang membosankan ini, juga terdapat musik yang begitu sempurna."
  },
  AvgCommunicate_134267_Content_7 = {
    Text = "Juga? Apa maksudnya?"
  },
  AvgCommunicate_134267_Content_8 = {
    Text = "Dulu, aku punya seorang sahabat. Musiknya adalah hasil dari kepekaan dan kreativitas yang luar biasa."
  },
  AvgCommunicate_134267_Content_9 = {
    Text = "Bakat yang ia curahkan dengan bebas dalam setiap pertunjukan, selalu mampu menciptakan karya improvisasi yang unik."
  },
  AvgCommunicate_134267_Option_14 = {Text = "Huhuhu"},
  AvgCommunicate_134267_Option_4 = {Text = "Memang"},
  AvgCommunicate_134267_Option_7 = {Text = "Juga?"},
  AvgCommunicate_134268_Content_1 = {
    Text = "Tamuku yang paling terhormat, bagaimana aku harus berterima kasih atas kemurahan hatimu?"
  },
  AvgCommunicate_134268_Content_10 = {
    Text = "Begitu rupanya, aku mengerti. Kau tidak menginginkan perayaan yang norak, dan aku pun merasa itu tidak cocok untukmu."
  },
  AvgCommunicate_134268_Content_11 = {
    Text = "Aku punya ide yang bagus. Mungkin, kau bersedia mencoba pergi bersamaku ke luar Kota Tulang Belulang untuk menyambut seorang yang menjelang ajalnya?"
  },
  AvgCommunicate_134268_Content_12 = {
    Text = "Seandainya kita mendapat kehormatan itu, aku berharap kau bisa bersama-sama denganku menyambut-Nya, mengantarkan-Nya menuju akhir dan kelahiran baru-Nya. Bagaimana menurutmu?"
  },
  AvgCommunicate_134268_Content_13 = {
    Text = "Meskipun agak kurang tepat waktunya... aku menebak pada akhirnya pasti tetap melibatkan makan, mengingat itu adalah adat Kota Tulang Belulang."
  },
  AvgCommunicate_134268_Content_14 = {
    Text = "Hmm, aku tidak akan menyebutnya sebagai makan. Sama seperti kisah-kisah yang sudah kau ketahui."
  },
  AvgCommunicate_134268_Content_15 = {
    Text = "Ini hanyalah sebuah perpisahan yang paling agung, sekaligus paling damai."
  },
  AvgCommunicate_134268_Content_16 = {
    Text = "Aku sangat bersedia ikut serta, asalkan aku diizinkan melewatkan beberapa bagian tertentu..."
  },
  AvgCommunicate_134268_Content_17 = {
    Text = "Tentu saja, tentu saja."
  },
  AvgCommunicate_134268_Content_18 = {
    Text = "Kalau begitu, kereta Kota Tulang Belulang dan aku akan menunggumu di depan pintu besok pagi."
  },
  AvgCommunicate_134268_Content_2 = {
    Text = "Berkat pemberianmu, aku kini memiliki kekuatan untuk benar-benar menjaga Kota Tulang Belulang dengan kokoh."
  },
  AvgCommunicate_134268_Content_3 = {
    Text = "Masakan biasa tak sepadan dengan pemberianmu, sementara koleksi berhargaku rasanya kurang cocok dengan seleramu."
  },
  AvgCommunicate_134268_Content_4 = {
    Text = "Sungguh dilema yang membahagiakan."
  },
  AvgCommunicate_134268_Content_5 = {
    Text = "Kau terlalu sopan, Dulcesein."
  },
  AvgCommunicate_134268_Content_6 = {
    Text = "Kita sudah melewati begitu banyak hal bersama, sebenarnya kau tak perlu repot-repot memikirkan basa-basi seperti itu."
  },
  AvgCommunicate_134268_Content_7 = {
    Text = "Oh tidak, tidak, ini sama sekali bukan sekadar basa-basi. Aku sedang serius memikirkan bagaimana menyiapkan sebuah pertemuan dengan sahabat karib."
  },
  AvgCommunicate_134268_Content_8 = {
    Text = "Kau sudah menyaksikan pesta dansa paling istimewa di Kota Tulang Belulang. Bagaimana cara mempererat hubungan kita lebih jauh lagi, itu memang pertanyaan yang sulit."
  },
  AvgCommunicate_134268_Content_9 = {
    Text = "Ehm... Kalau kau ingin tahu keinginanku, aku berharap acaranya biasa saja, tanpa kejutan yang mengagetkan..."
  },
  AvgCommunicate_134268_Option_13 = {
    Text = "Aku menebak"
  },
  AvgCommunicate_134268_Option_9 = {Text = "Ehm"},
  AvgCommunicate_134269_Content_1 = {
    Text = "Pohon kecilku..."
  },
  AvgCommunicate_134269_Content_10 = {
    Text = "Di dalam tubuhku, kekuatan \"proliferasi\" yang muncul setelah menyentuh yang terakhir sedang tumbuh."
  },
  AvgCommunicate_134269_Content_11 = {
    Text = "Betapa manis, betapa subur... Ah, aku sudah tidak rela hanya berbicara denganmu melalui bongkahan logam kecil ini."
  },
  AvgCommunicate_134269_Content_12 = {Text = "Taiysis?"},
  AvgCommunicate_134269_Content_13 = {
    Text = "Datanglah ke sisiku, pohon kecilku, sekarang juga, segera."
  },
  AvgCommunicate_134269_Content_14 = {
    Text = "Aku ingin menggenggam telapak tanganmu yang hangat, menyentuh kulitmu yang lembut……"
  },
  AvgCommunicate_134269_Content_15 = {
    Text = "Aku ingin memelukmu di bawah cahaya bulan, seperti malam ketika kita membuat janji itu."
  },
  AvgCommunicate_134269_Content_16 = {
    Text = "Dengan kekuatanku yang semakin melimpah, perlahan melebur bersamamu, dan membiarkan napasmu yang manis, perlahan menghangatkanku……"
  },
  AvgCommunicate_134269_Content_2 = {
    Text = "Janji yang kau berikan padaku, janji kita di bawah cahaya bulan dan lautan pasir waktu itu, kau sudah mulai menepatinya untukku."
  },
  AvgCommunicate_134269_Content_3 = {
    Text = "Aku sangat senang."
  },
  AvgCommunicate_134269_Content_4 = {
    Text = "Meskipun dunia di mana semua orang bisa hidup dengan tenang masih jauh, tapi aku akan terus berusaha."
  },
  AvgCommunicate_134269_Content_5 = {
    Text = "Sejak pertama kali kita bertemu, aku sudah percaya padamu."
  },
  AvgCommunicate_134269_Content_6 = {
    Text = "Kau adalah orang yang dikaruniai takdir, kau memiliki kekuatan itu, dan juga tekad itu."
  },
  AvgCommunicate_134269_Content_7 = {
    Text = "Pohon kecilku, penampilanmu saat serius menghadapi dunia sungguh sangat menggemaskan."
  },
  AvgCommunicate_134269_Content_8 = {
    Text = "Aku akan menunggu dengan sabar dan sungguh-sungguh, menunggu hari di mana janji itu terwujud."
  },
  AvgCommunicate_134269_Content_9 = {Text = "Pasti!"},
  AvgCommunicate_134269_Option_12 = {Text = "Taiysis?"},
  AvgCommunicate_134269_Option_4 = {
    Text = "Aku akan terus berusaha"
  },
  AvgCommunicate_134269_Option_9 = {Text = "Pasti!"},
  AvgCommunicate_134270_Content_1 = {
    Text = "Aku tidak akan membunuhmu."
  },
  AvgCommunicate_134270_Content_10 = {
    Text = "Setelah mengisapmu kering, aku akan pergi membunuh semua orang."
  },
  AvgCommunicate_134270_Content_11 = {
    Text = "Kalau begitu aku... berusaha hidup lebih lama sedikit?"
  },
  AvgCommunicate_134270_Content_12 = {
    Text = "Hahaha, jawaban yang menarik."
  },
  AvgCommunicate_134270_Content_13 = {
    Text = "Karena kau berniat melindungi seluruh dunia dengan tubuh lemah ini."
  },
  AvgCommunicate_134270_Content_14 = {
    Text = "Kalau begitu……"
  },
  AvgCommunicate_134270_Content_15 = {Text = "...Lalu?"},
  AvgCommunicate_134270_Content_16 = {
    Text = "Sebelum saat itu tiba, aku hanya akan membunuh semua musuhmu."
  },
  AvgCommunicate_134270_Content_17 = {
    Text = "Pada akhirnya tetap mau membunuh...?!"
  },
  AvgCommunicate_134270_Content_2 = {
    Text = "...? Hah? Aku harus bilang apa? Terima kasih?"
  },
  AvgCommunicate_134270_Content_3 = {
    Text = "Dunia ini menjadi sangat membosankan setelah Roma runtuh."
  },
  AvgCommunicate_134270_Content_4 = {
    Text = "Pembantaian, pembantaian, pembantaian, hanya pembunuhan dan darah semata, tanpa Roma, tidak ada apa-apa lagi."
  },
  AvgCommunicate_134270_Content_5 = {
    Text = "Hadiahmu telah membebaskanku dari belenggu itu, sekarang, aku akan pergi merobek satu dua lengan atau tenggorokan."
  },
  AvgCommunicate_134270_Content_6 = {
    Text = "Sayang sekali, Yuuhashi, di era modern membunuh orang sembarangan tanpa izin khusus itu melanggar hukum."
  },
  AvgCommunicate_134270_Content_7 = {
    Text = "Dan aku masih penghubungmu, bukan hanya membunuhku yang tidak boleh, membunuh orang lain juga tidak boleh."
  },
  AvgCommunicate_134270_Content_8 = {Text = "Cih."},
  AvgCommunicate_134270_Content_9 = {
    Text = "Sudahlah, setidaknya aromamu lebih enak daripada semua pemilik budak."
  },
  AvgCommunicate_134271_Content_1 = {
    Text = "Pen~jaga~Rahasia~ Kamu sedang sibuk? Aku ada sesuatu yang ingin kukatakan padamu~"
  },
  AvgCommunicate_134271_Content_10 = {Text = "Kosong?"},
  AvgCommunicate_134271_Content_11 = {
    Text = "Mm~ yaitu perasaan yang gelap gulita, dingin membeku, begitu angin berhembus, perasaan ditinggalkan oleh semua orang itu langsung muncul"
  },
  AvgCommunicate_134271_Content_12 = {
    Text = "Tapi sekarang, di sana hangat~ dan terang benderang~"
  },
  AvgCommunicate_134271_Content_13 = {
    Text = "Semua berkat %player%."
  },
  AvgCommunicate_134271_Content_14 = {
    Text = "Jadi ini memang ucapan terima kasih yang serius?"
  },
  AvgCommunicate_134271_Content_15 = {
    Text = "Hehe~ tentu saja, sesekali aku juga bisa serius tahu!"
  },
  AvgCommunicate_134271_Content_16 = {
    Text = "Tapi sebagai syarat pertukaran— kamu harus lebih sering menemaniku ya?"
  },
  AvgCommunicate_134271_Content_17 = {
    Text = "Kalau tidak, aku akan menggunakan kemampuan baru yang sudah kupelajari untuk meng~hu~kummu lho~"
  },
  AvgCommunicate_134271_Content_18 = {
    Text = "……Jadi begini caramu berterima kasih?!"
  },
  AvgCommunicate_134271_Content_19 = {
    Text = "Aduh, ini kan cara eksklusif Pandiya mengekspresikan cinta~ Muach~ Ingat untuk selalu bersyukur ya!"
  },
  AvgCommunicate_134271_Content_2 = {
    Text = "Kamu punya ide nakal apa lagi?"
  },
  AvgCommunicate_134271_Content_3 = {
    Text = "Kok ngomongnya begitu! Aku datang dengan tulus untuk berterima kasih padamu!"
  },
  AvgCommunicate_134271_Content_4 = {
    Text = "Barang-barang bagus yang kamu berikan sebelumnya……membuat tubuhku jadi panas sekali~"
  },
  AvgCommunicate_134271_Content_5 = {
    Text = "Rasanya seperti ada sesuatu yang membara mengalir di bawah kulit, manis dan pedas sekaligus~"
  },
  AvgCommunicate_134271_Content_6 = {
    Text = "Meskipun aku tahu tidak akan ada efek samping, tapi kamu yakin ini bukan efek samping……"
  },
  AvgCommunicate_134271_Content_7 = {
    Text = "Tentu saja bukan! Perasaan ini luar biasa! Seratus kali lebih mendebarkan daripada cambukan mana pun!"
  },
  AvgCommunicate_134271_Content_8 = {
    Text = "Dan lagi, yang paling luar biasa adalah……"
  },
  AvgCommunicate_134271_Content_9 = {
    Text = "Tempat yang dulu terasa kosong di dalam hati, sekarang sudah terisi penuh lho."
  },
  AvgCommunicate_134271_Option_14 = {Text = "Jadi"},
  AvgCommunicate_134271_Option_6 = {Text = "Meskipun"},
  AvgCommunicate_134272_Content_1 = {
    Text = "Tuan~ Bagaimana seharusnya Karen membalas budi Anda, minuman, bersih-bersih, makanan, silakan perintahkan Karen sesuka hati!"
  },
  AvgCommunicate_134272_Content_10 = {
    Text = "Selama Karen mau, kulit Karen bisa bersinar lebih terang dari permata termahal, lebih berkilau dan memesona dari mutiara tersempurna."
  },
  AvgCommunicate_134272_Content_11 = {
    Text = "Kalau sekarang pergi ke pesta dansa, Karen pasti akan menjadi pusat perhatian seluruh ruangan, bukan lagi orang kecil yang tak dipedulikan siapa pun."
  },
  AvgCommunicate_134272_Content_12 = {
    Text = "Meskipun menurutku ini seharusnya bukan tujuan utama penguatan Hukum Akhir, tapi……"
  },
  AvgCommunicate_134272_Content_13 = {
    Text = "Asalkan kamu senang, itu sudah cukup."
  },
  AvgCommunicate_134272_Content_2 = {
    Text = "Pertama-tama, mari kita singkirkan dulu soal makanan!"
  },
  AvgCommunicate_134272_Content_3 = {
    Text = "Aduh, kemampuan mengurus rumah tangga Karen diragukan, seharusnya Karen sedih, tapi, tapi……"
  },
  AvgCommunicate_134272_Content_4 = {
    Text = "Banyak sekali perhiasan dan aksesori, Karen seluruhnya seperti permata paling berkilau, Karen benar-benar susah untuk bersedih!"
  },
  AvgCommunicate_134272_Content_5 = {
    Text = "Tenang dulu, aku sudah hampir tidak mengerti apa yang kamu bicarakan."
  },
  AvgCommunicate_134272_Content_6 = {
    Text = "Maaf, Karen terlalu bersemangat. Setelah Tuan membantu Karen memahami apa itu jepit rambut? Pita atau semacamnya……"
  },
  AvgCommunicate_134272_Content_7 = {
    Text = "……itu Hukum."
  },
  AvgCommunicate_134272_Content_8 = {
    Text = "Oh iya, yaitu sesuatu yang sangat berharga dan sangat bagus itu. Lalu, Karen merasa seperti mendapatkan kemampuan yang sangat hebat."
  },
  AvgCommunicate_134272_Content_9 = {
    Text = "Belum lagi efisiensi dalam mengurus pekerjaan rumah tangga yang meningkat drastis, yang lebih penting lagi, tubuh Karen bersinar berkilauan."
  },
  AvgCommunicate_134272_Option_7 = {
    Text = "Bukan jepit rambut"
  },
  AvgCommunicate_134273_Content_1 = {
    Text = "%player%, ikatanku denganmu menjadi semakin mendalam."
  },
  AvgCommunicate_134273_Content_10 = {
    Text = "Seperti hasil perhitungan kalkulus, soal ujian mata kuliah umum, dan hal-hal semacamnya, bisa langsung didapat dari pengetahuan tanpa batas itu?"
  },
  AvgCommunicate_134273_Content_12 = {
    Text = "Memang benar kamu tidak perlu lagi bersusah payah mengingat banyak hal."
  },
  AvgCommunicate_134273_Content_13 = {
    Text = "Tapi, menurutku, makna belajar terletak pada proses mengejar pengetahuan, serta melatih kekuatan berpikir."
  },
  AvgCommunicate_134273_Content_14 = {
    Text = "Kamu harus terlebih dahulu mengetahui apa yang tidak kamu ketahui dan apa yang seharusnya kamu ketahui, barulah kamu bisa menemukan jawaban yang kamu butuhkan dari gudang ilmu yang tak terbatas itu."
  },
  AvgCommunicate_134273_Content_15 = {
    Text = "Baiklah, aku mengerti. Meskipun jawabannya berbeda dari Ramona, tapi ternyata hasilnya tetap sama."
  },
  AvgCommunicate_134273_Content_16 = {
    Text = "Iya iya, aku belajar, aku belajar deh!"
  },
  AvgCommunicate_134273_Content_17 = {
    Text = "Senang melihat sisi dirimu yang haus akan pengetahuan, semangat. Aku akan seperti biasa, menemanimu di sisimu."
  },
  AvgCommunicate_134273_Content_2 = {
    Text = "Selamat, dan terima kasih atas usahamu. Kini aku bisa mengumpulkan lebih banyak pecahan kesadaran, menyembunyikan keberadaan yang lebih utuh di celah-celah dunia."
  },
  AvgCommunicate_134273_Content_3 = {
    Text = "Kamu bisa turun ke dunia sekarang!?"
  },
  AvgCommunicate_134273_Content_4 = {
    Text = "Sayangnya, aku masih belum bisa benar-benar menampakkan keberadaanku, tidak bisa meninggalkan Kolam Hitam."
  },
  AvgCommunicate_134273_Content_5 = {
    Text = "Namun, jiwaku, mimpiku, pandanganku yang mengamati berbagai dunia, kini bisa hadir lebih banyak, dan lebih banyak tersampaikan kepadamu."
  },
  AvgCommunicate_134273_Content_6 = {
    Text = "Setidaknya, kamu sudah memiliki kunci untuk memperoleh pengetahuan tanpa batas."
  },
  AvgCommunicate_134273_Content_7 = {
    Text = "Maksudnya, apa pun yang kutanyakan, bisa mendapat jawaban?"
  },
  AvgCommunicate_134273_Content_8 = {
    Text = "Selama hal itu ada, atau dapat dibuktikan."
  },
  AvgCommunicate_134273_Content_9 = {
    Text = "Hehe, misalnya, maksudku misalnya saja."
  },
  AvgCommunicate_134273_Option_15 = {
    Text = "Aku mengerti"
  },
  AvgCommunicate_134273_Option_7 = {
    Text = "Pengetahuan tanpa batas?"
  },
  AvgCommunicate_134274_Content_1 = {
    Text = "Benih... menjadi semakin utuh."
  },
  AvgCommunicate_134274_Content_10 = {
    Text = "Suasana yang ramai seperti itu, bagiku masih terlalu menegangkan."
  },
  AvgCommunicate_134274_Content_11 = {
    Text = "Tidak apa-apa, aku dan Tincture akan menemanimu."
  },
  AvgCommunicate_134274_Content_12 = {
    Text = "Tentu saja, kalau kamu merasa lebih nyaman sendirian, aku juga sepenuhnya mendukung keputusanmu!"
  },
  AvgCommunicate_134274_Content_13 = {
    Text = "Keeper... terima kasih, jika itu harapanmu dan Tincture."
  },
  AvgCommunicate_134274_Content_14 = {
    Text = "Hmm... mari mulai beradaptasi dari sudut paling belakang di kelas dulu."
  },
  AvgCommunicate_134274_Content_2 = {
    Text = "Aku bisa merasakan, kekuatan yang mampu menopang pertumbuhanku, perlahan mengisi kekosongan dalam jiwaku."
  },
  AvgCommunicate_134274_Content_3 = {
    Text = "Jadi... sekarang kamu tidak akan menyerap daya hidup orang lain lagi?"
  },
  AvgCommunicate_134274_Content_4 = {
    Text = "Sayangnya, kemampuan bawaan lahir ini belum hilang."
  },
  AvgCommunicate_134274_Content_5 = {
    Text = "Tapi aku mulai bisa mengendalikan kekuatan ini."
  },
  AvgCommunicate_134274_Content_6 = {
    Text = "Asalkan terus berlatih, para penyelidik yang berinteraksi denganku tidak perlu lagi mengenakan baju pelindung yang berat itu."
  },
  AvgCommunicate_134274_Content_7 = {
    Text = "Sekarang, ada kemungkinan bagiku untuk berada di sisi semua orang dengan aman."
  },
  AvgCommunicate_134274_Content_8 = {
    Text = "Itu bagus sekali! Mulai sekarang kamu juga bisa ikut berbagai kegiatan sekolah, pesta malam, dan juga pesta antar Awakened!"
  },
  AvgCommunicate_134274_Content_9 = {
    Text = "Pe-pesta... Menurutku, menguasai kemampuan bergaul dengan orang lain jauh lebih sulit daripada menguasai pengendalian naluri."
  },
  AvgCommunicate_134274_Option_11 = {
    Text = "Tidak apa-apa"
  },
  AvgCommunicate_134274_Option_3 = {Text = "Jadi..."},
  AvgCommunicate_134274_Option_8 = {
    Text = "Itu bagus sekali!"
  },
  AvgCommunicate_134275_Content_1 = {
    Text = "Mempersembahkan segala hal mulia untuk Sang Putri adalah kehormatan bagimu."
  },
  AvgCommunicate_134275_Content_10 = {
    Text = "……Terima kasih? Bukankah kau ingin memberiku hadiah untuk menyenangkanku, lalu mendengar beberapa kata penyemangat dariku, atau membuatku memenuhi ekspektasimu?"
  },
  AvgCommunicate_134275_Content_11 = {
    Text = "\"Mephie\", aku memberi hadiah dan bersikap baik padamu, hanya karena kau adalah kau."
  },
  AvgCommunicate_134275_Content_12 = {
    Text = "Tidak ada hubungannya dengan statusmu sebagai Putri Raja, Ibu Dewa, atau apa pun itu. Kau adalah temanku, selain itu, aku tidak punya ekspektasi lain."
  },
  AvgCommunicate_134275_Content_14 = {
    Text = "Hmph! I-itu tetap saja basa-basi manis dan kata-kata gombal! Kau pikir dengan mengatakan hal seperti itu, aku akan terharu sampai menangis?"
  },
  AvgCommunicate_134275_Content_15 = {
    Text = "Jangan bermimpi, teman apa, kau cukup menjadi pengikut yang setia saja."
  },
  AvgCommunicate_134275_Content_16 = {
    Text = "Ucapan yang menyakitkan sekali, aku benar-benar akan menangis semalaman lho?"
  },
  AvgCommunicate_134275_Content_17 = {
    Text = "Ka-kau, aduh, dasar tidak berguna."
  },
  AvgCommunicate_134275_Content_18 = {
    Text = "Hanya kali ini saja ya, dengarkan baik-baik."
  },
  AvgCommunicate_134275_Content_19 = {
    Text = "……Terima kasih."
  },
  AvgCommunicate_134275_Content_2 = {
    Text = "Kerja bagus."
  },
  AvgCommunicate_134275_Content_20 = {
    Text = "Pokoknya, mulai sekarang, Putri Raja ini akan memiliki kekuatan yang cukup untuk melindungimu sepenuhnya. Kau tinggal bersyukur dan terus memujaku dengan baik!"
  },
  AvgCommunicate_134275_Content_3 = {
    Text = "Tidak ada hal lain yang ingin kamu katakan?"
  },
  AvgCommunicate_134275_Content_4 = {
    Text = "Kenapa, bukankah kekuatan ini memang seharusnya menjadi milikku?"
  },
  AvgCommunicate_134275_Content_5 = {
    Text = "Oh, aku mengerti, kau ingin hadiah, berkah, atau kedudukan yang lebih tinggi, atau mungkin gelar yang lebih terhormat?"
  },
  AvgCommunicate_134275_Content_7 = {
    Text = "Apa maksudnya \"……\"? Menyebalkan, aku tidak tertarik bermain teka-teki denganmu."
  },
  AvgCommunicate_134275_Content_8 = {
    Text = "Kuberi kau kesempatan terakhir, cepat katakan apa maumu, jangan berbelit-belit."
  },
  AvgCommunicate_134275_Content_9 = {
    Text = "Mungkinkah, maksudku setidaknya kau harus mengucapkan terima kasih."
  },
  AvgCommunicate_134275_Option_16 = {
    Text = "Menyakitkan sekali"
  },
  AvgCommunicate_134275_Option_3 = {Text = "Itu saja?"},
  AvgCommunicate_134275_Option_9 = {Text = "Mungkinkah"},
  AvgCommunicate_134276_Content_1 = {
    Text = "Terima kasih, Penjaga Rahasia, terima kasih! Aku, aku tidak tahu harus mengungkapkannya bagaimana..."
  },
  AvgCommunicate_134276_Content_10 = {
    Text = "Kurang lebih begitulah maksudnya?"
  },
  AvgCommunicate_134276_Content_11 = {
    Text = "Aku dengar warna dalam sebuah lukisan juga memiliki makna emosi dan suasana yang berbeda. Kau bisa berkreasi menciptakan warna baru sesuai dengan ide kreatifmu sendiri."
  },
  AvgCommunicate_134276_Content_12 = {
    Text = "Oh! Ooh! Mencampur kombinasi warna yang benar-benar baru sesuka hati!"
  },
  AvgCommunicate_134276_Content_13 = {
    Text = "Ide ini sungguh jenius! Polarisasi yang berbeda... tekstur yang berbeda... Aku sudah punya banyak ide!"
  },
  AvgCommunicate_134276_Content_14 = {
    Text = "Permisi dulu, Penjaga Rahasia!"
  },
  AvgCommunicate_134276_Content_15 = {
    Text = "Aku punya firasat, lukisanku berikutnya akan memiliki sapuan kuas yang lebih ajaib."
  },
  AvgCommunicate_134276_Content_16 = {
    Text = "Siapa tahu aku benar-benar bisa menciptakan dunia lukisan yang terhubung dengan yang tak diketahui. Saat itu tiba, kau pasti akan menjadi orang pertama yang melihatnya!"
  },
  AvgCommunicate_134276_Content_2 = {
    Text = "Terima kasih telah memberiku kesempatan untuk melihat wujud asli dunia ini. Hukum tertinggi alam semesta, warna dasar di atas kanvas dunia..."
  },
  AvgCommunicate_134276_Content_3 = {
    Text = "Ah, begitu indahnya... Bagaimana caraku mencampur warna seperti ini?"
  },
  AvgCommunicate_134276_Content_4 = {
    Text = "Kristal pelangi? Mithril? Mutiara? Serbuk serangga kristal? Sayap kupu-kupu bercahaya?"
  },
  AvgCommunicate_134276_Content_5 = {
    Text = "Tidak, tidak, tidak... Benda-benda biasa nan dangkal itu tak mungkin bisa mereplikasinya. Pikirkan lagi, harus pikirkan lagi..."
  },
  AvgCommunicate_134276_Content_6 = {
    Text = "Pickman? Sepertinya kau sudah tenggelam dalam dunia senimu sendiri..."
  },
  AvgCommunicate_134276_Content_7 = {
    Text = "Sst, menurutmu seperti apa warna asli alam semesta? Kau yang begitu istimewa, pasti bisa memberiku inspirasi yang berbeda!"
  },
  AvgCommunicate_134276_Content_8 = {
    Text = "Menurutku, dunia di mata setiap orang mungkin berbeda-beda."
  },
  AvgCommunicate_134276_Content_9 = {
    Text = "Oh! Maksudmu... biarkan aku mengikuti hatiku... mengikuti perasaanku, untuk melukiskan warna-warna alam semesta yang berbeda..."
  },
  AvgCommunicate_134276_Option_10 = {
    Text = "Mungkin begitu"
  },
  AvgCommunicate_134276_Option_8 = {Text = "Menurutku"},
  AvgCommunicate_134277_Content_1 = {
    Text = "Pen~ja~ga Rahasia——"
  },
  AvgCommunicate_134277_Content_10 = {
    Text = "Aku tidak akan mengasihanimu, tidak akan dengan angkuh berasumsi tentang logika perilakumu, aku hanya berharap kamu bersenang-senang di dunia ini."
  },
  AvgCommunicate_134277_Content_12 = {
    Text = "Wah, siapa di antara kita yang lebih gila ya? Hanya karena alasan seperti itu, kamu menyerahkan kekuatan sebesar ini kepada orang gila sepertiku?"
  },
  AvgCommunicate_134277_Content_13 = {
    Text = "Jangan-jangan kedatanganku ke dunia ini memang benar-benar takdir?"
  },
  AvgCommunicate_134277_Content_15 = {
    Text = "Singkatnya, berkat bantuanmu, aku telah menyentuh \"batas\" yang menjadi milikku di dunia kalian ini."
  },
  AvgCommunicate_134277_Content_16 = {
    Text = "Selanjutnya, cepat beri aku misi! Aku sudah tidak sabar ingin memenggal beberapa kepala untuk ditunjukkan pada kalian~"
  },
  AvgCommunicate_134277_Content_2 = {
    Text = "Seorang gadis yang tersesat di dunia asing, menerima hadiah mahal yang bisa membuatnya lebih kuat. Kau tahu hal seperti ini mirip apa?"
  },
  AvgCommunicate_134277_Content_3 = {
    Text = "Sebelum kau mengatakan sesuatu yang berbeda dari cara berpikir orang normal, aku mau menegaskan dulu—kau adalah bagian dari Myssagor. Kita saling membantu, itulah alasanku memberikan material-material itu kepadamu."
  },
  AvgCommunicate_134277_Content_4 = {
    Text = "Benarkah? Bukan semacam perilaku sosial manusia yang membosankan dan berbelit-belit?"
  },
  AvgCommunicate_134277_Content_5 = {
    Text = "\"Dia tidak bisa pulang ke rumah, kasihan sekali, mari beri dia lebih banyak perhatian.\""
  },
  AvgCommunicate_134277_Content_6 = {
    Text = "\"Sendirian mencari jalan keluar pasti sangat berat, mari beri dia sedikit bantuan.\" — bukankah seharusnya alasan umum seperti ini yang muncul di masyarakat biasa?"
  },
  AvgCommunicate_134277_Content_7 = {
    Text = "Pertama-tama, dari sudut pandang mana pun, Moxia, kamu sama sekali tidak ada hubungannya dengan kata \"biasa\"!"
  },
  AvgCommunicate_134277_Content_8 = {
    Text = "Hmph☆hmph, penilaian itu cukup kusuka."
  },
  AvgCommunicate_134277_Content_9 = {
    Text = "Kedua, apa pun persepsimu tentang dirimu sendiri, apa pun penampilanmu di luar, bagiku, seperti yang kamu bilang, \"Moxia\" ya \"Moxia\"."
  },
  AvgCommunicate_134277_Option_7 = {
    Text = "Pertama-tama"
  },
  AvgCommunicate_134278_Content_1 = {
    Text = "Terima kasih, sayangku. Kamu telah membawakan begitu banyak kebahagiaan untukku, dan juga membuatku bisa selamanya mempertahankan ambisiku."
  },
  AvgCommunicate_134278_Content_10 = {
    Text = "Apa pun bentuk ucapan terima kasih yang kamu inginkan, aku bisa mewujudkannya."
  },
  AvgCommunicate_134278_Content_11 = {
    Text = "Bahkan jika aku belum memilikinya, sekalipun itu bintang dan bulan, aku bersedia mencari cara untuk mengambilkannya untukmu."
  },
  AvgCommunicate_134278_Content_12 = {
    Text = "Bebas memilih? Apa pun boleh?"
  },
  AvgCommunicate_134278_Content_13 = {
    Text = "Menepati janji adalah tiket masuk yang tak tergantikan di dunia sosialita."
  },
  AvgCommunicate_134278_Content_14 = {
    Text = "Kalau begitu, saya ingin Nyonya memberikan saya sebuah janji. Mengenai isi persisnya, saya masih perlu memikirkannya."
  },
  AvgCommunicate_134278_Content_16 = {
    Text = "Hahahaha, pilihan yang licik sekali. Kamu benar-benar membuatku semakin menyukaimu."
  },
  AvgCommunicate_134278_Content_17 = {
    Text = "Tentu saja, sayangku, kamu punya banyak waktu untuk memikirkannya perlahan."
  },
  AvgCommunicate_134278_Content_18 = {
    Text = "Kalau kamu punya waktu, bagaimana kalau malam ini datang ke kediamanku? Mungkin, saat hanya ada kita berdua... kamu akan lebih mudah mendapatkan \"ide bagus\" yang menyegarkan."
  },
  AvgCommunicate_134278_Content_2 = {
    Text = "Melayani Anda, Nyonya, adalah suatu kehormatan bagi saya."
  },
  AvgCommunicate_134278_Content_3 = {
    Text = "Hehe, sopan, cerdas, berani, setia, ditambah sedikit... ketampanan yang pas."
  },
  AvgCommunicate_134278_Content_4 = {
    Text = "Siapa yang bisa bilang kamu bukan seorang yang sempurna..."
  },
  AvgCommunicate_134278_Content_5 = {
    Text = "...Sempurna dalam hal apa?"
  },
  AvgCommunicate_134278_Content_6 = {
    Text = "Kamu sepertinya sedikit gugup?"
  },
  AvgCommunicate_134278_Content_7 = {
    Text = "Nyonya selalu membuat orang kehabisan kata-kata."
  },
  AvgCommunicate_134278_Content_8 = {
    Text = "Ada hal-hal yang tak perlu diungkapkan dengan kata-kata. Selama ini, aku sudah menerima semua ketulusanmu."
  },
  AvgCommunicate_134278_Content_9 = {
    Text = "Tanah, properti, banyak harta langka dan karya seni, kesempatan bertemu berbagai selebriti dan bintang terkenal…… Dengan kekuatanku sekarang, semua itu mudah didapat."
  },
  AvgCommunicate_134278_Option_12 = {
    Text = "Benarkah apa pun boleh?"
  },
  AvgCommunicate_134278_Option_14 = {
    Text = "Saya ingin sebuah janji dari Nyonya."
  },
  AvgCommunicate_134278_Option_2 = {
    Text = "Suatu kehormatan bagi saya"
  },
  AvgCommunicate_134278_Option_5 = {Text = "Sempurna?"},
  AvgCommunicate_134279_Content_1 = {
    Text = "Penjaga Rahasia, Anda masih terjaga?"
  },
  AvgCommunicate_134279_Content_10 = {
    Text = "Tapi semua yang Anda curahkan untuk saya……telah berkumpul menjadi sebuah danau baru di dalam diri saya. Lebih luas dari lautan itu."
  },
  AvgCommunicate_134279_Content_11 = {
    Text = "Dia memberitahu saya: tidak perlu takut lagi."
  },
  AvgCommunicate_134279_Content_12 = {
    Text = "Aku memahami bahwa rasa sakit itu mungkin tidak bisa dihilangkan, tapi berapa kali pun, aku bersedia menarikmu kembali ke tepi pantai."
  },
  AvgCommunicate_134279_Content_13 = {
    Text = "……Jika Ayah dan Ibu bisa mendengar kata-kata Anda itu, mereka pasti akan merasa tenang."
  },
  AvgCommunicate_134279_Content_14 = {
    Text = "Saya rasa……mereka mungkin sedang berada di suatu tempat di lautan sana, melihat saya yang sekarang."
  },
  AvgCommunicate_134279_Content_15 = {
    Text = "Mulai sekarang, saya akan menggunakan kekuatan yang telah saya peroleh ini, menjadi pasang surut yang menjaga Anda."
  },
  AvgCommunicate_134279_Content_16 = {
    Text = "Mungkin, apakah Anda bersedia mengabulkan satu permintaan lancang lagi?"
  },
  AvgCommunicate_134279_Content_17 = {
    Text = "Apa? Selama itu sesuatu yang bisa kulakukan, aku sangat bersedia."
  },
  AvgCommunicate_134279_Content_18 = {
    Text = "Setelah cuaca cerah nanti, tolong temani saya berjalan-jalan ke pantai."
  },
  AvgCommunicate_134279_Content_19 = {
    Text = "Ada begitu banyak hal yang ingin saya sampaikan kepada Anda, cukup satu sore saja."
  },
  AvgCommunicate_134279_Content_2 = {
    Text = "Kalau saya mengganggu istirahat Anda, saya minta maaf……"
  },
  AvgCommunicate_134279_Content_20 = {
    Text = "Tentu saja tidak masalah, pasti."
  },
  AvgCommunicate_134279_Content_3 = {
    Text = "Tidak, aku belum tidur. Ada apa?"
  },
  AvgCommunicate_134279_Content_4 = {
    Text = "Setelah menerima hadiah dari Anda, saya tertidur lelap dan masuk ke dalam sebuah mimpi. Saya memimpikan lautan yang dulu, dan matahari terbenam di luar sanatorium."
  },
  AvgCommunicate_134279_Content_5 = {
    Text = "Tapi kali ini……saya tidak berjalan masuk ke dalam laut."
  },
  AvgCommunicate_134279_Content_6 = {
    Text = "Saya berdiri di tepi pantai, memandangi lautan itu. Lautan itu masih membuat saya merasa tenang, tapi saya tidak ingin melangkah maju."
  },
  AvgCommunicate_134279_Content_7 = {
    Text = "Kalau dugaan ini tidak menyinggung perasaanmu, apakah karena kali ini, kamu punya alasan untuk tetap tinggal?"
  },
  AvgCommunicate_134279_Content_8 = {Text = "Hm."},
  AvgCommunicate_134279_Content_9 = {
    Text = "Saya pernah dihancurkan oleh rasa sakit. Selain lautan yang mampu menghanyutkan dan menampung segalanya, tidak ada yang bisa membawa pergi beban berat yang tersumbat di tenggorokan saya."
  },
  AvgCommunicate_134279_Option_12 = {
    Text = "Nymphia……"
  },
  AvgCommunicate_134279_Option_17 = {Text = "Apa?"},
  AvgCommunicate_134279_Option_7 = {
    Text = "Karena……"
  },
  AvgCommunicate_134280_Content_1 = {
    Text = "%player%, tadi malam, aku bermimpi itu lagi."
  },
  AvgCommunicate_134280_Content_10 = {
    Text = "Mungkin ini adalah efek dari Hukum Akhir."
  },
  AvgCommunicate_134280_Content_11 = {
    Text = "Ya, jadi aku ingin mengatakan, aku mewakili semua \"24\" untuk berterima kasih kepadamu, %player%."
  },
  AvgCommunicate_134280_Content_12 = {
    Text = "Terima kasih telah membuat kami saling mendengar, saling melihat, saling memahami, dan saling menerima."
  },
  AvgCommunicate_134280_Content_13 = {
    Text = "Ini bukan jasaku."
  },
  AvgCommunicate_134280_Content_14 = {
    Text = "Tidak, bimbingan dan ketenangan yang Anda berikan telah meredakan semua jiwa yang gelisah."
  },
  AvgCommunicate_134280_Content_15 = {
    Text = "Kehadiran Andalah yang membuat semua sungai mengalir ke satu muara."
  },
  AvgCommunicate_134280_Content_16 = {
    Text = "\"Kami\" tidak akan pernah melupakan kebaikan Anda."
  },
  AvgCommunicate_134280_Content_2 = {
    Text = "Aku seperti kembali ke kaki gunung bersalju di ujung utara, di dalam sebuah gua yang gelap gulita."
  },
  AvgCommunicate_134280_Content_3 = {
    Text = "Tak terhitung gumpalan lendir, memantulkan bayangan \"24\" yang tak terhitung jumlahnya..."
  },
  AvgCommunicate_134280_Content_4 = {
    Text = "Mereka semua……adalah dirimu, semuanya adalah bagian dari dirimu."
  },
  AvgCommunicate_134280_Content_5 = {Text = "Aku tahu."},
  AvgCommunicate_134280_Content_6 = {
    Text = "Di tengah kekacauan, sepertinya aku mendengar seseorang mengatakan sesuatu kepadaku."
  },
  AvgCommunicate_134280_Content_7 = {
    Text = "Suaranya sangat samar, aku tidak bisa mendengarnya dengan jelas……"
  },
  AvgCommunicate_134280_Content_8 = {
    Text = "Tapi setelah orang itu pergi, aku merasakan semua kebisingan di sekitarku menjadi tenang."
  },
  AvgCommunicate_134280_Content_9 = {
    Text = "Bisikan-bisikan berisik di telinga menjadi harmonis dan alami, bagaikan melodi yang selaras……"
  },
  AvgCommunicate_134280_Option_4 = {
    Text = "Mereka semua adalah dirimu."
  },
  AvgCommunicate_134281_Content_1 = {
    Text = "Penjaga Rahasia, apakah kamu percaya pada takdir?"
  },
  AvgCommunicate_134281_Content_10 = {
    Text = "……Sebagai orang biasa, aku sudah sulit membayangkan senikmanya apa, izinkan aku bertanya sambil menggertakkan gigi, sebenarnya rasanya seperti apa?"
  },
  AvgCommunicate_134281_Content_11 = {
    Text = "Bagaimana mendeskripsikannya ya? Misalnya, sekarang aku merasa agak lapar……"
  },
  AvgCommunicate_134281_Content_12 = {Text = "? Lalu?"},
  AvgCommunicate_134281_Content_13 = {
    Text = "Oh, maaf menunggu lama, tadi ada yang mengetuk pintu, ternyata Nona Mason berbagi pound cake yang baru keluar dari oven."
  },
  AvgCommunicate_134281_Content_14 = {Text = "Apa???"},
  AvgCommunicate_134281_Content_15 = {
    Text = "Begitulah, lalu... aku agak haus."
  },
  AvgCommunicate_134281_Content_16 = {
    Text = "Eh? Tadi butler Tuan Dulseyin mengirimkan undangan, katanya mengundangku untuk mencicipi koleksi anggur merah yang disimpannya di restoran terdekat."
  },
  AvgCommunicate_134281_Content_17 = {
    Text = "...Cukup, bisakah lain kali kau dengan tulus ikhlas membantuku mengerjakan PR?"
  },
  AvgCommunicate_134281_Content_18 = {
    Text = "Hahaha, siap laksanakan, %player%, kau sekarang adalah penyandang dana terbesarku, sponsor, rekan baik, serta Watson yang tak tergantikan."
  },
  AvgCommunicate_134281_Content_19 = {
    Text = "Detektif Keberuntungan, dengan senang hati melayanimu."
  },
  AvgCommunicate_134281_Content_2 = {
    Text = "Aku percaya pada takdir, dan aku percaya bahwa aku memiliki takdir yang paling beruntung."
  },
  AvgCommunicate_134281_Content_3 = {
    Text = "Semua keberuntungan tak terduga, rezeki dari langit, dan hal-hal baik yang tiba-tiba jatuh dari langit terjadi padaku, aku sudah tak tergoyahkan lagi."
  },
  AvgCommunicate_134281_Content_4 = {
    Text = "Terbiasa dengan kemurahan takdir, semua hal menyenangkan pun menjadi biasa-biasa saja."
  },
  AvgCommunicate_134281_Content_5 = {
    Text = "Ucapanmu itu, benar-benar bikin iri sekaligus kesal."
  },
  AvgCommunicate_134281_Content_6 = {
    Text = "Jangan buru-buru, aku belum selesai bicara. Bertemu denganmu adalah hal paling beruntung di antara semua keberuntunganku."
  },
  AvgCommunicate_134281_Content_7 = {
    Text = "Apa yang kamu berikan padaku, selalu bisa membawa kejutan baru."
  },
  AvgCommunicate_134281_Content_8 = {
    Text = "Seperti sekarang, kekuatan yang muncul setelah memahami Hukum Akhir sudah membuatku bisa merasakan dengan jelas setiap kali keberuntungan akan datang."
  },
  AvgCommunicate_134281_Content_9 = {
    Text = "Hal-hal beruntung itu seperti tetesan hujan, dari rintik-rintik, byuur— berubah menjadi hujan deras yang mengguyur."
  },
  AvgCommunicate_134281_Option_10 = {
    Text = "Rasanya seperti apa?"
  },
  AvgCommunicate_134281_Option_14 = {Text = "???"},
  AvgCommunicate_134281_Option_5 = {
    Text = "Bikin iri sekaligus kesal"
  },
  AvgCommunicate_137645_Content_1 = {
    Text = "Sang Penjaga Rahasia."
  },
  AvgCommunicate_137645_Content_10 = {
    Text = "Tapi kamu punya begitu banyak kaki, bukankah agak tidak adil kalau ikut perlombaan lari……"
  },
  AvgCommunicate_137645_Content_11 = {
    Text = "Castor memiliki sayap, Nodira pun membawa kendaraannya."
  },
  AvgCommunicate_137645_Content_12 = {
    Text = "Keseharianku dihabiskan untuk menenun di teater, aku tidak pandai berolahraga. Namun, aku sudah mendaftarkan pelayanku."
  },
  AvgCommunicate_137645_Content_13 = {
    Text = "Sulit dibayangkan, mengapa kamu bisa tertarik dengan hal seperti ini?"
  },
  AvgCommunicate_137645_Content_14 = {
    Text = "Menyaksikan orang-orang menampilkan semangat hidup yang membara dan tekad yang kuat demi sebuah tujuan adalah hal yang menyenangkan."
  },
  AvgCommunicate_137645_Content_15 = {
    Text = "Dan... aku agak penasaran, sihir apa yang dimiliki kue sebagai hadiah itu, hingga bahkan Tavvi pun tergila-gila padanya."
  },
  AvgCommunicate_137645_Content_16 = {
    Text = "Selama bukan pilihan yang menghancurkan suatu dunia, apa pun tidak masalah..."
  },
  AvgCommunicate_137645_Content_17 = {
    Text = "Eh, kamu tidak akan memanipulasi hasil pertandingan dengan benang takdir, kan?"
  },
  AvgCommunicate_137645_Content_18 = {
    Text = "...Arachne?"
  },
  AvgCommunicate_137645_Content_2 = {Text = "Ada apa?"},
  AvgCommunicate_137645_Content_20 = {
    Text = "Sampai jumpa di tribun penonton, Penjaga Rahasia."
  },
  AvgCommunicate_137645_Content_3 = {
    Text = "Menurutmu……takdir seperti apa yang bisa disebut adil dan benar?"
  },
  AvgCommunicate_137645_Content_4 = {
    Text = "Adil dan benar?……Mungkin yang sebisa mungkin menjaga kepentingan sebagian besar orang."
  },
  AvgCommunicate_137645_Content_5 = {
    Text = "Lalu bagaimana jika——sudah ditakdirkan harus mengorbankan kepentingan sebagian kecil orang? Kau menyetujui arah takdir seperti itu, bukan?"
  },
  AvgCommunicate_137645_Content_6 = {
    Text = "Kamu……kenapa tiba-tiba bertanya ini? Jangan salah paham maksudku ya!"
  },
  AvgCommunicate_137645_Content_7 = {
    Text = "Kalau kamu mau melakukan sesuatu yang menghancurkan dunia lagi, tolong pikirkanlah baik-baik, Arachne!"
  },
  AvgCommunicate_137645_Content_8 = {
    Text = "Tidak perlu khawatir, Penjaga Rahasia, ini hanya perlombaan lari."
  },
  AvgCommunicate_137645_Content_9 = {
    Text = "Huh……kamu mengejutkanku……"
  },
  AvgCommunicate_137645_Option_2 = {Text = "Ada apa?"},
  AvgCommunicate_137646_Content_1 = {
    Text = "Penjaga Rahasia, setelah mendengar bahwa kamu akan pergi jauh untuk mengikuti penyelidikan, aku sengaja menulis sebuah karya untukmu."
  },
  AvgCommunicate_137646_Content_10 = {
    Text = "Selera penamaanmu sungguh luar biasa, Arachne..."
  },
  AvgCommunicate_137646_Content_11 = {
    Text = "Setiap helai benang tenun memiliki pemiliknya yang telah ditakdirkan. Setiap cerita pun memiliki pembacanya sendiri."
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "Sebuah nama yang mudah menyebar dapat membuat cerita-cerita luar biasa ini menjangkau lebih banyak orang yang seharusnya menerimanya."
  },
  AvgCommunicate_137646_Content_13 = {
    Text = "Seperti karya dengan penjualan tertinggi ini..."
  },
  AvgCommunicate_137646_Content_14 = {
    Text = "\"Panduan Memasak Makhluk Laut Dalam\"? Penjualan tertinggi?"
  },
  AvgCommunicate_137646_Content_15 = {
    Text = "Jangan-jangan Dulcesein membelinya satu per satu untuk semua orang di Kota Jenazah..."
  },
  AvgCommunicate_137646_Content_16 = {
    Text = "Apakah Tulu tahu soal ini?"
  },
  AvgCommunicate_137646_Content_18 = {
    Text = "Justru kepekaan tajammu dalam memahami hati manusia dan takdir itulah yang membuatku benar-benar mengagumimu."
  },
  AvgCommunicate_137646_Content_19 = {
    Text = "\"Semua Orang Suka Penjaga Rahasia\"."
  },
  AvgCommunicate_137646_Content_2 = {
    Text = "Tadinya ingin mementaskan sebuah drama untukmu, namun mempertimbangkan kemudahan dibawa, akhirnya kutulis dalam bentuk novel."
  },
  AvgCommunicate_137646_Content_20 = {
    Text = "Bawalah karya ini bersamamu dalam perjalananmu."
  },
  AvgCommunicate_137646_Content_3 = {Text = "Ini…"},
  AvgCommunicate_137646_Content_4 = {
    Text = "\"Penjaga Rahasia yang Luar Biasa\"? \"Kisah Petualangan Penjaga Rahasia\"? \"Dunia Penjaga Rahasia\"?"
  },
  AvgCommunicate_137646_Content_5 = {
    Text = "Apa yang biasanya kamu tulis!? Apakah ada yang benar-benar membaca ini???"
  },
  AvgCommunicate_137646_Content_6 = {
    Text = "Jangan meremehkan popularitasmu di Messager, semua ini adalah karya-karya yang sangat populer."
  },
  AvgCommunicate_137646_Content_7 = {
    Text = "Takdir yang begitu dramatis, tentu saja harus diperlihatkan kepada dunia."
  },
  AvgCommunicate_137646_Content_8 = {
    Text = "Sebenarnya, bukan hanya kamu. Aku juga pernah merangkai cerita dari takdir orang lain."
  },
  AvgCommunicate_137646_Content_9 = {
    Text = "\"Lima Tahun Medan Perang Tiga Tahun Simulasi\", \"Perawatan Pascamelahirkan Sang Tikus\", \"Pameran Agung Seni Tetes Lilin\"..."
  },
  AvgCommunicate_137646_Option_3 = {Text = "Ini…"},
  AvgCommunicate_137647_Content_1 = {
    Text = "Menghubungkan orang-orang dari ruang dan waktu yang berbeda dengan benang tak kasat mata……"
  },
  AvgCommunicate_137647_Content_10 = {
    Text = "Aku sangat menantikannya, Penjaga Rahasia."
  },
  AvgCommunicate_137647_Content_2 = {
    Text = "Peradaban manusia selalu bisa memberiku kejutan."
  },
  AvgCommunicate_137647_Content_3 = {Text = "Kejutan?"},
  AvgCommunicate_137647_Content_4 = {
    Text = "Tapi bukankah takdir-takdir ini kau pilih sendiri?"
  },
  AvgCommunicate_137647_Content_5 = {
    Text = "Yang aku pilih hanyalah arahnya, semua peradaban dan sejarah tetap kalian ciptakan sendiri."
  },
  AvgCommunicate_137647_Content_6 = {
    Text = "Benang takdir yang terbentang secara alami, pada akhirnya akan melahirkan kreasi baru dan titik asal yang tak diketahui."
  },
  AvgCommunicate_137647_Content_7 = {
    Text = "Karena menyaksikan semua ini terjadi, karena kegembiraan menenun ini, aku bisa terus mengemban tanggung jawab ini."
  },
  AvgCommunicate_137647_Content_8 = {
    Text = "Begitu rupanya……"
  },
  AvgCommunicate_137647_Content_9 = {
    Text = "Jika ada kreasi baru, tolong biarkan aku menikmatinya bersama."
  },
  AvgCommunicate_137647_Option_3 = {Text = "Kejutan?"},
  AvgCommunicate_140194_Content_1 = {
    Text = "Perasaan yang ajaib, ternyata sama sekali tidak ada yang ketakutan……"
  },
  AvgCommunicate_140194_Content_10 = {
    Text = "Semua orang sangat baik pada Saya, jadi tidak masalah!"
  },
  AvgCommunicate_140194_Content_11 = {
    Text = "……Mungkin. Untuk sementara."
  },
  AvgCommunicate_140194_Content_12 = {
    Text = "Untuk sementara……janji ya!"
  },
  AvgCommunicate_140194_Content_13 = {
    Text = "Untuk sementara~"
  },
  AvgCommunicate_140194_Content_2 = {
    Text = "Guru Dor sengaja mengembangkan feromon khusus. Sekarang, di mata siapa pun, Saya hanyalah gadis manusia biasa."
  },
  AvgCommunicate_140194_Content_4 = {
    Text = "Eh, meskipun sangat praktis, tapi kalau harus bilang……"
  },
  AvgCommunicate_140194_Content_5 = {
    Text = "Semua orang tidak takut saat melihat Saya, agak disayangkan ya?"
  },
  AvgCommunicate_140194_Content_6 = {Text = "...?"},
  AvgCommunicate_140194_Content_7 = {
    Text = "Bagaimana ya, hmm…… saat \"berburu\" jadi agak susah……"
  },
  AvgCommunicate_140194_Content_8 = {
    Text = "Berkat semua orang, memang tidak perlu khawatir soal makanan…… tapi sesekali tetap ingin…… hmm……"
  },
  AvgCommunicate_140194_Content_9 = {
    Text = "Meskipun sudah terbiasa dengan para Awakened yang mengeluarkan pernyataan seperti ini, tapi tetap saja berbahaya, ucapan yang berbahaya, Saya!"
  },
  AvgCommunicate_140195_Content_1 = {
    Text = "\"Permohonan Pengadaan\""
  },
  AvgCommunicate_140195_Content_10 = {
    Text = "Aku akan berpura-pura sama sekali tidak tahu apa-apa."
  },
  AvgCommunicate_140195_Content_2 = {
    Text = "Empat unit kulkas rumah tangga ukuran besar... Meskipun anggaran akademi tidak terlalu ketat, tapi untuk apa membelinya?"
  },
  AvgCommunicate_140195_Content_3 = {
    Text = "Kalau tidak salah ingat, Saya, di hari pertama kamu pindah ke Misage, kamu sudah mengajukan permohonan satu kulkas untuk asrama, kan?"
  },
  AvgCommunicate_140195_Content_4 = {
    Text = "Itu, kalau harus bilang... untuk berjaga-jaga..."
  },
  AvgCommunicate_140195_Content_5 = {
    Text = "Atau bisa dibilang, menjaga kesegaran itu penting..."
  },
  AvgCommunicate_140195_Content_7 = {
    Text = "Maaf, aku tidak bisa menyetujui lebih banyak kulkas lagi, tapi ini kontak Xu dan Dulcesein."
  },
  AvgCommunicate_140195_Content_9 = {
    Text = "Kalian seharusnya bisa berdiskusi dengan menyenangkan soal resep masakan."
  },
  AvgCommunicate_140196_Content_11 = {
    Text = "Salah lho, itu patapata!"
  },
  AvgCommunicate_140196_Content_12 = {
    Text = "Feromon yang dikembangkan Profesor Dor, sepertinya tidak berpengaruh pada Nona Moth ya."
  },
  AvgCommunicate_140196_Content_13 = {
    Text = "Tapi meskipun begitu, sikap Nona Moss terhadapku tetap sama seperti biasa."
  },
  AvgCommunicate_140196_Content_14 = {
    Text = "Itu artinya, eh, bagaimana mengatakannya ya..."
  },
  AvgCommunicate_140196_Content_15 = {
    Text = "Dalam hal tertentu, kemampuan bersosialisasinya benar-benar luar biasa ya, Moss..."
  },
  AvgCommunicate_140196_Content_2 = {
    Text = "A……Abandon, ah, ternyata ini. Hehe."
  },
  AvgCommunicate_140196_Content_3 = {Text = "?"},
  AvgCommunicate_140196_Content_4 = {
    Text = "Aku sedang belajar berbagai bahasa sekarang. ……Sangat menarik."
  },
  AvgCommunicate_140196_Content_6 = {
    Text = "Selain bahasa umum, aku juga belajar banyak hal baru lho, misalnya ini——"
  },
  AvgCommunicate_140196_Content_7 = {Text = "Guruguru?"},
  AvgCommunicate_140196_Content_8 = {
    Text = "Klap-klap-klap!"
  },
  AvgCommunicate_140196_Content_9 = {Text = "Benar!"},
  AvgCommunicate_140196_Option_8 = {
    Text = "Klap-klap-klap!"
  },
  AvgCommunicate_141374_Content_1 = {
    Text = "Ucapan terima kasih yang terlalu resmi mungkin terasa agak asing, namun, dari lubuk hatiku, terima kasih, untukku sendiri, juga untuk seluruh Epoyanis."
  },
  AvgCommunicate_141374_Content_10 = {
    Text = "Aku menunjukkan sifat-sifat itu karena memang begitulah asli diriku."
  },
  AvgCommunicate_141374_Content_12 = {
    Text = "Jangan bilang hal seperti itu dengan nada yang begitu bangga."
  },
  AvgCommunicate_141374_Content_13 = {
    Text = "Jadi, membantuku menyentuh batas itu, melepaskan diri dari kendali-Nya, sungguh merupakan pertolongan yang sangat besar bagiku."
  },
  AvgCommunicate_141374_Content_14 = {
    Text = "Banyak hal yang sebelumnya sulit dilakukan, kini bukan lagi masalah."
  },
  AvgCommunicate_141374_Content_15 = {
    Text = "Apakah masih belum terlambat jika aku menarik kembali perkataanku sekarang?"
  },
  AvgCommunicate_141374_Content_16 = {
    Text = "Tenang dulu, Pontos, Londinium memiliki sistem hukum yang lengkap!"
  },
  AvgCommunicate_141374_Content_2 = {
    Text = "Tiba-tiba jadi seserius ini, memang agak membuat orang tidak terbiasa."
  },
  AvgCommunicate_141374_Content_3 = {
    Text = "Kamu mungkin tidak tahu apa artinya ini, sebelum aku cukup kuat, Epoyanis sebenarnya tidak pernah bisa lepas dari kendali keberadaan kuno itu."
  },
  AvgCommunicate_141374_Content_4 = {
    Text = "Ini adalah kesepakatan yang kubuat dengan-Nya, untungnya, Dia tidak memiliki niat jahat, bahkan bisa dibilang murah hati."
  },
  AvgCommunicate_141374_Content_5 = {
    Text = "Namun Dia bagaimanapun juga bukan bagian dari umat manusia, di bawah kendali-Nya, Epoyanis akan semakin sulit diprediksi, dan orang-orang di Epoyanis pun akan semakin ekstrem dalam sifatnya."
  },
  AvgCommunicate_141374_Content_6 = {
    Text = "Kalau begitu, jangan-jangan kamu sebelumnya juga karena pengaruh-Nya, makanya jadi begitu, ehm…"
  },
  AvgCommunicate_141374_Content_7 = {
    Text = "Biar kutebak, kamu ingin bilang Paranoia, pendendam, atau gila kontrol?"
  },
  AvgCommunicate_141374_Content_9 = {Text = "Tidak."},
  AvgCommunicate_141374_Option_2 = {
    Text = "Agak tidak terbiasa"
  },
  AvgCommunicate_141374_Option_6 = {
    Text = "Jangan-jangan"
  },
  AvgCommunicate_143429_Content_1 = {
    Text = "Meskipun para pengikut ajaran sesat yang menyembah dewa palsu ini bodohnya menggelikan, namun harus diakui, selera sebagian dari mereka lumayan juga."
  },
  AvgCommunicate_143429_Content_10 = {
    Text = "Lagipula eranya pun tidak sesuai!"
  },
  AvgCommunicate_143429_Content_11 = {
    Text = "Menurutku, jika kamu lebih banyak menerima pengaruh semacam itu, meningkatkan semangat maju, mungkin bisa membantu mengurangi frekuensi meminta pertolongan saat dalam bahaya di lapangan."
  },
  AvgCommunicate_143429_Content_12 = {
    Text = "Tentu saja, kalau kamu mau lebih sering memanggilku paman, aku dengan senang hati akan selalu menutupi kekurangan anak kecil yang tidak punya semangat maju."
  },
  AvgCommunicate_143429_Content_13 = {
    Text = "…Aku akan pergi bicara dengan Goliath sekarang."
  },
  AvgCommunicate_143429_Content_14 = {
    Text = "Aku akan memasukkan mereka ke daftar film terlarang Mythag, tidak boleh sembarangan merekomendasikan ke orang lain!"
  },
  AvgCommunicate_143429_Content_2 = {
    Text = "Beberapa hari lalu ketika dia sering meninggalkan Mythag tanpa sepengetahuan Miryam, aku sudah sangat terkejut…"
  },
  AvgCommunicate_143429_Content_3 = {
    Text = "Yang kamu maksud bukan Goliath, kan…"
  },
  AvgCommunicate_143429_Content_4 = {
    Text = "Hmm, pertama, aku sangat mengagumi tekadnya untuk rela merendahkan diri demi mencapai tujuannya."
  },
  AvgCommunicate_143429_Content_5 = {
    Text = "Kedua, pertunjukan yang dia rekomendasikan memang sangat menarik."
  },
  AvgCommunicate_143429_Content_6 = {
    Text = "Sulit dibayangkan Goliath mau pergi ke teater."
  },
  AvgCommunicate_143429_Content_7 = {
    Text = "Dia merekomendasikan kepadaku \"Kisah Lalu Leo\", \"Pelajaran ■\", semua orang sangat menyukainya."
  },
  AvgCommunicate_143429_Content_8 = {
    Text = "Malam ini, Epoyanis seharusnya akan menayangkan \"Serigala Londinium\"."
  },
  AvgCommunicate_143429_Content_9 = {
    Text = "Bukan, tunggu dulu, Mythag tidak mengizinkan adanya bos geng, budaya serigala pun tidak boleh!"
  },
  AvgCommunicate_143429_Option_2 = {
    Text = "Yang kamu maksud jangan-jangan adalah"
  },
  AvgCommunicate_143430_Content_1 = {
    Text = "Permohonan pindah keenam bulan ini, tampaknya peraturan bagian urusan sekolah pun tidak selalu berlaku."
  },
  AvgCommunicate_143430_Content_10 = {
    Text = "Ah, sayang sekali."
  },
  AvgCommunicate_143430_Content_11 = {
    Text = "Hei?? Hah?! Kenapa ada Nightmare yang membawa selembar jawaban ujian, lalu duduk dan mulai menulis makalahku?"
  },
  AvgCommunicate_143430_Content_12 = {
    Text = "Bebanmu terlalu berat, bahkan hanya mengucapkan hal seperti itu sebagai candaan pun menunjukkan bahwa kamu seharusnya benar-benar Relaksasi, anak kecil."
  },
  AvgCommunicate_143430_Content_13 = {
    Text = "Hanya kali ini, meski aku sangat senang melakukannya, aku tetap akan berusaha untuk tidak menjadi orang tua yang memanjakan anak."
  },
  AvgCommunicate_143430_Content_14 = {
    Text = "Sekarang, buka jendelanya, aku ajak kamu bermain semalam, rasakan kesenangan melupakan kenyataan tanpa harus pergi ke Epoyanis."
  },
  AvgCommunicate_143430_Content_15 = {
    Text = "……Asyik!"
  },
  AvgCommunicate_143430_Content_3 = {
    Text = "Nilai, kehadiran, tingkat konversi praktik efektif, ehm, serta tekanan kerja yang ada pada sebagian besar pelajar biasa meski Penjaga tidak memilikinya."
  },
  AvgCommunicate_143430_Content_4 = {
    Text = "Meski Korosi Lebur sudah di depan mata, masalah nyata tetap saja menakutkan."
  },
  AvgCommunicate_143430_Content_5 = {
    Text = "Wajar saja semua orang ingin melarikan diri dari kenyataan, bagaimana kalau kamu bawa aku juga ke Epoyanis……"
  },
  AvgCommunicate_143430_Content_6 = {
    Text = "Kamu serius?"
  },
  AvgCommunicate_143430_Content_7 = {
    Text = "Apakah benar ada suara kepakan sayap di luar jendela, atau aku sudah berhalusinasi setelah belajar tiga malam berturut-turut."
  },
  AvgCommunicate_143430_Content_8 = {
    Text = "Kesempatan tidak datang dua kali, dengan peluang sebaik ini, meski setelah ini seluruh Mythag akan mencari masalah denganku, aku tetap dengan senang hati menerimanya."
  },
  AvgCommunicate_143430_Content_9 = {
    Text = "Tidak tidak tidak tidak tidak tidak aku hanya bercanda tolong jangan sekali-kali lakukan hal seperti itu."
  },
  AvgCommunicate_143431_Content_1 = {
    Text = "Ada yang perlu dicari dariku?"
  },
  AvgCommunicate_143431_Content_10 = {
    Text = "Hahahahaha, sudahlah, jangan pasang Ekspresi seperti itu."
  },
  AvgCommunicate_143431_Content_11 = {
    Text = "Mendapatkan stempel pribadinya bukan hal yang sulit, soal alamat pesta amal, bagaimana kalau di Epoyanis?"
  },
  AvgCommunicate_143431_Content_12 = {
    Text = "Langkah selanjutnya polisi akan menangkap kita semua karena melanggar properti pribadi."
  },
  AvgCommunicate_143431_Content_14 = {
    Text = "Baiklah, sayang sekali, aku akan Menghindar untuk beberapa hari."
  },
  AvgCommunicate_143431_Content_15 = {
    Text = "Membunuhnya saat dia tidak waspada mungkin akan lebih menyenangkan."
  },
  AvgCommunicate_143431_Content_16 = {Text = "¿¿¿???!"},
  AvgCommunicate_143431_Content_2 = {
    Text = "Eh, Pontos, apakah kamu mau mempertimbangkan untuk kembali ke Epoyanis untuk sementara waktu."
  },
  AvgCommunicate_143431_Content_3 = {
    Text = "Profesor Dexter sudah dua bulan penuh tidak datang ke Sekolah."
  },
  AvgCommunicate_143431_Content_4 = {
    Text = "Ha, makhluk kotor yang pengecut, sekarang mungkin sedang melampiaskan kemarahannya kepada salah satu anak buahnya yang malang."
  },
  AvgCommunicate_143431_Content_5 = {
    Text = "Tenang saja, sebelum dia Kembali ke Genesis-nya, dia belum layak menjadi lawan-ku."
  },
  AvgCommunicate_143431_Content_6 = {
    Text = "Masalahnya ada setumpuk dokumen yang masih menunggu cap pribadinya, bagaimana dengan pesta amal tahun ini! Meminta Direktur Czort dan Profesor Doll untuk menghadiri acara semacam itu lebih sulit daripada meminta mereka langsung menghancurkan Mythag."
  },
  AvgCommunicate_143431_Content_7 = {
    Text = "Kalau Guru Sylvia yang memimpin, yang perlu dikhawatirkan adalah hal lain lagi…"
  },
  AvgCommunicate_143431_Content_8 = {
    Text = "Sungguh menyedihkan, anak kecil, aku tahu, kamu dilindungi banyak orang di Mythag, tidak lagi membutuhkanku, padahal aku sudah melakukan begitu banyak untukmu, kamu bahkan……"
  },
  AvgCommunicate_145234_Content_1 = {
    Text = "Sudah tenang."
  },
  AvgCommunicate_145234_Content_10 = {
    Text = "Kalau begitu, apakah kamu tidak ingin terus bertarung lagi?"
  },
  AvgCommunicate_145234_Content_11 = {Text = "Hehehe..."},
  AvgCommunicate_145234_Content_12 = {
    Text = "Tentu saja tidak."
  },
  AvgCommunicate_145234_Content_13 = {
    Text = "Aku tidak lagi perlu bertarung untuk menenangkan tubuhku, tapi..."
  },
  AvgCommunicate_145234_Content_14 = {
    Text = "Sekarang, aku bisa lebih bebas menggunakan seluruh Kekuatanku untuk menantang mereka yang ingin kutantang!"
  },
  AvgCommunicate_145234_Content_15 = {
    Text = "Kurasa, aku harus mengucapkan terima kasih padamu."
  },
  AvgCommunicate_145234_Content_16 = {
    Text = "Kamu membawaku ke puncak yang selalu aku rindukan. Tapi..."
  },
  AvgCommunicate_145234_Content_17 = {
    Text = "Jalan Kekuatan tidak pernah ada ujungnya. Begitu bukan, Penjaga?"
  },
  AvgCommunicate_145234_Content_2 = {
    Text = "Tenang? Maksudnya apa?"
  },
  AvgCommunicate_145234_Content_3 = {
    Text = "Darah tidak lagi mendidih, tulang tidak lagi gelisah, pedangku pun tidak lagi mengaum..."
  },
  AvgCommunicate_145234_Content_4 = {
    Text = "Sejak aku lahir, semuanya tidak pernah berhenti."
  },
  AvgCommunicate_145234_Content_5 = {
    Text = "Sekarang, semuanya telah tenang."
  },
  AvgCommunicate_145234_Content_6 = {
    Text = "Apakah ini hal yang buruk?"
  },
  AvgCommunicate_145234_Content_7 = {Text = "Apa kabar?"},
  AvgCommunicate_145234_Content_8 = {
    Text = "Kebisingan itu dulu ada karena Kelaparan, karena Ketidaktenangan yang muncul akibat kurang kuat dan kurang cepat."
  },
  AvgCommunicate_145234_Content_9 = {
    Text = "Tapi sekarang semuanya menghilang. Tubuhku... untuk pertama kalinya merasa puas."
  },
  AvgCommunicate_145234_Option_6 = {
    Text = "Apakah ini hal yang buruk?"
  },
  AvgCommunicate_145234_Option_7 = {Text = "Apa kabar?"},
  AvgCommunicate_146392_Content_1 = {Text = "Ada?"},
  AvgCommunicate_146392_Content_10 = {
    Text = "Aku memberinya sejumlah uang agar dia menyerahkan pekerjaan itu kepadaku."
  },
  AvgCommunicate_146392_Content_11 = {
    Text = "Apakah kamu sudah menemukannya?"
  },
  AvgCommunicate_146392_Content_12 = {
    Text = "Dia ada di depanku. Tampaknya tidur dengan nyenyak."
  },
  AvgCommunicate_146392_Content_13 = {
    Text = "Aku sedang menunggu dia terbangun."
  },
  AvgCommunicate_146392_Content_14 = {
    Text = "Sepenuhnya mengerti…"
  },
  AvgCommunicate_146392_Content_15 = {
    Text = "Biar aku pikir, apakah ada cara untuk membuat kamu mengisi waktu…"
  },
  AvgCommunicate_146392_Content_16 = {
    Text = "Ah, aku tahu! Kamu bisa…"
  },
  AvgCommunicate_146392_Content_17 = {
    Text = "Mata bergerak… Dia akan terbangun."
  },
  AvgCommunicate_146392_Content_18 = {
    Text = "Pergi dulu."
  },
  AvgCommunicate_146392_Content_19 = {
    Text = "Hei? Lotan?"
  },
  AvgCommunicate_146392_Content_2 = {Text = "?"},
  AvgCommunicate_146392_Content_3 = {
    Text = "Lotan? Kukira kamu tidak tertarik dengan hal-hal seperti ini."
  },
  AvgCommunicate_146392_Content_4 = {
    Text = "Agak bosan, mencoba mainan mekanik yang diberikan Doll."
  },
  AvgCommunicate_146392_Content_5 = {
    Text = "Siapa tahu berguna nanti."
  },
  AvgCommunicate_146392_Content_6 = {
    Text = "Ternyata kamu juga bisa bosan?"
  },
  AvgCommunicate_146392_Content_7 = {
    Text = "Kukira kamu tidak sedang berkelahi, ya sedang dalam perjalanan untuk berkelahi."
  },
  AvgCommunicate_146392_Content_8 = {
    Text = "Ngomong-ngomong, kamu ada di mana? Sepertinya sudah beberapa hari aku tidak melihatmu…"
  },
  AvgCommunicate_146392_Content_9 = {
    Text = "Katanya Daffodil sedang memburu keberadaan kuno yang sangat kuat."
  },
  AvgCommunicate_146392_Option_14 = {
    Text = "Sepenuhnya mengerti…"
  },
  AvgCommunicate_146392_Option_6 = {
    Text = "Ternyata kamu juga bisa bosan?"
  },
  AvgCommunicate_146393_Content_1 = {
    Text = "Tanduk. Gigi. Cakar. Potongan daging. Bola mata. Tentakel."
  },
  AvgCommunicate_146393_Content_10 = {
    Text = "Semoga kamu juga bisa sekuat itu."
  },
  AvgCommunicate_146393_Content_12 = {
    Text = "Terima kasih banyak!"
  },
  AvgCommunicate_146393_Content_2 = {
    Text = "Pilih satu."
  },
  AvgCommunicate_146393_Content_3 = {
    Text = "Ini lagi segmen tebak kesukaanmu?…"
  },
  AvgCommunicate_146393_Content_4 = {
    Text = "Aku membawa pulang monster yang kuburu terakhir kali."
  },
  AvgCommunicate_146393_Content_5 = {
    Text = "Toh tidak ada tempat untuk menyimpannya, kuberikan sedikit untukmu sebagai kenang-kenangan."
  },
  AvgCommunicate_146393_Content_6 = {
    Text = "Kedengarannya tidak ada yang ingin kuambil…"
  },
  AvgCommunicate_146393_Content_7 = {
    Text = "Apakah tidak apa-apa kalau ingin semuanya…"
  },
  AvgCommunicate_146393_Content_8 = {
    Text = "Susah memilih… Bagaimana kalau kamu saja yang memilih…"
  },
  AvgCommunicate_146393_Content_9 = {
    Text = "Tanduknya lumayan, butuh tiga tebasan pedangku untuk memutusnya, sangat cocok untukmu."
  },
  AvgCommunicate_146393_Option_6 = {
    Text = "Kedengarannya tidak ada yang ingin kuambil…"
  },
  AvgCommunicate_146393_Option_7 = {
    Text = "Apakah tidak apa-apa kalau ingin semuanya…"
  },
  AvgCommunicate_146394_Content_1 = {
    Text = "Aku mengalami masalah."
  },
  AvgCommunicate_146394_Content_10 = {
    Text = "Aku sudah pergi tiga kali. Setiap kali aku pergi mereka mulai mengorbankan diri sendiri, mereka menganggap itu semacam ujian dari dewa."
  },
  AvgCommunicate_146394_Content_11 = {
    Text = "Sekumpulan orang gila."
  },
  AvgCommunicate_146394_Content_12 = {
    Text = "Kenapa kamu malah kembali lagi??"
  },
  AvgCommunicate_146394_Content_13 = {
    Text = "Pedangku tertancap di bangkai makhluk itu dan belum kucabut."
  },
  AvgCommunicate_146394_Content_14 = {
    Text = "Sekarang pedang itu pun sudah dipuja-puja oleh mereka."
  },
  AvgCommunicate_146394_Content_16 = {
    Text = "Aku butuh cara untuk membuat mereka mengembalikan pedangku, sekaligus mencegah mereka bunuh diri bersama di hadapanku."
  },
  AvgCommunicate_146394_Content_17 = {
    Text = "Kamu lebih memahami cara berpikir makhluk lemah seperti itu, bantu aku pikirkan."
  },
  AvgCommunicate_146394_Content_18 = {
    Text = "……Maksud kamu apa, Hei!"
  },
  AvgCommunicate_146394_Content_2 = {
    Text = "Langka sekali, kamu juga bisa punya masalah rupanya!"
  },
  AvgCommunicate_146394_Content_3 = {
    Text = "Katanya ada serangga yang sangat kuat, lalu aku membunuhnya."
  },
  AvgCommunicate_146394_Content_4 = {
    Text = "Setelah ia mati, orang-orang dari planet di bawah kakinya semua berlarian keluar."
  },
  AvgCommunicate_146394_Content_5 = {
    Text = "Orang-orang itu memanggilku dewa, berlutut menyembahku, bahkan membuatkan patung emas untukku, jelek sekali."
  },
  AvgCommunicate_146394_Content_6 = {
    Text = "Hahahahahaha"
  },
  AvgCommunicate_146394_Content_7 = {
    Text = "Jangan tertawa."
  },
  AvgCommunicate_146394_Content_8 = {
    Text = "Kamu langsung pergi saja tidak bisa?"
  },
  AvgCommunicate_146394_Content_9 = {
    Text = "Kamu tidak suka disembah?"
  },
  AvgCommunicate_146394_Option_6 = {Text = "Hahahahaha"},
  AvgCommunicate_146394_Option_8 = {
    Text = "Tidak bisa langsung pergi saja?"
  },
  AvgCommunicate_146394_Option_9 = {
    Text = "Tidak suka disembah?"
  },
  AvgCommunicate_148438_Content_1 = {
    Text = "Kamu sudah tahu semuanya?"
  },
  AvgCommunicate_148438_Content_10 = {
    Text = "Hehe, jangan terlalu banyak berpikir, kalau terlalu banyak berpikir nanti jadi orang yang membosankan dan tidak menyenangkan~"
  },
  AvgCommunicate_148438_Content_11 = {
    Text = "Tentu saja, jika Penjaga juga tak bisa menahan diri untuk tertarik pada peri agung ini, ingin mengikuti langkah peri agung ini setiap saat, hanya demi mendapatkan ketulusan sang peri, itu pun adalah hal yang wajar~"
  },
  AvgCommunicate_148438_Content_12 = {Text = "Ih……"},
  AvgCommunicate_148438_Content_13 = {
    Text = "Apel gula yang paling manis sudah diletakkan di atas meja asrama Anda."
  },
  AvgCommunicate_148438_Content_14 = {
    Text = "Anda harus, harus benar-benar, menikmatinya perlahan-lahan, menganalisisnya dengan seksama, dan menikmatinya sendiri ya~"
  },
  AvgCommunicate_148438_Content_2 = {
    Text = "Jadi, kamu bersusah payah mendapatkan izin keluar, hanya untuk membelikan Aigis, Ogier, dan Murphy apel gula edisi terbatas yang kata mereka belum pernah mereka makan?"
  },
  AvgCommunicate_148438_Content_3 = {
    Text = "Bocah kecil… ehm ehm, anak-anak yang saleh meski tidak membayar iuran penuh, namun memainkan peran yang sangat penting dalam proses sang peri menyebarkan berkah."
  },
  AvgCommunicate_148438_Content_4 = {
    Text = "Belajar menjaga para pengikut sendiri, membuat mereka lebih aktif menyebarkan kabar baik gereja, tentu saja juga merupakan salah satu tanggung jawab yang dipikul sang peri ini~"
  },
  AvgCommunicate_148438_Content_5 = {
    Text = "Meskipun kali ini ada alasan yang sah, kenapa harus menggunakan uang dari rekeningku……"
  },
  AvgCommunicate_148438_Content_7 = {
    Text = "Jangan terlalu memperhatikan detail kecil seperti itu, lihat, anak-anak sekarang sudah percaya sepenuhnya, kapan Penjaga akhirnya mau bergabung bersama mereka?"
  },
  AvgCommunicate_148438_Content_9 = {
    Text = "Sungguh tidak tahu apakah kamu sesekali menunjukkan sedikit ketulusan, atau seperti bawang, selalu menyembunyikan tujuan sebenarnya lapis demi lapis……"
  },
  AvgCommunicate_148439_Content_1 = {Text = "\"Gambar\""},
  AvgCommunicate_148439_Content_10 = {
    Text = "\"Gambar berhasil dimuat\""
  },
  AvgCommunicate_148439_Content_11 = {Text = "\"Gambar\""},
  AvgCommunicate_148439_Content_12 = {
    Text = "Apa… ini benar-benar surat permintaan maaf…"
  },
  AvgCommunicate_148439_Content_13 = {
    Text = "Maaf… Caraboo, aku tidak seharusnya memberikan reaksi seperti ini di saat kamu dengan langkanya benar-benar merenungkan diri."
  },
  AvgCommunicate_148439_Content_14 = {
    Text = "Aku akan langsung membatalkan laporan yang baru saja aku ajukan, usul larangan keluar… menolak semua permohonan keluar… selesai! Semua laporan yang sebelumnya aku ajukan terhadapmu sudah dibatalkan."
  },
  AvgCommunicate_148439_Content_15 = {
    Text = "Syukurlah~ hehe, Penjaga, aku ingat setelah membatalkan laporan, dalam satu bulan tidak bisa mengajukan laporan kedua terhadap Awakener yang sama kan?"
  },
  AvgCommunicate_148439_Content_17 = {
    Text = "Aku punya firasat buruk."
  },
  AvgCommunicate_148439_Content_18 = {
    Text = "Aduh, masa sang peri mau mempermainkan ketulusan hati %player%, setiap kata dalam surat permintaan maaf itu adalah kata-kata yang tulus, setelah aku kembali dari luar, pasti akan kubawakan apel merah paling manis untukmu~"
  },
  AvgCommunicate_148439_Content_19 = {
    Text = "Tunggu, kenapa Aigis datang padaku sambil menangis bilang meski tidak tahu kesalahan apa yang dia perbuat, tapi berharap aku bisa memaafkannya setelah melihat surat permintaan maaf itu."
  },
  AvgCommunicate_148439_Content_2 = {
    Text = "Memuat……"
  },
  AvgCommunicate_148439_Content_20 = {
    Text = "Dan kamu berjanji membantunya menyampaikan surat itu, tapi dia demi memastikan aku tidak marah padanya memutuskan untuk meminta maaf langsung sekali lagi?!"
  },
  AvgCommunicate_148439_Content_21 = {
    Text = "Hei, Caraboo, Caraboo!!"
  },
  AvgCommunicate_148439_Content_3 = {Text = "?"},
  AvgCommunicate_148439_Content_4 = {
    Text = "Caraboo, trik ini sudah kamu pakai sekali, apapun yang kamu katakan aku tidak akan membuka gambar itu."
  },
  AvgCommunicate_148439_Content_5 = {
    Text = "Tidak, %player%… aku sudah benar-benar merenungkan diri, kamu dan semua orang di Mythag sudah begitu baik padaku, aku sungguh tidak seharusnya membawa kebiasaan buruk dari luar ke tanah suci ini."
  },
  AvgCommunicate_148439_Content_6 = {
    Text = "Lagipula, awalnya aku tidak melakukan ini atas kemauanku sendiri."
  },
  AvgCommunicate_148439_Content_7 = {
    Text = "Jadi aku dengan sungguh-sungguh menulis surat permintaan maaf, ditulis tangan satu per satu oleh diriku sendiri lho, tak disangka sungguh tidak beruntung, komunikasi Perak kebetulan mengalami gangguan tepat di saat itu…"
  },
  AvgCommunicate_148439_Content_8 = {
    Text = "Wajar jika kamu tidak mau mempercayaiku, aku akan menunggu dengan sabar, menunggu hari di mana kamu bersedia kembali memberikan kepercayaanmu padaku…"
  },
  AvgCommunicate_148439_Content_9 = {
    Text = "…kenapa hatiku terasa sedikit perih, tapi bagaimanapun aku sama sekali tidak akan…"
  },
  AvgCommunicate_148440_Content_1 = {Text = "\"Gambar\""},
  AvgCommunicate_148440_Content_10 = {
    Text = "Apa yang kamu bicarakan! Mana mungkin dikembalikan?"
  },
  AvgCommunicate_148440_Content_11 = {Text = "Hah?"},
  AvgCommunicate_148440_Content_12 = {
    Text = "Bahkan tidak berpura-pura lagi?"
  },
  AvgCommunicate_148440_Content_13 = {
    Text = "Hehe, melayani peri suci itu sendiri sudah merupakan kemuliaan terbesarmu, yang akan membimbingmu menuju surga tertinggi, dibandingkan dengan itu, imbalan duniawi tentu tidak ada artinya."
  },
  AvgCommunicate_148440_Content_14 = {
    Text = "Sudahlah jangan bicara soal itu, kalau tidak cepat transfer, peta tidak bisa dipulihkan lagi."
  },
  AvgCommunicate_148440_Content_16 = {
    Text = "Aku sudah membukanya dan melihatnya, ini tidak lebih dari Teknologi chip perak pemalsuan gambar yang murahan……"
  },
  AvgCommunicate_148440_Content_17 = {
    Text = "Eh? Kamu membukanya? Ini adalah pilihanmu sendiri lho~ Luar biasa! Peri suci akan selalu mengingat persembahan %player%."
  },
  AvgCommunicate_148440_Content_18 = {
    Text = "Tunggu, kenapa ada notifikasi bahwa 1000 Léofang-ku terpotong, itu tunjangan lapanganku!"
  },
  AvgCommunicate_148440_Content_2 = {
    Text = "Memuat……"
  },
  AvgCommunicate_148440_Content_20 = {
    Text = "Baiklah, baiklah, tidak menyangka kamu cukup kaya juga ya, kali ini hanya akan diambil 200 Léofang saja, sebagai imbalan atas kebaikan hati mendidikmu agar tidak membuka Teknologi chip perak komunikator yang tidak dikenal, harus benar-benar bersyukur atas belas kasihan peri suci, ya?"
  },
  AvgCommunicate_148440_Content_21 = {
    Text = "\"Transfer·800 Léofang\""
  },
  AvgCommunicate_148440_Content_3 = {
    Text = "\"Gambar rusak\""
  },
  AvgCommunicate_148440_Content_4 = {
    Text = "……Apa yang kamu kirim?"
  },
  AvgCommunicate_148440_Content_5 = {Text = "Aduh!"},
  AvgCommunicate_148440_Content_6 = {
    Text = "Ini benar-benar buruk, di dalamnya ada peta wilayah timur yang didapatkan dengan susah payah oleh umat setia peri suci, dan file aslinya juga ikut rusak, pasti ada kekuatan @2 jahat yang menghalangi kita untuk pergi ke timur!"
  },
  AvgCommunicate_148440_Content_7 = {
    Text = "%player%l, berapa banyak Léofang yang kamu punya? Cepat berikan semuanya padaku, masih ada harapan untuk memulihkannya……"
  },
  AvgCommunicate_148440_Content_8 = {
    Text = "Nanti dikembalikan sepuluh kali lipat setelah sampai di timur, ya? Trik seperti ini sudah terlalu umum di Mythag."
  },
  AvgCommunicate_148440_Content_9 = {
    Text = "Penipuan yang tidak mengikuti perkembangan zaman tidak akan punya masa depan."
  },
  AvgCommunicate_149803_Content_1 = {
    Text = "Tugas pengawalan yang sebelumnya diberikan akademi kepadaku telah selesai. Apakah ada hal yang perlu kulakukan untuk Tuan?"
  },
  AvgCommunicate_149803_Content_10 = {
    Text = "Bagaimanapun, jika kamu tidak mau berdiam diri, beberapa hari lagi akan ada banyak kegiatan di sekolah, mau ikut bermain-main?"
  },
  AvgCommunicate_149803_Content_11 = {
    Text = "…Karena ini perintah Tuan, aku akan mengikutinya."
  },
  AvgCommunicate_149803_Content_12 = {
    Text = "Aku akan pergi berpatroli sekarang."
  },
  AvgCommunicate_149803_Content_13 = {
    Text = "Semoga kamu benar-benar akan mengikutinya nanti!"
  },
  AvgCommunicate_149803_Content_2 = {
    Text = "Tidakkah kamu ingin beristirahat sejenak?"
  },
  AvgCommunicate_149803_Content_3 = {
    Text = "Tidak perlu."
  },
  AvgCommunicate_149803_Content_4 = {
    Text = "Lagipula… aku tidak berhak untuk menikmati ketenangan seperti itu."
  },
  AvgCommunicate_149803_Content_5 = {
    Text = "Bayangan hitam itu masih sesekali menggangguku di telingaku."
  },
  AvgCommunicate_149803_Content_6 = {
    Text = "Mungkin justru ketika ada pekerjaan di tangan, aku malah merasa lebih tenang."
  },
  AvgCommunicate_149803_Content_7 = {
    Text = "Hanya itu saja, Tuan tidak perlu mengkhawatirkannya."
  },
  AvgCommunicate_149803_Content_8 = {
    Text = "Mungkin aku perlu mengajarkan pentingnya bersantai sejenak."
  },
  AvgCommunicate_149803_Content_9 = {
    Text = "Lebih banyak bersantai agar bisa bertarung dengan lebih baik."
  },
  AvgCommunicate_149803_Option_8 = {
    Text = "Mungkin aku perlu mengajarkan pentingnya bersantai sejenak."
  },
  AvgCommunicate_149803_Option_9 = {
    Text = "Lebih banyak bersantai agar bisa bertarung dengan lebih baik."
  },
  AvgCommunicate_149950_Content_10 = {
    Text = "Hmph......apakah kamu sedang mengejekku? Ini sudah batas maksimal yang bisa kulakukan untuk mengendalikan tubuh ini sekarang!"
  },
  AvgCommunicate_149950_Content_11 = {
    Text = "Apa yang ingin kamu lakukan? Terus memprovokasi dan mengendalikannya?"
  },
  AvgCommunicate_149950_Content_12 = {
    Text = "Kalau aku bisa melakukannya, sudah dari tadi......"
  },
  AvgCommunicate_149950_Content_13 = {
    Text = "Sudahlah, daripada menjadi pisau tajam, menjadi perisai atau benteng sepertinya juga tidak buruk......"
  },
  AvgCommunicate_149950_Content_14 = {
    Text = "Adapun tuan yang ia percayai dan ia abdikan—kamu, setelah berinteraksi, ternyata cukup menarik juga."
  },
  AvgCommunicate_149950_Content_15 = {
    Text = "Aku mengerti sekarang, kamu sudah terpengaruh balik oleh Ogier, bukan?"
  },
  AvgCommunicate_149950_Content_17 = {Text = "???"},
  AvgCommunicate_149950_Content_18 = {
    Text = "Tuan, mohon maaf. Aku tiba-tiba kehilangan kesadaran beberapa menit tadi."
  },
  AvgCommunicate_149950_Content_19 = {
    Text = "Setelah sadar kembali, aku melihat alat komunikasi sedang menyala."
  },
  AvgCommunicate_149950_Content_2 = {
    Text = "Akhirnya aku bisa menemuimu......"
  },
  AvgCommunicate_149950_Content_20 = {
    Text = "Entah kenapa, rasanya tadi aku kembali mendengar suara menjengkelkan itu setelah sekian lama......"
  },
  AvgCommunicate_149950_Content_21 = {
    Text = "Bagaimana ya......sepertinya kamu dan kekuatan yang ada padamu sudah bisa hidup berdampingan dengan sangat harmonis."
  },
  AvgCommunicate_149950_Content_22 = {
    Text = "......Aku sudah membaca catatannya."
  },
  AvgCommunicate_149950_Content_23 = {
    Text = "Aku masih khawatir, Dia akan seperti dulu, mengucapkan kata-kata jahat dan penuh permusuhan."
  },
  AvgCommunicate_149950_Content_24 = {
    Text = "Sungguh mengejutkan, dulu selalu akulah yang tergerus oleh-Nya, namun kini tampaknya berbalik."
  },
  AvgCommunicate_149950_Content_25 = {
    Text = "Ini seharusnya kabar baik. Setidaknya... ini membuktikan bahwa aku telah sepenuhnya mengalahkan-Nya."
  },
  AvgCommunicate_149950_Content_26 = {
    Text = "Tentu saja, apakah karena peningkatan kekuatan Ogier, sehingga penguasaan terhadap sesuatu yang tak kasat mata ini bisa mencapai tingkat seperti ini?"
  },
  AvgCommunicate_149950_Content_27 = {
    Text = "Hmm, pasti begitu. Ini pasti juga merupakan perubahan yang terjadi karena Anda."
  },
  AvgCommunicate_149950_Content_28 = {
    Text = "Dan, bagi diriku, \"Hukum Akhir\" yang kupahami bukan sekadar kekuatan......"
  },
  AvgCommunicate_149950_Content_29 = {
    Text = "Ada pula keyakinan untuk melindungi orang lain ini, yang kini membara di dadaku jauh lebih kuat dari biasanya. Kurasa, inilah akar sesungguhnya."
  },
  AvgCommunicate_149950_Content_3 = {
    Text = "Kamu bukan Ogier, kamu siapa?"
  },
  AvgCommunicate_149950_Content_4 = {
    Text = "Kembalikan alat komunikasi itu kepada pemiliknya!"
  },
  AvgCommunicate_149950_Content_5 = {
    Text = "Sungguh menggelikan, tanpa keberadaanku, bagaimana anak ini bisa bertahan hidup, dan bagaimana ia bisa tinggal di sini sebagai Awakener?"
  },
  AvgCommunicate_149950_Content_6 = {
    Text = "Kamu adalah......sesuatu yang tak kasat mata yang menempel padanya?"
  },
  AvgCommunicate_149950_Content_7 = {
    Text = "Tepat sekali. Wahai Penjaga Mythag, ternyata kamu tidak mengenaliku."
  },
  AvgCommunicate_149950_Content_8 = {
    Text = "Eh......karena kamu selalu ditekan habis-habisan oleh Ogier, aku sama sekali belum pernah melihatmu."
  },
  AvgCommunicate_149950_Option_3 = {
    Text = "Kamu bukan Ogier, kamu siapa?"
  },
  AvgCommunicate_149950_Option_4 = {
    Text = "Kembalikan alat komunikasi itu kepada pemiliknya!"
  },
  AvgCommunicate_149986_Content_1 = {
    Text = "Tuan, saya datang untuk mengundang Anda."
  },
  AvgCommunicate_149986_Content_10 = {
    Text = "...... Sebuah pohon."
  },
  AvgCommunicate_149986_Content_11 = {Text = "Hah?"},
  AvgCommunicate_149986_Content_12 = {
    Text = "Mungkin karena saya sudah terlatih secara profesional, sehingga tidak peduli sekacau apa pun, saya tetap bisa berdiri kokoh di atas panggung."
  },
  AvgCommunicate_149986_Content_13 = {
    Text = "Memangnya apa yang akan terjadi dalam pertunjukan kalian!"
  },
  AvgCommunicate_149986_Content_14 = {
    Text = "Saya tidak tahu, saya hanyalah sebuah pohon."
  },
  AvgCommunicate_149986_Content_15 = {
    Text = "...... Baiklah, dalam pertunjukan itu, Jenkin yang memerankan putri akan turun dari langit, sementara Lily yang memerankan pangeran harus menangkapnya."
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "Aigis yang memerankan raja iblis juga akan turun panggung untuk berinteraksi dengan penonton."
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "Saya sudah tidak ingin berkomentar soal pembagian peran ini..."
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "Tapi, bukankah ini namanya spoiler?"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "Karena, saya tidak ingin menyembunyikan apa pun dari Anda."
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "Klub teater akan mementaskan sebuah drama dongeng, dan mengajak para Awakener yang masih di bawah umur dari Mythag untuk tampil bersama."
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "Dan lagi, berdasarkan jalannya latihan, setiap kali selalu ada kejadian tak terduga yang berbeda, jadi saya pun tidak bisa menjamin apa yang sebenarnya akan Tuan saksikan."
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "...... Kalau begitu, itu memang benar-benar membuat penasaran."
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "Tindakan-tindakan dalam pertunjukan ini semuanya mengandung tingkat bahaya tertentu."
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "Oleh karena itu, sambil memerankan pohon, aku perlu memperhatikan kondisi di atas dan di bawah panggung semaksimal mungkin, demi memastikan keselamatan para aktor dan penonton."
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "Ternyata kamu sebenarnya pergi bekerja paruh waktu sebagai pengawal... kedengarannya sangat melelahkan."
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "Ya. Bagaimanapun juga, mohon tenang. Selama aku masih berada di atas panggung, aku tidak akan membiarkan siapa pun terluka lagi."
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "Agak sulit untuk diucapkan... saya pun akan naik panggung. Saya berharap Anda datang untuk menyaksikannya."
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "! Saya sangat menantikannya."
  },
  AvgCommunicate_149986_Content_5 = {
    Text = "Tapi, tidak menyangka kamu mau setuju untuk ikut dalam acara seperti ini."
  },
  AvgCommunicate_149986_Content_6 = {
    Text = "Hmm, saya sudah bukan anak kecil lagi, jadi sebenarnya kurang cocok untuk ikut serta."
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "Namun, mereka bersikeras meminta..."
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "Saya tidak ingin mengecewakan mereka, dan selain itu, saya menyadari bahwa peran ini memang hanya bisa dimainkan oleh saya."
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "Jadi, peran apa yang akan dimainkan Ogier? Ksatria?"
  },
  AvgCommunicate_149987_Content_1 = {
    Text = "Tuan, apakah belakangan ini ada kelas yang berkaitan dengan Fenomena-d?"
  },
  AvgCommunicate_149987_Content_10 = {
    Text = "Sungguh rajin belajar... Kalau aku serajin kamu, pasti aku tidak perlu khawatir soal ujian."
  },
  AvgCommunicate_149987_Content_11 = {
    Text = "Tolong jangan memuji aku seperti itu, tanggung jawab yang Anda emban jauh lebih berat dariku."
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "Lagipula, ini hanyalah pekerjaan rumah yang perlu kulakukan sebagai penebusan dosa."
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "Tapi kamu belajar dengan cepat, siapa tahu Ogier juga punya potensi untuk menjadi seorang cendekiawan."
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "Seperti yang dipikirkan setiap orang sewaktu kecil, tentang topik masa depan."
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "Apakah Ogier pernah memikirkan ingin menjadi apa setelah dewasa?"
  },
  AvgCommunicate_149987_Content_16 = {
    Text = "Anda tahu bahwa aku telah menjadi Awakener, tidak ada lagi kemungkinan bagiku untuk tumbuh dewasa."
  },
  AvgCommunicate_149987_Content_17 = {
    Text = "Tapi kamu tetap bisa membayangkan rencana ke depannya! Tidak perlu sepesimis itu."
  },
  AvgCommunicate_149987_Content_18 = {
    Text = "Apakah Ogier tidak punya hal lain yang ingin dilakukan selain \"melindungi orang lain\"?"
  },
  AvgCommunicate_149987_Content_19 = {
    Text = "Terima kasih atas dorongan semangat Anda."
  },
  AvgCommunicate_149987_Content_2 = {
    Text = "Aku ingin mempelajarinya lebih dalam."
  },
  AvgCommunicate_149987_Content_20 = {
    Text = "Soal hal lain yang ingin kulakukan... Maaf, ternyata aku tidak bisa memikirkannya."
  },
  AvgCommunicate_149987_Content_21 = {
    Text = "Setelah tubuh ini tidak lagi dipenuhi dosa, baru aku akan memikirkannya."
  },
  AvgCommunicate_149987_Content_3 = {
    Text = "Ada, ada. Nanti aku ajak kamu pergi bersama."
  },
  AvgCommunicate_149987_Content_4 = {
    Text = "Tapi, kenapa Ogier tiba-tiba ingin mempelajari hal ini?"
  },
  AvgCommunicate_149987_Content_5 = {
    Text = "Karena hari ini ada seseorang yang bertanya kepadaku, apakah kekuatan yang menyelimuti tubuhku ada hubungannya dengan Lumpur Hitam."
  },
  AvgCommunicate_149987_Content_6 = {
    Text = "Begitu ya, kalau dilihat dari bentuknya saja, memang agak mirip."
  },
  AvgCommunicate_149987_Content_7 = {
    Text = "Ya, aku juga selalu penasaran dengan hakikat sesuatu yang tak kasat mata ini. Mungkin setelah cukup memahaminya, aku bisa lebih baik dalam mengendalikan-Nya."
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "Meski begitu, setelah datang ke Mythag baru aku sadari, keberadaan yang sulit dipahami jauh lebih banyak dari yang kubayangkan......"
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "Maka aku memutuskan untuk lebih banyak mempelajari pengetahuan terkait fusi terlebih dahulu, bagaimanapun ini juga musuh yang telah lama dilawan oleh Tuan."
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "Anjing kecilku yang nakal, yang selalu berkeliaran ke mana-mana."
  },
  AvgCommunicate_149988_Content_10 = {
    Text = "Tidak ada yang peduli."
  },
  AvgCommunicate_149988_Content_11 = {
    Text = "Bagaimanapun, jangan lupa, kamu adalah anjing peliharaan pribadiku, ancaman terhadap nyawamu berarti kerugian asetku."
  },
  AvgCommunicate_149988_Content_12 = {
    Text = "Selain itu, ini adalah celah yang aku pilih dengan cermat, yang tidak tergerus oleh erosi."
  },
  AvgCommunicate_149988_Content_13 = {
    Text = "Hati-hati, jangan sampai menghancurkan dunia ini."
  },
  AvgCommunicate_149988_Content_2 = {
    Text = "Sinyal mulai putus-putus lagi, kamu pergi ke daerah terpencil mana sekarang?"
  },
  AvgCommunicate_149988_Content_3 = {
    Text = "Aku di Benua Utara."
  },
  AvgCommunicate_149988_Content_4 = {
    Text = "Aku di dataran tinggi."
  },
  AvgCommunicate_149988_Content_5 = {
    Text = "Selanjutnya akan bersiap mendaki gunung. Aku sangat khawatir dengan kondisi fisikku."
  },
  AvgCommunicate_149988_Content_6 = {
    Text = "Udara di dataran tinggi memang sangat tipis, rasanya baru berlari beberapa langkah saja aku sudah hampir kehabisan napas."
  },
  AvgCommunicate_149988_Content_7 = {
    Text = "Dengan kondisi seperti itu kamu masih mau mendaki gunung? Sungguh anjing kecil yang ceroboh dan tidak tahu diri."
  },
  AvgCommunicate_149988_Content_8 = {
    Text = "Aku tahu kamu peduli padaku, tapi ada hal yang harus aku selesaikan."
  },
  AvgCommunicate_149988_Content_9 = {
    Text = "Tenang saja, Senior William juga ada di sini, kami tidak akan dalam bahaya."
  },
  AvgCommunicate_149988_Option_3 = {
    Text = "Benua Utara."
  },
  AvgCommunicate_149988_Option_4 = {
    Text = "Dataran tinggi."
  },
  AvgCommunicate_150103_Content_1 = {
    Text = "Aku merasakan dari ujung yang jauh, benang takdir mengirimkan getaran halus."
  },
  AvgCommunicate_150103_Content_10 = {
    Text = "Apakah ini bagian dari takdir?"
  },
  AvgCommunicate_150103_Content_11 = {
    Text = "Aku harus tutup mulut."
  },
  AvgCommunicate_150103_Content_12 = {
    Text = "Lalu bagaimana dengan orang-orang di dunia asal itu? Apa yang akan terjadi pada mereka?"
  },
  AvgCommunicate_150103_Content_13 = {
    Text = "Mereka akan kembali ke wujud murni — Perak."
  },
  AvgCommunicate_150103_Content_14 = {
    Text = "Dan sang Raja Dewa itu akan memungut serpihan-serpihan ini dari balik tirai hujan, lalu setelah melewati tidur panjang, membentuk kembali dunia."
  },
  AvgCommunicate_150103_Content_15 = {
    Text = "Aku akan menyaksikannya bersamamu."
  },
  AvgCommunicate_150103_Content_2 = {
    Text = "Kurasa, kau telah melewati simpul takdir dan tiba di tanah yang dijanjikan yang telah lama kau cari."
  },
  AvgCommunicate_150103_Content_3 = {
    Text = "Aku tak percaya."
  },
  AvgCommunicate_150103_Content_4 = {
    Text = "Dunia menghilang."
  },
  AvgCommunicate_150103_Content_5 = {
    Text = "Aku melihat langit meleleh, salju runtuh, puncak-puncak hancur berantakan."
  },
  AvgCommunicate_150103_Content_6 = {
    Text = "Mereka adalah kepalsuan sejati."
  },
  AvgCommunicate_150103_Content_7 = {
    Text = "Kau selalu tahu, kau selalu bisa melihatnya?"
  },
  AvgCommunicate_150103_Content_8 = {
    Text = "Aku selalu berdiri di luar panggung dunia, menenun tanpa henti."
  },
  AvgCommunicate_150103_Content_9 = {
    Text = "Termasuk keinginan Caraboo? Bagaimanapun, tanpa permohonannya, dunia tidak akan lenyap."
  },
  AvgCommunicate_150103_Option_3 = {
    Text = "Aku melihat…"
  },
  AvgCommunicate_150103_Option_4 = {
    Text = "Dunia menghilang…"
  },
  AvgCommunicate_57593_Content_1 = {
    Text = "Partner, buku-buku tentang sejarah dan ilmu alam yang kubawakan untukmu terakhir kali sudah selesai dibaca semua?"
  },
  AvgCommunicate_57593_Content_10 = {
    Text = "Hah? Perlu seserius itu..."
  },
  AvgCommunicate_57593_Content_11 = {
    Text = "Ini semua adalah buku wajib baca untuk penyelidik. Mau hafal mati pun kamu harus mempelajarinya."
  },
  AvgCommunicate_57593_Content_12 = {
    Text = "Aku berencana memberimu les tambahan satu jam setiap hari. Kalau kamu ingin cepat selesai, aku juga tidak keberatan menemanimu begadang membaca buku."
  },
  AvgCommunicate_57593_Content_13 = {
    Text = "Pe-pelan saja deh... Menurutku satu jam sudah cukup! Belajar terlalu banyak tidak baik untuk mengulang dan memantapkan materi!"
  },
  AvgCommunicate_57593_Content_14 = {
    Text = "Bagus, sikap belajarmu sangat baik."
  },
  AvgCommunicate_57593_Content_15 = {
    Text = "Ingat bawa buku catatan, aku akan memeriksa hasil reviewmu kapan saja."
  },
  AvgCommunicate_57593_Content_17 = {
    Text = "Aku benci mulut bodohku ini..."
  },
  AvgCommunicate_57593_Content_2 = {
    Text = "Ehm, itu, anu, bisa dibilang sudah... dibaca."
  },
  AvgCommunicate_57593_Content_3 = {
    Text = "Sudah baca berapa banyak?"
  },
  AvgCommunicate_57593_Content_4 = {
    Text = "Kira-kira, sudah baca... daftar isinya."
  },
  AvgCommunicate_57593_Content_6 = {
    Text = "Buku-buku itu terlalu tebal dan membosankan! Begitu melihat tulisan yang rapat-rapat langsung ketiduran..."
  },
  AvgCommunicate_57593_Content_7 = {
    Text = "Setiap kali sehabis baca buku, kualitas tidurku memang jadi sangat baik sih..."
  },
  AvgCommunicate_57593_Content_8 = {
    Text = "Ya sudahlah, nanti kamu datang ke tempatku, akan kujelaskan satu per satu."
  },
  AvgCommunicate_57593_Content_9 = {
    Text = "Setiap hari setelah kelas selesai, datanglah ke asramaku untuk laporan."
  },
  AvgCommunicate_57593_Option_10 = {
    Text = "Hah? Perlu seserius itu..."
