  AvgCommunicate_57594_Content_1 = {
    Text = "Partner, ini catatan pelajaran dan tugas yang kamu lewatkan saat menjalankan misi kemarin."
  },
  AvgCommunicate_57594_Content_10 = {Text = "Kan?!"},
  AvgCommunicate_57594_Content_12 = {
    Text = "Tidak masalah, ini sudah seharusnya dilakukan sebagai partner."
  },
  AvgCommunicate_57594_Content_13 = {
    Text = "Guru Doer juga sangat senang, dan memutuskan untuk merancang satu set soal tambahan eksklusif untukmu lho."
  },
  AvgCommunicate_57594_Content_2 = {
    Text = "Ingat untuk menyusulkan pengumpulannya."
