  },
  AvgCommunicate_57594_Content_6 = {
    Text = "Oh ya? Lupa bilang, Guru Doer ada di sampingku dan sedang memperhatikan lho."
  },
  AvgCommunicate_57594_Content_7 = {
    Text = "Tiba-tiba muncul semangat belajar yang membara."
  },
  AvgCommunicate_57594_Content_8 = {
    Text = "Ternyata ada tugas yang tertinggal, mana bisa aku diam saja?"
