  },
  AvgCommunicate_57595_Content_10 = {
    Text = "Aku akan menulis surat tantangan duel dan mengirimkannya ke asrama semua orang. Pasti cukup sopan kan."
  },
  AvgCommunicate_57595_Content_11 = {
    Text = "Sudah diputuskan, menulis empat puluh lembar cukup tidak ya……"
  },
  AvgCommunicate_57595_Content_12 = {
    Text = "?! Tunggu, masalahnya bukan soal surat tantangan duel! Ini terlalu mengganggu orang lain!"
  },
  AvgCommunicate_57595_Content_13 = {
    Text = "Kamu tidak mengerti. Aku pernah dengar dari Dexter, di masa lalu bertarung melalui surat tantangan duel itu perilaku seorang gentleman. Belajarlah, anak muda!"
  },
  AvgCommunicate_57595_Content_14 = {
    Text = "Bukan, kamu, aku, pokoknya jangan pergi aaaaah!"
  },
  AvgCommunicate_57595_Content_2 = {Text = "?"},
  AvgCommunicate_57595_Content_3 = {
    Text = "Kenapa semua orang tidak mau berlatih tanding denganku lagi?"
  },
  AvgCommunicate_57595_Content_4 = {
    Text = "Ehm……mungkin karena auramu terlalu kuat."
  },
  AvgCommunicate_57595_Content_5 = {
    Text = "Semua orang merasa tekanannya terlalu besar."
  },
  AvgCommunicate_57595_Content_6 = {
    Text = "Ternyata begitu ya, aku mengerti. Sikapku memang agak terlalu keras."
  },
  AvgCommunicate_57595_Content_7 = {
    Text = "Kamu ternyata sadar diri juga?"
  },
  AvgCommunicate_57595_Content_8 = {
    Text = "Meskipun masalahnya bukan cuma soal sikap sih!"
  },
  AvgCommunicate_57595_Content_9 = {
