  AvgCommunicate_57897_Content_1 = {
    Text = "%player%, nilaimu sudah keluar."
  },
  AvgCommunicate_57897_Content_10 = {
    Text = "Jangan sungkan, sudah diputuskan ya. Sampai jumpa di kelas besok."
  },
  AvgCommunicate_57897_Content_11 = {
    Text = "Aku masih punya latihan lain selama liburan—"
  },
  AvgCommunicate_57897_Content_12 = {
    Text = "Bercanda kok."
  },
  AvgCommunicate_57897_Content_13 = {
    Text = "Aku sudah menyesuaikan jadwal latihanmu. Istirahatlah dengan baik beberapa hari ke depan."
  },
  AvgCommunicate_57897_Content_14 = {
    Text = "Serius? Syukurlah, terima kasih!"
  },
  AvgCommunicate_57897_Content_2 = {
    Text = "Tahu berapa nilaimu?"
  },
  AvgCommunicate_57897_Content_3 = {
    Text = "…Kamu bikin aku tertekan kalau begini."
  },
  AvgCommunicate_57897_Content_4 = {
    Text = "Aku datang untuk mengucapkan selamat. Meskipun banyak hal terjadi semester ini, performamu sejauh ini cukup baik."
  },
  AvgCommunicate_57897_Content_5 = {
    Text = "Sebagai hadiah, aku sudah menyesuaikan jadwal latihanmu. Istirahatlah dengan baik beberapa hari ke depan."
  },
  AvgCommunicate_57897_Content_6 = {
