  AvgCommunicate_57898_Content_12 = {
    Text = "Aku akan terus mengawasimu."
  },
  AvgCommunicate_57898_Content_2 = {
    Text = "Siapa kamu? Kenapa tidak punya akun resmi?"
  },
  AvgCommunicate_57898_Content_3 = {
    Text = "Coba gunakan otak pintarmu itu untuk menebak."
  },
  AvgCommunicate_57898_Content_4 = {
    Text = "Kamu tahu soal komunikator, kamu orang sekolah?"
  },
  AvgCommunicate_57898_Content_5 = {
    Text = "Kenapa tidak, kalau semua orang masih mau mengakuinya."
  },
  AvgCommunicate_57898_Content_6 = {
    Text = "Kamu... itu Dor."
  },
  AvgCommunicate_57898_Content_7 = {
    Text = "Benar sekali, anjing pintar dapat hadiah."
  },
  AvgCommunicate_57898_Content_8 = {
    Text = "...Hadiah apa?"
  },
  AvgCommunicate_57898_Content_9 = {
