  AvgCommunicate_57898_Option_6 = {
    Text = "Kamu itu Dor."
  },
  AvgCommunicate_57898_Option_8 = {
    Text = "Hadiah apa?"
  },
  AvgCommunicate_57899_Content_1 = {
    Text = "%player%{Male=tuan,Female=nyonya}, apakah kamu melihat Jenkin?"
  },
  AvgCommunicate_57899_Content_10 = {
    Text = "Terima kasih, %player%."
  },
  AvgCommunicate_57899_Content_2 = {
    Text = "Tadi pagi dia bilang sesuatu tentang cokelat klik-klik, lalu pergi begitu saja, dan sampai sekarang belum kembali."
  },
  AvgCommunicate_57899_Content_3 = {
    Text = "Aku agak khawatir."
  },
  AvgCommunicate_57899_Content_4 = {
    Text = "Hanna bilang Jenkin sedang bersamanya."
  },
  AvgCommunicate_57899_Content_5 = {
    Text = "Sepertinya dia ingin membeli cokelat untuk dijadikan hadiah untukmu."
  },
  AvgCommunicate_57899_Content_6 = {Text = "Hadiah?"},
  AvgCommunicate_57899_Content_7 = {
    Text = "Tapi sekarang bukan hari perayaan apa pun, jangan-jangan aku yang lupa..."
  },
  AvgCommunicate_57899_Content_8 = {
    Text = "Menurutku, terkadang, hadiah tidak harus dibeli hanya saat hari perayaan saja."
  },
  AvgCommunicate_57899_Content_9 = {
    Text = "Begitu ya…… Kalau begitu, aku juga akan menyiapkan sesuatu."
  },
  AvgCommunicate_57899_Option_4 = {
    Text = "Hanna bilang Jenkin sedang bersamanya."
  },
  AvgCommunicate_57899_Option_8 = {
    Text = "Menurutku..."
  },
  AvgCommunicate_57900_Content_1 = {Text = "Tuanku?"},
  AvgCommunicate_57900_Content_10 = {
    Text = "Hebat sekali, bagaimana caranya?"
  },
  AvgCommunicate_57900_Content_11 = {
    Text = "Tunggu, aku akan ke sana sekarang untuk mengajarimu."
  },
  AvgCommunicate_57900_Content_2 = {
    Text = "Ada apa, Augier?"
  },
  AvgCommunicate_57900_Content_3 = {
    Text = "Wah, benar-benar ada tulisannya."
  },
  AvgCommunicate_57900_Content_4 = {
    Text = "Maaf, Tuanku, tadi aku kehilangan kendali."
  },
  AvgCommunicate_57900_Content_5 = {
    Text = "Nona Dor baru saja mengirimkan komunikator yang sudah diperbaiki kepadaku, memintaku untuk mengujinya. Tidak kusangka ternyata sangat mudah digunakan."
  },
  AvgCommunicate_57900_Content_6 = {
    Text = "Kira-kira apalagi yang bisa dikirim lewat alat ini ya."
  },
  AvgCommunicate_57900_Content_7 = {
    Text = "Ternyata bisa kirim gambar juga!"
  },
