  AvgCommunicate_57901_Content_1 = {
    Text = "?！#¥%&*()"
  },
  AvgCommunicate_57901_Content_10 = {
    Text = "Ah! Maaf, Penjaga Rahasia!"
  },
  AvgCommunicate_57901_Content_11 = {
    Text = "Kali ini aku pasti tidak akan lupa, pasti!"
  },
  AvgCommunicate_57901_Content_2 = {Text = "??"},
  AvgCommunicate_57901_Content_3 = {
    Text = "Maaf, maaf, aku masih belum terlalu bisa menggunakan keyboard."
  },
  AvgCommunicate_57901_Content_4 = {
    Text = "Tidak apa-apa, aku juga terbata-bata saat pertama kali menggunakannya. Banyak berlatih beberapa kali pasti bisa."
  },
  AvgCommunicate_57901_Content_5 = {
    Text = "Haah, memang begitu sih, tapi aku takut besok sudah lupa lagi."
  },
  AvgCommunicate_57901_Content_6 = {
    Text = "Kalau begitu, coba lagi berkali-kali, pasti tidak masalah!"
  },
  AvgCommunicate_57901_Content_7 = {
    Text = "Kamu benar! Terima kasih, Elva!"
  },
  AvgCommunicate_57901_Content_8 = {
    Text = "……Anu, aku bukan Elva."
  },
  AvgCommunicate_57901_Content_9 = {
    Text = "Aku adalah Penjaga Rahasia."
  },
  AvgCommunicate_57901_Option_2 = {Text = "??"},
  AvgCommunicate_57901_Option_4 = {
    Text = "Banyak berlatih saja."
  },
  AvgCommunicate_57901_Option_6 = {
    Text = "Kalau begitu, coba lagi berkali-kali!"
  },
  AvgCommunicate_57901_Option_8 = {
    Text = "Aku bukan Elva."
  },
  AvgCommunicate_57901_Option_9 = {
    Text = "Aku adalah Penjaga Rahasia."
  },
  AvgCommunicate_57903_Content_1 = {
    Text = "Selamat siang, Utusan Pucat."
  },
  AvgCommunicate_57903_Content_10 = {
    Text = "Harus kuakui, sangat menakjubkan."
  },
  AvgCommunicate_57903_Content_2 = {
    Text = "Halo, Uskup Salvador."
  },
  AvgCommunicate_57903_Content_3 = {
    Text = "Sepertinya kau sudah menerima komunikator terbaru, bagaimana menurutmu?"
  },
  AvgCommunicate_57903_Content_4 = {
    Text = "Sangat menarik, dan juga praktis. Meskipun terpisah ratusan mil, kita masih bisa berkomunikasi seolah bertatap muka."
  },
  AvgCommunicate_57903_Content_5 = {
    Text = "Jika seluruh dunia bisa memiliki perangkat seperti ini, jarak antara manusia pasti tidak akan sejauh sekarang."
  },
  AvgCommunicate_57903_Content_6 = {
    Text = "Tapi aku paham, kekhususan teknologi ini—apakah kau tahu bahwa ia mengirimkan informasi dengan membangun tautan dengan jiwa lain?"
  },
  AvgCommunicate_57903_Content_7 = {
    Text = "Aku hanya tahu di dalamnya ada Inti Perak."
  },
  AvgCommunicate_57903_Content_8 = {
    Text = "Apakah kau melihatnya?"
  },
  AvgCommunicate_57903_Content_9 = {
    Text = "Tepat sekali, jiwa kita terhubung dengan Inti Perak, dan Inti Perak terhubung dengan Inti Perak di perangkat sejenis lainnya."
  },
  AvgCommunicate_57903_Option_2 = {
    Text = "Halo, Uskup Salvador."
  },
  AvgCommunicate_57903_Option_7 = {
    Text = "Aku hanya tahu di dalamnya ada Inti Perak."
