  AvgCommunicate_57903_Option_8 = {
    Text = "Apakah kau melihatnya?"
  },
  AvgCommunicate_57904_Content_1 = {
    Text = "Penjaga Rahasia, terima kasih banyak atas pasokan yang dikirim ke sanatorium kemarin. Tolong sampaikan juga rasa terima kasihku kepada Lord Dexter atas bantuannya selama ini."
  },
  AvgCommunicate_57904_Content_10 = {
    Text = "Ini juga satu-satunya hal yang bisa kulakukan untuk anak itu."
  },
  AvgCommunicate_57904_Content_2 = {
    Text = "Ini sudah seharusnya kami lakukan."
  },
  AvgCommunicate_57904_Content_3 = {
    Text = "Tanpa kalian, sanatorium tidak akan bisa bertahan hingga hari ini."
  },
  AvgCommunicate_57904_Content_4 = {
    Text = "Kepala panti pasti juga akan sangat berterima kasih kepada kalian."
  },
  AvgCommunicate_57904_Content_5 = {
    Text = "Mengelola panti perawatan sendirian, kamu pasti lelah."
  },
  AvgCommunicate_57904_Content_6 = {
    Text = "Apa yang kulakukan bukan hal yang besar."
  },
  AvgCommunicate_57904_Content_7 = {
    Text = "Aku hanya berharap para pasien di panti perawatan bisa mendapatkan sedikit ketenangan."
  },
  AvgCommunicate_57904_Content_8 = {
    Text = "Kalau ada waktu, tolong sering-seringlah bawa Lily kembali berkunjung."
  },
  AvgCommunicate_57904_Content_9 = {
    Text = "Aku akan membersihkan kantor kepala panti dan menunggu kedatangan kalian."
  },
  AvgCommunicate_57904_Option_2 = {
    Text = "Ini sudah seharusnya kami lakukan."
  },
  AvgCommunicate_57904_Option_5 = {
    Text = "Mengelola panti perawatan sendirian, kamu pasti lelah."
