  },
  AvgCommunicate_57907_Content_6 = {
    Text = "Seumur hidup aku menjadi prajurit, hanya bisa mematuhi perintah. Bahkan di Lemvashi, sebagian besar waktu aku tidak yakin apa yang harus kulakukan, apa yang bisa kulakukan."
