  AvgCommunicate_57918_Content_11 = {Text = "Shilo?"},
  AvgCommunicate_57918_Content_2 = {
    Text = "Ini semacam cara pengawasan baru?"
  },
  AvgCommunicate_57918_Content_3 = {
    Text = "Hanya alat untuk memudahkan komunikasi."
  },
  AvgCommunicate_57918_Content_4 = {
    Text = "Kalau kamu butuh bantuan, cukup beritahu aku di sini, kami akan segera berangkat."
  },
  AvgCommunicate_57918_Content_5 = {
    Text = "……Aku mengerti."
  },
  AvgCommunicate_57918_Content_6 = {
    Text = "Terima kasih."
  },
  AvgCommunicate_57918_Content_9 = {
    Text = "Sulit dipercaya, kamu ternyata mengirim gambar seperti ini."
  },
  AvgCommunicate_57918_Option_3 = {
    Text = "Hanya alat untuk memudahkan komunikasi."
  },
  AvgCommunicate_57919_Content_1 = {
    Text = "Penjaga Rahasia! Ayo keluar main!"
  },
  AvgCommunicate_57919_Content_2 = {
    Text = "Ayo, Oreta mau pergi ke mana?"
  },
  AvgCommunicate_57919_Content_3 = {
    Text = "Teman bilang ingin pergi ke tempat yang ada airnya!"
  },
  AvgCommunicate_57919_Content_4 = {
    Text = "Air ya…… Bagaimana kalau ke pantai? Kebetulan hari ini aku libur."
  },
  AvgCommunicate_57919_Content_5 = {
    Text = "Asyik asyik, boleh nggak aku ajak Jenkins dan yang lain?"
  },
  AvgCommunicate_57919_Content_6 = {
    Text = "Boleh dong, nanti ketemu di gerbang sekolah ya."
  },
  AvgCommunicate_57919_Content_7 = {
    Text = "Oke! Pantai pantai—berangkat—"
  },
  AvgCommunicate_57919_Option_2 = {Text = "Ayo."},
  AvgCommunicate_57919_Option_4 = {
    Text = "Air ya……"
  },
  AvgCommunicate_57919_Option_6 = {
    Text = "Boleh dong, nanti ketemu di gerbang sekolah ya."
  },
  AvgCommunicate_57920_Content_1 = {
    Text = "Kamu melihatnya?"
  },
  AvgCommunicate_57920_Content_2 = {
    Text = "Di taman kecil di belakang asrama, muncul bunga-bunga putih."
  },
  AvgCommunicate_57920_Content_3 = {
    Text = "Mereka sangat cantik."
  },
  AvgCommunicate_57920_Content_4 = {
    Text = "Iya, kecil-kecil, sedikit demi sedikit, tapi begitu kuat..."
  },
  AvgCommunicate_57920_Content_5 = {
    Text = "Menurutmu, apakah benih-benihku juga bisa mekar menjadi bunga yang sama?"
  },
  AvgCommunicate_57920_Content_6 = {
    Text = "Pasti bisa, kok."
  },
  AvgCommunicate_57920_Option_3 = {
    Text = "Mereka sangat cantik."
  },
  AvgCommunicate_57920_Option_6 = {
    Text = "Pasti bisa, kok."
  },
  AvgCommunicate_57956_Content_1 = {
    Text = "Aku akhir-akhir ini agak terganggu."
  },
  AvgCommunicate_57956_Content_2 = {Text = "Ada apa?"},
  AvgCommunicate_57956_Content_3 = {
    Text = "Kalau tidak keberatan, bisa ceritakan padaku?"
  },
  AvgCommunicate_57956_Content_4 = {
    Text = "Wanita yang selalu duduk di perangkat aneh itu dan setiap hari minum banyak cairan berwarna gelap, sudah tiga hari menginap di kamarku."
  },
  AvgCommunicate_57956_Content_5 = {
    Text = "Aku tahu dia takut kegelapan, dan aku memahami penderitaan mengikuti petunjuk namun tak pernah bisa kembali ke tanah air, tapi..."
  },
  AvgCommunicate_57956_Content_6 = {
    Text = "Dia bahkan ingin ikut masuk ke kamar mandi bersamaku, hal ini benar-benar agak memalukan."
  },
  AvgCommunicate_57956_Content_7 = {
    Text = "Aku akan bicara dengan Winkel."
  },
  AvgCommunicate_57956_Content_8 = {
    Text = "Kalau begitu, terima kasih sebelumnya."
  },
  AvgCommunicate_57956_Content_9 = {
    Text = "Tapi, tolong bersikap lembut padanya. Bagaimanapun, ini bukan salahnya."
  },
  AvgCommunicate_57956_Option_2 = {Text = "Ada apa?"},
  AvgCommunicate_57956_Option_3 = {
    Text = "Kalau tidak keberatan, bisa ceritakan padaku?"
  },
  AvgCommunicate_57956_Option_7 = {
    Text = "Aku akan bicara dengan Winkel."
  },
  AvgCommunicate_57957_Content_1 = {
    Text = "Sudah menerima hadiahku?"
  },
  AvgCommunicate_57957_Content_2 = {
    Text = "Seharusnya aku sudah menduganya. Selain kamu, tidak ada orang lain yang akan memberiku ini."
  },
  AvgCommunicate_57957_Content_3 = {
    Text = "Seperti semua seni, pahatan juga merupakan sesuatu yang sangat personal."
  },
  AvgCommunicate_57957_Content_4 = {
    Text = "Tidak semua orang bisa sepertiku, menganggap ciptaan batu ini sebagai perpanjangan diri sendiri, kelanjutan dari kehidupan."
  },
  AvgCommunicate_57957_Content_5 = {
    Text = "Tapi kamu berbeda, bukan begitu?"
  },
  AvgCommunicate_57957_Content_6 = {
    Text = "\"Gadis Karang\"-ku yang tersayang?"
  },
  AvgCommunicate_57957_Option_2 = {
    Text = "Seharusnya aku sudah menduganya."
  },
  AvgCommunicate_57958_Content_1 = {
    Text = "{Male=Tuan,Female=Nyonya}, boleh minta waktumu sebentar?"
  },
  AvgCommunicate_57958_Content_10 = {
    Text = "Tak mengapa, demi menyebarkan rahmat Tuhanku, aku tidak akan menyerah pada siapa pun yang keras kepala."
  },
  AvgCommunicate_57958_Content_11 = {
    Text = "Besok pukul tiga dini hari, aku akan mengadakan upacara di Aula Misager, untuk menceritakan keagungan Tuhanku kepada dunia."
  },
  AvgCommunicate_57958_Content_12 = {
    Text = "Sebagai seseorang yang memiliki ikatan mendalam dengan Tuhanku, kuharap Penjaga Rahasia {Male=tuan,Female=nyonya} hadir tepat waktu."
  },
  AvgCommunicate_57958_Content_2 = {
    Text = "Aku ingin menceritakan tentang Raja Muda dan Juru Selamat kami — Thulu."
  },
  AvgCommunicate_57958_Content_3 = {
    Text = "Tolong Pendeta Agung perhatikan identitas Anda, jangan meniru gaya propaganda jalanan seperti ini."
  },
  AvgCommunicate_57958_Content_4 = {
    Text = "Juliette pernah menyarankan kepadaku, jika ingin memperluas jemaat, perlu menggunakan cara penyebaran yang lebih lembut dan proaktif."
  },
  AvgCommunicate_57958_Content_5 = {
    Text = "Kurasa, perkataannya ada benarnya."
  },
  AvgCommunicate_57958_Content_6 = {
    Text = "Selama bisa menyebarkan rahmat Tuhanku, aku bersedia mencoba mempelajari gaya bahasa yang sedang populer saat ini."
  },
  AvgCommunicate_57958_Content_7 = {
    Text = "Ada sesuatu yang lupa kuberitahukan, sebenarnya aku lebih suka Haas..."
  },
  AvgCommunicate_57958_Content_9 = {
    Text = "Penistaan... Kebodohan..."
  },
  AvgCommunicate_57958_Option_3 = {
    Text = "Pelajari sesuatu yang lebih baik"
  },
  AvgCommunicate_57958_Option_7 = {
    Text = "Aku lebih suka Haas..."
  },
  AvgCommunicate_57959_Content_1 = {Text = "Hei."},
  AvgCommunicate_57959_Content_10 = {
    Text = "Mana mungkin manusia lemah bisa menangkapku?"
  },
  AvgCommunicate_57959_Content_11 = {
    Text = "Sudahlah, aku akan menyelesaikannya sendiri."
  },
  AvgCommunicate_57959_Content_2 = {
    Text = "Kenapa kamu juga punya komunikator?"
  },
  AvgCommunicate_57959_Content_3 = {
    Text = "Kenapa kamu juga punya komunikator?"
  },
  AvgCommunicate_57959_Content_4 = {
    Text = "Misage bukan satu-satunya kekuatan yang menguasai teknologi Silver Core."
  },
  AvgCommunicate_57959_Content_5 = {
    Text = "Jadi apa yang ingin kamu katakan? Aku tidak percaya kamu menghubungiku hanya untuk memamerkan komunikatormu."
  },
  AvgCommunicate_57959_Content_6 = {
    Text = "Lumayan pintar juga."
  },
  AvgCommunicate_57959_Content_7 = {
    Text = "Segera datang ke Jalan Bern No. 38, ada urusan denganmu."
  },
  AvgCommunicate_57959_Content_8 = {
    Text = "……Kenapa kamu mencariku di kantor polisi?"
  },
  AvgCommunicate_57959_Content_9 = {
    Text = "Jangan bilang kamu ditangkap."
  },
  AvgCommunicate_57959_Option_2 = {
    Text = "Pertama, namaku bukan \"Hei\"."
  },
  AvgCommunicate_57959_Option_3 = {
    Text = "Kedua, kenapa kamu juga punya komunikator?"
  },
  AvgCommunicate_57959_Option_5 = {
    Text = "Apa yang ingin kamu katakan?"
  },
  AvgCommunicate_57959_Option_8 = {
    Text = "……Kenapa kamu mencariku di kantor polisi?"
  },
  AvgCommunicate_57987_Content_1 = {
    Text = "Ternyata bisa langsung menerima harapan orang-orang dari kotak ini."
  },
  AvgCommunicate_57987_Content_10 = {
    Text = "Harapan orang-orang selalu banyak."
  },
  AvgCommunicate_57987_Content_11 = {
    Text = "Aku akan berusaha sekuat tenaga untukmu."
  },
  AvgCommunicate_57987_Content_2 = {
    Text = "Apakah ini perlengkapan doa yang baru?"
  },
  AvgCommunicate_57987_Content_3 = {
    Text = "Ini cuma alat komunikasi biasa kok."
  },
  AvgCommunicate_57987_Content_4 = {
    Text = "Komunikasi ya?"
  },
  AvgCommunicate_57987_Content_5 = {
    Text = "Kalau begitu, silakan komunikasikan harapanmu kepadaku."
  },
  AvgCommunicate_57987_Content_6 = {
    Text = "Bukan begitu maksudnya!"
  },
  AvgCommunicate_57987_Content_7 = {
    Text = "Tidak tidak, aku tidak ada yang perlu merepotkanmu."
  },
  AvgCommunicate_57987_Content_8 = {
    Text = "Belum punya harapan ya?"
  },
  AvgCommunicate_57987_Content_9 = {
    Text = "Tidak apa-apa, saat ingin membuat permohonan, komunikasikan saja kepadaku."
  },
  AvgCommunicate_57987_Option_3 = {
    Text = "Ini cuma alat komunikasi biasa kok."
  },
  AvgCommunicate_57987_Option_6 = {
    Text = "Bukan begitu maksudnya!"
  },
  AvgCommunicate_57987_Option_7 = {
    Text = "Tidak tidak, aku tidak ada yang perlu merepotkanmu."
  },
  AvgCommunicate_57988_Content_1 = {
    Text = "Anu, Penjaga Rahasia."
  },
  AvgCommunicate_57988_Content_10 = {
    Text = "Sebagai investasi, tolong berikan aku lima puluh, aku akan pergi membeli resep itu."
  },
  AvgCommunicate_57988_Content_11 = {
    Text = "Setelah aku mendapatkan kekuatan dan kembali, pasti akan kubalas seratus kali lipat."
  },
  AvgCommunicate_57988_Content_12 = {
    Text = "Jadi ternyata kamu datang untuk pinjam uang!"
  },
  AvgCommunicate_57988_Content_13 = {
    Text = "Terlalu banyak yang perlu dikomentari sampai tidak tahu harus mulai dari mana!"
  },
  AvgCommunicate_57988_Content_14 = {
    Text = "Meskipun tidak mudah bagimu untuk tetap berpegang pada soal garis darah ini, tapi kurasa kamu sebaiknya mempertimbangkan kemungkinan bahwa kamu sedang ditipu."
  },
  AvgCommunicate_57988_Content_15 = {
    Text = "Begitu ya, ternyata bahkan kamu pun tidak percaya padaku."
  },
  AvgCommunicate_57988_Content_16 = {
    Text = "Bukan aku, aku tidak..."
  },
  AvgCommunicate_57988_Content_17 = {
    Text = "Baiklah, aku akan mencari cara sendiri. Saat aku kembali, kalian semua pasti akan terkagum-kagum."
  },
  AvgCommunicate_57988_Content_2 = {
    Text = "Ada apa? Ada perlu apa denganku?"
  },
  AvgCommunicate_57988_Content_3 = {
    Text = "Aku menemukan resep rahasia yang bisa membangkitkan kekuatan garis darah."
  },
  AvgCommunicate_57988_Content_4 = {
    Text = "Katanya kalau menggunakan resep ini, aku bisa memiliki kekuatan yang sama seperti Tuan Goliath dan yang lainnya."
  },
  AvgCommunicate_57988_Content_5 = {
    Text = "Itu hal bagus, tapi kenapa rasanya agak mencurigakan ya?"
  },
  AvgCommunicate_57988_Content_6 = {
    Text = "Aku tahu kamu mungkin iri dengan kekuatan ini, tidak apa-apa, aku akan mencobanya sendiri."
  },
  AvgCommunicate_57988_Content_7 = {
    Text = "Eh……meskipun aku tidak tahu kenapa kamu berpikir begitu, kalau begitu semoga berhasil ya."
  },
  AvgCommunicate_57988_Content_8 = {Text = "Jadi."},
  AvgCommunicate_57988_Content_9 = {Text = "?"},
  AvgCommunicate_57988_Option_12 = {
    Text = "Jadi ternyata kamu datang untuk pinjam uang!"
  },
  AvgCommunicate_57988_Option_13 = {
    Text = "Terlalu banyak yang perlu dikomentari sampai tidak tahu harus mulai dari mana!"
  },
  AvgCommunicate_57988_Option_16 = {
    Text = "Bukan aku, aku tidak..."
  },
  AvgCommunicate_57988_Option_2 = {Text = "Ada apa?"},
