  AvgCommunicate_57989_Content_11 = {Text = "%player%."},
  AvgCommunicate_57989_Content_12 = {Text = "?!"},
  AvgCommunicate_57989_Content_13 = {
    Text = "Aku sudah menyiapkan kursi VVIP untukmu."
  },
  AvgCommunicate_57989_Content_14 = {
    Text = "Jangan sampai ingkar janji ya."
  },
  AvgCommunicate_57989_Content_2 = {
    Text = "Apakah kamu sering mendambakan sebuah api yang membakar hati dan jiwamu sekaligus?"
  },
  AvgCommunicate_57989_Content_3 = {
    Text = "Cassia, apa lagi yang kamu rencanakan?"
  },
  AvgCommunicate_57989_Content_4 = {
    Text = "Tenang, tenang, Maestro Sihir Cassia akan segera membawa titik balik dalam hidupmu dan menyuntikkan semangat!"
  },
  AvgCommunicate_57989_Content_5 = {
    Text = "Dengan bangga kami umumkan kepada semuanya, Karnaval Sulap Cassia edisi terbaru akan segera digelar dengan megah!"
  },
  AvgCommunicate_57989_Content_7 = {
    Text = "Kamu salah kirim orang ya?"
  },
  AvgCommunicate_57989_Content_8 = {
    Text = "Dari ada menjadi tiada, dari tiada menjadi ada, mengubah batu menjadi emas, pencangkokan tubuh manusia — hanya ada yang tak terpikirkan, tak ada yang tak terlihat. Maestro Cassia menjamin otakmu akan dikosongkan dan membuatmu tak bisa melupakannya!"
  },
  AvgCommunicate_57989_Content_9 = {
    Text = "Balas pesan sekarang untuk menikmati diskon 20% tiket masuk! Kuota terbatas, siapa cepat dia dapat, Karnaval Sulap menantikan kehadiranmu!"
  },
  AvgCommunicate_57989_Option_12 = {Text = "?!"},
  AvgCommunicate_57989_Option_3 = {
    Text = "Cassia, apa lagi yang kamu rencanakan?"
  },
  AvgCommunicate_57989_Option_7 = {
