  },
  AvgCommunicate_57990_Content_1 = {
    Text = "%player%{Male=tuan,Female=nyonya}, apakah kamu ada waktu belakangan ini?"
  },
  AvgCommunicate_57990_Content_10 = {
    Text = "Kamu setuju? Bagus sekali. Sampai jumpa nanti."
  },
  AvgCommunicate_57990_Content_2 = {
    Text = "Aku... ingin minta bantuanmu."
  },
  AvgCommunicate_57990_Content_3 = {Text = "Ada apa?"},
  AvgCommunicate_57990_Content_4 = {
    Text = "Kebetulan hari ini aku sedang senggang."
  },
  AvgCommunicate_57990_Content_5 = {
    Text = "Sebulan lagi aku akan mengadakan pertunjukan kecil di Aula Misagar, dan sebelum itu aku ingin seseorang mendengarkan nyanyianku."
  },
  AvgCommunicate_57990_Content_6 = {
    Text = "Kalau mengajak Feint, dia pasti akan bilang bagus apa pun yang terjadi. Sedangkan orang lain... aku agak sungkan."
  },
  AvgCommunicate_57990_Content_7 = {
    Text = "Setelah dipikir-pikir, hanya Penjaga Rahasia yang paling bisa diandalkan dan paling kupercaya."
  },
  AvgCommunicate_57990_Content_8 = {Text = "Jadi..."},
  AvgCommunicate_57990_Content_9 = {
    Text = "Baiklah, nanti ketemu di aula?"
  },
  AvgCommunicate_57990_Option_3 = {Text = "Ada apa?"},
  AvgCommunicate_57990_Option_4 = {
    Text = "Kebetulan hari ini aku sedang senggang."
  },
  AvgCommunicate_57990_Option_9 = {Text = "Baiklah."},
  AvgCommunicate_57991_Content_1 = {
    Text = "Penjaga Rahasia {Male=tuan,Female=nyonya}, apakah Anda masih ingat trem ulat bulu itu?"
  },
  AvgCommunicate_57991_Content_10 = {
    Text = "Dikombinasikan dengan situasi saat itu, saya melihat keindahan yang berbeda dari karya Anda..."
  },
  AvgCommunicate_57991_Content_11 = {
    Text = "Di antologi puisi baru saya, saya ingin memasukkan baris puisi Anda itu."
  },
  AvgCommunicate_57991_Content_12 = {
    Text = "Bolehkah, Penjaga Rahasia {Male=tuan,Female=nyonya}?"
  },
  AvgCommunicate_57991_Content_13 = {
    Text = "Kamu serius?"
  },
  AvgCommunicate_57991_Content_14 = {
    Text = "Tentu saja!"
  },
  AvgCommunicate_57991_Content_16 = {
    Text = "...Jadi begini ya kesadaran seorang penyair jenius?"
  },
  AvgCommunicate_57991_Content_17 = {
    Text = "Mungkin kamu terlalu lelah menulis belakangan ini. Istirahatlah yang cukup!"
  },
  AvgCommunicate_57991_Content_18 = {
    Text = "Tidak masalah! Setelah diterbitkan, jangan lupa bagi honornya denganku."
  },
  AvgCommunicate_57991_Content_19 = {
    Text = "Pasti akan kuingat!"
  },
  AvgCommunicate_57991_Content_2 = {
    Text = "Di dalam trem itu, Anda menulis sebuah bait puisi…"
  },
  AvgCommunicate_57991_Content_20 = {
    Text = "Terima kasih, Penjaga Rahasia {Male=tuan,Female=nyonya}!"
  },
  AvgCommunicate_57991_Content_3 = {
    Text = "Kenangan yang sudah mati mulai menyerangku…"
  },
  AvgCommunicate_57991_Content_4 = {
    Text = "Penjaga Rahasia {Male=tuan,Female=nyonya}, kenapa berkata begitu?"
  },
  AvgCommunicate_57991_Content_5 = {
    Text = "Karya seagung itu, ulat bulu itu malah tidak mengizinkan saya duduk. Tidak punya selera!"
  },
  AvgCommunicate_57991_Content_6 = {
    Text = "Penjaga Rahasia {Male=tuan,Female=nyonya}, saya juga berpikir begitu!"
  },
  AvgCommunicate_57991_Content_7 = {
    Text = "Setelah kembali, saya memikirkannya dengan saksama."
  },
  AvgCommunicate_57991_Content_8 = {
    Text = "Meskipun dari sudut pandang tradisional, bait puisi itu kurang memiliki hubungan yang diperlukan dengan keindahan."
  },
  AvgCommunicate_57991_Content_9 = {
    Text = "Tapi ketidakharmonisan, ironi, kesalahan, semua itu juga seharusnya menjadi bagian dari puisi."
  },
  AvgCommunicate_57991_Option_13 = {
    Text = "Kamu serius?"
  },
  AvgCommunicate_57991_Option_18 = {
    Text = "Jangan lupa bayar honorku"
  },
  AvgCommunicate_57991_Option_3 = {
    Text = "Tidak ingin mengingatnya."
  },
  AvgCommunicate_57991_Option_5 = {
    Text = "Karya yang agung."
  },
  AvgCommunicate_57992_Content_1 = {
    Text = "Ruang musik di sini benar-benar sederhana."
  },
  AvgCommunicate_57992_Content_10 = {Text = "?!"},
  AvgCommunicate_57992_Content_11 = {
    Text = "Aku tidak mendaftar!"
  },
  AvgCommunicate_57992_Content_2 = {
    Text = "Aula-nya juga sungguh tidak layak dilihat."
  },
  AvgCommunicate_57992_Content_3 = {
    Text = "Dan instrumen-instrumen kalian itu, siapa yang bertanggung jawab merawatnya? Tidak tahu kalau harus di-tuning secara berkala?"
  },
  AvgCommunicate_57992_Content_4 = {Text = "Hamelin..."},
  AvgCommunicate_57992_Content_5 = {
    Text = "Tidak bisa dipercaya, inikah apresiasi musik dari institusi pendidikan tinggi? Sungguh tidak bisa diterima."
  },
  AvgCommunicate_57992_Content_6 = {
    Text = "Mulai hari ini, semua ini akan kuambil alih sepenuhnya."
  },
  AvgCommunicate_57992_Content_7 = {
    Text = "Sebelum Festival Silverfrost, aku harus melatih sebuah orkestra yang layak."
  },
  AvgCommunicate_57992_Content_8 = {
    Text = "Untung aku bukan anggota orkestra."
  },
  AvgCommunicate_57992_Content_9 = {
    Text = "Kamu juga jangan harap bisa kabur, Konduktor."
  },
