  AvgCommunicate_66974_Option_8 = {
    Text = "Kapan itu terjadi?!"
  },
  AvgCommunicate_66975_Content_1 = {
    Text = "Tuan!! Duniaku, hidupku, semuanya runtuh! Huhuhuhu——"
  },
  AvgCommunicate_66975_Content_10 = {
    Text = "Bukankah itu bagus."
  },
  AvgCommunicate_66975_Content_11 = {
    Text = "Hmph, Jialen langsung menggigit bibir, mengeluarkan semua tabungan untuk membeli semua perhiasan itu, dan langsung memakainya semua."
  },
  AvgCommunicate_66975_Content_12 = {
    Text = "Hmm… kamu juga tidak merasa berat ya."
  },
  AvgCommunicate_66975_Content_13 = {
    Text = "Ternyata, ternyata saat Jialen pergi melayani Nyonya Soreil, Nyonya hanya melihat sekilas dan langsung bilang semua batu mulia itu palsu! Barang tiruan!!"
  },
  AvgCommunicate_66975_Content_14 = {
    Text = "Kok bisa begitu? Dia menipu berapa banyak uangmu?"
  },
  AvgCommunicate_66975_Content_15 = {
    Text = "Lima ratus Leo penuh lho!!"
  },
  AvgCommunicate_66975_Content_16 = {
    Text = "Lima ratus koin mau beli yang asli itu mustahil!!! Katanya tabungan bertahun-tahun??"
  },
  AvgCommunicate_66975_Content_17 = {
    Text = "Ka, karena Karen terlalu suka benda berkilau, begitu punya uang langsung dihabiskan untuk beli benda berkilau, jadi tidak banyak yang bisa ditabung..."
  },
  AvgCommunicate_66975_Content_18 = {
    Text = "Sudahlah... Lagipula kalau kamu hanya suka batu yang berkilau, batu-batu ini memang cukup berkilau, dan pengerjaannya juga cukup halus."
  },
  AvgCommunicate_66975_Content_19 = {
    Text = "Dibandingkan membeli yang asli, kamu malah menghemat banyak uang, apa yang perlu disedihkan?"
  },
  AvgCommunicate_66975_Content_2 = {
    Text = "?? Ada apa ini?"
  },
  AvgCommunicate_66975_Content_20 = {
    Text = "Eh, kamu benar juga ya."
  },
  AvgCommunicate_66975_Content_21 = {
    Text = "Karen langsung merasa untung deh, terima kasih Tuan!"
  },
  AvgCommunicate_66975_Content_3 = {
    Text = "Daphodel, wanita licik jahat itu! Dia menipu semua tabungan yang Jialen kumpulkan dari kerja keras bertahun-tahun!"
  },
  AvgCommunicate_66975_Content_4 = {
    Text = "Daphodel menipu uangmu? Kamu beli apa darinya?"
  },
  AvgCommunicate_66975_Content_5 = {
    Text = "Gara-gara waktu itu Jialen melihat harga perhiasan di majalah sambil mengeluh, lalu ketahuan oleh wanita jahat itu."
  },
  AvgCommunicate_66975_Content_6 = {
