  AvgCommunicate_66976_Content_1 = {
    Text = "Anu, %player%{Male=tuan,Female=nyonya}, sepertinya aku membuat sedikit masalah."
  },
  AvgCommunicate_66976_Content_10 = {
    Text = "Ah, maaf sekali, aku merepotkan semua orang lagi."
