  AvgCommunicate_66976_Content_11 = {
    Text = "Aku akan mengembalikan topinya, sekalian memberikan ikan kering kecil sebagai kompensasi untuk kucing kampus itu."
  },
  AvgCommunicate_66976_Content_12 = {
    Text = "Dibanding ikan kering, kucing kampus itu mungkin lebih suka sesuatu seperti Pecahan Silver Core..."
  },
  AvgCommunicate_66976_Content_13 = {
    Text = "Benarkah begitu? Terima kasih banyak atas bantuanmu, aku akan berusaha mengumpulkannya!"
  },
  AvgCommunicate_66976_Content_2 = {
    Text = "Kamu tahu topi hitam kecil seperti ini milik siapa?"
  },
  AvgCommunicate_66976_Content_3 = {
    Text = "Ukurannya benar-benar tidak seperti untuk orang dewasa, tapi aku juga tidak ingat ada anak kecil yang memakai topi seperti ini."
  },
  AvgCommunicate_66976_Content_4 = {
    Text = "Topi hitam kecil? Jangan-jangan itu topi kucing sekolah?!"
  },
  AvgCommunicate_66976_Content_5 = {
    Text = "Apa yang terjadi? Kenapa topi kucing sekolah bisa ada padamu?"
  },
  AvgCommunicate_66976_Content_6 = {
    Text = "Kucing sekolah? Kalau begitu pantas saja. Tadi kepribadian kucingku muncul untuk beberapa saat."
  },
  AvgCommunicate_66976_Content_7 = {
    Text = "Aku hanya bisa mengingat samar-samar kalau dia sepertinya pergi berkelahi dengan seseorang."
  },
  AvgCommunicate_66976_Content_8 = {
    Text = "Lalu merebut topi lawan……Dia sepertinya sangat menyukai topi itu."
  },
  AvgCommunicate_66976_Option_12 = {
    Text = "Dibanding ikan kering, kucing kampus itu mungkin lebih suka sesuatu seperti Pecahan Silver Core..."
  },
  AvgCommunicate_66976_Option_4 = {
