  AvgCommunicate_66977_Content_1 = {
    Text = "Penjaga Rahasia! Apakah tadi aku baru saja mengantarkan kue untukmu?"
  },
  AvgCommunicate_66977_Content_10 = {
    Text = "Bagaimana ini, aku merepotkanmu lagi, a-aku akan menghubungi Nona Sylvia sekarang!"
  },
  AvgCommunicate_66977_Content_11 = {
    Text = "Tunggu, tunggu, tidak usah……Aku sudah tahu apa yang dia masukkan……"
  },
  AvgCommunicate_66977_Content_12 = {
    Text = "Apa? Kamu kenapa, Penjaga Rahasia?"
  },
  AvgCommunicate_66977_Content_13 = {
    Text = "Itu obat pencahar……Sudah, tidak usah dibahas lagi……Aku harus segera ke toilet……"
  },
  AvgCommunicate_66977_Content_14 = {
    Text = "Tisu di kamarku mungkin tidak cukup, nanti tolong bawakan aku tisu ya……"
  },
  AvgCommunicate_66977_Content_15 = {
    Text = "Ba-baik, akan kubawakan! Maafkan aku!!"
  },
  AvgCommunicate_66977_Content_2 = {
    Text = "Eh, benar? Aku baru saja menghabiskannya, rasanya sangat enak, keterampilanmu semakin bagus saja."
  },
  AvgCommunicate_66977_Content_3 = {
    Text = "Ah! Ya ampun! Aku datang justru untuk memberitahumu agar jangan memakan kue itu! Kue itu bukan buatanku!"
  },
  AvgCommunicate_66977_Content_4 = {
    Text = "Apa? Bukan buatanmu?"
  },
  AvgCommunicate_66977_Content_5 = {
    Text = "Benar, yang tadi mengantarkan kue untukmu adalah kepribadianku yang baru lahir, dia sangat suka berbuat iseng..."
  },
  AvgCommunicate_66977_Content_6 = {
    Text = "Aku samar-samar ingat dia sepertinya menambahkan sesuatu saat membuat kue itu... Pokoknya, apakah sekarang kamu merasa tidak enak badan?"
  },
  AvgCommunicate_66977_Content_7 = {
    Text = "Setelah kamu bilang begitu, tiba-tiba aku merasa seluruh tubuhku tidak enak..."
  },
  AvgCommunicate_66977_Content_8 = {
    Text = "Sebenarnya apa yang dia masukkan, jangan-jangan racun mematikan??"
  },
  AvgCommunicate_66977_Content_9 = {
    Text = "Seharusnya tidak! Dia hanya suka berbuat iseng, tidak sejahat itu kok."
  },
  AvgCommunicate_66977_Option_11 = {
    Text = "Tunggu, tunggu, tidak usah……"
  },
  AvgCommunicate_66977_Option_13 = {
    Text = "Itu obat pencahar……"
  },
  AvgCommunicate_66977_Option_2 = {Text = "Eh, benar?"},
