  },
  AvgCommunicate_66978_Content_1 = {
    Text = "Hei! Cepat bantu aku! Aku terjerat selimut!"
  },
  AvgCommunicate_66978_Content_10 = {
    Text = "Ini sudah termasuk pekerjaan rumah paling mudah lho, kamu benar-benar sudah terlalu lama jauh dari kehidupan sehari-hari."
  },
  AvgCommunicate_66978_Content_11 = {
    Text = "Hmph……kalau begitu mulai sekarang aku akan lebih lembut pada budak-budak, cepat carikan aku beberapa budak yang rajin!"
  },
  AvgCommunicate_66978_Content_12 = {
    Text = "Sudah kubilang Roma sudah runtuh!"
  },
  AvgCommunicate_66978_Content_13 = {
    Text = "Sekarang ini masyarakat hukum, bermimpilah sana!"
  },
  AvgCommunicate_66978_Content_14 = {
    Text = "Aku tidak peduli! Aku tidak peduli aaaaaa, daripada setiap hari mengerjakan pekerjaan rumah ini lebih baik aku mati saja!!"
  },
  AvgCommunicate_66978_Content_15 = {
    Text = "Hehe, bukan cuma pekerjaan rumah, masih ada PR sekolah juga lho."
  },
  AvgCommunicate_66978_Content_16 = {
    Text = "Akan kulempar kau ke labirin untuk jadi makanan anak-anaknya!!!!"
  },
  AvgCommunicate_66978_Content_2 = {
    Text = "? Kamu terjerat apa??"
  },
  AvgCommunicate_66978_Content_3 = {
    Text = "Ini semua gara-gara kalian tidak memberiku budak!! Siapa sangka mengganti seprai jelek ini begitu susahnya!"
  },
  AvgCommunicate_66978_Content_4 = {
    Text = "Bagaimanapun aku memasangnya tetap tidak benar, kesal sampai aku berkelahi dengan selimutnya!"
