  AvgCommunicate_66978_Content_5 = {
    Text = "……………"
  },
  AvgCommunicate_66978_Content_6 = {
    Text = "Ngapain bengong, cepat ke sini selamatkan aku! Aku tidak bisa keluar!"
  },
  AvgCommunicate_66978_Content_7 = {
    Text = "Kadang aku heran, orang sepertimu itu bagaimana bisa bertahan hidup sampai sebesar ini."
  },
  AvgCommunicate_66978_Content_8 = {
    Text = "Padahal ini semua pekerjaan yang seharusnya dilakukan budak, kenapa bisa sesulit ini……"
  },
  AvgCommunicate_66978_Content_9 = {
    Text = "Dulu para budak itu setiap hari melakukan semua ini? Tidak mungkin, bagaimana mereka bisa melakukannya?"
  },
  AvgCommunicate_66978_Option_10 = {
    Text = "Ini sudah termasuk pekerjaan rumah paling mudah lho, kamu benar-benar sudah terlalu lama jauh dari kehidupan sehari-hari."
