  AvgCommunicate_66978_Option_7 = {
    Text = "Kadang aku heran, orang sepertimu itu bagaimana bisa bertahan hidup sampai sebesar ini."
  },
  AvgCommunicate_66979_Content_1 = {
    Text = "Keeper, kue yang baru saja kau kirimkan ke Black Pool, itu kue ulang tahun milik karyawan senior yang bertanggung jawab membuat Silver Key, kan?"
  },
  AvgCommunicate_66979_Content_10 = {
    Text = "Pfft, aku mengerti, aku akan segera mengirimkan sepotong lagi untukmu!"
  },
  AvgCommunicate_66979_Content_11 = {
    Text = "Terima kasih."
  },
  AvgCommunicate_66979_Content_2 = {
    Text = "Hmm! Meskipun tahu kamu tidak akan memakannya, tapi semua orang ingin kamu ikut meramaikan, jadi kami kirimkan ke sana."
  },
  AvgCommunicate_66979_Content_3 = {
    Text = "Terima kasih atas kebaikan kalian. Tolong sampaikan ucapan selamat ulang tahun dariku, dan... bisakah kuenya dikirimkan satu potong lagi?"
  },
  AvgCommunicate_66979_Content_4 = {
    Text = "Hah? Kamu benar-benar memakannya?!"
  },
  AvgCommunicate_66979_Content_5 = {
    Text = "Hanya iseng. Karyawan itu sudah bekerja sama denganku selama bertahun-tahun, tidak pernah melakukan kesalahan."
  },
  AvgCommunicate_66979_Content_6 = {
    Text = "Meskipun aku memiliki pengetahuan tanpa batas dan memahami semua teorinya, tapi... sebenarnya aku belum pernah makan kue."
  },
  AvgCommunicate_66979_Content_7 = {
    Text = "Oh begitu, jadi maksudmu kamu hanya memahami teori tentang kue?"
  },
  AvgCommunicate_66979_Content_8 = {
