  },
  AvgCommunicate_66979_Content_9 = {
    Text = "Tapi aku tidak menyangka, ternyata rasanya semanis dan sewangi ini..."
  },
  AvgCommunicate_66979_Option_10 = {
    Text = "Pfft, aku mengerti."
  },
  AvgCommunicate_66979_Option_2 = {Text = "Ya!"},
  AvgCommunicate_66979_Option_4 = {
