  AvgCommunicate_66980_Content_12 = {
    Text = "Ini adalah komunikator yang diberikan pihak sekolah untuk kalian, digunakan untuk saling berkomunikasi jarak jauh, dan juga bisa dipakai untuk meminta bantuan saat menghadapi bahaya."
  },
  AvgCommunicate_66980_Content_13 = {
    Text = "Oh begitu rupanya, penemuan yang menarik, terima kasih Penjaga Rahasia."
  },
  AvgCommunicate_66980_Content_14 = {
    Text = "Kamu benar-benar ingat siapa aku?"
  },
  AvgCommunicate_66980_Content_15 = {
    Text = "Aku ingat kok, aku sudah berjanji padamu bahwa aku tidak akan lupa."
  },
  AvgCommunicate_66980_Content_16 = {
    Text = "Kamu adalah %player%, kamu adalah temanku!"
  },
  AvgCommunicate_66980_Content_2 = {
    Text = "? Jangan bilang kamu lupa semuanya?"
  },
  AvgCommunicate_66980_Content_3 = {
    Text = "Lupa semuanya? Aku tidak ingat kotak ini dari mana asalnya."
  },
  AvgCommunicate_66980_Content_4 = {
    Text = "Tapi aku melihat riwayat obrolan di dalamnya, sepertinya aku pernah memakainya sebelumnya, tapi sekarang aku lupa cara menggunakannya."
  },
  AvgCommunicate_66980_Content_5 = {
    Text = "Lalu sekarang kamu memakainya bagaimana?!"
  },
  AvgCommunicate_66980_Content_6 = {Text = "Hehe."},
  AvgCommunicate_66980_Content_7 = {
    Text = "Jangan ketawa, aku takut!"
  },
  AvgCommunicate_66980_Content_8 = {
    Text = "Aku membongkarnya lalu memasangnya kembali, dan kurang lebih aku jadi paham cara pakainya."
  },
  AvgCommunicate_66980_Content_9 = {
    Text = "Meskipun prinsip penggerak di dalamnya sangat rumit, aku belum memahaminya, mungkin perlu diteliti lebih lanjut."
  },
  AvgCommunicate_66980_Option_10 = {
