  AvgCommunicate_66981_Content_1 = {
    Text = "Penjaga Rahasia, bagaimana pandanganmu terhadap emosi manusia?"
  },
  AvgCommunicate_66981_Content_10 = {
    Text = "Lalu bagaimana denganmu? Sebagai Substansi Kebijaksanaan, bukankah kau juga tidak sepenuhnya rasional?"
  },
  AvgCommunicate_66981_Content_11 = {
    Text = "Kau sangat tajam, Penjaga Rahasia. Ini juga salah satu alasan mengapa aku selalu berusaha mengurangi kontak dengan dunia."
  },
  AvgCommunicate_66981_Content_12 = {
    Text = "Ketika aku melayang di luar dunia, tidak menjaga hubungan yang terlalu erat dengan manusia, aku bisa mempertahankan kejernihan dan kemandirian pikiranku."
  },
  AvgCommunicate_66981_Content_13 = {
    Text = "Seperti halnya jika aku tidak pernah merasakan manisnya kue, aku tidak akan sering memiliki kecondongan terhadapnya dalam pikiranku."
  },
  AvgCommunicate_66981_Content_14 = {
    Text = "Aku mengerti…… jadi, sekarang kau ingin makan kue kecil?"
  },
  AvgCommunicate_66981_Content_15 = {
    Text = "Bukan kebutuhan yang mendesak, tapi jika kau tidak keberatan, terima kasih banyak."
  },
  AvgCommunicate_66981_Content_2 = {
    Text = "Langsung saja topik sedalam ini!"
  },
  AvgCommunicate_66981_Content_3 = {
    Text = "Emosi…… sesuatu yang dimiliki setiap orang, kan? Bagaimanapun kita semua adalah makhluk fana."
  },
  AvgCommunicate_66981_Content_4 = {
    Text = "Benar, manusia adalah makhluk yang bergantung pada tubuh fisik, dan emosi lahir dari reaksi naluriah."
  },
  AvgCommunicate_66981_Content_5 = {
    Text = "Dibandingkan dengan pemikiran rasional yang membutuhkan pengendalian diri dan latihan untuk dihasilkan, sebagian besar pilihan manusia dipengaruhi oleh emosi."
  },
  AvgCommunicate_66981_Content_6 = {
    Text = "Memang benar, mempertahankan rasionalitas absolut setiap saat, rasanya hanya Guru Dor yang bisa melakukannya."
  },
  AvgCommunicate_66981_Content_7 = {
    Text = "Tidak, Dor pun tidak bisa melakukannya. Di dalam hatinya juga masih ada keteguhan yang berasal dari emosi, dan saat menghadapi pilihan, dia juga bisa memilih untuk bertaruh segalanya."
  },
  AvgCommunicate_66981_Content_8 = {
    Text = "Begitu rupanya, jadi semua orang seperti itu? Termasuk mereka yang menyimpang dan gila?"
