  AvgCommunicate_66982_Content_11 = {
    Text = "Barang mewah yang bahkan punya uang pun belum tentu bisa dibeli, bagaimana aku membelinya!"
  },
  AvgCommunicate_66982_Content_12 = {
    Text = "Aku tidak peduli! Pikirkan caranya. Kelinci itu pasti juga sangat ingin datang ke sisiku."
  },
  AvgCommunicate_66982_Content_13 = {
    Text = "Aku sudah memikirkan namanya, namanya Ivy!"
  },
  AvgCommunicate_66982_Content_14 = {
    Text = "Dia akan ikut pesta teh bersamaku, juga bersama Jenny dan Oliver."
  },
  AvgCommunicate_66982_Content_15 = {
    Text = "Iya iya iya, nanti aku akan memohon kepada Nyonya Soreil, pasti akan kubawa pulang untuk berkumpul dengan kalian."
  },
  AvgCommunicate_66982_Content_16 = {
    Text = "Hehe, nah begitu dong!"
  },
  AvgCommunicate_66982_Content_2 = {
