  },
  AvgCommunicate_66982_Content_5 = {
    Text = "Hmph, meskipun kue juga tidak buruk, tapi kali ini bukan soal makanan."
  },
  AvgCommunicate_66982_Content_6 = {
    Text = "Nona ini melihat di majalah yang kamu bawa pulang terakhir kali, Londinium Department Store baru saja meluncurkan boneka mewah seni kerajinan tangan."
  },
  AvgCommunicate_66982_Content_7 = {
    Text = "Di dalamnya ada boneka kelinci berwarna hitam-pink yang sangat istimewa!"
  },
  AvgCommunicate_66982_Content_8 = {
    Text = "Boneka itu seolah-olah tertulis nama Nona ini di badannya. Majalah itu bilang boneka itu buatan tangan seorang maestro. Cepat belikan untukku!"
  },
  AvgCommunicate_66982_Content_9 = {
    Text = "Buatan tangan maestro?"
