  },
  AvgCommunicate_66982_Option_9 = {
    Text = "Buatan tangan maestro?"
  },
  AvgCommunicate_66983_Content_1 = {
    Text = "Hei, beberapa hari ini kau tidak perlu mengantarkan kue untukku."
  },
  AvgCommunicate_66983_Content_10 = {
    Text = "Apalagi bahan-bahannya yang beraneka ragam itu, mau tambah sebanyak apa pun juga bisa, benar-benar puas!"
  },
  AvgCommunicate_66983_Content_11 = {
    Text = "Ini baru poin utamanya kan! Kebanyakan topping nanti eneg lho!"
  },
  AvgCommunicate_66983_Content_12 = {
    Text = "Kamu tahu apa sih, kreasi baru Nona ini dipuji habis-habisan oleh para koki itu!"
  },
  AvgCommunicate_66983_Content_13 = {
    Text = "Kemarin sudah mulai diproduksi massal dan dijual di kantin, banyak orang yang antre lho!"
  },
  AvgCommunicate_66983_Content_14 = {
    Text = "Jadi kue kecil baru yang langsung ludes kemarin itu buatanmu!"
  },
  AvgCommunicate_66983_Content_15 = {
    Text = "Ahahahahaha hebat kan aku! Cepat panggil Nona ini jenius!"
  },
  AvgCommunicate_66983_Content_16 = {Text = "Jenius!"},
  AvgCommunicate_66983_Content_17 = {
    Text = "Tapi aku tiba-tiba menyadari, kue yang dibuat sendiri rasanya ternyata lebih enak, kalau terus begini ke depannya juga tidak buruk."
  },
  AvgCommunicate_66983_Content_18 = {
    Text = "Senang sekali rasanya, Nona Besar akhirnya merasakan kebahagiaan dari bekerja keras."
  },
  AvgCommunicate_66983_Content_2 = {
    Text = "Apa yang kulihat ini, kau mendapat pukulan apa??"
  },
  AvgCommunicate_66983_Content_3 = {
    Text = "Pukulan apa, aku baik-baik saja!"
  },
  AvgCommunicate_66983_Content_4 = {
    Text = "Lalu kenapa?"
  },
  AvgCommunicate_66983_Content_5 = {
    Text = "Haah, ini semua gara-gara kue-kue kecil di kantin yang sudah membuatku bosan. Para koki itu juga otaknya kosong, sama sekali tidak berniat meluncurkan menu baru!"
  },
  AvgCommunicate_66983_Content_6 = {
    Text = "Memang tidak ada orang yang kebutuhannya akan kue kecil sebesar kamu……"
  },
  AvgCommunicate_66983_Content_7 = {
    Text = "Salahkan mereka yang tidak becus, jadi aku langsung menerobos ke dapur dan menyuruh mereka mengajari Nona ini membuat kue."
  },
  AvgCommunicate_66983_Content_8 = {
    Text = "Hah? Kamu, masak?"
  },
  AvgCommunicate_66983_Content_9 = {
    Text = "Tidak menyangka kan! Lalu Nona ini menemukan bahwa membuat kue ternyata tidak sesulit itu! Aku memang berbakat luar biasa!"
  },
  AvgCommunicate_66983_Option_11 = {
