  AvgCommunicate_66984_Content_1 = {
    Text = "%player%{Male=tuan,Female=nyonya}, aku mengalami sedikit masalah kecil dan ingin meminta bantuanmu."
  },
  AvgCommunicate_66984_Content_10 = {
    Text = "Tapi aku membalasnya bahwa aku sudah punya pasangan dansa."
  },
  AvgCommunicate_66984_Content_11 = {
    Text = "Padahal sebenarnya, aku baru sekarang datang mencari pasangan dansa tersayangku."
  },
  AvgCommunicate_66984_Content_12 = {
    Text = "Kurasa, {Male=dia,Female=dia} pasti tidak akan tega membiarkanku pergi ke pesta dansa sendirian, kan?"
  },
  AvgCommunicate_66984_Content_13 = {
    Text = "Bagaimana menurutmu?"
  },
  AvgCommunicate_66984_Content_14 = {
    Text = "Suatu kehormatan bagi saya, Nyonya."
  },
  AvgCommunicate_66984_Content_15 = {
    Text = "Sepertinya aku harus segera belajar langkah dansa dan tata kramanya, supaya nanti tidak menginjak kaki Nyonya."
  },
  AvgCommunicate_66984_Content_16 = {
    Text = "Kamu selalu bisa diandalkan dan penuh perhatian, ksatriaku."
  },
  AvgCommunicate_66984_Content_2 = {
    Text = "Hal apa yang menyulitkan Nona Sorelle kita?"
  },
  AvgCommunicate_66984_Content_3 = {
    Text = "Aku siap mendengarkan."
  },
  AvgCommunicate_66984_Content_4 = {
    Text = "Beberapa hari lagi aku harus menghadiri pesta dansa malam, kamu tahu kan, yang jenis di mana sekelompok orang angkuh dan berlebihan berkumpul tanpa melakukan apa-apa."
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "Yang menyebalkan adalah akhir-akhir ini ada orang yang sama sekali tidak sopan terus menggangguku, dia juga akan pergi ke pesta dansa itu, dan bahkan dengan mencolok mengundangku menjadi pasangan dansanya."
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "Masih ada orang menyebalkan seperti itu, mau saya bantu Nyonya menyingkirkannya?"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "Hehehe, kamu sekarang semakin pandai bercanda ya."
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "Sayangnya sekarang belum bisa, dunia orang dewasa memang serumit ini. Tapi, aku sudah menolak undangannya."
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "Kalau begitu, bukankah masalahnya sudah selesai?"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "Suatu kehormatan bagi saya, Nyonya."
  },
  AvgCommunicate_66984_Option_2 = {
