  },
  AvgCommunicate_66984_Option_9 = {
    Text = "Kalau begitu, bukankah masalahnya sudah selesai?"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "Ksatria kecilku, berkat bantuanmu di pesta dansa kemarin, sekarang aku sudah berhasil menyingkirkan orang menyebalkan itu."
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "Membuat permohonan? Kalau begitu, aku berharap Nyonya Soreil yang cantik bersedia menikmati makan malam lilin yang mewah bersamaku."
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "Hanya kamu dan aku, tanpa perlu meladeni siapa pun."
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "Sesuai keinginanmu, anak kecil yang licik."
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "Mau makan apa? Katakan saja, aku akan menemanimu menikmatinya."
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "Ini benar-benar menguji imajinasi seseorang yang setiap hari makan di kantin. Kalau begitu, biarkan aku mencicipi makanan favorit Nyonya."
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "Hehe, benar-benar anak yang pandai menyenangkan hati orang."
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "Kalau begitu, aku akan menunggu kedatanganmu di kediamanku."
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "Sebagai ucapan terima kasih atas kebaikan dan kemurahan hatimu, aku ingin melakukan sesuatu untukmu sebagai tanda terima kasihku."
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "Anda terlalu sopan, Nyonya Soreil. Kupikir hubungan kita sudah tidak perlu mengucapkan terima kasih lagi."
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "Memang aku tidak suka mengungkapkan terima kasih secara lisan, sebagian besar waktu itu hanyalah basa-basi yang munafik."
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "Tapi, kesempatan untuk mengajukan permintaan apa pun kepadaku, kamu benar-benar tidak tertarik?"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "Wah, permintaan apa pun? Kalau sampai terdengar oleh para bangsawan itu, mereka pasti iri setengah mati padaku."
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "Kamu selalu layak mendapat perlakuan istimewa dariku."
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "Ini benar-benar membuatku bingung, sangat galau. Kalau nekat minta satu set mansion, apakah akan ketahuan sekolah ya..."
  },
  AvgCommunicate_66985_Content_9 = {
    Text = "Tidak apa-apa, aku akan mengurus semuanya untukmu, kamu bisa tenang membuat permohonan."
  },
  AvgCommunicate_66985_Option_10 = {
    Text = "Membuat permohonan?"
