  },
  AvgCommunicate_66986_Content_1 = {
    Text = "Aku baru saja bertarung dengan Rotan, kami seri."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Ahaha... Kurasa pikiran pengganggu di kepalaku tidak sebanyak itu, jadi tidak usah deh..."
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "Kalau begitu, kamu juga kuat."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "Sayangnya, selalu ada seseorang yang memancing di dekat air terjun itu. Agak berisik."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "Suatu kali aku keluar dari air terjun dan ingin menyuruhnya agar lebih tenang. Dia kaget sampai melempar ikannya ke wajahku, lalu kabur."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "Entah dia masih akan datang lagi atau tidak."
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Hmm... Kurasa dia tidak akan datang lagi..."
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "Ada apa dengan kalian?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "Kalian tidak bertengkar, kan?"
  },
  AvgCommunicate_66986_Content_4 = {
