  },
  AvgCommunicate_66986_Content_5 = {
    Text = "Sebelumnya dia bilang pertarunganku kurang murni, sekarang aku kira-kira sudah paham maksudnya."
  },
  AvgCommunicate_66986_Content_6 = {
    Text = "Aku menemukan cara untuk menjadi lebih murni. Sekarang, aku jadi lebih kuat."
  },
  AvgCommunicate_66986_Content_7 = {
    Text = "Itu hal bagus, tapi cara apa yang kamu pakai untuk menjadi lebih murni?"
  },
  AvgCommunicate_66986_Content_8 = {
    Text = "Berdiri di bawah air terjun, biarkan aliran air membawa pergi semua pikiran yang mengganggu."
  },
  AvgCommunicate_66986_Content_9 = {
    Text = "Sangat berguna. Mau ikut bersama?"
  },
  AvgCommunicate_66986_Option_10 = {
    Text = "Ahaha... Kurasa pikiran pengganggu di kepalaku tidak sebanyak itu, jadi tidak usah deh..."
