  AvgCommunicate_66987_Content_10 = {
    Text = "Benar-benar nenek yang baik hati dan lembut."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Mm, jadi, aku juga ingin belajar cara memasak ikan. Lain kali, aku yang akan memasakkannya untuknya."
  },
  AvgCommunicate_66987_Content_12 = {
    Text = "Sungguh mengharukan! Harus dilakukan! Aku akan pergi sekarang dan menginterogasi koki kantin untukmu!"
