  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Mm, setelah terakhir kali pemancing itu kabur karena ketakutan melihatku, area sekitar air terjun jadi sepi untuk waktu yang lama."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "Belakangan ini ada seorang nenek yang datang memancing di sini, dia tidak pernah berisik, jadi aku juga tidak menampakkan diri."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Lalu suatu kali, dia menyalakan api dan memanggang ikan hasil pancingannya."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "Karena aromanya sangat harum, perutku mengeluarkan sedikit suara, dan dia menyadari keberadaanku."
  },
  AvgCommunicate_66987_Content_7 = {
    Text = "Hah? Dia juga ketakutan melihatmu?"
