  AvgCommunicate_66987_Option_12 = {
    Text = "Sungguh mengharukan! Harus dilakukan! Aku akan pergi sekarang dan menginterogasi koki kantin untukmu!"
  },
  AvgCommunicate_66987_Option_2 = {
    Text = "Resep?? Kamu mau memasak?"
  },
  AvgCommunicate_66987_Option_7 = {
    Text = "Hah? Dia juga ketakutan melihatmu?"
  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Baru-baru ini dapat sejumlah uang lagi, tapi hampir mati, untung dewi keberuntungan selalu melindungiku."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "Tapi saat kami berkelahi, jebakan yang terpicu malah tidak sengaja mengenai dirinya sendiri."
  },
  AvgCommunicate_66988_Content_11 = {Text = "Hah?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "Aku bahkan melakukan pertolongan pertama untuk menghentikan pendarahannya, baru setelah itu mengantarnya hidup-hidup ke kantor polisi."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "Kantor polisi memberiku hadiah uang, dan penjahat itu kembali masuk penjara. Kudengar hukumannya akan diubah menjadi seumur hidup."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "Padahal tinggal beberapa tahun lagi dia bisa bebas, kenapa harus melakukan hal bodoh begitu, haah…"
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Sejenak sulit menentukan siapa yang lebih menyedihkan antara kamu dan dia…"
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "Tapi kalau tidak salah ingat, kemarin kamu masih dikejar-kejar orang dari tempat judi untuk menagih utang. Ke mana uang hadiahmu?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "Ahaha… bagaimanapun keberuntunganku juga ada batasnya. Kalau sudah dihabiskan duluan, di meja judi pasti sesekali kalah juga…"
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "Mendengar ini, tiba-tiba hatiku merasa jauh lebih lega."
  },
  AvgCommunicate_66988_Content_2 = {
    Text = "Apa yang terjadi??"
  },
  AvgCommunicate_66988_Content_3 = {
    Text = "Kamu tahu kan, biasanya aku menerima komisi detektif dari luar, dan karena tingkat keberhasilan memecahkan kasus yang sangat tinggi, aku selalu diminati."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "Tapi sebaliknya, para penjahat yang kukirim ke penjara sangat membenciku sampai gigi mereka gatal."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Karena mereka memang kalah dengan cara yang tidak masuk akal, sih."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "Dua hari lalu, seorang penjahat kabur dari penjara dan pergi ke tempat judi yang sering kukunjungi, menunggu di sana selama beberapa hari, dan akhirnya berhasil menemukanku."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "Dia datang untuk balas dendam?!"
