  },
  AvgCommunicate_66988_Option_5 = {
    Text = "Karena mereka memang kalah dengan cara yang tidak masuk akal, sih."
  },
  AvgCommunicate_66988_Option_7 = {
    Text = "Dia datang untuk balas dendam?!"
  },
  AvgCommunicate_66989_Content_1 = {
    Text = "Keeper, pertanyaan yang kamu ajukan padaku soal rencana penanganan krisis Investigator sudah selesai aku susun."
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "Meskipun aku lebih peduli pada kebutuhanmu dibanding Ramona yang itu, tapi jangan lupa, aku juga pernah menjadi dirinya."
  },
  AvgCommunicate_66989_Content_11 = {
