  AvgCommunicate_66990_Content_1 = {
    Text = "Penjaga Kucing, nama-nama kalian semua terlalu susah ditulis, aku sama sekali tidak bisa ingat huruf mana yang benar!"
  },
  AvgCommunicate_66990_Content_10 = {
