  },
  AvgCommunicate_66990_Content_12 = {
    Text = "Tentu saja ya Aegis dan Lily, mereka kan teman, nama teman mana bisa disamakan!"
  },
  AvgCommunicate_66990_Content_13 = {
    Text = "Lalu kenapa aku dipanggil Penjaga Kucing..."
  },
  AvgCommunicate_66990_Content_14 = {
    Text = "Bukannya mirip-mirip saja! Jangan pelit begitu, cepat bantu aku memikirkan nama kode untuk orang lain!"
  },
  AvgCommunicate_66990_Content_15 = {
    Text = "Kurasa lebih baik aku carikan seseorang untuk mengajarimu membaca dulu."
  },
  AvgCommunicate_66990_Content_2 = {
    Text = "Hmm, memang agak berat untukmu sih. Bagaimana kalau minta Ramona mengajarimu membaca dan menulis?"
  },
  AvgCommunicate_66990_Content_3 = {
    Text = "Ogah! Apa-apaan, orang Distrik Barat, kau meremehkan orang yang tidak bisa baca tulis ya?"
