  },
  AvgCommunicate_66990_Content_5 = {
    Text = "Heheh, masalah kecil seperti ini mana bisa mengalahkan pencuri ulung sepertiku."
  },
  AvgCommunicate_66990_Content_6 = {
    Text = "Aku memutuskan untuk memberi semua orang nama kode, jadi aku bisa menuliskannya."
  },
