  AvgCommunicate_66991_Content_10 = {
    Text = "Hanya bisa begitu untuk sekarang... Terima kasih, Penjaga Rahasia."
  },
  AvgCommunicate_66991_Content_11 = {
    Text = "Di saat seperti ini malah bersopan santun denganku. Tunggu aku ganti baju dulu baru keluar... Tunggu sebentar."
  },
  AvgCommunicate_66991_Content_12 = {
    Text = "Kenapa ada ekor yang familiar di tumpukan bajuku..."
  },
  AvgCommunicate_66991_Content_13 = {
    Text = "Brown?! Brown ada di tempatmu?!"
  },
  AvgCommunicate_66991_Content_14 = {
    Text = "Ya, tidak perlu dicari lagi, dan juga dia terjerat kemejaku, mulutnya masih menggigit kaus kakiku dan tidak mau melepaskannya. Kamu punya penjelasan soal ini?"
  },
  AvgCommunicate_66991_Content_15 = {
    Text = "I-ini pasti hobi dia sendiri sebagai tikus, tidak ada hubungannya denganku!"
  },
  AvgCommunicate_66991_Content_16 = {
    Text = "Paling-paling aku ganti sepasang kaus kaki untukmu, sudahlah."
  },
  AvgCommunicate_66991_Content_2 = {
    Text = "Brown? Bukankah dia selalu bersamamu?"
  },
  AvgCommunicate_66991_Content_3 = {
    Text = "Kebanyakan waktu memang begitu, tapi kadang dia juga keluar untuk mencu... ehm, berburu sesuatu. Paling lama setengah hari dia pasti kembali, tapi aku sudah seharian penuh tidak melihatnya!"
  },
  AvgCommunicate_66991_Content_4 = {
    Text = "Jangan panik dulu, aku bantu kamu berpikir. Biasanya dia sering pergi ke mana saja?"
  },
  AvgCommunicate_66991_Content_5 = {
    Text = "Biasanya yang paling sering dikunjungi adalah dapur, tapi orang-orang bodoh itu tidak mungkin bisa menangkap Brown."
  },
  AvgCommunicate_66991_Content_6 = {
    Text = "Mungkin juga dia pergi ke laboratorium untuk mencari benda-benda berkilau, tapi aku sudah mencari satu per satu dan tidak menemukan jejak Brown sama sekali."
  },
  AvgCommunicate_66991_Content_7 = {
    Text = "...Oh, jadi begitu asal muasal kejadian misterius komponen laboratorium yang sering hilang."
  },
  AvgCommunicate_66991_Content_8 = {
    Text = "Aku sudah berkeliling kampus berkali-kali, jangan-jangan dia... jangan-jangan dia dimakan kucing kampus sialan itu!!"
  },
  AvgCommunicate_66991_Content_9 = {
    Text = "Hmm, kucing kampus itu seharusnya bukan selera seperti itu... Begini saja, aku akan segera membuat selebaran pencarian tikus dan menempelkannya di seluruh kampus. Kalau semua orang ikut membantu mencari, pasti bisa ditemukan!"
