  },
  AvgCommunicate_66992_Content_13 = {
    Text = "Gawat, kok ada orang mengetuk pintu..."
  },
  AvgCommunicate_66992_Content_14 = {
    Text = "Hilarest, aku mau mengajukan permintaan ulang, cepat selamatkan aku!!!"
  },
  AvgCommunicate_66992_Content_15 = {
