  },
  AvgCommunicate_66994_Content_12 = {
    Text = "Tuan, bisakah belikan kami beberapa buku dongeng?"
  },
  AvgCommunicate_66994_Content_13 = {
    Text = "Tidak masalah, kali ini aku pasti belikan kalian buku yang asli."
