  },
  AvgCommunicate_66995_Content_4 = {
    Text = "Berhenti banyak bicara, pergi usir wanita bernama Rotan itu."
  },
  AvgCommunicate_66995_Content_5 = {
    Text = "Orang gila itu sudah menggangguku selama sebulan."
  },
  AvgCommunicate_66995_Content_6 = {
    Text = "Lagipula, dia tidak bisa dikalahkan tidak peduli bagaimana aku melawannya. Menyebalkan sekali!"
