  },
  AvgCommunicate_66996_Content_10 = {
    Text = "Kalau begitu, semoga kau mendapatkan apa yang kau inginkan. Jika suatu hari nanti kau ingin kembali, pintu Mesagard akan selalu terbuka untukmu."
  },
  AvgCommunicate_66996_Content_2 = {
    Text = "Sekelompok orang yang mengaku pembela keadilan, mengurung sekumpulan binatang buas yang dikalungi rantai."
  },
  AvgCommunicate_66996_Content_3 = {
    Text = "Aku benar-benar tidak mengerti kenapa diriku yang satu itu mau ikut-ikutan permainan kalian yang membosankan ini. Tapi kalau dipikir-pikir dia memang selemah itu, semuanya jadi masuk akal."
