  AvgCommunicate_66996_Content_4 = {
    Text = "Kau tidak pernah dijaga dengan sungguh-sungguh oleh siapa pun, wajar saja kau tidak memahami perasaan dan makna dari melindungi seseorang."
  },
  AvgCommunicate_66996_Content_5 = {
    Text = "Shilo adalah pejuang yang hebat. Dia hanya memilih untuk menerima kehangatan dan bantuan yang diberikan orang lain."
  },
  AvgCommunicate_66996_Content_6 = {
    Text = "Hah, terserah kalian saja. Kalau dia mau memakai kalung rantai itu, biarkan saja dia tinggal di sini."
  },
  AvgCommunicate_66996_Content_7 = {
    Text = "Aku akan pergi. Terus tinggal di sini hanya akan membuat seorang pejuang menjadi tumpul."
  },
  AvgCommunicate_66996_Content_8 = {
