  AvgCommunicate_66999_Content_1 = {
    Text = "%player%{Male=tuan,Female=nyonya}, tadi aku diundang oleh pihak sekolah untuk membantu Misager merekam musik yang diputar saat jam masuk dan jam pulang."
  },
  AvgCommunicate_66999_Content_10 = {
    Text = "Kalau harus menyebutkan keistimewaannya, mungkin karena lagu itu dipenuhi perasaanku untuk menjagamu."
  },
  AvgCommunicate_66999_Content_11 = {
    Text = "Sebenarnya aku selalu agak susah bangun tidur. Kalau ada musik yang membangkitkan semangat, bangun pagi pasti akan lebih mudah!"
  },
  AvgCommunicate_66999_Content_12 = {
    Text = "Yang membangkitkan semangat? Aku mengerti."
  },
  AvgCommunicate_66999_Content_13 = {
    Text = "Meskipun menurutku tidur yang cukup dan berkualitas itu lebih penting, tapi mengingat kamu memikul begitu banyak tanggung jawab, kesibukan memang tidak bisa dihindari."
  },
  AvgCommunicate_66999_Content_14 = {
    Text = "Semoga mars ini bisa memberimu kekuatan."
  },
  AvgCommunicate_66999_Content_2 = {
    Text = "Saat rekaman, Profesor Doer juga menyebutkan bahwa pihak sekolah telah membuat perekam suara model baru yang berukuran kecil, kualitas suaranya halus, bahkan bisa dibawa saat menjalankan misi, dengan fungsi merekam dan memutar."
  },
  AvgCommunicate_66999_Content_3 = {
    Text = "Begitu melihatnya, aku langsung teringat padamu. Kalau kamu mau, aku bisa merekamkan lagu yang ingin kamu dengarkan."
  },
  AvgCommunicate_66999_Content_4 = {
    Text = "Dengan begitu, meskipun terkadang aku tidak ada di sisimu, aku tidak perlu khawatir tidak ada musik yang menenangkan jiwamu."
  },
  AvgCommunicate_66999_Content_5 = {
    Text = "Hamelin... Aku sangat terharu!"
  },
  AvgCommunicate_66999_Content_6 = {
    Text = "Ini sudah menjadi kewajibanku. Jadi, ada lagu yang ingin kamu dengarkan?"
  },
  AvgCommunicate_66999_Content_7 = {
    Text = "Ngomong-ngomong, setiap kali mendengarmu memainkan lagu pengantar tidur, aku selalu bisa tidur nyenyak."
  },
  AvgCommunicate_66999_Content_8 = {
