  AvgCommunicate_67000_Content_1 = {
    Text = "%player%{Male=tuan,Female=nyonya}, baru-baru ini aku menciptakan sebuah lagu baru, aku ingin mengundangmu untuk memberikan komentar di waktu senggangmu."
  },
  AvgCommunicate_67000_Content_10 = {
    Text = "Ah, permintaan seperti itu memang agak berlebihan, aku kurang mempertimbangkannya."
  },
  AvgCommunicate_67000_Content_11 = {
    Text = "Bagaimana kalau lain kali aku bermain musik di samping tempat tidurmu, biar aku yang mencatat secara detail tidurmu."
  },
  AvgCommunicate_67000_Content_12 = {
    Text = "Aku berharap setiap kali kamu terlelap, ada aku yang menjagamu."
  },
  AvgCommunicate_67000_Content_2 = {
    Text = "Kau terlalu sopan, Hamelin, orang setengah-setengah sepertiku mana layak mengomentari karyamu."
