  },
  AvgCommunicate_67000_Content_5 = {
    Text = "Lagumu memang sangat indah, permainannya juga sempurna, hanya saja setiap kali aku seperti terhipnotis dan langsung tertidur pulas. Mungkin aku memang tidak punya bakat musik."
