  },
  AvgCommunicate_67000_Content_8 = {
    Text = "Lebih tepatnya, bisakah kau mendeskripsikan secara detail perasaan yang dibawa oleh setiap lagu yang berbeda, serta kualitas tidur setelah mendengarkannya, kecepatan tertidur, durasi tidur, dan sebagainya."
