  AvgCommunicate_67005_Option_9 = {
    Text = "Hmm... Lake akan mengadakan meja judi malam ini, tentu saja yang rahasia."
  },
  AvgCommunicate_67006_Content_1 = {
    Text = "Aku menyadari, meskipun kemajuan teknologi dan perkembangan bisnis di era sekarang masih tetap membosankan, namun bantal ternyata sudah ditemukan dalam berbagai variasi baru."
  },
  AvgCommunicate_67006_Content_10 = {
    Text = "Tenaga penjual itu menarikku sambil berkata bahwa aku benar-benar penguji tidur alami, dan memaksa agar aku menguji bantal untuk mereka secara jangka panjang."
  },
  AvgCommunicate_67006_Content_11 = {
    Text = "Mereka menyuruhmu bekerja? Kalau Miriam tahu, bukankah dia akan pergi menghabisi mereka."
  },
  AvgCommunicate_67006_Content_12 = {
    Text = "Awalnya aku ingin menolak, tapi dia bilang penguji tidur bisa mendapatkan semua produk baru secara gratis untuk dibawa pulang dan dicoba."
  },
  AvgCommunicate_67006_Content_13 = {
    Text = "Melihat ketulusannya, aku pun menyetujuinya."
  },
  AvgCommunicate_67006_Content_14 = {
    Text = "Tidak kusangka kau bisa disuap dengan bantal... ah maksudku, sungguh raja yang baik hati."
  },
  AvgCommunicate_67006_Content_2 = {
    Text = "Dua hari lalu, aku kebetulan melewati department store di Londinium dan menemukan mereka sedang mempromosikan serangkaian bantal baru."
  },
  AvgCommunicate_67006_Content_3 = {
    Text = "Aku baru melihat sekilas saja, tapi tenaga penjual itu sudah menarikku ke tempat tidur sampel untuk mencoba tidur. Sungguh tidak sopan."
  },
  AvgCommunicate_67006_Content_4 = {
    Text = "Eh, memang khas gaya promosi mereka sih."
  },
  AvgCommunicate_67006_Content_5 = {
    Text = "Tapi bantal yang disebut 'bantal awan' itu memang luar biasa lembut, tidak seperti bulu angsa, juga tidak seperti kapas. Entah terbuat dari bahan apa."
  },
  AvgCommunicate_67006_Content_6 = {
    Text = "Mungkin semacam produk industri? Memang sesuatu yang tidak ada di zaman dulu."
  },
  AvgCommunicate_67006_Content_7 = {
    Text = "Gara-gara bantal itu terlalu nyaman, aku tiba-tiba mengantuk dan benar-benar tertidur di tempat tidur itu. Sungguh memalukan."
  },
  AvgCommunicate_67006_Content_8 = {
    Text = "Senyaman itu kah?!"
  },
  AvgCommunicate_67006_Content_9 = {
    Text = "Setelah bangun, aku membahas beberapa masalah tentang bentuk bantal dengan tenaga penjual itu."
  },
