  AvgCommunicate_67007_Content_11 = {
    Text = "Iya iya iya, beli semua, beli semua!"
  },
  AvgCommunicate_67007_Content_12 = {
    Text = "Tuan, alat komunikasinya tadi direbut dan jatuh ke tanah, sepertinya ada komponen yang copot."
  },
  AvgCommunicate_67007_Content_13 = {
    Text = "Yang ini juga bisa beli yang baru?"
  },
  AvgCommunicate_67007_Content_14 = {Text = "Hah???"},
  AvgCommunicate_67007_Content_2 = {
    Text = "Dia bilang ada mainan bernama tangram, seperti tujuh keping balok pipih yang bisa disusun menjadi banyak pola, dan bisa disusun kembali ke dalam bingkai persegi besar."
  },
  AvgCommunicate_67007_Content_3 = {
    Text = "Jenkin bilang bisa membuat satu dari kertas, tapi kami berpikir lama dan tetap tidak bisa menggambar bentuk tangram itu."
  },
  AvgCommunicate_67007_Content_4 = {
    Text = "Apakah Tuan pernah melihat bentuk tangram?"
