  AvgCommunicate_67008_Content_12 = {
    Text = "Aku sudah lama merasa, ini bukan masalahmu. Kamu benar-benar ditipu oleh orang yang menjual ramuan itu, mereka hanya memanfaatkan perasaan putus asamu."
  },
  AvgCommunicate_67008_Content_13 = {
