  AvgCommunicate_67008_Content_15 = {
    Text = "Bukankah aku sudah bilang dari tadi!!"
  },
  AvgCommunicate_67008_Content_16 = {
    Text = "Ternyata aku hanya sakit, berarti kebangkitanku masih ada harapan."
  },
  AvgCommunicate_67008_Content_17 = {
    Text = "Iya iya... benar sekali, jadi kamu cukup berobat dengan baik saja."
  },
  AvgCommunicate_67008_Content_18 = {
    Text = "Aku mengerti, terima kasih, Penjaga Rahasia."
  },
  AvgCommunicate_67008_Content_19 = {
