  AvgCommunicate_67013_Option_10 = {
    Text = "Kosongkan samsak di ruang latihan, lalu masukkan kamu ke dalamnya. Ingat, jangan bersuara."
  },
  AvgCommunicate_67013_Option_2 = {
    Text = "……Kamu kenapa? Kalau sakit, kamu bisa pergi ke ruang medis untuk berobat."
  },
  AvgCommunicate_67013_Option_4 = {
    Text = "Separah itu? Kamu di mana? Mau aku segera panggilkan dokter?"
  },
  AvgCommunicate_67013_Option_7 = {
    Text = "……………"
  },
  AvgCommunicate_67014_Content_1 = {
    Text = "Penjaga Rahasia, terkadang aku juga berpikir, aku sudah melakukan begitu banyak hal untuk Rajaku dengan segala cara, apakah itu benar-benar membuatnya puas?"
  },
  AvgCommunicate_67014_Content_10 = {
    Text = "Tapi aku percaya satu-satunya hal yang bisa dirasakan oleh dewa adalah hati para pengikutnya yang penuh semangat, tulus, dan berdedikasi untuk sang dewa."
  },
  AvgCommunicate_67014_Content_11 = {
    Text = "Jadi apa yang kamu lakukan mungkin bukan yang terpenting, yang penting adalah ketulusan hatimu untuknya. Lagipula, Tulu tidak pernah menghalangimu, bukan?"
  },
  AvgCommunicate_67014_Content_12 = {
    Text = "Tak kusangka ada hari di mana aku dicerahkan oleh orang yang tidak beriman sepertimu. Aku akan mengingat kata-katamu, terima kasih."
  },
  AvgCommunicate_67014_Content_2 = {
    Text = "Apakah pilihan yang kuambil benar-benar tepat?"
  },
  AvgCommunicate_67014_Content_3 = {
    Text = "Tak kusangka kau juga punya hari untuk merefleksikan diri."
  },
  AvgCommunicate_67014_Content_4 = {
    Text = "Karena aku juga bisa merasa bingung, lelah, dan kehilangan arah. Jika semua yang kulakukan sudah benar, mengapa Raja tidak memberiku jawaban?"
  },
  AvgCommunicate_67014_Content_5 = {
    Text = "Meskipun aku tidak memiliki keyakinan yang setulus kalian, tapi menurutku apa yang dilakukan para pengikut untuk dewa mereka belum tentu merupakan hal yang dibutuhkan sang dewa."
  },
  AvgCommunicate_67014_Content_6 = {
    Text = "Apa katamu?"
  },
  AvgCommunicate_67014_Content_7 = {
    Text = "Eh, eh, jangan terburu-buru, aku belum selesai bicara."
  },
  AvgCommunicate_67014_Content_8 = {
    Text = "Perbedaan antara manusia fana dan dewa itu seperti perbedaan antara semut dan manusia. Aku tidak percaya manusia bisa sepenuhnya memahami kebutuhan dewa."
  },
  AvgCommunicate_67014_Content_9 = {
    Text = "Semut ya... Mungkin kau benar."
  },
  AvgCommunicate_67014_Option_10 = {
    Text = "Tapi aku percaya……"
  },
  AvgCommunicate_67014_Option_3 = {
    Text = "Tak kusangka kau juga punya hari untuk merefleksikan diri."
  },
  AvgCommunicate_67014_Option_5 = {
    Text = "Meskipun aku tidak memiliki keyakinan yang setulus kalian..."
  },
  AvgCommunicate_67014_Option_7 = {
    Text = "Eh, eh, jangan terburu-buru, aku belum selesai bicara."
  },
  AvgCommunicate_67015_Content_1 = {
    Text = "Penjaga Rahasia, ceramah yang kuadakan di kampus serta brosur yang kucetak sebelumnya sudah disambut baik oleh banyak orang."
  },
  AvgCommunicate_67015_Content_10 = {
    Text = "Nona Shan? Aku jarang bertemu dengannya, kudengar dia seorang pematung yang luar biasa."
  },
  AvgCommunicate_67015_Content_11 = {
    Text = "Kalau dia bersedia memahat patung untukku, itu akan sangat sempurna. Kerajaan Dewa akan memberkatinya."
  },
  AvgCommunicate_67015_Content_2 = {
    Text = "Mereka semua mulai memiliki rasa pemujaan terhadap Tuhanku yang agung. Beberapa jemaat bilang padaku, mereka ingin mendapatkan patung mini Tuhan, supaya mudah untuk berdoa dan menyembah di kamar mereka."
  },
  AvgCommunicate_67015_Content_3 = {
    Text = "Menurutku apa yang mereka katakan masuk akal. Di mana bisa menemukan pengrajin untuk memesan sejumlah patung seperti itu?"
  },
  AvgCommunicate_67015_Content_4 = {
    Text = "Patung mini? Kenapa kedengarannya agak aneh..."
  },
  AvgCommunicate_67015_Content_5 = {
    Text = "Kenapa? Patung seperti ini memang memerlukan keahlian yang halus, apakah di Mitsagor saat ini tidak ada pengrajin seperti itu?"
  },
  AvgCommunicate_67015_Content_6 = {
    Text = "Bukan masalah pengrajinnya sih, hanya saja rasanya mereka menginginkan patung-patung itu bukan untuk berdoa dan menyembah..."
  },
  AvgCommunicate_67015_Content_7 = {
    Text = "Tidak mungkin, aku sudah menyaksikan sendiri betapa fanatiknya mereka terhadap Tuhanku. Mereka bahkan memperhatikan setiap detail kesukaan dan kehidupan Tuhan."
  },
  AvgCommunicate_67015_Content_8 = {
    Text = "Justru itu yang membuktikannya... Sudahlah, yang penting kau senang."
  },
  AvgCommunicate_67015_Content_9 = {
    Text = "Biar aku tanyakan pada Shan apakah dia bersedia membuat patung-patung ini."
  },
  AvgCommunicate_67015_Option_4 = {
    Text = "Patung mini? Kenapa kedengarannya agak aneh..."
  },
  AvgCommunicate_67015_Option_6 = {
    Text = "Bukan masalah pengrajinnya sih..."
  },
  AvgCommunicate_67015_Option_8 = {
    Text = "Justru itu yang membuktikannya... Sudahlah, yang penting kau senang."
  },
  AvgCommunicate_67016_Content_1 = {
    Text = "Haah, Penjaga Rahasia, saya datang untuk melaporkan kelalaian saya kepada Anda dan Lord Dexter, semoga bisa mendapatkan maaf dari kalian."
  },
  AvgCommunicate_67016_Content_10 = {
    Text = "Uhuk, meskipun kasihan, tapi ini bukan salahmu. Jangan menyalahkan diri sendiri."
  },
  AvgCommunicate_67016_Content_11 = {
    Text = "Tidak, ini semua masalah yang disebabkan oleh kelalaian saya. Saya akan menerbitkan pernyataan introspeksi secara terbuka dan memperketat manajemen sehari-hari."
  },
  AvgCommunicate_67016_Content_2 = {
    Text = "Karena kelalaian manajemen pribadi saya, dua pasien di sanatorium keracunan parah. Untungnya, setelah mendapat pertolongan darurat, mereka sudah melewati masa kritis."
  },
  AvgCommunicate_67016_Content_3 = {
    Text = "Hah? Apa yang terjadi?"
  },
  AvgCommunicate_67016_Content_4 = {
    Text = "Begini, di belakang sanatorium ada sebuah kolam kecil yang jarang dikunjungi orang."
  },
  AvgCommunicate_67016_Content_5 = {
    Text = "Anda tahu betapa saya menyukai air. Di hari-hari kerja yang sibuk, saya akan diam-diam menyelam ke kolam di malam hari, menikmati ketenangan dunia bawah air sejenak."
  },
  AvgCommunicate_67016_Content_6 = {
    Text = "Hmm... bisa dimengerti, siapa sih yang tidak stres saat bekerja."
  },
  AvgCommunicate_67016_Content_7 = {
    Text = "Mungkin karena saya terlalu sering pergi ke sana, racun dari tubuh saya secara bertahap menyebar ke kolam dan ikan-ikan di dalamnya."
  },
  AvgCommunicate_67016_Content_8 = {
    Text = "Sebenarnya kolam itu tidak berada di area aktivitas pasien, tapi dua hari lalu ada dua pasien yang kelaparan diam-diam pergi ke kolam untuk memancing dan memanggang ikan untuk dimakan."
  },
  AvgCommunicate_67016_Content_9 = {
    Text = "Ketika staf medis menemukan mereka, mereka sudah berbusa mulutnya dan pingsan di tanah..."
  },
  AvgCommunicate_67016_Option_10 = {
    Text = "Uhuk, meskipun kasihan, tapi ini bukan salahmu. Jangan menyalahkan diri sendiri."
  },
  AvgCommunicate_67016_Option_3 = {
    Text = "Hah? Apa yang terjadi?"
  },
  AvgCommunicate_67016_Option_6 = {
    Text = "Hmm... bisa dimengerti, siapa sih yang tidak stres saat bekerja."
  },
  AvgCommunicate_67017_Content_1 = {
    Text = "Penjaga Rahasia, sebelumnya ada tamu yang berkunjung ke Myssagor yang tidak sengaja mendengar nyanyianku saat latihan."
  },
  AvgCommunicate_67017_Content_10 = {
    Text = "Kamu mencintai menyanyi, mencintai tampil, kenapa tidak membiarkan nyanyianmu didengar oleh lebih banyak orang?"
  },
  AvgCommunicate_67017_Content_11 = {
    Text = "Mencintai ya... Aku mengerti, terima kasih, Penjaga Rahasia."
  },
  AvgCommunicate_67017_Content_12 = {
    Text = "Aku akan mencoba untuk bersinar kembali di planet ini."
  },
  AvgCommunicate_67017_Content_2 = {
    Text = "Sekarang dia mengundangku untuk bekerja sama dengan perusahaannya, merilis beberapa album. Haruskah aku menerimanya?"
  },
  AvgCommunicate_67017_Content_3 = {
    Text = "Menurutku boleh saja, kalau tidak salah kamu dulu juga penyanyi terkenal, kan?"
  },
  AvgCommunicate_67017_Content_4 = {
    Text = "Ya, nyanyianku pernah populer di seluruh Bintang Tandus, tapi kebanyakan itu hanya untuk bertransaksi dengan para bangsawan."
  },
  AvgCommunicate_67017_Content_5 = {
    Text = "Sekarang aku sudah kembali memiliki kakak, aku tidak lagi membutuhkan apa pun."
  },
  AvgCommunicate_67017_Content_6 = {
    Text = "Lalu bagaimana denganmu sendiri? Saat bernyanyi, apakah kamu masih merasa bahagia?"
  },
  AvgCommunicate_67017_Content_7 = {
    Text = "Bahagia... mungkin memang bahagia, lagipula selain bernyanyi aku juga tidak bisa melakukan hal lain."
  },
  AvgCommunicate_67017_Content_8 = {
    Text = "Tidak, Tincture, kalau bukan karena benar-benar mencintainya, tidak ada orang yang akan terus berlatih menyanyi setiap hari."
  },
  AvgCommunicate_67017_Content_9 = {
    Text = "Mempertahankan apa yang kamu cintai adalah hal yang sudah sewajarnya."
  },
  AvgCommunicate_67017_Option_3 = {
    Text = "Menurutku boleh saja, kalau tidak salah kamu dulu juga penyanyi terkenal, kan?"
  },
  AvgCommunicate_67017_Option_6 = {
    Text = "Lalu bagaimana denganmu sendiri? Saat bernyanyi, apakah kamu masih merasa bahagia?"
  },
  AvgCommunicate_67017_Option_8 = {
    Text = "Kalau bukan karena benar-benar mencintainya, tidak ada orang yang akan terus berlatih menyanyi setiap hari."
  },
  AvgCommunicate_67018_Content_1 = {
    Text = "Utusan yang Pucat, aku ingin menghubungimu secara khusus untuk memberitahu bahwa aku akan segera mengunjungi Mesagge."
  },
  AvgCommunicate_67018_Content_2 = {
    Text = "Kunjungan sebelumnya tampaknya memberikan sedikit bantuan bagi semua orang, dan aku diundang untuk datang lagi, berbincang-bincang dengan semua orang di aula."
  },
  AvgCommunicate_67018_Content_3 = {
    Text = "Jika kamu kebetulan punya waktu luang, aku berharap bisa bertemu denganmu di kampus."
  },
  AvgCommunicate_67018_Content_4 = {
    Text = "Aku sangat senang!"
  },
  AvgCommunicate_67018_Content_5 = {
    Text = "Bagus sekali, aku akan menyediakan waktu khusus untukmu, mendengarkan semua yang ingin kamu ceritakan padaku."
  },
  AvgCommunicate_67018_Content_6 = {
    Text = "Kita bertemu berdua saja?"
  },
  AvgCommunicate_67018_Content_7 = {
    Text = "Ya, bagaimanapun ini bukan kebaktian, hanya pertemuan antara teman, bukan?"
  },
  AvgCommunicate_67018_Content_8 = {
    Text = "Tidak masalah, aku akan mengajakmu berkeliling melihat tempat-tempat menarik di Mesagge, mungkin kamu ingin mencicipi kantin Kebangkitan?"
  },
  AvgCommunicate_67018_Content_9 = {
    Text = "Semuanya terserah pengaturanmu, aku sangat menantikannya."
  },
  AvgCommunicate_67018_Option_4 = {
    Text = "Aku sangat senang!"
  },
  AvgCommunicate_67018_Option_6 = {
    Text = "Kita bertemu berdua saja?"
  },
  AvgCommunicate_67018_Option_8 = {
    Text = "Tidak masalah!"
  },
  AvgCommunicate_67019_Content_1 = {
    Text = "Utusan yang pucat, dalam waktu dekat akan diadakan misa besar di Distrik Katedral."
  },
  AvgCommunicate_67019_Content_10 = {
    Text = "Ketulusanmu membuatku merasa begitu hangat, kalau begitu aku tidak akan menolak lagi."
  },
  AvgCommunicate_67019_Content_11 = {
    Text = "Datanglah saat kamu senggang, dan bantu aku melakukan sedikit bersih-bersih dan penataan sederhana saja."
  },
  AvgCommunicate_67019_Content_12 = {
    Text = "Tidak masalah, sampai jumpa nanti!"
  },
  AvgCommunicate_67019_Content_13 = {
    Text = "Sekali lagi terima kasih, Utusan yang Pucat. Semoga Sang Ayah memberkati jalanmu."
  },
  AvgCommunicate_67019_Content_2 = {
    Text = "Aku akan memimpin upacara di sana, membagikan ajaran Bapa."
  },
  AvgCommunicate_67019_Content_3 = {
    Text = "Saat itu, umat dari Londinium dan sekitarnya akan datang. Jika kau tertarik, kau juga dipersilakan untuk menghadiri perayaan syukur ini."
  },
  AvgCommunicate_67019_Content_4 = {
    Text = "Dengan senang hati! Tapi harus memperhatikan begitu banyak umat, persiapan misa kali ini pasti tidak mudah ya."
  },
  AvgCommunicate_67019_Content_5 = {
    Text = "Kau selalu begitu perhatian, baik hati, dan memikirkan orang lain."
  },
  AvgCommunicate_67019_Content_6 = {
    Text = "Memang benar, untuk memastikan setiap orang mendapat pengaturan yang layak dan merasakan berkat Bapa, ada banyak hal yang perlu dipersiapkan."
  },
  AvgCommunicate_67019_Content_7 = {
    Text = "Tapi jangan khawatir, pengalamanku dalam memimpin misa sudah sangat banyak, aku bisa menangani urusan-urusan kecil ini."
  },
  AvgCommunicate_67019_Content_8 = {
    Text = "Sepengalaman apa pun, kau tetap tidak punya tiga kepala enam tangan. Kalau boleh, biarkan aku datang lebih awal untuk membantumu!"
  },
  AvgCommunicate_67019_Content_9 = {
    Text = "Bagaimanapun, acara sebesar ini tentu memerlukan persiapan yang semakin detail semakin baik."
  },
  AvgCommunicate_67019_Option_12 = {
    Text = "Tidak masalah, sampai jumpa nanti!"
  },
  AvgCommunicate_67019_Option_4 = {
    Text = "Dengan senang hati!"
  },
  AvgCommunicate_67019_Option_8 = {
    Text = "Kalau boleh, biarkan aku datang lebih awal untuk membantumu!"
  },
  AvgCommunicate_67020_Content_1 = {
    Text = "Haah, sejak Misager mengeluarkan perintah pembatasan, tidak ada lagi anak-anak manis yang datang menemaniku mengobrol."
  },
  AvgCommunicate_67020_Content_10 = {
    Text = "Baiklah, kalau begitu aku hanya bisa berdoa agar matahari cepat terbenam."
  },
  AvgCommunicate_67020_Content_11 = {
    Text = "Ah, mulai menantikan cahaya bulan malam ini."
  },
  AvgCommunicate_67020_Content_2 = {
    Text = "Katanya tanpa pendampinganmu, orang lain tidak boleh menemuiku."
  },
  AvgCommunicate_67020_Content_3 = {
    Text = "Kamu ini, coba katakan, bukankah ini karena kamu cemburu lalu mengadu ke sekolah?"
  },
  AvgCommunicate_67020_Content_4 = {
    Text = "Jelas-jelas kamu duluan yang membujuk murid-murid minum sesuatu yang aneh…"
  },
  AvgCommunicate_67020_Content_5 = {
    Text = "Itu jelas-jelas anugerah cinta, apakah di matamu aku serendah itu?"
  },
  AvgCommunicate_67020_Content_6 = {
    Text = "Setiap hari aku menunggumu dalam kesepian, tidak kusangka begitulah pandanganmu terhadapku…"
  },
  AvgCommunicate_67020_Content_7 = {
    Text = "Cukup! Aku mengerti, aku akan lebih sering datang menemanimu."
  },
  AvgCommunicate_67020_Content_8 = {
    Text = "Anak yang benar-benar pengertian, tapi aku ingin melihatmu setiap saat, sekarang juga, tidak mau menunggu barang sedetik pun."
  },
  AvgCommunicate_67020_Content_9 = {
    Text = "Malam ini, malam ini aku akan datang, oke!"
  },
  AvgCommunicate_67020_Option_4 = {
    Text = "Jelas-jelas kamu duluan yang membujuk murid-murid minum sesuatu yang aneh…"
  },
  AvgCommunicate_67020_Option_7 = {
    Text = "Cukup! Aku mengerti, aku akan lebih sering datang menemanimu."
  },
  AvgCommunicate_67020_Option_9 = {
    Text = "Malam ini, malam ini aku akan datang, oke!"
  },
  AvgCommunicate_67021_Content_1 = {
    Text = "Penjaga Rahasia, maaf mengganggu. Apakah kamu punya waktu luang belakangan ini?"
  },
  AvgCommunicate_67021_Content_10 = {
    Text = "Jadi, boleh minta aku menemanimu pergi?"
  },
  AvgCommunicate_67021_Content_11 = {
    Text = "Mm, bolehkah?"
  },
  AvgCommunicate_67021_Content_12 = {
    Text = "Tentu saja tidak masalah, kedengarannya akan sangat seru!"
  },
  AvgCommunicate_67021_Content_13 = {
    Text = "Terima kasih, Penjaga Rahasia! Dengan kamu menemaniku, rasanya jauh lebih tenang."
  },
  AvgCommunicate_67021_Content_14 = {
    Text = "Kudengar puisi yang dibuat langsung di tempat berkesempatan mendapatkan hadiah. Kalau nanti aku beruntung mendapatkannya, akan kuberikan padamu sebagai tanda terima kasih."
  },
  AvgCommunicate_67021_Content_2 = {
    Text = "Ada apa? Jarang sekali kamu yang mencari aku duluan."
  },
  AvgCommunicate_67021_Content_3 = {
    Text = "Begini, belakangan ini ada acara pasar puisi dan sastra di Londinium. Banyak buku baru dan lama akan dijual di pasar itu, dan banyak penyair juga akan datang untuk bertukar pikiran."
  },
  AvgCommunicate_67021_Content_4 = {
    Text = "Penyelenggara juga mengundangku untuk membuka stan di sana, untuk membagikan kumpulan puisiku."
  },
  AvgCommunicate_67021_Content_5 = {
    Text = "Mereka sangat ramah mengundangku, dan tanpa sadar aku sudah menyetujuinya, tapi……"
  },
  AvgCommunicate_67021_Content_6 = {
    Text = "Tapi kalau buka stan sendirian, rasanya terlalu gugup?"
  },
  AvgCommunicate_67021_Content_7 = {
    Text = "Mm…… kamu selalu bisa memahami aku."
  },
  AvgCommunicate_67021_Content_8 = {
    Text = "Tapi hal yang sudah disanggupi, aku tidak mau mengingkarinya, lagipula acara ini kelihatannya sangat menarik! Katanya ada juga sesi kreasi berantai secara langsung."
  },
  AvgCommunicate_67021_Content_9 = {Text = "Jadi..."},
  AvgCommunicate_67021_Option_10 = {
    Text = "Jadi, boleh minta aku menemanimu pergi?"
  },
  AvgCommunicate_67021_Option_12 = {
    Text = "Tentu saja tidak masalah, kedengarannya akan sangat seru!"
  },
  AvgCommunicate_67021_Option_2 = {
