  AvgCommunicate_67021_Option_6 = {
    Text = "Tapi kalau buka stan sendirian, rasanya terlalu gugup?"
  },
  AvgCommunicate_67022_Content_1 = {
    Text = "Penjaga Rahasia, akhirnya aku menemukan cara yang bagus untuk tidur dengan nyenyak."
  },
  AvgCommunicate_67022_Content_10 = {
    Text = "Ini sudah sangat mengganggu orang lain, tahu!"
  },
  AvgCommunicate_67022_Content_11 = {
    Text = "Anggap saja sebagai hiasan seni! Aku tidak mendengkur saat tidur, kok!"
  },
  AvgCommunicate_67022_Content_12 = {
    Text = "Tunggu, jangan bilang orang yang kamu percaya itu adalah aku."
  },
  AvgCommunicate_67022_Content_13 = {
    Text = "Tentu saja, Penjaga Rahasia Misagar yang paling lembut, paling bisa diandalkan, dan paling kuat — tidak ada pilihan lain selain kamu!"
  },
  AvgCommunicate_67022_Content_14 = {
    Text = "Aku berencana memindahkan bola tidurnya malam ini. Kalau kamu mau, aku juga bisa menemanimu mengobrol sebelum tidur, lho~"
  },
  AvgCommunicate_67022_Content_15 = {
    Text = "Penjaga Rahasia?"
  },
  AvgCommunicate_67022_Content_16 = {
    Text = "Penjaga Rahasia??"
  },
  AvgCommunicate_67022_Content_2 = {
    Text = "Selamat! Cara apa itu?"
  },
  AvgCommunicate_67022_Content_3 = {
    Text = "Aku merancang sebuah bola tidur yang bisa menjaga bagian dalamnya tetap terang sepanjang malam. Dengan begini, tidak perlu lampu yang terlalu kuat, dan juga bisa memastikan tidak ada sudut gelap di sekitarnya."
  },
  AvgCommunicate_67022_Content_4 = {
    Text = "Kedengarannya bagus, akhirnya kamu tidak perlu lagi masuk ke kamar orang lain setiap hari, lalu ditendang keluar."
  },
  AvgCommunicate_67022_Content_5 = {
    Text = "Tidak! Untuk mencegah kerusakan apa pun pada bola tidur, serta menghindari bahaya dari luar, aku perlu menaruh bola tidur ini di tempat yang ada orangnya."
  },
  AvgCommunicate_67022_Content_6 = {
    Text = "? Kamu mau menaruh benda ini di kamar orang lain?"
  },
  AvgCommunicate_67022_Content_7 = {
    Text = "Benar, aku akan menyerahkan tombol restart darurat bola tidur ini kepada orang yang kupercaya, dengan begitu semuanya pasti aman!"
  },
  AvgCommunicate_67022_Content_8 = {
    Text = "Lagipula, dengan ini kebiasaanku tidur dengan lampu menyala juga tidak akan mengganggu orang lain. Sempurna sekali."
  },
  AvgCommunicate_67022_Content_9 = {
    Text = "Sempurna apanya!"
  },
  AvgCommunicate_67022_Option_10 = {
    Text = "Ini sudah sangat mengganggu orang lain, tahu!"
  },
  AvgCommunicate_67022_Option_12 = {
    Text = "Tunggu, jangan bilang orang yang kamu percaya itu adalah aku."
