  AvgCommunicate_67023_Content_1 = {
    Text = "Penjaga Rahasia, akhir-akhir ini di depan mataku selalu muncul bintik-bintik aneh, dan sering pusing, jantung berdebar, sesak napas, telinga berdenging…… Apa aku akan mati!!"
  },
  AvgCommunicate_67023_Content_10 = {
    Text = "Tidak, kau tidak mengerti, kegelapan itu ada di mana-mana, ke mana pun aku pergi ia akan menemukanku! Tidak boleh tidur, tidak boleh menutup mata……"
  },
  AvgCommunicate_67023_Content_11 = {
    Text = "Ehm……bagaimana kalau kau menyewa seseorang untuk langsung memukulmu sampai pingsan? Dengan begitu kau kehilangan kesadaran dan tidak akan merasa takut lagi."
  },
  AvgCommunicate_67023_Content_12 = {
    Text = "Eh? Sepertinya perkataanmu ada benarnya juga."
  },
  AvgCommunicate_67023_Content_13 = {
    Text = "Karena bagaimanapun juga kehancuran akan datang, lebih baik biarkan aku mati dengan tenang dalam ketidaksadaran……"
  },
  AvgCommunicate_67023_Content_14 = {
    Text = "Cuma dipukul sampai pingsan saja, masih jauh dari mati!"
  },
  AvgCommunicate_67023_Content_15 = {
    Text = "Terima kasih, Penjaga Rahasia, kalau begitu urusan ini kuserahkan padamu yang paling kupercaya."
  },
  AvgCommunicate_67023_Content_16 = {
    Text = "…………Seharusnya aku tidak usah bicara!!"
  },
  AvgCommunicate_67023_Content_2 = {
    Text = "Ehm, dilihat dari pola tidurmu, sepertinya kamu terlalu sering begadang. Kusarankan kamu tidur lebih awal."
  },
  AvgCommunicate_67023_Content_3 = {
    Text = "Apa? Tubuh ini juga sudah mencapai batasnya……"
  },
  AvgCommunicate_67023_Content_4 = {
    Text = "Tapi, menghadapi kegelapan yang menakutkan itu juga bisa membunuhku!"
  },
  AvgCommunicate_67023_Content_5 = {
    Text = "Ah, sial, penderitaan panjang atau penderitaan singkat, hidup atau binasa, bagaimana harus memilih……"
  },
  AvgCommunicate_67023_Content_6 = {
    Text = "Selebay itu kah! Sampai naik ke level filosofis!"
  },
  AvgCommunicate_67023_Content_7 = {
    Text = "Tapi kamu juga tidak pernah mengalami hal buruk saat tidur kan? Rasa takut itu cuma imajinasimu saja. Menurutku kamu harus mencoba desensitisasi."
