  },
  AvgCommunicate_67024_Content_12 = {
    Text = "Tapi Guru Kassia bisa mengajari kalian cara membuat tangan menjadi lebih terampil, jadi kalau nanti menemui tali yang tak bisa dilepas, gembok yang tak bisa dibuka, kalian juga bisa menguasai teknik membuka kunci dan mengambil barang dengan cekatan!"
  },
  AvgCommunicate_67024_Content_13 = {
    Text = "Sudah kuduga kamu tetap mengajarkan hal-hal aneh!!"
  },
  AvgCommunicate_67024_Content_14 = {
    Text = "Jangan sembarangan pakai istilah aneh begitu!!"
  },
  AvgCommunicate_67024_Content_15 = {
    Text = "Tsk, murid-murid yang dihadapi Doer juga serewel ini ya? Merepotkan sekali, jadi guru benar-benar membosankan."
  },
  AvgCommunicate_67024_Content_16 = {
    Text = "Memang Guru Doer sangat berjuang keras, tapi satu-satunya yang tidak ingin kudengar adalah keluhan darimu!"
  },
  AvgCommunicate_67024_Content_2 = {
    Text = "Kamu mau bikin ulah apa lagi??"
  },
  AvgCommunicate_67024_Content_3 = {
    Text = "Apa-apaan sih, kali ini aku diundang oleh sekolah untuk mengajar semua orang dengan serius, tahu!"
  },
  AvgCommunicate_67024_Content_4 = {
    Text = "Doer memberitahuku, mencoba menjadi guru sekali bisa merasakan pengalaman mendidik dan mewariskan ilmu."
  },
  AvgCommunicate_67024_Content_5 = {
