  AvgCommunicate_67025_Content_1 = {
    Text = "Efek latihan pendampingan anjing militer yang diterapkan belakangan ini melampaui ekspektasiku."
  },
  AvgCommunicate_67025_Content_10 = {
    Text = "Tolong sisakan satu tempat untukku!!!"
  },
  AvgCommunicate_67025_Content_2 = {
    Text = "Bahkan ada siswa yang awalnya tidak ikut latihan fisik juga datang mendaftar ke kelasku, antusiasme semua orang benar-benar membuatku terkejut."
  },
  AvgCommunicate_67025_Content_3 = {
    Text = "Soalnya tidak ada yang bisa menolak anak anjing berbulu lembut!!!"
  },
  AvgCommunicate_67025_Content_4 = {
    Text = "Memang benar, agar anak-anak anjing dan para siswa bisa membangun kerja sama yang lebih baik, aku memilih anak anjing yang belum dewasa."
  },
  AvgCommunicate_67025_Content_5 = {
    Text = "Meskipun aku sama seperti yang lain menyukai makhluk-makhluk kecil ini, tapi anak anjing memang membutuhkan perawatan dan bimbingan yang jauh lebih banyak dibandingkan anjing dewasa."
  },
  AvgCommunicate_67025_Content_6 = {
    Text = "Sekarang jumlah pendaftar bertambah, jumlah anak anjing juga harus ditambah, ini benar-benar membuatku agak kewalahan."
  },
  AvgCommunicate_67025_Content_7 = {
    Text = "Ini sangat mudah, selama Instruktur Elva memberi perintah, dijamin akan ada lebih banyak orang yang bersedia mendaftar untuk merawat anak anjing, nanti malah anak anjingnya yang tidak cukup dibagi."
  },
  AvgCommunicate_67025_Content_8 = {
    Text = "Maksudmu merekrut beberapa sukarelawan? Memang ide yang bagus."
  },
  AvgCommunicate_67025_Content_9 = {
    Text = "Kalau begitu aku akan menemui Kepala Sekolah Helert untuk mengajukan hal ini, kalau lancar, para siswa juga bisa bertemu lebih banyak anak anjing."
  },
  AvgCommunicate_67025_Option_10 = {
