  AvgCommunicate_67027_Content_10 = {
    Text = "Daripada disebut permohonan, lebih seperti semua orang berharap mendapatkan keberuntungan dan berkah."
  },
  AvgCommunicate_67027_Content_11 = {
    Text = "Permohonan itu, meskipun tidak bisa langsung terwujud, menyimpannya di hati juga merupakan sebuah penghiburan dan harapan."
  },
  AvgCommunicate_67027_Content_12 = {
    Text = "Permohonan yang tidak bisa langsung terwujud... juga seberharga itu kah?"
  },
  AvgCommunicate_67027_Content_13 = {
    Text = "Sepertinya aku mengerti sekarang. Mulai besok, aku akan pergi ke air mancur sekolah untuk memberikan berkah kepada semua orang."
  },
  AvgCommunicate_67027_Content_14 = {
    Text = "Tunggu, kenapa harus di air mancur sekolah?"
  },
  AvgCommunicate_67027_Content_15 = {
    Text = "Kudengar banyak tempat yang populer membuat kolam permohonan. Jadi kalau aku mengubah air mancur sekolah menjadi kolam permohonan, semua orang bisa datang untuk meminta berkah."
  },
  AvgCommunicate_67027_Content_16 = {
    Text = "Meskipun kedengarannya masuk akal, tapi rasanya tetap aneh!"
  },
  AvgCommunicate_67027_Content_2 = {
    Text = "Hmm... mungkin karena semua orang di Misagar itu tipe yang realistis."
  },
  AvgCommunicate_67027_Content_3 = {
    Text = "Menghadapi bahaya tak terhitung setiap hari, mental mereka sudah sangat stabil, tidak akan mengandalkan permohonan untuk menyelesaikan masalah."
  },
  AvgCommunicate_67027_Content_4 = {
