  AvgCommunicate_67028_Content_10 = {
    Text = "Kalau begitu, bagus sekali. Aku akan memilih waktu yang tepat untuk berkunjung."
  },
  AvgCommunicate_67028_Content_11 = {
    Text = "Tolong rahasiakan dulu dari Lily ya, aku ingin memberinya kejutan."
  },
  AvgCommunicate_67028_Content_2 = {
    Text = "Baru-baru ini aku secara tidak sengaja mendapatkan dua ekor ikan mas merah yang cantik."
  },
  AvgCommunicate_67028_Content_3 = {
    Text = "Beruntungnya, setelah aku rawat, mereka berhasil bertelur cukup banyak, dan sekarang telur-telurnya sudah menetas menjadi banyak sekali ikan kecil."
  },
  AvgCommunicate_67028_Content_4 = {
