  AvgCommunicate_67028_Content_5 = {
    Text = "Ya, aku memiliki keterikatan yang mendalam terhadap dunia bawah air."
  },
  AvgCommunicate_67028_Content_6 = {
    Text = "Ikan yang berenang di air, rumput laut, dan karang adalah tempat yang sangat hangat dalam ingatanku, seperti rumah sendiri."
  },
  AvgCommunicate_67028_Content_7 = {
    Text = "Maaf, pembicaraannya jadi melenceng. Sebenarnya aku ingin bertanya, apakah Anda tertarik untuk memelihara beberapa ikan mas kecil?"
  },
  AvgCommunicate_67028_Content_8 = {
