  },
  AvgCommunicate_67029_Content_11 = {
    Text = "……Jadi ayam-ayam itu sekarang ada di mana?"
  },
  AvgCommunicate_67029_Content_12 = {
    Text = "Di kamar Cassia, sekarang sudah banyak anak ayam yang menetas! Setiap hari sangat ramai lho!"
  },
  AvgCommunicate_67029_Content_13 = {
    Text = "Kembalikan ke kantin sekarang juga!!"
  },
  AvgCommunicate_67029_Content_14 = {
    Text = "Eh, kamu tega-teganya memisahkan ibu dan anak, benar-benar kejam! Dasar orang yang tidak punya naluri keibuan!"
  },
  AvgCommunicate_67029_Content_15 = {
    Text = "Kenapa juga aku harus punya naluri keibuan terhadap ayam!"
  },
  AvgCommunicate_67029_Content_16 = {
    Text = "Dan lagi, satu-satunya orang yang tidak ingin disebut kejam adalah olehmu!"
  },
  AvgCommunicate_67029_Content_2 = {
    Text = "Benar, Kassia. Ada yang melaporkan kepadaku bahwa setelah pertunjukan sulap dadukanmu di kantin sekolah kemarin, tiga ekor ayam betina dan dua puluh butir telur dari gudang kantin menghilang."
  },
  AvgCommunicate_67029_Content_3 = {
    Text = "Apa? Ada kejadian seperti itu? Kassia tidak tahu apa-apa lho."
