    Text = "Kalau kamu masih tidak mau bicara jujur..."
  },
  AvgCommunicate_67030_Content_1 = {
    Text = "Haah, Tuan, menurutmu kenapa kue kecil buatan Karen yang dibuat dengan penuh perhatian tidak ada yang beli ya?"
  },
  AvgCommunicate_67030_Content_10 = {
    Text = "Sebenarnya yang seleranya unik itu siapa sih!!"
  },
  AvgCommunicate_67030_Content_11 = {
    Text = "Haah, memulai usaha memang susah ya. Sepertinya aku harus ganti jualan yang lain. Bagaimana kalau kali ini bikin minuman?"
  },
  AvgCommunicate_67030_Content_12 = {
    Text = "Hentikan, jangan bikin sengsara orang lain lagi!!!"
  },
  AvgCommunicate_67030_Content_2 = {
    Text = "Waktu buka lapak di kampus, malah dimuntahkan Murphy ke tanah. Kalau aku tidak lari cepat, hampir saja dipukuli olehnya!"
  },
  AvgCommunicate_67030_Content_3 = {
    Text = "Memangnya seenak apa sih sampai begitu..."
  },
  AvgCommunicate_67030_Content_4 = {
    Text = "Tapi aku sendiri sudah coba dan rasanya enak kok!"
  },
  AvgCommunicate_67030_Content_5 = {
    Text = "Kue kecilmu itu dibuat dari apa saja?"
  },
  AvgCommunicate_67030_Content_6 = {
    Text = "Aku memilih laba-laba kering terbaik, ditambah lamprey segar, direbus di kuali besar lalu dicampur ke dalam adonan..."
