  },
  AvgCommunicate_67031_Content_13 = {
    Text = "Aaargh menyebalkan! Aku ini Penguasa Labirin, kenapa aku harus belajar!"
  },
  AvgCommunicate_67031_Content_14 = {
    Text = "Cepat carikan aku beberapa budak untuk melayaniku!"
  },
  AvgCommunicate_67031_Content_15 = {
    Text = "Sadarlah, Roma sudah runtuh."
  },
  AvgCommunicate_67031_Content_16 = {
    Text = "Sekarang ini masyarakat yang taat hukum."
  },
  AvgCommunicate_67031_Content_17 = {
    Text = "Aku tidak peduli, kalau tidak bisa menemukan budak, kamu sendiri yang harus melayaniku!"
  },
  AvgCommunicate_67031_Content_18 = {
    Text = "Kalau begitu, lanjutkan saja sikat gigi pakai sabun cuci muka."
  },
  AvgCommunicate_67031_Content_19 = {
    Text = "Aku akan melemparmu ke dalam labirin untuk jadi makanan anak-anakku!!!"
  },
  AvgCommunicate_67031_Content_2 = {
    Text = "Kamu kenapa??"
  },
  AvgCommunicate_67031_Content_3 = {
    Text = "Terakhir kali kalian bilang, pasta gigi bukan yang ada di kotak kecil bulat itu, tapi yang bentuknya panjang."
  },
  AvgCommunicate_67031_Content_4 = {
    Text = "Kenapa setelah aku pakai yang panjang itu, sekarang mulutku pahit sekali! Pedas dan pahit!!"
