  AvgCommunicate_67032_Content_1 = {
    Text = "Anak anjing, di dalam Kolam Hitam sangat dingin, setiap hari aku merasakan daya hidupku terus memudar."
  },
  AvgCommunicate_67032_Content_10 = {
    Text = "Bagaimana kalau kubilang, aku sudah berhasil melonggarkan sedikit perangkat yang menjebakku ini?"
  },
  AvgCommunicate_67032_Content_11 = {
    Text = "?! Aku segera ke sana."
  },
  AvgCommunicate_67032_Content_2 = {
    Text = "Kalau kamu tidak segera datang menjengukku, mungkin suatu hari aku akan melebur menjadi cairan korosi dan menghilang."
  },
  AvgCommunicate_67032_Content_3 = {
    Text = "...Aku sudah tidak akan tertipu olehmu lagi."
  },
  AvgCommunicate_67032_Content_4 = {
    Text = "Bukankah sudah seharusnya peduli pada gurumu? Kenapa bisa disebut tertipu?"
  },
  AvgCommunicate_67032_Content_5 = {
    Text = "Aku masih merindukan penampilanmu dulu saat sering bermalas-malasan di kelas tapi takut ketahuan olehku."
  },
  AvgCommunicate_67032_Content_6 = {
    Text = "Saat datang menangkapku, wajah penuh keadilan dan polos itu juga sangat menggemaskan."
  },
  AvgCommunicate_67032_Content_7 = {
    Text = "Kalau sudah selesai bicara, aku akan mematikan komunikatornya."
  },
  AvgCommunicate_67032_Content_8 = {
    Text = "Haah, benar-benar dingin ya, bagaimanapun juga kamu tidak mau menemuiku?"
  },
  AvgCommunicate_67032_Content_9 = {Text = "Menurutmu?"},
  AvgCommunicate_67032_Option_11 = {
