  },
  AvgCommunicate_67032_Option_9 = {Text = "Menurutmu?"},
  AvgCommunicate_67033_Content_1 = {
    Text = "Watson, hidup ini benar-benar membosankan ya."
  },
  AvgCommunicate_67033_Content_10 = {
    Text = "Jangan bilang kamu kalah darinya?"
  },
  AvgCommunicate_67033_Content_11 = {
    Text = "Tidak juga, kami berdua sama-sama tidak mau mengalah, taruhannya makin lama makin besar, hampir kehilangan akal sehat."
  },
  AvgCommunicate_67033_Content_12 = {
    Text = "Hasilnya, kakek tua itu terlalu bersemangat dan menunjukkan celah, aku menemukan bahwa dia sebenarnya selama ini berbuat curang."
  },
  AvgCommunicate_67033_Content_13 = {
    Text = "Jadi selama ini kamu imbang dengan orang yang berbuat curang?"
  },
  AvgCommunicate_67033_Content_14 = {
    Text = "Iya, benar-benar mengecewakan. Yang lebih menyebalkan lagi, kakek tua itu malu jadi marah, dan menyerangku sampai kami berkelahi."
  },
  AvgCommunicate_67033_Content_15 = {
    Text = "Dia malah mencurigai aku sama sepertinya, seorang penipu profesional! Benar-benar penghinaan!"
  },
  AvgCommunicate_67033_Content_16 = {
    Text = "Akhirnya aku dan dia sama-sama dilempar keluar oleh orang-orang rumah judi, pantatku masih sakit sampai sekarang, benar-benar sial."
  },
  AvgCommunicate_67033_Content_17 = {
    Text = "Entah kenapa, rasanya tidak bisa bersimpati ya……"
  },
  AvgCommunicate_67033_Content_2 = {
    Text = "? Kamu pasti pergi berjudi lagi, kan? Apa lagi-lagi menang sampai orang lain kehilangan celana mereka?"
  },
  AvgCommunicate_67033_Content_3 = {
    Text = "Kali ini benar-benar tidak! Awalnya aku memang seperti biasa pergi ke rumah judi untuk bersenang-senang... uhuk."
  },
  AvgCommunicate_67033_Content_4 = {
    Text = "Tidak apa-apa, lanjutkan ceritamu."
  },
  AvgCommunicate_67033_Content_5 = {
    Text = "Aku dengarkan kamu terus berdalih."
  },
  AvgCommunicate_67033_Content_6 = {
    Text = "Haah, lalu hari ini aku tiba-tiba bertemu lawan yang seimbang denganku."
  },
  AvgCommunicate_67033_Content_7 = {
    Text = "Setelah aku bergabung di meja judi itu, menang-kalahku hampir seimbang dengan kakek tua yang tidak mencolok itu."
  },
  AvgCommunicate_67033_Content_8 = {
    Text = "Itu memang sangat mengejutkan, bisa menang dengan keberuntunganmu yang seperti itu, pasti dia seorang ahli."
  },
  AvgCommunicate_67033_Content_9 = {
    Text = "Aku juga berpikir begitu, jadi aku mengeluarkan konsentrasi maksimal untuk terus bertaruh dengannya, bahkan punggungku sampai tegak lurus!"
