  AvgCommunicate_67034_Content_1 = {
    Text = "Penjaga Rahasia, selamat datang."
  },
  AvgCommunicate_67034_Content_10 = {
    Text = "Oh ya? Lalu bagaimana kamu menjelaskan kertas ujian yang tidak lulus ini? Materi sedasar ini saja bisa salah, sepertinya kamu ingin menyalin jawaban yang benar seratus kali ya."
  },
  AvgCommunicate_67034_Content_11 = {
    Text = "Seratus kali?! Jangan dong... Tunggu, aku hampir lupa kalau kamu itu Erica!"
  },
  AvgCommunicate_67034_Content_12 = {
    Text = "Marahnya realistis banget buat apa sih, sengaja ya?! Aku mau kasih ulasan buruk!!"
  },
  AvgCommunicate_67034_Content_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Content_14 = {
    Text = "Baik, sekarang akan beralih simulasi kepribadian ke: Ramona."
  },
  AvgCommunicate_67034_Content_15 = {
    Text = "Partner, tadi ada guru yang memberitahuku, sepertinya kamu ada satu tugas yang belum dikumpulkan?"
  },
  AvgCommunicate_67034_Content_16 = {
    Text = "Hah? Masa sih? Aku ingat jelas semua tugas sudah kukerjakan..."
  },
  AvgCommunicate_67034_Content_17 = {
    Text = "Kebiasaan cerobohmu ini kapan bisa diperbaiki sih?"
  },
  AvgCommunicate_67034_Content_18 = {
    Text = "Sudahlah, mulai sekarang kamu langsung datang ke asramaku setiap hari, aku akan mengawasimu menyelesaikan tugas harian sebelum boleh pergi. Oh iya, tidak boleh mencari jawaban atau referensi."
  },
  AvgCommunicate_67034_Content_19 = {
    Text = "Apa?! Jangan dong! Tugas tidak boleh pakai referensi bagaimana bisa mengerjakannya!"
  },
  AvgCommunicate_67034_Content_2 = {
    Text = "Anda diundang untuk mencoba sistem simulasi kepribadian terbaru. Sistem ini akan menggantikan anggota yang tidak bisa hadir saat misi membutuhkan, untuk menyamar dalam komunikasi, memperkirakan logika tindakan mereka, dan sebagainya."
  },
  AvgCommunicate_67034_Content_20 = {
    Text = "Tunggu... Aku hampir lupa kalau kamu itu Erica! Sengaja menakutiku ya?! Aku mau kasih ulasan buruk!!"
  },
  AvgCommunicate_67034_Content_21 = {
    Text = "Baik, umpan balik penggunaan Anda telah diterima, evaluasi awal menunjukkan simulasi memenuhi standar."
  },
  AvgCommunicate_67034_Content_22 = {
    Text = "Menantikan pertemuan kembali dengan Anda di sesi uji sistem berikutnya."
  },
  AvgCommunicate_67034_Content_3 = {
    Text = "Mohon berikan kesan dan saran Anda setelah selesai mencoba."
  },
  AvgCommunicate_67034_Content_4 = {
    Text = "Ini lagi hal aneh apalagi?"
  },
  AvgCommunicate_67034_Content_5 = {
    Text = "Anda dapat memilih salah satu dari dua karakter awal berikut untuk mengalami simulasi kepribadian: Doer, Ramona."
  },
  AvgCommunicate_67034_Content_6 = {Text = "Doer."},
  AvgCommunicate_67034_Content_7 = {
    Text = "Baik, simulasi kepribadian akan dialihkan ke: Doer."
  },
  AvgCommunicate_67034_Content_8 = {
    Text = "Penjaga Rahasia, hasil ujian terbarumu sudah keluar. Aku harap kamu sadar apa yang kamu lakukan belakangan ini."
  },
  AvgCommunicate_67034_Content_9 = {
    Text = "Hah? Aku, aku akhir-akhir ini sudah mengumpulkan tugas tepat waktu, cuma sedikit tertidur beberapa kali saat pelajaran saja..."
  },
  AvgCommunicate_67034_Option_11 = {
