  AvgCommunicate_67035_Content_1 = {
    Text = "Tuan Penjaga Rahasia yang tersayang! Tolong bantu aku!"
  },
  AvgCommunicate_67035_Content_10 = {
    Text = "Itu mana bisa disebut pekerjaan!!"
  },
  AvgCommunicate_67035_Content_11 = {
    Text = "Sudahlah…… Belakangan ini di kelas pelatihan Elva sedang melatih anjing untuk mengejar musuh."
  },
  AvgCommunicate_67035_Content_12 = {
    Text = "Kalau kamu tidak keberatan digigit anjing, pergilah ke sana untuk berperan sebagai penjahat."
  },
  AvgCommunicate_67035_Content_13 = {
    Text = "Apa? Maksudmu aku bisa digigit-gigit oleh anjing kecil yang lucu?"
  },
  AvgCommunicate_67035_Content_14 = {
    Text = "Aku mau! Kamu benar-benar baik sekali, Penjaga Rahasia!"
  },
  AvgCommunicate_67035_Content_2 = {
    Text = "Tidak memaki, tidak memukul, tidak ada di kamar."
  },
  AvgCommunicate_67035_Content_3 = {
    Text = "Aduh, kali ini aku benar-benar tidak ada di depan pintu kamarmu kok."
  },
  AvgCommunicate_67035_Content_4 = {
    Text = "Berkat bantuanmu waktu itu, aku menikmati waktu yang lama di dalam samsak di ruang latihan, rasanya seperti pulang ke rumah. Aku belum pernah sebahagia itu seumur hidupku."
  },
  AvgCommunicate_67035_Content_5 = {
    Text = "Hmm... sama-sama, yang penting kamu senang."
  },
  AvgCommunicate_67035_Content_6 = {
    Text = "Haah, tapi belakangan ini aku akhirnya ketahuan juga. Entah bagaimana Yuuhahashi bisa mengenali bahwa itu aku di dalamnya."
  },
  AvgCommunicate_67035_Content_7 = {
    Text = "Setelah semua orang tahu bahwa samsak sebelumnya itu aku, mereka semua memarahiku habis-habisan."
  },
  AvgCommunicate_67035_Content_8 = {
    Text = "Meskipun bagian itu memang nikmat sih, tapi sekarang aku sudah tidak bisa menyamar jadi samsak lagi."
  },
  AvgCommunicate_67035_Content_9 = {
    Text = "Bagaimana ini, rasanya sangat menyedihkan jadi pengangguran, Tuan Penjaga Rahasia! Tolong carikan aku pekerjaan seperti ini lagi!"
  },
  AvgCommunicate_67035_Option_10 = {
    Text = "Itu mana bisa disebut pekerjaan!!"
  },
  AvgCommunicate_67035_Option_2 = {
    Text = "Tidak memaki, tidak memukul, tidak ada di kamar."
  },
  AvgCommunicate_67035_Option_5 = {
    Text = "Hmm... sama-sama, yang penting kamu senang."
  },
  AvgCommunicate_67036_Content_1 = {
    Text = "Penjaga Rahasia! Modifikasi terbaruku berhasil!"
  },
  AvgCommunicate_67036_Content_10 = {
    Text = "Dengan begitu aku tidak perlu khawatir lupa membaca buku harianku dan kehilangan ingatan sebelumnya."
  },
  AvgCommunicate_67036_Content_11 = {
    Text = "Ide bagus! Tapi bukankah sebelumnya kamu tidak terlalu mempermasalahkan sifat pelupamu?"
  },
  AvgCommunicate_67036_Content_12 = {
    Text = "Memang sih, tapi sekarang aku tidak ingin melupakan teman-temanku."
  },
  AvgCommunicate_67036_Content_13 = {
    Text = "Aku akan mengingatmu dengan baik, Penjaga Rahasia!"
  },
  AvgCommunicate_67036_Content_2 = {
    Text = "Selamat! Maksudmu Nautilus-mu? Tapi ternyata kamu masih ingat aku."
  },
  AvgCommunicate_67036_Content_3 = {
    Text = "Bukan, maksudku kotak percakapan kecil ini."
  },
  AvgCommunicate_67036_Content_4 = {
    Text = "? Itu namanya komunikator, dan apa yang kamu modifikasi??"
  },
  AvgCommunicate_67036_Content_5 = {
    Text = "Sekarang aku bisa membuat pesan yang sudah ditulis terkirim secara tertunda, dan waktu tundanya bisa diatur sendiri."
  },
  AvgCommunicate_67036_Content_6 = {
    Text = "Misalnya pesan pertama yang baru saja kukirim padamu, itu ditulis lima menit yang lalu saat aku sedang mengujinya."
  },
  AvgCommunicate_67036_Content_7 = {
    Text = "Hebat sekali?! Rasanya bisa dipakai untuk mengatur tindakan lanjutan saat menjalankan misi, juga praktis untuk mengaktifkan rencana cadangan."
  },
  AvgCommunicate_67036_Content_8 = {
    Text = "Ah, aku tidak berpikir sejauh itu kok."
  },
  AvgCommunicate_67036_Content_9 = {
    Text = "Aku cuma berpikir, kalau aku mengirimkan hal-hal yang kuingat hari ini ke diriku besok, aku jadi tidak akan lupa."
  },
  AvgCommunicate_67036_Option_11 = {
    Text = "Ide bagus! Tapi bukankah sebelumnya kamu tidak terlalu mempermasalahkan sifat pelupamu?"
  },
  AvgCommunicate_67036_Option_2 = {
    Text = "Selamat! Maksudmu Nautilus-mu? Tapi ternyata kamu masih ingat aku."
  },
  AvgCommunicate_67036_Option_4 = {
    Text = "? Itu namanya komunikator, dan apa yang kamu modifikasi??"
  },
  AvgCommunicate_67036_Option_7 = {
    Text = "Hebat sekali?!"
  },
  AvgCommunicate_67037_Content_1 = {
    Text = "Penjaga Rahasia, aku baru-baru ini melihat permainan menulis puisi yang sangat menarik."
  },
  AvgCommunicate_67037_Content_10 = {Text = "Dingin."},
  AvgCommunicate_67037_Content_11 = {Text = "Kematian."},
