  AvgCommunicate_67037_Content_13 = {Text = "Cinta."},
  AvgCommunicate_67037_Content_14 = {Text = "Sendu."},
  AvgCommunicate_67037_Content_15 = {Text = "Harum."},
  AvgCommunicate_67037_Content_16 = {
    Text = "Hmm, kurasa sudah cukup, biar aku coba merangkainya menjadi bait puisi."
  },
  AvgCommunicate_67037_Content_17 = {
    Text = "Cinta bulbul pada bulan, mekar setiap malam dalam nyanyian merdunya, namun bulan tetap saja begitu dingin."
  },
  AvgCommunicate_67037_Content_18 = {
    Text = "Ia bernyanyi, terus bernyanyi, hingga duri mawar menusuk dadanya."
  },
  AvgCommunicate_67037_Content_19 = {
    Text = "Nyanyian itu mengalir pergi bersama kematian yang merah darah, hanya tersisa mawar, hanya tersisa mawar yang menghembuskan keharuman yang sendu."
