  AvgCommunicate_67038_Content_1 = {
    Text = "Penjaga Rahasia, patung Tulu yang kamu minta kubuatkan untuk Miriam sudah kuantar ke kamarmu."
  },
  AvgCommunicate_67038_Content_10 = {
    Text = "Pemahamannya tentang Tulu bahkan tidak sebanding dengan pemahamanku tentang kamu, benar-benar tidak kompeten."
  },
  AvgCommunicate_67038_Content_11 = {
    Text = "Stop, jangan bilang begitu, jangan sampai dia melihat ini."
  },
  AvgCommunicate_67038_Content_12 = {
    Text = "Pokoknya, terima kasih atas kerja kerasmu. Biar aku pikirkan dulu bagaimana cara bicara dengan Miriam..."
  },
  AvgCommunicate_67038_Content_2 = {
    Text = "Aku sudah melihatnya, tapi penampilannya ini…… bukankah terlalu imut?"
  },
  AvgCommunicate_67038_Content_3 = {
    Text = "Apakah Tulu memang terlihat seperti ini? Miriam tidak akan mencekikku kan……"
