  AvgCommunicate_67038_Content_4 = {
    Text = "Kenapa? Kamu juga pengikut setia Raja Muda itu?"
  },
  AvgCommunicate_67038_Content_5 = {
    Text = "Di mataku, dia hanyalah seorang anak kecil, yang begitu saja dikenakan mahkota dan belenggu oleh orang lain."
  },
  AvgCommunicate_67038_Content_6 = {
    Text = "Kamu tidak merasa penampilannya yang selalu mengantuk dan malas-malasan itu lucu? Mirip sekali dengan kucing berbulu panjang yang dipelihara keluargaku waktu aku kecil."
  },
  AvgCommunicate_67038_Content_7 = {
    Text = "Meskipun apa yang kamu bilang memang tidak salah, para pengikut yang ingin membuat patung itu juga pasti akan puas..."
  },
  AvgCommunicate_67038_Content_8 = {
    Text = "Satu-satunya kabar buruk mungkin adalah hanya dunia di mana Miriam terluka yang terlahir..."
  },
  AvgCommunicate_67038_Content_9 = {
    Text = "Itu hanya membuktikan bahwa dia adalah seorang pendeta yang buta, yang tidak memahami dewa yang dia sembah."
