  },
  AvgCommunicate_67039_Content_1 = {
    Text = "Penjaga Rahasia tersayang, sudah menerima karya terbaruku?"
  },
  AvgCommunicate_67039_Content_10 = {
    Text = "Tiba-tiba dipuji begitu, aku jadi malu..."
  },
  AvgCommunicate_67039_Content_11 = {
    Text = "Tidak perlu malu, kamu selalu menjadi muse-ku. Kalau ada waktu luang, maukah kamu mampir ke studioku?"
  },
  AvgCommunicate_67039_Content_12 = {
    Text = "Aku masih punya banyak sekali karya yang ingin diselesaikan, dan aku perlu menggambarkan jiwamu dengan detail."
  },
  AvgCommunicate_67039_Content_13 = {
    Text = "Aku akan menunggumu di sini, menunggu kamu memberiku lebih banyak inspirasi."
  },
  AvgCommunicate_67039_Content_2 = {
    Text = "Ini... aku yang sedang tidur?"
  },
  AvgCommunicate_67039_Content_3 = {
    Text = "Dalam inspirasiku, ini adalah dirimu yang tenggelam dalam mimpi indah."
  },
  AvgCommunicate_67039_Content_4 = {
    Text = "Mendapatkan kebahagiaan yang buta dan palsu, atau kejernihan yang menyakitkan dan penuh kesengsaraan?"
  },
  AvgCommunicate_67039_Content_5 = {
    Text = "Pilihan yang serba sulit selalu menjadi tema abadi seni dan filsafat."
  },
  AvgCommunicate_67039_Content_6 = {
    Text = "Tidak bisakah aku mendapatkan kebahagiaan yang jernih dan nyata?"
  },
  AvgCommunicate_67039_Content_7 = {
    Text = "Hehe, benar-benar orang yang serakah."
  },
  AvgCommunicate_67039_Content_8 = {
    Text = "Tidak ada yang sempurna, mungkin pahatan pun tidak bisa mewujudkan kesempurnaan."
  },
  AvgCommunicate_67039_Content_9 = {
    Text = "Tapi kamu bisa terus berjalan di jalan mengejar kebahagiaan seperti itu, itulah yang membuatmu begitu mempesona."
  },
  AvgCommunicate_67039_Option_10 = {
