  },
  AvgCommunicate_67040_Content_1 = {
    Text = "Yah, sayangku, bagaimana perasaanmu tentang waktu manis kita yang lalu? Pasti setiap hari mengenangnya terus, kan?"
  },
  AvgCommunicate_67040_Content_10 = {
    Text = "Katakan saja, apa lagi yang kau inginkan……"
  },
  AvgCommunicate_67040_Content_11 = {
    Text = "Jangan tegang begitu, hubungan kita kan sudah sedekat ini~"
  },
  AvgCommunicate_67040_Content_12 = {
    Text = "Percayalah padaku, ikuti aku, aku akan membawamu menemukan kebahagiaan yang baru."
  },
  AvgCommunicate_67040_Content_13 = {
    Text = "Kali ini, mau mencoba sendiri cara menggunakan lilin dan cambuk kecil?"
  },
  AvgCommunicate_67040_Content_14 = {
    Text = "Aku akan mengajarimu semuanya pelan-pelan, langkah demi langkah, sayangku."
