  },
  AvgCommunicate_67040_Content_4 = {
    Text = "Dasar orang yang tidak berperasaan, padahal waktu itu aku begitu lembut~"
  },
  AvgCommunicate_67040_Content_5 = {
    Text = "Kusarankan kau untuk berhati-hati dalam berkata dan bertindak……"
  },
  AvgCommunicate_67040_Content_6 = {
    Text = "Hmph, pura-pura bodoh juga tidak ada gunanya, karena aku sudah merekam konturmu, lekukmu, semua bentukmu dengan lilin!"
  },
  AvgCommunicate_67040_Content_7 = {
    Text = "Rasanya ingin sekali memamerkannya ke semua orang~"
