  AvgCommunicate_67041_Content_1 = {
    Text = "Tuan, kamu baru saja memberi isyarat padaku, maksudnya kamu ingin aku menghubungimu?"
  },
  AvgCommunicate_67041_Content_10 = {
    Text = "Haah, harus segera mengajarimu mengenali wanita jahat di sekolah, supaya kamu belajar beberapa langkah pencegahan."
  },
  AvgCommunicate_67041_Content_11 = {
    Text = "Dengarkan aku, sekarang segera pergi dari depan pintunya, semakin jauh semakin baik, nanti bilang saja kamu dipanggil olehku!"
  },
  AvgCommunicate_67041_Content_12 = {
    Text = "Ta-tapi aku sudah berjanji kepada Nona Pandiya, aku tidak bisa mengingkari janji."
  },
  AvgCommunicate_67041_Content_13 = {
    Text = "Tidak apa-apa, Tuan, aku punya kekuatan untuk melindungi diriku sendiri!"
  },
  AvgCommunicate_67041_Content_14 = {
    Text = "Kamu, aku... Sudahlah, kalau kamu memang harus berdiri di sana, ingat jangan sekali-kali masuk ke kamarnya."
  },
  AvgCommunicate_67041_Content_15 = {
    Text = "Baik, tentu saja aku tidak akan masuk ke kamar seorang wanita!"
  },
  AvgCommunicate_67041_Content_16 = {
    Text = "Apapun yang dia katakan, jangan masuk, kalau ada apa-apa panggil aku. Oh iya, dan jangan sekali-kali mencium lilinnya!"
  },
  AvgCommunicate_67041_Content_17 = {
    Text = "Aku sudah mengingatnya, Tuan. Tapi kenapa tidak boleh mencium lilinnya?"
  },
  AvgCommunicate_67041_Content_18 = {
    Text = "Jangan tanya... Ini semua pelajaran berdarah dan penuh air mata yang kudapatkan untukmu..."
  },
  AvgCommunicate_67041_Content_2 = {
    Text = "Benar, kenapa kamu terus berdiri di depan pintu Pandiya??"
  },
  AvgCommunicate_67041_Content_3 = {
    Text = "Ah, ini permintaan dari Nona Pandiya. Dia bilang ada hal yang sangat penting yang harus dilakukan, dan dia berharap aku bisa menjaga pintunya."
  },
  AvgCommunicate_67041_Content_4 = {
    Text = "Hal yang sangat penting? Jangan percaya karangannya! Hal-hal yang dia lakukan itu... Sudahlah, kamu pasti sudah ditipu olehnya!"
  },
  AvgCommunicate_67041_Content_5 = {
    Text = "Hah? Tapi, ekspresinya tadi sangat serius, dan dia juga dengan sungguh-sungguh menggenggam tanganku..."
  },
  AvgCommunicate_67041_Content_6 = {
