  },
  AvgCommunicate_67043_Content_1 = {
    Text = "Sudah lama tinggal di Mesagard, tiba-tiba aku jadi rindu bulan di padang pasir."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Ayo ciptakan kenangan baru bersamaku, ke taman bunga, ke padang luas, melihat lautan dan lembah, kota dan desa."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "Aku ingin meninggalkan kenangan bersamamu di setiap tempat yang indah. Kamu akan menemaniku, kan?"
