  AvgCommunicate_67043_Content_2 = {
    Text = "Ternyata kamu juga bisa merasa rindu kampung halaman ya?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "Daripada rindu kampung halaman, mungkin aku hanya merindukan kenangan yang pernah kulalui bersama orang-orang, perasaan yang begitu mendalam itu."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "Tidak kusangka kamu ternyata senostalgia ini."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "Kenapa? Kamu pikir aku orang yang bebas dan tak berperasaan? Tidak, aku mengingat setiap orang, setiap kenangan yang hangat dan manis."
  },
  AvgCommunicate_67043_Content_6 = {
    Text = "Termasuk kenangan bersamamu."
  },
  AvgCommunicate_67043_Content_7 = {
    Text = "Haruskah aku merasa tersanjung atau cemburu ya?"
  },
  AvgCommunicate_67043_Content_8 = {
    Text = "Aku suka melihatmu yang canggung seperti ini, benar-benar manis."
  },
  AvgCommunicate_67043_Content_9 = {
    Text = "Meskipun masa lalu memang indah untuk dikenang, tapi kebahagiaan malam ini adalah yang paling berharga."
