  AvgCommunicate_67043_Option_4 = {
    Text = "Tidak kusangka kamu ternyata senostalgia ini."
  },
  AvgCommunicate_67043_Option_7 = {
    Text = "Haruskah aku merasa tersanjung atau cemburu ya?"
  },
  AvgCommunicate_67044_Content_1 = {
    Text = "Belakangan ini aku sedang merancang beberapa hiasan untuk mempercantik koleksi-koleksiku."
  },
  AvgCommunicate_67044_Content_10 = {
    Text = "Kalau boleh, terimalah kalung-kalung yang sudah kupilih dengan cermat ini. Kali ini sebagai hadiah gratis."
  },
  AvgCommunicate_67044_Content_11 = {
    Text = "Kalau setelah mencobanya kamu menyukai salah satunya, tolong beritahu aku."
  },
  AvgCommunicate_67044_Content_12 = {
    Text = "Meskipun tengkorakmu belum menjadi milikku, hanya dengan melihatmu memakainya saja sudah cukup membuatku senang."
  },
  AvgCommunicate_67044_Content_2 = {
    Text = "Pilihan desainnya agak banyak, membuatku sedikit bingung, jadi ingin bertanya pendapatmu."
  },
  AvgCommunicate_67044_Content_3 = {Text = "Koleksi?"},
  AvgCommunicate_67044_Content_4 = {
