  AvgCommunicate_67045_Content_1 = {
    Text = "Haah, bisnis toko kecilku akhir-akhir ini terus lesu. Sudah lama aku tidak menemukan tengkorak yang memuaskan."
  },
  AvgCommunicate_67045_Content_10 = {
    Text = "Kalau kalian bisa bekerja sama memburu buronan kelas kakap, mungkin bisa tercipta legenda penegak keadilan kota yang membasmi kejahatan."
