    Text = "Hmm... Tengkorak memang bukan sesuatu yang bisa dicari sesuka hati."
  },
  AvgCommunicate_67045_Content_3 = {
    Text = "Makanya akhir-akhir ini aku menjalin kerja sama dengan Dewan Inspeksi. Aku membantu mereka melacak jejak buronan, dan sebagai gantinya mereka diam-diam memberiku tengkorak terpidana mati."
  },
  AvgCommunicate_67045_Content_4 = {
    Text = "Menukar satu orang hidup dengan tengkorak orang mati — itu kesepakatan yang menguntungkan bagi kedua belah pihak."
  },
  AvgCommunicate_67045_Content_5 = {
    Text = "Hah? Tidak kusangka Dewan Inspeksi mau menyetujui kerja sama seperti itu."
  },
  AvgCommunicate_67045_Content_6 = {
