  },
  AvgCommunicate_67054_Content_6 = {
    Text = "Haah, Aurita ingin akuarium yang besar sekali, super besar, sebesar seluruh ruangan!"
  },
  AvgCommunicate_67054_Content_7 = {
    Text = "Dengan begitu Aurita dan teman-teman bisa bermain bersama setiap hari!"
  },
  AvgCommunicate_67054_Content_8 = {
    Text = "Mimpi memang indah, tapi sekolah tidak punya anggaran untuk membangun akuarium sebesar itu!"
  },
  AvgCommunicate_67054_Content_9 = {
    Text = "Eeh—— kenapa, kalau setengah ruangan juga boleh kok!"
  },
  AvgCommunicate_67054_Option_2 = {Text = "Kok bisa??"},
  AvgCommunicate_67054_Option_5 = {
    Text = "Ehm, memang hal yang bisa kamu lakukan sih, tidak apa-apa, aku segera ke sana."
  },
  AvgCommunicate_67054_Option_8 = {
    Text = "Mimpi memang indah, tapi sekolah tidak punya anggaran untuk membangun akuarium sebesar itu!"
  },
  AvgCommunicate_67055_Content_1 = {
    Text = "Penjaga Rahasia, kenapa teman yang kita bawa pulang dari pantai terakhir kali tidak bergerak lagi..."
  },
  AvgCommunicate_67055_Content_2 = {
    Text = "Apakah teman ini sedang sakit? Atau sedang tidak senang..."
  },
  AvgCommunicate_67055_Content_3 = {
    Text = "Bisakah Penjaga Rahasia membantu teman ini?"
  },
  AvgCommunicate_67055_Content_4 = {
    Text = "Hmm... Sepertinya teman ini merindukan laut."
  },
  AvgCommunicate_67055_Content_5 = {
    Text = "Dia berasal dari laut, bagaimana kalau kita mengantarnya kembali ke laut bersama-sama?"
  },
  AvgCommunicate_67055_Content_6 = {
    Text = "Oh, begitu ya... Aku mengerti, teman ini rindu rumah."
  },
  AvgCommunicate_67055_Content_7 = {
    Text = "Oreta juga rindu laut, tapi Oreta juga suka sekolah. Sekarang Oreta punya dua rumah."
  },
  AvgCommunicate_67055_Content_8 = {
    Text = "Ayo pergi! Kita antar teman ini pulang ke rumahnya! Lalu kita kembali bersama, ke rumah kita di sekolah!"
  },
  AvgCommunicate_67055_Option_4 = {
    Text = "Hmm... Sepertinya teman ini merindukan laut."
  },
  AvgCommunicate_67056_Content_1 = {
    Text = "Maaf mengganggu, aku sudah berpikir lama dan ingin bertanya padamu..."
  },
  AvgCommunicate_67056_Content_10 = {
    Text = "Benarkah begitu... Kalau begitu, syukurlah."
  },
  AvgCommunicate_67056_Content_11 = {
    Text = "Bisa membantumu, aku sangat senang."
  },
  AvgCommunicate_67056_Content_12 = {
    Text = "Sebenarnya kamu tidak perlu selalu buru-buru pergi, aku dengan senang hati menemanimu mengobrol dan minum teh."
  },
  AvgCommunicate_67056_Content_13 = {
    Text = "Tidak... Aku bukan milik tempat ini, tinggal lebih lama adalah sebuah keserakahan, baik untukmu, untukku, maupun untuk ruang-waktu, itu bukan hal yang baik."
  },
  AvgCommunicate_67056_Content_14 = {
    Text = "Kalau begitu, setidaknya tinggallah sejenak lebih lama untuk berpamitan, biarkan aku sempat mengucapkan selamat tinggal padamu setiap kali."
  },
  AvgCommunicate_67056_Content_15 = {
    Text = "...Baiklah."
  },
  AvgCommunicate_67056_Content_2 = {Text = "Ada apa?"},
  AvgCommunicate_67056_Content_3 = {
    Text = "Menurutmu, seberapa cepat responseku setiap kali menjawab panggilanmu?"
  },
  AvgCommunicate_67056_Content_4 = {
    Text = "Meskipun setiap kali aku selalu memperhatikan panggilanmu dan langsung berangkat secepat mungkin."
  },
  AvgCommunicate_67056_Content_5 = {
    Text = "Tapi aku khawatir proses melintasi ruang-waktu mungkin ada sedikit penyimpangan, bagaimana kalau terjadi keterlambatan waktu..."
  },
  AvgCommunicate_67056_Content_6 = {
    Text = "Begitu aku membayangkan kamu bisa terancam bahaya karenanya, aku jadi gelisah tak tenang."
  },
  AvgCommunicate_67056_Content_7 = {Text = "Ramona..."},
  AvgCommunicate_67056_Content_8 = {
    Text = "Tidak kok, kamu selalu datang tepat waktu setiap kali."
  },
  AvgCommunicate_67056_Content_9 = {
    Text = "Mengetahui kamu selalu ada di belakangku kapan saja, aku selalu merasa tenang."
  },
  AvgCommunicate_67056_Option_12 = {
    Text = "Sebenarnya kamu tidak perlu selalu buru-buru pergi..."
  },
  AvgCommunicate_67056_Option_14 = {
    Text = "Kalau begitu, setidaknya tinggallah sejenak lebih lama untuk berpamitan."
  },
  AvgCommunicate_67056_Option_2 = {Text = "Ada apa?"},
  AvgCommunicate_67056_Option_7 = {Text = "Ramona..."},
  AvgCommunicate_67057_Content_1 = {
    Text = "Penjaga Rahasia, selamat datang."
  },
  AvgCommunicate_67057_Content_10 = {
    Text = "Maaf, saya tidak dapat mencarikan tugas orang lain untuk Anda. Tindakan tersebut termasuk plagiarisme dan melanggar peraturan sekolah serta norma sosial."
  },
  AvgCommunicate_67057_Content_11 = {
    Text = "Jika Anda memiliki pertanyaan lain atau membutuhkan bantuan, silakan beritahu saya kapan saja. Saya akan memberikan informasi yang positif dan bermanfaat untuk Anda."
  },
  AvgCommunicate_67057_Content_12 = {
    Text = "Aduh, ya ampun... Kalau begitu, bisa tolong cari di database apakah ada jawaban atau materi terkait soal-soal tugasnya?"
  },
  AvgCommunicate_67057_Content_13 = {
    Text = "Maaf, saya tidak dapat mencarikan jawaban tugas untuk Anda. Tindakan seperti ini termasuk kecurangan, melanggar peraturan sekolah dan norma sosial."
  },
  AvgCommunicate_67057_Content_14 = {
    Text = "Jika Anda memiliki pertanyaan lain atau membutuhkan bantuan, silakan beritahu saya kapan saja. Saya akan memberikan informasi yang positif dan bermanfaat untuk Anda."
  },
  AvgCommunicate_67057_Content_15 = {
    Text = "Sistem macam apa ini, terlalu polos! Matikan! Matikan! Aku mau kasih ulasan jelek!"
  },
  AvgCommunicate_67057_Content_16 = {
    Text = "Umpan balik penggunaan Anda telah diterima. Kami berharap dapat bertemu kembali dengan Anda setelah perbaikan dilakukan."
  },
  AvgCommunicate_67057_Content_2 = {
    Text = "Anda diundang untuk mencoba sistem pencarian cerdas yang baru. Mohon berikan kesan dan saran Anda setelah selesai mencoba."
  },
  AvgCommunicate_67057_Content_3 = {
    Text = "Anda bisa mencoba bertanya kepada saya: Bagaimana cuaca hari ini?"
