  AvgCommunicate_67057_Content_4 = {
    Text = "Bagaimana cuaca hari ini?"
  },
  AvgCommunicate_67057_Content_5 = {
    Text = "Londinium hari ini hujan ringan lalu berawan, suhu delapan belas hingga dua puluh lima derajat Celsius, angin barat daya kecepatan dua hingga tiga, disarankan membawa payung saat bepergian."
  },
  AvgCommunicate_67057_Content_6 = {
