  },
  AvgCommunicate_67057_Content_7 = {
    Text = "Jadwal kuliah yang sudah dirapikan telah dikirim secara terpisah. Ditemukan tiga tugas yang belum Anda kumpulkan, mohon perhatikan tenggat waktu pengumpulan."
  },
  AvgCommunicate_67057_Content_8 = {
    Text = "Ugh, benar-benar menyentuh hal yang paling tidak ingin dibahas..."
