  AvgCommunicate_70486_Content_1 = {
    Text = "Kudengar……"
  },
  AvgCommunicate_70486_Content_10 = {
    Text = "Ramona memang telah dibawa ke Black Pool, tapi Anda tahu, tempat itu bukan tempat yang bisa Anda kunjungi..."
  },
  AvgCommunicate_70486_Content_11 = {
    Text = "Tenang saja, saya pasti akan membawa Ramona kembali dengan selamat!"
  },
  AvgCommunicate_70486_Content_12 = {
    Text = "Terima kasih atas informasinya. Tapi sayang sekali, kali ini sepertinya aku harus mengecewakanmu."
  },
  AvgCommunicate_70486_Content_13 = {
    Text = "Tolong pahami perasaan seorang ayah."
  },
  AvgCommunicate_70486_Content_14 = {
    Text = "Apa yang akan kulakukan nanti, kuharap kau bisa memaafkanku."
  },
  AvgCommunicate_70486_Content_15 = {
    Text = "Black Pool sekarang sangat berbahaya, kekuatan mentalmu tidak akan mampu bertahan di sana!"
  },
  AvgCommunicate_70486_Content_16 = {
    Text = "Tolong jangan gegabah, Profesor Dexter!"
  },
  AvgCommunicate_70486_Content_17 = {
    Text = "Profesor Dexter?"
  },
  AvgCommunicate_70486_Content_18 = {
    Text = "Profesor Dexter?!..."
  },
  AvgCommunicate_70486_Content_2 = {
    Text = "Ramona, dibawa ke Black Pool?"
  },
  AvgCommunicate_70486_Content_3 = {
    Text = "Aku gagal melindunginya……"
  },
  AvgCommunicate_70486_Content_4 = {
    Text = "Ini bukan salahmu, tidak perlu menyalahkan diri sendiri, Penjaga Rahasia."
  },
  AvgCommunicate_70486_Content_5 = {
    Text = "Saat mengawal Dekan Horlert, dia bertemu dengan Herbert……"
  },
  AvgCommunicate_70486_Content_6 = {
    Text = "Bukan bertemu, Penjaga Rahasia."
  },
  AvgCommunicate_70486_Content_7 = {
    Text = "Herbert memang sengaja mengincar Ramona."
  },
  AvgCommunicate_70486_Content_8 = {
    Text = "Yang ingin kuketahui sekarang hanyalah, apakah dia benar-benar dibawa ke Black Pool."
  },
  AvgCommunicate_70486_Content_9 = {
    Text = "Saya tidak ingin menyembunyikannya, Profesor Dexter."
  },
  AvgCommunicate_70486_Option_15 = {
    Text = "Tolong jangan gegabah!"
  },
  AvgCommunicate_70486_Option_3 = {
    Text = "Aku gagal melindunginya……"
  },
  AvgCommunicate_70486_Option_5 = {
    Text = "Saat mengawal Dekan Horlert, dia bertemu dengan Herbert……"
  },
  AvgCommunicate_70486_Option_9 = {Text = "Ya……"},
  AvgCommunicate_70487_Content_1 = {
    Text = "Si lemah itu, bagaimana pemulihannya."
  },
  AvgCommunicate_70487_Content_11 = {
    Text = "Aku tidak menyukainya, dan juga tidak menyukai kalian. Tapi aku lebih membenci gunung salju yang sombong itu, membenci orang-orang yang ingin memanfaatkan dan mengkhianatiku."
  },
  AvgCommunicate_70487_Content_12 = {
    Text = "Hanya itu saja."
  },
  AvgCommunicate_70487_Content_2 = {
    Text = "Setelah dia kembali dari Gunung Salju, dia menjalani perawatan, dan lukanya pulih dengan baik."
  },
  AvgCommunicate_70487_Content_3 = {
    Text = "Soal gunung salju, aku sudah dengar dari dirimu yang satu lagi."
  },
  AvgCommunicate_70487_Content_4 = {
    Text = "Terima kasih, Shilo. Kaulah yang telah membantu kami."
  },
  AvgCommunicate_70487_Content_5 = {
    Text = "Terima kasih? Kata yang begitu lemah."
  },
  AvgCommunicate_70487_Content_6 = {
    Text = "Aku hanya ingin mendapatkan kekuatan gunung salju, tidak ada hubungannya dengan membantu kalian."
  },
  AvgCommunicate_70487_Content_7 = {
    Text = "Nyawa sekelompok semut, aku tidak peduli."
  },
  AvgCommunicate_70487_Content_8 = {
    Text = "Di gunung salju, kau punya kesempatan untuk membunuh dirimu yang satu lagi, menelan kekuatan gunung salju sendirian, atau membiarkan gunung salju menelan kami."
  },
  AvgCommunicate_70487_Content_9 = {
    Text = "Tapi kau tidak melakukannya, bukan?"
  },
  AvgCommunicate_70487_Option_3 = {
    Text = "Soal Gunung Salju, terima kasih."
  },
  AvgCommunicate_70487_Option_8 = {
    Text = "Tapi kau tidak memilih untuk membunuh dirimu yang lain"
  },
  AvgCommunicate_70488_Content_1 = {
    Text = "Tubuh Kapten terus melemah……"
  },
  AvgCommunicate_70488_Content_10 = {
    Text = "Penjaga Rahasia, aku akan melakukan semampuku untuk membantu kalian."
  },
  AvgCommunicate_70488_Content_11 = {
    Text = "Jika ada kesempatan, tolong selamatkan Kapten."
  },
  AvgCommunicate_70488_Content_12 = {
    Text = "Ini adalah... permohonanku."
  },
  AvgCommunicate_70488_Content_2 = {
    Text = "Apakah ada cara untuk membantunya?"
  },
  AvgCommunicate_70488_Content_3 = {
    Text = "Itu mungkin sulit, Celeste."
  },
  AvgCommunicate_70488_Content_4 = {
    Text = "Bahkan bagi seorang Investigator, menjalin tautan dengan Awakened Body adalah beban yang sangat besar."
  },
  AvgCommunicate_70488_Content_5 = {
    Text = "Terlebih lagi, Kapten Elton dalam hal ini hanyalah orang biasa."
  },
  AvgCommunicate_70488_Content_6 = {
    Text = "Dia bisa menjalin tautan denganmu selama ini, itu sudah merupakan keajaiban."
  },
  AvgCommunicate_70488_Content_7 = {
    Text = "Tapi tenang saja, aku pasti akan mencari cara untuk membantu kalian."
  },
  AvgCommunicate_70488_Content_8 = {
    Text = "Apa yang bisa dilakukan Miriam, Misage pasti juga bisa melakukannya."
  },
  AvgCommunicate_70488_Content_9 = {
    Text = "Orang-orang memanjatkan permohonan kepadaku, tapi untuk orang-orang di sekitarku, aku tak berdaya..."
  },
  AvgCommunicate_70488_Option_3 = {
    Text = "Itu mungkin sulit, tapi Misage pasti punya cara"
  },
  AvgCommunicate_70489_Content_1 = {
    Text = "Maaf mengganggu, Pupil Tanpa Mata yang pucat."
  },
  AvgCommunicate_70489_Content_10 = {
    Text = "Menghubungimu semata-mata karena ketertarikan pribadiku."
  },
  AvgCommunicate_70489_Content_11 = {
    Text = "Setelah urusan yang ada di depan mata ini selesai, aku sangat berharap bisa punya kesempatan untuk bertemu denganmu secara pribadi."
  },
  AvgCommunicate_70489_Content_12 = {
    Text = "Berbincang denganmu tentang masa lalumu, dan juga masa depanmu."
  },
  AvgCommunicate_70489_Content_13 = {
    Text = "Tentu saja, dengan syarat kau bisa selamat dari semua kejadian ini."
  },
  AvgCommunicate_70489_Content_14 = {
    Text = "Semoga segalanya berjalan lancar untukmu, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70489_Content_15 = {
    Text = "Masa depanku?"
  },
  AvgCommunicate_70489_Content_16 = {
    Text = "Apa maksud kata-katamu?"
  },
  AvgCommunicate_70489_Content_18 = {
    Text = "Clementine?"
  },
  AvgCommunicate_70489_Content_2 = {
    Text = "Ternyata kau…… kebetulan, masih banyak hal yang ingin kutanyakan padamu."
  },
  AvgCommunicate_70489_Content_3 = {
    Text = "Di panti penampungan, apa yang kau lakukan pada kami?"
