  AvgCommunicate_70489_Content_5 = {
    Text = "Bisa membuatku pergi, sekaligus membuat kalian tidur nyenyak."
  },
  AvgCommunicate_70489_Content_6 = {
    Text = "Kata Pupil Tanpa Mata sudah kau sebutkan lebih dari sekali. Apa sebenarnya artinya?"
