  AvgCommunicate_70489_Content_7 = {
    Text = "Sst, ini bukan sesuatu yang seharusnya kau ketahui sekarang."
  },
  AvgCommunicate_70489_Content_8 = {
    Text = "Percayalah, kau akan mengetahuinya — saat waktunya tiba."
  },
  AvgCommunicate_70489_Content_9 = {
    Text = "Singkatnya, aku tidak bermaksud buruk, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70489_Option_15 = {
    Text = "Masa depanku?"
  },
  AvgCommunicate_70489_Option_2 = {
