  AvgCommunicate_70490_Content_1 = {
    Text = "Saat tubuh buatan itu meledak, aku meninggalkan sebuah inti perak kecil yang memiliki fungsi perekaman dan transmisi informasi untuk Herbert."
  },
  AvgCommunicate_70490_Content_10 = {
    Text = "Sama persis dengan simbol dalam mimpi yang kau gambar itu."
