  AvgCommunicate_70490_Content_11 = {
    Text = "Sebenarnya simbol apa itu?"
  },
  AvgCommunicate_70490_Content_12 = {
    Text = "Gereja Lentera."
  },
  AvgCommunicate_70490_Content_13 = {
    Text = "Ternyata mereka..."
  },
  AvgCommunicate_70490_Content_14 = {
    Text = "Asosiasi Pematung, Elworth... bayangan Lentera sudah bukan pertama kalinya muncul."
  },
  AvgCommunicate_70490_Content_15 = {
    Text = "Musuh sejati Mesagard sedang mendekat ke arah kita."
  },
  AvgCommunicate_70490_Content_16 = {
    Text = "Bersiaplah, %player%."
  },
  AvgCommunicate_70490_Content_2 = {
    Text = "Berkat keserakahan Herbert, perangkat kecil ini berhasil mengumpulkan cukup banyak informasi."
  },
  AvgCommunicate_70490_Content_3 = {
    Text = "Luar biasa, Profesor Dor!"
  },
  AvgCommunicate_70490_Content_4 = {
    Text = "Dia saja yang kurang waspada."
  },
  AvgCommunicate_70490_Content_5 = {
    Text = "Seseorang yang menganggap dirinya jenius, keangkuhannya akan membuatnya lengah."
  },
  AvgCommunicate_70490_Content_6 = {
    Text = "Kau sudah merencanakan langkah ini sejak awal?!"
  },
  AvgCommunicate_70490_Content_7 = {
    Text = "Meskipun hanya mengendalikan tubuh buatan, keluar sekali saja sudah sangat merepotkan."
  },
  AvgCommunicate_70490_Content_8 = {
    Text = "Kalau tidak bisa mendapatkan sesuatu, lebih baik aku menikmati teh sore di ruang istirahat."
  },
  AvgCommunicate_70490_Content_9 = {
    Text = "Singkatnya, di antara semua informasi yang diperoleh, yang paling penting adalah sebuah simbol."
  },
  AvgCommunicate_70490_Option_11 = {
    Text = "Sebenarnya simbol apa itu?"
