  AvgCommunicate_70491_Content_2 = {Text = "Selamat."},
  AvgCommunicate_70491_Content_3 = {
    Text = "Aku tidak menyangka, misi lapangan resmi pertama sudah harus menghadapi semua ini."
  },
  AvgCommunicate_70491_Content_4 = {
    Text = "Tapi bagaimanapun juga, kita berhasil."
