  },
  AvgCommunicate_70492_Content_1 = {
    Text = "Aku berencana mengadakan upacara persembahan baru-baru ini, tapi ikan hidup dan kapal yang dibutuhkan agak kurang."
  },
  AvgCommunicate_70492_Content_10 = {
    Text = "Karena kamu sudah mengetahui masa laluku, maka kamu seharusnya juga tahu jawabanku."
  },
  AvgCommunicate_70492_Content_11 = {
    Text = "Jika bisa mengulang kembali, aku tetap akan melakukan apa yang pernah kulakukan."
  },
  AvgCommunicate_70492_Content_12 = {
    Text = "Dulu, sekarang, dan masa depan. Pendeta Agung Lemuria tidak pernah menyesal."
  },
  AvgCommunicate_70492_Content_13 = {
    Text = "Aku juga... tidak pernah punya pilihan lain, Penjaga Rahasia."
  },
  AvgCommunicate_70492_Content_2 = {
    Text = "Bisakah Misagar meminjamkan beberapa? Aku menjamin dengan identitasku sebagai Pendeta Utama Lemuria, semuanya akan dikembalikan tepat waktu."
  },
  AvgCommunicate_70492_Content_3 = {
    Text = "Tidak masalah, aku akan membantumu berkomunikasi dengan pihak sekolah. Dewan sekolah seharusnya akan menyetujuinya."
  },
  AvgCommunicate_70492_Content_4 = {
    Text = "Barang-barang ini, untuk keluargamu, atau untuk Deborah?"
  },
  AvgCommunicate_70492_Content_5 = {
    Text = "...Kamu sudah tahu semuanya?"
  },
  AvgCommunicate_70492_Content_6 = {
    Text = "Menurut adat Lemuria, kalian menggunakan ikan hidup dan perahu untuk mengirimkan salam kepada orang yang paling kalian hargai yang telah tiada."
  },
  AvgCommunicate_70492_Content_7 = {
    Text = "Kamu masih tidak bisa melupakan mereka. Kamu masih sangat mencintai mereka."
  },
  AvgCommunicate_70492_Content_8 = {
    Text = "Jadi... apakah kamu menyesal, Miriam?"
  },
  AvgCommunicate_70492_Option_3 = {
    Text = "Tidak masalah."
  },
  AvgCommunicate_70492_Option_4 = {
    Text = "Ini untuk keluargamu, atau untuk Deborah?"
  },
  AvgCommunicate_70492_Option_8 = {
    Text = "Apakah kamu menyesal?"
  },
  AvgCommunicate_70493_Content_1 = {
    Text = "Surat wasiatmu, sudah selesai kubacakan."
  },
  AvgCommunicate_70493_Content_10 = {
    Text = "Dan aku pasti akan dengan bangga menceritakan kisahmu kepada semua orang, hingga... hari ketika ingatanku tererosi."
  },
  AvgCommunicate_70493_Content_11 = {
    Text = "Tapi saat membacakan surat wasiat, saat ini, penyesalan adalah satu-satunya yang memenuhi pikiranku."
  },
  AvgCommunicate_70493_Content_12 = {
    Text = "Kau bilang dirimu seorang pengecut. Kau bilang kau tidak akan pernah rela meninggalkan kami."
  },
  AvgCommunicate_70493_Content_13 = {
    Text = "Tapi pada akhirnya, kau tetap memilih jalan ini."
  },
  AvgCommunicate_70493_Content_14 = {
    Text = "Ayah sudah tiada. Kau pun sudah tiada."
  },
  AvgCommunicate_70493_Content_15 = {
    Text = "Aku tidak keberatan dengan kebohongan yang kau ucapkan. Betapa aku berharap kau bisa membohongiku sedikit lebih lama. Setahun, sebulan..."
  },
  AvgCommunicate_70493_Content_16 = {
    Text = "Walau hanya sehari saja, setidaknya kata-kata yang belum sempat terucap itu masih ada kesempatan untuk disampaikan..."
  },
  AvgCommunicate_70493_Content_17 = {
    Text = "Aku sangat takut, %player%."
  },
  AvgCommunicate_70493_Content_18 = {
    Text = "Aku takut suatu hari nanti akan melupakan wajahmu, namamu."
  },
  AvgCommunicate_70493_Content_19 = {
    Text = "Aku takut, suatu hari nanti kau akan lenyap sepenuhnya dari ingatanku..."
  },
  AvgCommunicate_70493_Content_2 = {
    Text = "Aku mencoba membacakan kata-kata itu dengan nada lega, sesuai keinginanmu."
  },
  AvgCommunicate_70493_Content_20 = {
    Text = "Tapi kau tahu, aku bukan orang yang akan menyerah."
  },
  AvgCommunicate_70493_Content_21 = {
    Text = "Aku tidak percaya, kau akan menghilang begitu saja."
  },
  AvgCommunicate_70493_Content_22 = {
    Text = "Tidak peduli berapa lama pun, aku akan terus menunggu, terus mengingat. Hingga hari di mana kau terbangun dari Black Pool, membuka pintu itu, dan kembali ke kampus ini."
  },
  AvgCommunicate_70493_Content_23 = {
    Text = "Saat itu tiba, hal-hal yang terjadi selama ketidakhadiranmu, kata-kata yang belum sempat terucap, akan kuceritakan satu per satu kepadamu……"
  },
  AvgCommunicate_70493_Content_24 = {
    Text = "Aku tahu, kau pasti sangat lelah sekarang, terlalu lelah untuk membalas…… Tidak apa-apa, tidurlah dengan nyenyak."
  },
  AvgCommunicate_70493_Content_25 = {
    Text = "Aku menunggumu……%player%."
  },
  AvgCommunicate_70493_Content_3 = {
    Text = "Aku sudah berusaha. Tapi aku tidak sanggup, %player%..."
  },
  AvgCommunicate_70493_Content_4 = {
    Text = "Makam Kunci dipenuhi orang, tapi aku tak bisa melihat siapa pun."
  },
  AvgCommunicate_70493_Content_5 = {
    Text = "Seluruh dunia menjadi hening. Hanya ada suara hujan, hanya ada kau dan aku."
  },
  AvgCommunicate_70493_Content_6 = {
    Text = "Ketika pintu itu tertutup di hadapanku, ketika kata-kata itu melintas baris demi baris di depan mataku, yang kurasakan hanyalah penyesalan."
  },
  AvgCommunicate_70493_Content_7 = {
    Text = "Aku menyesal telah menanamkan prinsip-prinsip penyelidik kepadamu, menyesal mengajarimu pengetahuan investigasi, menyesal membawamu keluar dari Akut..."
  },
  AvgCommunicate_70493_Content_8 = {
    Text = "Aku tahu, aku tidak seharusnya berpikir seperti ini."
  },
  AvgCommunicate_70493_Content_9 = {
    Text = "Aku seorang penyelidik. Kau telah menyelamatkan dunia kita dari Erosi, seharusnya aku merasa lega untukmu."
  },
  AvgCommunicate_70494_Content_1 = {
    Text = "Selamat siang, Penjaga Rahasia Mesagge."
  },
  AvgCommunicate_70494_Content_10 = {
    Text = "Kudengar Mesagge memiliki seorang Penjaga Rahasia yang luar biasa."
  },
  AvgCommunicate_70494_Content_11 = {
    Text = "Seharusnya aku tidak lancang mengganggu, tapi aku benar-benar tidak bisa menahan rasa penasaranku dan ingin melihat langsung."
  },
  AvgCommunicate_70494_Content_12 = {
    Text = "Kau tidak mengecewakanku, %player%."
  },
  AvgCommunicate_70494_Content_13 = {
    Text = "Apa sebenarnya yang ingin kau lakukan?"
  },
  AvgCommunicate_70494_Content_14 = {
    Text = "Jika ada kesempatan, aku ingin mengundangmu berkunjung ke laboratoriumku."
  },
  AvgCommunicate_70494_Content_15 = {
    Text = "Seorang Penjaga Rahasia yang mampu terhubung dengan tak terhitung banyaknya Awakened Body……rahasia yang ada dalam dirimu sangat menarik perhatianku."
  },
  AvgCommunicate_70494_Content_16 = {
    Text = "Jika kau membawa anggota Sculptor Association dan menyerahkan diri ke Mesagge, kerja sama bukan hal yang tidak bisa dipertimbangkan."
  },
  AvgCommunicate_70494_Content_17 = {
    Text = "Heh... Kukira aku akan menerima serentetan makian."
  },
  AvgCommunicate_70494_Content_18 = {
    Text = "Kau lebih menarik dari yang kubayangkan."
  },
  AvgCommunicate_70494_Content_19 = {
    Text = "Masih panjang waktu di depan kita. Ke depannya, kita akan punya banyak kesempatan untuk bertukar pikiran."
  },
  AvgCommunicate_70494_Content_2 = {
    Text = "Ternyata kau……Herbert·Rosenthal……"
  },
  AvgCommunicate_70494_Content_20 = {
    Text = "Nantikanlah, %player%."
  },
  AvgCommunicate_70494_Content_3 = {
    Text = "Wah, sepertinya sudah ada orang yang memperkenalkan diriku terlebih dahulu."
  },
  AvgCommunicate_70494_Content_4 = {
    Text = "Itu justru menghemat banyak waktu untukku."
  },
  AvgCommunicate_70494_Content_5 = {
    Text = "Komunikasi Silver Core memerlukan tautan dua arah. Bagaimana kau bisa menghubungiku?"
  },
  AvgCommunicate_70494_Content_6 = {
    Text = "Soal itu……"
  },
  AvgCommunicate_70494_Content_7 = {
    Text = "Bagi mereka yang beruntung pernah ikut serta dalam pengembangannya, teknologi Komunikasi Silver Core tidak menyimpan rahasia apa pun."
  },
  AvgCommunicate_70494_Content_8 = {
    Text = "Kau adalah pengembang Komunikasi Silver Core?"
  },
  AvgCommunicate_70494_Content_9 = {
    Text = "Itu cerita lama, kita bisa membicarakannya pelan-pelan kalau ada waktu luang nanti."
  },
  AvgCommunicate_70494_Option_13 = {
    Text = "Apa sebenarnya yang ingin kau lakukan?"
  },
  AvgCommunicate_70494_Option_16 = {
    Text = "Kecuali jika kau menyerahkan diri ke Mesagge"
  },
  AvgCommunicate_70494_Option_2 = {
    Text = "Herbert·Rosenthal……"
  },
  AvgCommunicate_70494_Option_5 = {
    Text = "Bagaimana kau bisa menghubungiku?"
  },
  AvgCommunicate_70495_Content_1 = {
    Text = "Jasad Anderson telah dirusak oleh orang-orang dari Asosiasi Pematung, tidak bisa lagi disusun menjadi bentuk manusia yang utuh."
  },
  AvgCommunicate_70495_Content_10 = {
    Text = "Mungkin, suatu hari kita…"
  },
  AvgCommunicate_70495_Content_11 = {
    Text = "Apakah kau merasa takut, Senior William?"
  },
  AvgCommunicate_70495_Content_13 = {
    Text = "Mungkin ada orang yang bisa melampaui hidup dan mati, tapi bukan aku."
  },
  AvgCommunicate_70495_Content_14 = {
    Text = "Aku selalu diliputi rasa takut setiap saat, %player%."
  },
  AvgCommunicate_70495_Content_15 = {
    Text = "Tapi aku tidak pernah melihat emosi ketakutan apa pun darimu."
  },
  AvgCommunicate_70495_Content_16 = {
    Text = "Karena aku tidak punya waktu. Karena Erosi ada tepat di hadapanku."
  },
  AvgCommunicate_70495_Content_17 = {
    Text = "Banyak orang mati, tapi aku masih hidup."
  },
  AvgCommunicate_70495_Content_18 = {
    Text = "Entah itu ketakutan atau duka, penyelidik Mithsage tidak berhak untuk berhenti melangkah karenanya."
  },
  AvgCommunicate_70495_Content_2 = {
    Text = "Inti perak yang diekstraksi secara paksa itu juga telah hancur sepenuhnya."
  },
  AvgCommunicate_70495_Content_20 = {
    Text = "Misi baru telah tiba."
  },
  AvgCommunicate_70495_Content_21 = {
    Text = "Kita akan tetap hidup, %player%. Hidup sampai hari di mana Erosi berhasil diatasi."
  },
  AvgCommunicate_70495_Content_3 = {
    Text = "Kami menggeledah seluruh laboratorium di rumah penampungan, dan hanya menemukan ini."
  },
  AvgCommunicate_70495_Content_4 = {
    Text = "Kunci Perak, nomor L-1463, milik Investigator Anderson—dulunya miliknya."
  },
  AvgCommunicate_70495_Content_5 = {
    Text = "Kunci perak ini… bagaimana sekolah akan menanganinya?"
  },
  AvgCommunicate_70495_Content_6 = {
    Text = "Ditarik kembali, dimasukkan ke dalam Kolam Hitam untuk dibuat ulang, lalu pada upacara Makam Kunci tahun berikutnya, diberikan kepada investigator baru."
  },
  AvgCommunicate_70495_Content_7 = {
    Text = "Kunci itu akan menemani investigator baru, terus menuju tempat-tempat paling berbahaya."
  },
  AvgCommunicate_70495_Content_8 = {
    Text = "Hingga investigator itu pensiun, atau meninggal."
  },
  AvgCommunicate_70495_Content_9 = {
    Text = "Mungkin, suatu hari kita…"
  },
  AvgCommunicate_70495_Option_10 = {
    Text = "Apakah kau merasa takut?"
  },
  AvgCommunicate_70495_Option_15 = {
    Text = "Aku tidak pernah merasakan ketakutanmu."
  },
  AvgCommunicate_70495_Option_5 = {
    Text = "Kunci perak ini… bagaimana sekolah akan menanganinya?"
  },
  AvgCommunicate_70495_Option_9 = {
    Text = "Apakah kita akan bernasib sama seperti Anderson?"
  },
  AvgCommunicate_70496_Content_1 = {
    Text = "Ritual orang-orang Yalan ini... benar-benar mengerikan."
  },
  AvgCommunicate_70496_Content_10 = {
    Text = "Menurutmu aku orang seperti itu?"
  },
  AvgCommunicate_70496_Content_11 = {
    Text = "Aku cuma bertanya biasa saja, kenapa setegang itu?"
  },
  AvgCommunicate_70496_Content_12 = {
    Text = "Kalau sikapmu seperti itu, di meja kartu orang akan langsung membaca pikiranmu. Mental masih perlu diasah, Penjaga Rahasia."
  },
  AvgCommunicate_70496_Content_13 = {
    Text = "Singkatnya, rahasia gurun pasir ini mungkin jauh lebih rumit dari yang kita perkirakan."
  },
  AvgCommunicate_70496_Content_14 = {
    Text = "Untuk penyelidikan selanjutnya, kita harus lebih berhati-hati."
  },
  AvgCommunicate_70496_Content_2 = {
    Text = "Kukira kau akan menerima ajakan wanita Yalan itu."
  },
  AvgCommunicate_70496_Content_4 = {
    Text = "Sebenarnya aku ini seperti apa di matamu..."
  },
  AvgCommunicate_70496_Content_5 = {
    Text = "Tak kusangka Leik yang selalu berkharisma juga punya hal yang tidak bisa diterimanya."
  },
  AvgCommunicate_70496_Content_6 = {
    Text = "Tanpa bunga dan kisah pengiring anggur, yang ada hanyalah nafsu paling primitif dan paling liar."
  },
  AvgCommunicate_70496_Content_7 = {
    Text = "Ritual semacam ini memang bukan seleraku."
  },
  AvgCommunicate_70496_Content_8 = {
    Text = "Ngomong-ngomong, kau tidak menerima ajakan aneh apa pun, kan?"
  },
  AvgCommunicate_70496_Content_9 = {
    Text = "Te... tentu saja tidak... mana mungkin!"
  },
  AvgCommunicate_70496_Option_2 = {
    Text = "Kukira kau akan menerima ajakan wanita Yalan itu"
  },
  AvgCommunicate_70496_Option_5 = {
    Text = "Tak kusangka ada hal yang tidak bisa kauterima juga"
  },
  AvgCommunicate_70496_Option_9 = {
    Text = "Te... tentu saja tidak... mana mungkin!"
  },
  AvgCommunicate_70497_Content_1 = {
    Text = "Halo, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70497_Content_2 = {
    Text = "Senang bermain dengan mainan Juliette?"
  },
  AvgCommunicate_70497_Content_3 = {
    Text = "Kau... pengkhianat itu?!"
  },
  AvgCommunicate_70497_Content_4 = {
    Text = "Kupikir seharusnya kau lebih cepat menyadari siapa aku. Sungguh disayangkan."
  },
  AvgCommunicate_70497_Content_5 = {
    Text = "Tapi tidak apa-apa, ini hanya permainan terakhir."
  },
  AvgCommunicate_70497_Content_6 = {
    Text = "Sekarang, permainan akan segera berakhir."
  },
  AvgCommunicate_70497_Content_7 = {
    Text = "Sebelum kehancuran yang tak terelakkan tiba, ada satu hal yang membuatku penasaran."
  },
  AvgCommunicate_70497_Content_8 = {
    Text = "Kebenaran tentang kekacauan abadi itu, apakah kita para penjaga rahasia yang angkuh, para penyelamat Misagar yang gagah berani, benar-benar memiliki keberanian untuk menghadapinya?"
  },
  AvgCommunicate_70497_Option_3 = {
    Text = "Kau... pengkhianat itu?!"
  },
  AvgCommunicate_70498_Content_1 = {
    Text = "Aku bukanlah pedagang yang bodoh, tapi kalau dipikir-pikir, sepertinya aku telah melakukan transaksi yang merugikan ya..."
  },
  AvgCommunicate_70498_Content_10 = {
    Text = "Selalu waspada terhadap kebohongan adalah kualitas dasar seorang pebisnis yang kompeten."
  },
  AvgCommunicate_70498_Content_11 = {
    Text = "Jadi... apakah itu benar-benar wajah asli Nyonya Dafodel?"
  },
  AvgCommunicate_70498_Content_12 = {
    Text = "Tidak ada biaya yang lebih mahal daripada kebenaran, Penjaga Rahasia kecil."
  },
  AvgCommunicate_70498_Content_13 = {
    Text = "Terima kasih, Nyonya Dafodel."
  },
  AvgCommunicate_70498_Content_14 = {
    Text = "Yang tadi itu cuma bercanda. Aku tahu bagi orang sepertimu, menunjukkan sisi yang sebenarnya itu berarti apa."
  },
  AvgCommunicate_70498_Content_15 = {
    Text = "Ini adalah hadiah yang berharga, aku akan menjaganya baik-baik."
  },
  AvgCommunicate_70498_Content_16 = {
    Text = "Jangan pikir dua tiga kalimat saja sudah cukup untuk membujukku, Nak."
  },
  AvgCommunicate_70498_Content_17 = {
    Text = "Sebagai balasannya, bukankah seharusnya kau juga memberiku sebuah hadiah?"
  },
  AvgCommunicate_70498_Content_18 = {
    Text = "Ketahuan ya……"
  },
  AvgCommunicate_70498_Content_19 = {
    Text = "Nyonya Daffodil, apa yang kau inginkan?"
  },
  AvgCommunicate_70498_Content_2 = {Text = "?"},
  AvgCommunicate_70498_Content_20 = {
    Text = "Karena kau sudah melihat wujud asliku, lalu wujud aslimu, kapan kau berencana memperlihatkannya padaku?"
  },
  AvgCommunicate_70498_Content_21 = {
    Text = "Wujud asliku? Apa maksudnya……Aku kurang mengerti, Nyonya Daffodil."
  },
  AvgCommunicate_70498_Content_22 = {
    Text = "Sepertinya Misage belum mengatakan apa pun padamu……"
  },
  AvgCommunicate_70498_Content_23 = {
    Text = "Waktunya belum tiba, tak mengapa."
  },
  AvgCommunicate_70498_Content_24 = {
    Text = "Ingat kesepakatan kita hari ini, Nak."
  },
  AvgCommunicate_70498_Content_25 = {
    Text = "Aku sangat menantikan hari di mana kau menunjukkan wajah aslimu."
  },
  AvgCommunicate_70498_Content_3 = {
    Text = "Bukankah kau sudah mendapatkan tengkorak yang kau inginkan?"
  },
  AvgCommunicate_70498_Content_4 = {
    Text = "Lautan materi abu-abu yang berkilauan itu, kini bertambah satu lagi koleksi yang kau sukai."
  },
  AvgCommunicate_70498_Content_5 = {
    Text = "Memang benar, itu adalah tengkorak yang indah. Transaksi ini tidak bisa dibilang sia-sia."
  },
  AvgCommunicate_70498_Content_6 = {
    Text = "Namun, biaya yang kukeluarkan tetap terlalu tinggi."
  },
  AvgCommunicate_70498_Content_7 = {
    Text = "Kau hanya memperlihatkan wujud aslimu sekilas kepadaku..."
  },
  AvgCommunicate_70498_Content_8 = {
    Text = "Lagipula, apakah itu benar-benar wujud aslimu, itu pun masih belum pasti."
  },
  AvgCommunicate_70498_Content_9 = {
    Text = "Hehe... Tidak buruk, Nak."
  },
  AvgCommunicate_70498_Option_11 = {
    Text = "Jadi... apakah itu benar-benar wajah asli Nyonya Dafodel?"
  },
  AvgCommunicate_70498_Option_13 = {
    Text = "Terima kasih, Nyonya Dafodel."
  },
  AvgCommunicate_70498_Option_18 = {
    Text = "Ketahuan ya……"
  },
  AvgCommunicate_70498_Option_2 = {
    Text = "Bukankah tengkoraknya sudah didapat?"
  },
  AvgCommunicate_70498_Option_21 = {
    Text = "Wujud asliku? Apa maksudnya……"
  },
  AvgCommunicate_70498_Option_7 = {
    Text = "Hanya melihat wujud aslimu sebentar..."
  },
  AvgCommunicate_70499_Content_1 = {
    Text = "Menyingkirkan lawan, melepaskan diri dari belenggu Lamber dan kontrak. Tanpa hambatan itu, hanya dalam beberapa minggu, dia sudah menjadi pemburu paling ganas di dunia bisnis Londinium."
  },
  AvgCommunicate_70499_Content_10 = {
    Text = "Tenang saja, Profesor Dexter, lain kali kami tidak akan meminta Anda melakukan hal berbahaya seperti ini lagi... Maksud saya, sebisa mungkin."
  },
  AvgCommunicate_70499_Content_11 = {
    Text = "Keberadaan yang tersembunyi di dalam kesadaran Soleil, tampaknya bernama\"N\". Apakah Anda tahu sesuatu tentang dia?"
  },
  AvgCommunicate_70499_Content_12 = {
    Text = "Tidak terlalu jelas. Kedengarannya kalau bukan penipu ya orang gila, kemungkinan besar keduanya sekaligus."
  },
  AvgCommunicate_70499_Content_13 = {
    Text = "Tapi bagaimanapun jahatnya, setidaknya dia orang yang punya selera tinggi. Bisa terdengar dari nyanyiannya."
  },
  AvgCommunicate_70499_Content_14 = {
    Text = "Lain kali ada kesempatan, saya harus berkenalan dengannya dengan baik, siapa tahu kami bisa minum bersama."
  },
  AvgCommunicate_70499_Content_15 = {
    Text = "...Tentu saja, dalam lingkungan yang aman. Tuan tua yang sudah lanjut usia ini sudah tidak sanggup lagi menerima kejutan apa pun."
  },
  AvgCommunicate_70499_Content_2 = {
    Text = "Kurasa tidak lama lagi, seluruh tanah di Londinium akan menyandang nama marganya."
  },
  AvgCommunicate_70499_Content_3 = {
    Text = "Nyonya Soreil, benar-benar orang yang luar biasa. Untung Misage ada di pihaknya."
  },
  AvgCommunicate_70499_Content_4 = {
    Text = "Kali ini berkat bantuan Anda, Profesor Dexter."
  },
  AvgCommunicate_70499_Content_5 = {
    Text = "Terima kasih sudah membantu memancing tersangka keluar, kalau tidak, entah berapa lama lagi urusan ini baru bisa diselesaikan."
  },
  AvgCommunicate_70499_Content_6 = {
    Text = "Hanya menjalankan kewajiban seorang pria terhormat, itu saja."
  },
  AvgCommunicate_70499_Content_7 = {
    Text = "Rencana yang diajukan Ramona, ayah tua ini tidak punya hak untuk menolak."
  },
  AvgCommunicate_70499_Content_8 = {
    Text = "Tapi, kalau lain kali ada kejadian seperti ini lagi, kuharap kalian bisa bertindak lebih cepat."
  },
  AvgCommunicate_70499_Content_9 = {
    Text = "Jangan tunggu sampai pisau orang itu tinggal lima sentimeter dari leherku baru keluar, bikin kaget saja."
  },
  AvgCommunicate_70499_Option_10 = {
    Text = "Tidak akan ada lain kali lagi... sebisa mungkin"
  },
  AvgCommunicate_70499_Option_11 = {
    Text = "Apakah Anda tahu tentang\"N\"?"
  },
  AvgCommunicate_70499_Option_4 = {
    Text = "Terima kasih sudah membantu memancing tersangka keluar"
  },
  AvgCommunicate_70500_Content_1 = {
    Text = "Obrolan di kafe tadi sangat menyenangkan, Penjaga Rahasia{Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70500_Content_10 = {
    Text = "Kalau lain kali kau menghadapi situasi serupa, dan kau harus menembak diriku yang asli agar bisa membawa yang lain keluar dari bahaya, apa kau juga akan menembak?"
  },
  AvgCommunicate_70500_Content_11 = {
    Text = "Hmm… tentu saja."
  },
  AvgCommunicate_70500_Content_12 = {
    Text = "Tapi tenang saja, Penjaga Rahasia {Male=tuan,Female=nyonya}. Keberuntungan akan tetap berpihak padaku."
  },
  AvgCommunicate_70500_Content_13 = {
    Text = "Saat itu, pistolku pasti tidak ada pelurunya."
  },
  AvgCommunicate_70500_Content_14 = {
    Text = "70% tidak ada."
  },
  AvgCommunicate_70500_Content_2 = {
    Text = "Suatu kehormatan, bisa menyaksikan masa lalu seorang penjudi."
  },
  AvgCommunicate_70500_Content_3 = {
    Text = "Bagian favoritku adalah saat sang penjudi kehilangan segalanya, dan jiwanya dicuri orang lain."
  },
  AvgCommunicate_70500_Content_4 = {
    Text = "Ha... ada kalah ada menang, itulah hidup."
  },
  AvgCommunicate_70500_Content_5 = {
    Text = "Lihat, bukankah kali ini aku berhasil menebus kekalahan?"
  },
  AvgCommunicate_70500_Content_6 = {
    Text = "Jadi tembakan yang kau arahkan padaku itu, juga sebuah taruhan?"
  },
  AvgCommunicate_70500_Content_7 = {
    Text = "Mana mungkin. Aku punya keyakinan 70% penuh terhadap penilaianku sendiri."
  },
  AvgCommunicate_70500_Content_8 = {
    Text = "Lalu 30% sisanya?"
  },
  AvgCommunicate_70500_Content_9 = {
    Text = "Tidak ada sisa 30%. 70% itu sudah 100%."
  },
  AvgCommunicate_70500_Option_2 = {
    Text = "Suatu kehormatan, bisa menyaksikan masa lalu seorang penjudi"
  },
  AvgCommunicate_70500_Option_6 = {
    Text = "Jadi tembakan yang kau arahkan padaku itu, juga sebuah taruhan?"
  },
  AvgCommunicate_70500_Option_8 = {
    Text = "Lalu 30% sisanya?"
  },
  AvgCommunicate_70501_Content_1 = {
    Text = "Bagus tidak?"
  },
  AvgCommunicate_70501_Content_10 = {
    Text = "Tapi… kisah yang diceritakan oleh kelompok patung itu, terlalu kejam rasanya."
  },
  AvgCommunicate_70501_Content_11 = {
    Text = "Kau memahaminya, Penjaga Rahasia…"
  },
  AvgCommunicate_70501_Content_12 = {
    Text = "Semua karya seni, pada dasarnya kejam."
  },
  AvgCommunicate_70501_Content_13 = {
    Text = "Justru dalam kekejaman itulah, seni yang diam memperoleh kehidupan yang nyata."
  },
  AvgCommunicate_70501_Content_14 = {
    Text = "Kalau aku, mungkin akan merasa proses berkarya seperti itu sangat menyiksa…"
  },
  AvgCommunicate_70501_Content_15 = {
    Text = "Tapi kau berbeda, Shan. Aku memahami pilihanmu."
  },
  AvgCommunicate_70501_Content_16 = {
    Text = "Karya seperti \"Kematian Gadis Karang\" adalah makna yang kau kejar."
  },
  AvgCommunicate_70501_Content_17 = {
    Text = "Aku sangat menantikan, menantikan \"kekejaman\" itu, kembali mekar dalam garis-garis yang kau pahat."
  },
  AvgCommunicate_70501_Content_19 = {
    Text = "Kukira, kau akan sama seperti orang-orang biasa itu, menyarankan agar seniku lebih \"normal\" sedikit."
  },
  AvgCommunicate_70501_Content_2 = {
    Text = "Apa... Wajahmu maksudnya?"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "Kata-kata ini sangat berarti bagiku… Terima kasih, Penjaga Rahasia{Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "Sebagai balasan, akan kuberitahu sebuah rahasia kecil: saat kau masuk ke dalam mimpi, aku berdiri tepat di sampingmu."
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "Semua ekspresi memalukanmu, sudah kupahat semuanya. Sangat·mirip·aslinya."
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "Kalau ada waktu, datanglah ke ruang pameran kecilku untuk melihatnya~"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "Shan! Kuberikan lima puluh Leiofang, tolong buang patung-patung itu…"
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "Bukankah kau sendiri yang bilang, seni yang hidup dan \"kejam\". Benar kan, Penjaga Rahasia?"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "Tentu saja patung yang kau lihat di dalam mimpi."
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "Lekuk tubuh manusia memang alami dan harmonis, tetapi kurang memiliki keindahan abadi yang statis, juga kurang tema dan kreativitas, sehingga sulit dibandingkan dengan karya pahatan."
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "Kelompok patung itu, sekarang sudah sangat jarang ada orang yang pernah melihatnya. Aku ingin tahu penilaianmu..."
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "Apa... Patungmu maksudnya?"
  },
  AvgCommunicate_70501_Content_7 = {
    Text = "Tentu saja. Kelompok patung itu, sekarang sudah sangat jarang ada orang yang pernah melihatnya. Aku ingin tahu penilaianmu..."
  },
  AvgCommunicate_70501_Content_8 = {
    Text = "Itu adalah kelompok patung terindah yang pernah kulihat."
  },
  AvgCommunicate_70501_Content_9 = {
    Text = "Jelas-jelas hanya garis-garis yang diam, namun mampu menggambarkan dinamika dan vitalitas yang bahkan makhluk hidup pun tak memilikinya."
  },
  AvgCommunicate_70501_Option_14 = {
    Text = "Aku memahami pilihanmu"
  },
  AvgCommunicate_70501_Option_2 = {Text = "Wajahmu?"},
  AvgCommunicate_70501_Option_24 = {Text = "Jangan!!!"},
  AvgCommunicate_70501_Option_6 = {Text = "Patungmu?"},
  AvgCommunicate_70501_Option_8 = {
    Text = "Indah... dan kejam."
  },
  AvgCommunicate_70502_Content_1 = {
    Text = "Bosan. Bosan bosan bosan……"
  },
  AvgCommunicate_70502_Content_10 = {
    Text = "Londinium tidak mengizinkan memelihara budak, tempat barbar ini."
  },
  AvgCommunicate_70502_Content_11 = {
    Text = "Terpaksa aku menuruti kata-katamu, menyuruh-nyuruh mereka di dalam labirin saja."
  },
  AvgCommunicate_70502_Content_12 = {
    Text = "Saat mereka bertarung di arena, benar-benar persis sama seperti yang pernah kulihat dulu!"
  },
  AvgCommunicate_70502_Content_13 = {
    Text = "Ternyata labirin itu digunakan untuk ini……"
  },
  AvgCommunicate_70502_Content_14 = {
    Text = "Benar sekali! Seru banget!"
  },
  AvgCommunicate_70502_Content_15 = {
    Text = "Ayo ikut aku untuk melihatnya! Ini adalah kehormatan tertinggi!"
  },
  AvgCommunicate_70502_Content_16 = {
    Text = "Boleh juga sih, mengenal lebih banyak tentang sejarah tidak ada ruginya……"
  },
  AvgCommunicate_70502_Content_17 = {
    Text = "Yuuhashi pasti akan sangat menyukai arenamu. Bagaimana kalau sekalian mengajaknya juga?"
  },
  AvgCommunicate_70502_Content_18 = {
    Text = "Tidak boleh! Jauhkan iblis itu dariku!!!"
  },
  AvgCommunicate_70502_Content_2 = {
    Text = "Setiap hari terjebak di tempat menyebalkan ini, benar-benar bikin kesal!"
  },
  AvgCommunicate_70502_Content_3 = {
    Text = "Labirinku sudah selesai dibangun ulang. Aku membangun seluruh arena di sana berdasarkan ingatanku!"
  },
  AvgCommunicate_70502_Content_4 = {
    Text = "Ayo kita main bersama! Sekarang juga!"
  },
  AvgCommunicate_70502_Content_5 = {
    Text = "Nada bicaramu yang seperti memerintah budak itu, kapan baru mau diubah……"
  },
  AvgCommunicate_70502_Content_6 = {
    Text = "Hmph, memangnya apa yang perlu diubah."
  },
  AvgCommunicate_70502_Content_7 = {
    Text = "Aku sudah mengalah banyak sekali! Sekarang aku hanya menyuruh-nyuruh budak di dalam labirin saja."
  },
  AvgCommunicate_70502_Content_8 = {
    Text = "Sekarang kamu sudah tidak takut mengingat hal-hal itu?"
  },
  AvgCommunicate_70502_Content_9 = {
    Text = "Tentu saja. Memangnya ada yang perlu ditakuti!"
  },
  AvgCommunicate_70502_Option_16 = {
    Text = "Kalau begitu aku ajak Yuuhashi juga ya"
  },
  AvgCommunicate_70502_Option_5 = {
    Text = "Kapan kamu bisa mengubah nada bicaramu itu……"
  },
  AvgCommunicate_70502_Option_8 = {
    Text = "Sekarang kamu sudah tidak takut mengingat hal-hal itu?"
  },
  AvgCommunicate_70503_Content_1 = {
    Text = "Kejadian di gereja itu, jika kau tidak ada di sana, akan ada lebih banyak orang tak bersalah yang menjadi korban……"
  },
  AvgCommunicate_70503_Content_10 = {
    Text = "Namun sekarang, dia sudah menjadi pemimpin Gereja Lentera yang sekarang."
  },
  AvgCommunicate_70503_Content_11 = {
    Text = "Apa? Pemimpin Gereja Lentera?!!"
  },
  AvgCommunicate_70503_Content_12 = {
    Text = "Di dunia keagamaan, Gereja Lentera adalah musuh terbesar gerejamu…… Bagaimana mungkin muridmu……"
  },
  AvgCommunicate_70503_Content_13 = {
    Text = "Sebuah kisah yang panjang, Utusan."
  },
  AvgCommunicate_70503_Content_14 = {
    Text = "Dia pernah bersamaku menjalankan kehendak Sang Bapa, mengabdikan segala yang kami miliki untuk umat Sang Bapa."
  },
  AvgCommunicate_70503_Content_15 = {
    Text = "Namun, seperti yang kau lihat, mereka yang tersesat dan menolak Sang Bapa, tidaklah mudah untuk diubah. Kekerasan dan prasangka itu, bukanlah sesuatu yang bisa dihapus hanya dengan beberapa berkat."
  },
  AvgCommunicate_70503_Content_16 = {
    Text = "Karena malapetaka yang kualami, dia melangkah ke jalan sesat yang sulit untuk kembali."
  },
  AvgCommunicate_70503_Content_17 = {
    Text = "Jadi begitu……"
  },
  AvgCommunicate_70503_Content_18 = {
    Text = "Aku mengerti. Sama seperti yang terjadi di gereja sebelumnya, orang-orang yang tidak berubah karena kebaikan kalian, menyebabkan perubahan pada dirinya……"
  },
  AvgCommunicate_70503_Content_19 = {
    Text = "Bapa pernah mengajarkan kepada kami, urusan duniawi tidaklah hitam putih. Kebaikan, terkadang juga bisa menjadi sebuah kesalahan."
  },
  AvgCommunicate_70503_Content_2 = {
    Text = "Aku mewakili gereja, mewakili para korban selamat yang tak bersalah, menyampaikan rasa terima kasih yang tulus kepadamu, Utusan Pucat."
  },
  AvgCommunicate_70503_Content_20 = {
    Text = "Aku telah mendedikasikan segalanya untuk mereka yang menderita, tapi aku lupa, muridku juga termasuk salah satu dari mereka yang menderita."
  },
  AvgCommunicate_70503_Content_21 = {
    Text = "Gereja dan keyakinanku, mungkin telah menyelamatkan banyak orang, tapi tidak bisa menyelamatkan dia."
  },
  AvgCommunicate_70503_Content_22 = {
    Text = "Aku bukanlah guru yang layak, Utusan."
  },
  AvgCommunicate_70503_Content_23 = {
    Text = "Aku akan tetap menjalani jalan Bapa. Tapi aku tidak tahu, apakah aku masih memiliki kesempatan untuk menebus penyesalanku terhadap murid ini……"
  },
  AvgCommunicate_70503_Content_3 = {
    Text = "Tidak perlu berterima kasih, Uskup Salvado, ini semua sudah menjadi kewajibanku."
  },
  AvgCommunicate_70503_Content_4 = {
    Text = "Uskup, mengenai masa lalumu, ada sebuah pertanyaan yang ingin kutanyakan……"
  },
  AvgCommunicate_70503_Content_5 = {
    Text = "Aku akan menjawab semua yang kutahu, Utusan."
  },
  AvgCommunicate_70503_Content_6 = {
    Text = "Masa laluku, akan terbuka bagi setiap orang yang berada dalam lindungan Sang Bapa."
  },
  AvgCommunicate_70503_Content_7 = {
    Text = "Saat terhubung denganmu, selain Sophia, aku melihat seorang wanita yang berbincang denganmu."
  },
  AvgCommunicate_70503_Content_8 = {
    Text = "Ingatan itu memiliki porsi yang sangat besar dalam jiwamu…… Kalian tampaknya sangat akrab?"
  },
  AvgCommunicate_70503_Content_9 = {
    Text = "Memang, sangat akrab. Dulu, dia adalah muridku yang paling berbakat."
  },
  AvgCommunicate_70503_Option_11 = {
    Text = "Pemimpin Gereja Lentera?!"
  },
  AvgCommunicate_70503_Option_17 = {
    Text = "Jadi begitu……"
  },
  AvgCommunicate_70503_Option_3 = {
    Text = "Itu sudah menjadi kewajibanku"
  },
  AvgCommunicate_70503_Option_7 = {
    Text = "Siapa wanita yang terakhir muncul dalam ingatanmu?"
  },
  AvgCommunicate_70504_Content_1 = {
    Text = "Apakah tidur semalam cukup nyenyak, tamu yang terhormat?"
  },
  AvgCommunicate_70504_Content_10 = {
    Text = "Tenang saja, aku telah mencapai kesepakatan dengan seorang tuan tertentu, dan tidak akan melakukan hal-hal yang melampaui batas."
  },
  AvgCommunicate_70504_Content_11 = {
    Text = "Bagi seorang pedagang, kepercayaan itu sangat penting."
  },
  AvgCommunicate_70504_Content_12 = {
    Text = "Lagipula, rahasiamu tidak lebih sedikit dariku. Bukankah begitu?"
  },
  AvgCommunicate_70504_Content_13 = {
    Text = "Rahasiaku? Apa maksudmu?"
  },
  AvgCommunicate_70504_Content_14 = {
    Text = "Sekarang belum waktunya. Tapi tenang saja, transaksi mengenai rahasia baru akan segera dimulai."
  },
  AvgCommunicate_70504_Content_15 = {
    Text = "Badai salju di perjalanan lebih ganas dari yang kau bayangkan."
  },
  AvgCommunicate_70504_Content_16 = {
    Text = "Selagi ada waktu, nikmatilah kehangatan perapian ini, Nak."
  },
  AvgCommunicate_70504_Content_2 = {
    Text = "Toko kecil yang hangat seperti ini sangat langka di tengah badai salju. Terima kasih banyak atas kebaikanmu menampung kami, Nyonya Daphodel."
  },
  AvgCommunicate_70504_Content_3 = {
    Text = "Namun, tokomu tampaknya menyimpan banyak rahasia."
  },
  AvgCommunicate_70504_Content_4 = {
    Text = "Koleksi-koleksi itu, sepertinya tidak sesederhana yang terlihat."
  },
  AvgCommunicate_70504_Content_5 = {
    Text = "Pengamatan yang tajam. Tapi, sembarangan mengorek rahasia orang lain bukanlah perilaku seorang pria terhormat, lho."
  },
  AvgCommunicate_70504_Content_6 = {
    Text = "Maafkan aku, Nyonya Daphodel."
  },
  AvgCommunicate_70504_Content_7 = {
    Text = "Kami datang ke tempat asing ini untuk melakukan penyelidikan, dan yang pertama harus kami pastikan adalah keselamatan kami sendiri."
  },
  AvgCommunicate_70504_Content_8 = {
    Text = "Kuharap kau bisa memahaminya."
  },
  AvgCommunicate_70504_Content_9 = {
    Text = "Tentu saja. Jika seseorang bisa begitu mudah tertidur pulas di rumah orang asing, maka pendidikan Missage terhadap para Penjaga Rahasia jelas tidak memadai."
  },
  AvgCommunicate_70504_Option_13 = {Text = "Rahasiaku?"},
  AvgCommunicate_70504_Option_2 = {
    Text = "Tempat ini tampaknya menyimpan banyak rahasia"
  },
  AvgCommunicate_70504_Option_6 = {
    Text = "Maaf, tapi aku perlu memastikan keamanan misi"
  },
  AvgCommunicate_70505_Content_1 = {
    Text = "Miriam, adalah pendeta utama yang paling dipercaya oleh-Ku."
  },
  AvgCommunicate_70505_Content_10 = {
    Text = "Perihal para Pemeluk Laut, aku turut bertanggung jawab."
  },
  AvgCommunicate_70505_Content_11 = {
    Text = "Tak ada yang bisa menduga perkembangan situasi, ini tak seharusnya disebut dosa."
  },
  AvgCommunicate_70505_Content_12 = {
    Text = "Apa yang kaulakukan adalah pilihan paling tepat saat itu."
  },
  AvgCommunicate_70505_Content_13 = {
    Text = "Kesalahan bukan padamu, Tulu."
  },
  AvgCommunicate_70505_Content_14 = {
    Text = "Mungkin. Tapi kau telah menyelesaikan masalah ini dengan tanganmu sendiri."
  },
  AvgCommunicate_70505_Content_15 = {
    Text = "Tak ada yang bisa menduga perkembangan situasi."
  },
  AvgCommunicate_70505_Content_16 = {
    Text = "Sekalipun ada kesalahan, kau telah memperbaikinya."
  },
  AvgCommunicate_70505_Content_17 = {
    Text = "Kau telah menunaikan tanggung jawabmu sebagai Raja Lemuria, Tulu."
  },
  AvgCommunicate_70505_Content_19 = {
    Text = "Kata-kata penghiburannya agak canggung, tapi aku menerimanya."
  },
  AvgCommunicate_70505_Content_2 = {
    Text = "Aku dan dia, pernah membawa masa kemakmuran singkat bagi Lemuria."
  },
  AvgCommunicate_70505_Content_20 = {
    Text = "Aku akan beristirahat."
  },
  AvgCommunicate_70505_Content_21 = {
    Text = "Saat dibutuhkan, aku akan terbangun."
  },
  AvgCommunicate_70505_Content_22 = {
    Text = "Tanggung jawabku, selain di Lemuria, juga di Misag."
  },
  AvgCommunicate_70505_Content_3 = {
    Text = "Dia dan rakyat Lemuria sama-sama percaya, bahwa Aku akan mengembalikan kejayaan Kerajaan Dewa bagi Lemuria."
  },
  AvgCommunicate_70505_Content_4 = {
    Text = "Tapi... itu adalah kebohongan, bukan?"
  },
  AvgCommunicate_70505_Content_5 = {
    Text = "Dalam mimpi, aku mendapat wahyu."
  },
  AvgCommunicate_70505_Content_6 = {
    Text = "Akhir dari Lemuria, tak dapat dihindari."
  },
  AvgCommunicate_70505_Content_7 = {
    Text = "Dari awal hingga akhir, Lemuria hidup dalam kebohongan."
  },
  AvgCommunicate_70505_Content_8 = {
    Text = "Aku menggunakan kebohongan untuk mengakhiri hubungan antara Lemuria dan Miriam."
  },
  AvgCommunicate_70505_Content_9 = {
    Text = "Hanya saja tak pernah kusangka, kebohongan itu akan menimbulkan situasi seperti ini setelah sekian tahun."
  },
  AvgCommunicate_70505_Option_11 = {
    Text = "Tak ada yang bisa menduganya, ini tak seharusnya disebut dosa"
  },
  AvgCommunicate_70505_Option_14 = {
    Text = "Masalahnya sudah kauselesaikan dengan tanganmu sendiri"
  },
  AvgCommunicate_70505_Option_4 = {
    Text = "Tapi... itu adalah kebohongan, bukan?"
  },
  AvgCommunicate_70506_Content_1 = {
    Text = "Talimu tidak diikat dengan kencang."
  },
  AvgCommunicate_70506_Content_10 = {
    Text = "Lagipula, membunuh hanyalah cara, bukan tujuan."
  },
  AvgCommunicate_70506_Content_11 = {
    Text = "Lebih baik pikirkan urusanmu sendiri."
  },
  AvgCommunicate_70506_Content_12 = {
    Text = "Apa yang ingin kulakukan, bukan urusanmu."
  },
  AvgCommunicate_70506_Content_13 = {
    Text = "Kau punya kartu as di tanganmu."
  },
  AvgCommunicate_70506_Content_14 = {
    Text = "Si cebol itu... dia pasti bisa membuat Miriam gila, ha."
  },
  AvgCommunicate_70506_Content_15 = {
    Text = "Manfaatkanlah dengan baik, Penjaga Rahasia Misage."
  },
  AvgCommunicate_70506_Content_16 = {
    Text = "Sampai sejauh mana kalian bisa memojokkan Pendeta Agung yang kumuliakan itu, aku sangat menantikannya."
  },
  AvgCommunicate_70506_Content_2 = {
    Text = "Berhati-hatilah sendiri, jangan sampai ketahuan."
  },
  AvgCommunicate_70506_Content_3 = {
    Text = "Kau masih berguna bagiku sekarang, aku tidak ingin kau mati terlalu cepat."
  },
  AvgCommunicate_70506_Content_4 = {
    Text = "Kau ingin menyelamatkan Murphy?"
  },
  AvgCommunicate_70506_Content_5 = {
    Text = "Apa aku terlihat seperti orang yang berhati baik?"
  },
  AvgCommunicate_70506_Content_6 = {
    Text = "Lebih baik pikirkan urusanmu sendiri."
