  },
  AvgCommunicate_70509_Content_18 = {
    Text = "Pejuang tidak pernah mengingkari janjinya. Kau adalah pejuang sejati, Shilo!"
  },
  AvgCommunicate_70509_Content_19 = {
    Text = "Aku akan segera kembali. Tolong siapkan Rotan, Penjaga Rahasia."
