  },
  AvgCommunicate_70510_Content_23 = {
    Text = "Dalam arti tertentu, bisa dianggap sebagai semacam keyakinan jahat."
  },
  AvgCommunicate_70510_Content_24 = {
    Text = "Teori evolusi mekanis yang dibicarakan kepribadian itu, memang agak ekstrem dan sepihak."
  },
  AvgCommunicate_70510_Content_25 = {
    Text = "Tapi dalam arti tertentu, itu memang merupakan sebuah pemikiran yang bisa melawan Erosi."
  },
  AvgCommunicate_70510_Content_26 = {
    Text = "Namun hal itu juga akan melibatkan banyak masalah teknis dan etika..."
