  },
  AvgCommunicate_70510_Content_4 = {
    Text = "Tapi, bukan eksperimen kecil yang tidak penting itu."
  },
  AvgCommunicate_70510_Content_5 = {
    Text = "Melainkan penemuan besar yang benar-benar bisa mengubah situasi kita."
  },
  AvgCommunicate_70510_Content_6 = {
    Text = "Kalian selalu melawan Substansi Hitam, tapi sebenarnya, solusinya sudah ada di depan mata kalian sejak lama."
