  },
  AvgCommunicate_70511_Content_12 = {
    Text = "Baiklah, baiklah... Ini salahku, seharusnya aku tidak menggodamu seperti itu."
  },
  AvgCommunicate_70511_Content_13 = {
    Text = "Aku tahu, kau adalah seorang ksatria yang setia. Apa pun bahaya yang dihadapi, kau akan tetap memegang teguh sumpahmu."
  },
  AvgCommunicate_70511_Content_14 = {
    Text = "Pengalaman dalam mimpi kali ini membuatku semakin mengenalmu."
  },
  AvgCommunicate_70511_Content_15 = {
    Text = "Terima kasih... Terima kasih, Tuanku..."
  },
  AvgCommunicate_70511_Content_16 = {
    Text = "Sekarang aku berlatih setiap hari. Aku akan menjadi ksatria yang layak dan mampu melindungi Tuanku. Apa yang pernah terjadi, aku tidak akan membiarkannya terulang lagi!"
  },
  AvgCommunicate_70511_Content_17 = {
    Text = "Jadi, Tuanku... Aku benar-benar tidak boleh berlatih berkuda di sekolah ya..."
