  AvgCommunicate_70511_Content_18 = {
    Text = "Tidak boleh!"
  },
  AvgCommunicate_70511_Content_19 = {
    Text = "Tapi, ada arena berkuda baru di distrik barat... Akhir pekan ini, mau kuajak ke sana untuk mencobanya?"
  },
  AvgCommunicate_70511_Content_2 = {
