  },
  AvgCommunicate_70511_Content_5 = {
    Text = "Benar, Tuan!"
  },
  AvgCommunicate_70511_Content_6 = {
    Text = "Aku ingin tahu, apa sebenarnya yang Anda lihat di dalam mimpi itu?"
  },
  AvgCommunicate_70511_Content_7 = {
    Text = "Aku melihat sebuah bencana, seorang putri yang baik hati, dan seorang ksatria kecil yang berani dan teguh."
