  AvgCommunicate_70512_Content_1 = {
    Text = "Sejak berpisah di Lemvashi, sudah lama tidak bertemu, Keeper {Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70512_Content_10 = {
    Text = "Kehancuran dan kebusukan dunia ini tentu saja tidak akan dipahami oleh kalian yang hidup dalam kemewahan."
  },
  AvgCommunicate_70512_Content_11 = {
    Text = "Kehendak tertinggi, Sang Pencipta yang pertama, akan membawa pemurnian akhir bagi dunia."
  },
  AvgCommunicate_70512_Content_12 = {
    Text = "Aku tidak bermaksud memusuhi Missage, tapi Missage menghalangi jalan datangnya dunia baru."
  },
  AvgCommunicate_70512_Content_13 = {
    Text = "Tenang saja, Penjaga Rahasia {Male=tuan,Female=nyonya}, Tuanku tidak akan meninggalkan kalian karena hal ini."
  },
  AvgCommunicate_70512_Content_14 = {
    Text = "Kalian juga akan menjadi bagian dari dunia baru."
  },
  AvgCommunicate_70512_Content_15 = {
    Text = "Beliau akan membuat kalian melihat masa depan yang baru itu."
  },
  AvgCommunicate_70512_Content_16 = {
    Text = "Saat itu tiba, Beliau akan mendengarkan pengakuan tulus kalian."
  },
  AvgCommunicate_70512_Content_17 = {
    Text = "Kau juga tenang saja, Juliette."
  },
  AvgCommunicate_70512_Content_18 = {
    Text = "Tuanmu tidak akan punya kesempatan untuk datang."
  },
  AvgCommunicate_70512_Content_19 = {
    Text = "Aku akan menghentikanmu. Pasti!"
  },
  AvgCommunicate_70512_Content_2 = {
    Text = "Juliette... kau menerobos masuk ke Misage, sebenarnya apa yang ingin kau lakukan?!"
  },
  AvgCommunicate_70512_Content_3 = {
    Text = "Di Lemvashi, aku pernah memberitahumu."
  },
  AvgCommunicate_70512_Content_4 = {
    Text = "Dewa kami akan menciptakan masa depan yang lebih indah bagi dunia."
  },
  AvgCommunicate_70512_Content_5 = {
    Text = "Masih ingat, Keeper?"
  },
  AvgCommunicate_70512_Content_6 = {
    Text = "Informasi sepenting ini, tentu saja aku tidak akan lupa."
  },
  AvgCommunicate_70512_Content_7 = {
    Text = "Apa hubungannya dengan Misage?"
  },
  AvgCommunicate_70512_Content_8 = {
    Text = "Aku tidak mengingat retorika musuh yang meracuni pikiran orang."
  },
  AvgCommunicate_70512_Content_9 = {
    Text = "Aku sudah banyak melihat orang-orang keras kepala yang tak bisa diselamatkan, jadi aku tidak terkejut."
  },
  AvgCommunicate_70512_Option_17 = {
    Text = "Aku akan menghentikanmu"
  },
  AvgCommunicate_70512_Option_2 = {
