  },
  AvgCommunicate_70512_Option_6 = {Text = "Aku ingat"},
  AvgCommunicate_70512_Option_8 = {
    Text = "Aku tidak mengingat bujuk rayu musuh"
  },
  AvgCommunicate_70513_Content_1 = {
    Text = "Mengenai suara seruling yang kau dengar saat pingsan sebelumnya, aku sudah menyelidikinya."
  },
  AvgCommunicate_70513_Content_10 = {
    Text = "Aku tidak tahu harus memuji optimismemu atau mengkritik ketidaktahuanmu."
  },
  AvgCommunicate_70513_Content_11 = {
    Text = "Hal yang secara khusus disebutkan oleh Tavy, biasanya adalah sebuah malapetaka."
  },
  AvgCommunicate_70513_Content_12 = {
    Text = "Yang paling buruk dari semuanya."
  },
  AvgCommunicate_70513_Content_13 = {
    Text = "Toh sudah terjadi... anggap saja sebagai penghiburan diri."
  },
  AvgCommunicate_70513_Content_14 = {
    Text = "Bagaimanapun, aku akan terus menyelidiki hal ini."
