  },
  AvgCommunicate_70513_Content_4 = {
    Text = "Apakah itu hanya khayalanku?"
  },
  AvgCommunicate_70513_Content_5 = {
    Text = "Bisa dipastikan, bukan."
  },
  AvgCommunicate_70513_Content_6 = {
    Text = "Aku sudah berkonsultasi dengan Profesor Alistair."
  },
  AvgCommunicate_70513_Content_7 = {
    Text = "Meskipun saat ini belum ada catatan apa pun mengenai suara seruling semacam itu, Tavy pernah menyebutkan soal suara seruling itu kepadanya."
  },
