  },
  AvgCommunicate_70514_Content_10 = {
    Text = "Di bawah perlindungannya, aku bisa berkelana tanpa beban di dunia bunga dan puisi."
  },
  AvgCommunicate_70514_Content_11 = {
    Text = "Baik perlindungan maupun luka itu, sekarang semuanya sudah berlalu..."
  },
  AvgCommunicate_70514_Content_12 = {
    Text = "Penjaga Rahasia, terima kasih sudah membawaku ke Cité kali ini... Perjalanan ini sangat berarti bagiku."
  },
  AvgCommunicate_70514_Content_13 = {
    Text = "Benar. Masa lalumu dengan Colette, sekarang sudah berlalu."
  },
  AvgCommunicate_70514_Content_14 = {
    Text = "Tataplah ke depan, Orla."
  },
  AvgCommunicate_70514_Content_15 = {
    Text = "Ya! Penjaga Rahasia{Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70514_Content_16 = {
    Text = "Antologi puisi ini adalah perpisahanku dengan masa lalu."
  },
  AvgCommunicate_70514_Content_17 = {
    Text = "Aku akan mengingat Colette kecil. Aku akan mengingat Colette yang tua. Dan aku juga akan merelakan mereka..."
  },
  AvgCommunicate_70514_Content_18 = {
    Text = "Masih ada kehidupan baru, puisi baru, yang menantiku."
  },
  AvgCommunicate_70514_Content_2 = {
    Text = "Mereka mengucapkan selamat kepadaku, kumpulan puisi kali ini meraih hasil yang sangat baik."
  },
  AvgCommunicate_70514_Content_3 = {
    Text = "Selamat, Orlya!"
  },
  AvgCommunicate_70514_Content_4 = {
    Text = "Terima kasih, Penjaga Rahasia."
  },
  AvgCommunicate_70514_Content_5 = {
    Text = "Dulu, semua hal ini diurus oleh Colette."
  },
  AvgCommunicate_70514_Content_6 = {
    Text = "Selama ini, dialah yang menanggung bagian ini."
  },
  AvgCommunicate_70514_Content_7 = {
    Text = "Seingat saya, ini pertama kalinya aku melihatmu peduli soal penjualan."
  },
  AvgCommunicate_70514_Content_8 = {
    Text = "Karena, penulis antologi puisi ini adalah Orla Colette..."
  },
  AvgCommunicate_70514_Content_9 = {
    Text = "Colette akan peduli. Selama ini, dialah yang menanggung bagian itu."
  },
  AvgCommunicate_70514_Option_13 = {
    Text = "Tataplah ke depan."
  },
  AvgCommunicate_70514_Option_3 = {Text = "Selamat!"},
  AvgCommunicate_70514_Option_7 = {
    Text = "Pertama kalinya aku melihatmu peduli soal penjualan"
  },
  AvgCommunicate_70515_Content_1 = {
    Text = "Baru saja kembali untuk melihat sekitar museum lilin... Benar-benar berantakan."
  },
  AvgCommunicate_70515_Content_10 = {
    Text = "Demi menghindari anjing-anjing gila dari Dewan Audit, sudah lama aku tidak memainkan permainanku..."
  },
  AvgCommunicate_70515_Content_11 = {
    Text = "Kamu bisa mempertimbangkan untuk menyerahkan diri bersama Rogers ke Misagar."
  },
  AvgCommunicate_70515_Content_12 = {
    Text = "Kamu seharusnya tahu apa yang terjadi jika tertangkap oleh Dewan Audit."
  },
  AvgCommunicate_70515_Content_13 = {
    Text = "Mulutmu benar-benar pandai membujuk, sayang."
  },
  AvgCommunicate_70515_Content_14 = {
    Text = "Tapi, bermain dengan kalian di museum lilin sangat menyenangkan."
  },
  AvgCommunicate_70515_Content_15 = {
    Text = "Mungkin aku benar-benar akan mempertimbangkannya."
  },
  AvgCommunicate_70515_Content_16 = {
    Text = "Mungkin akan ada hari di mana kita bertemu lagi. Nantikanlah, Penjaga Rahasia {Male=tuan,Female=nyonya}~"
  },
  AvgCommunicate_70515_Content_2 = {
    Text = "Kalian benar-benar tidak tahu cara menghargai!"
  },
  AvgCommunicate_70515_Content_3 = {Text = "Pandiya?"},
  AvgCommunicate_70515_Content_4 = {
    Text = "Kamu dan Rogers pergi ke mana?"
  },
  AvgCommunicate_70515_Content_5 = {
    Text = "Kenapa, rindu dengan cambukku?"
  },
  AvgCommunicate_70515_Content_6 = {
    Text = "Kalian telah melakukan begitu banyak kejahatan, aku hanya ingin menangkap kalian."
  },
  AvgCommunicate_70515_Content_7 = {
    Text = "Orang-orang yang tewas karena museum lilin harus mendapatkan keadilan."
  },
  AvgCommunicate_70515_Content_8 = {
    Text = "Aduh, itu semua karya Tuan Rogers, aku tidak punya bakat seni seperti itu."
  },
  AvgCommunicate_70515_Content_9 = {
    Text = "Sayang sekali, tangan Tuan Rogers yang lahir untuk seni sudah tidak ada lagi."
  },
  AvgCommunicate_70515_Option_11 = {
    Text = "Mungkin kamu bisa memilih datang ke Misagar."
  },
  AvgCommunicate_70515_Option_3 = {Text = "Pandiya?"},
  AvgCommunicate_70515_Option_6 = {
    Text = "Rindu. Rindu menangkap kalian."
  },
  AvgCommunicate_70516_Content_1 = {
    Text = "%player%......"
  },
  AvgCommunicate_70516_Content_10 = {
    Text = "Pastikan kau menjaga dirimu baik-baik, Ramona!"
  },
  AvgCommunicate_70516_Content_11 = {
    Text = "Sekurang percaya itu pada partnermu?"
  },
  AvgCommunicate_70516_Content_12 = {
    Text = "Tenang saja, setelah aku menyelesaikan urusan di sini, aku akan segera bergabung denganmu."
  },
  AvgCommunicate_70516_Content_13 = {
    Text = "Situasimu sekarang yang paling berbahaya, berhati-hatilah, %player%……"
  },
  AvgCommunicate_70516_Content_2 = {
    Text = "Ramona?! Kamu baik-baik saja?"
  },
  AvgCommunicate_70516_Content_3 = {
    Text = "Mm, aku tidak apa-apa."
  },
  AvgCommunicate_70516_Content_4 = {
    Text = "Baru saja bertemu beberapa orang dari Dewan Inspeksi, sudah kuurus semuanya."
  },
  AvgCommunicate_70516_Content_5 = {
    Text = "Aku ingin ke sana untuk bergabung denganmu, tapi aku melihat serombongan orang Dewan Inspeksi menuju gedung pengajaran……"
  },
  AvgCommunicate_70516_Content_6 = {
    Text = "Banyak guru dan murid sedang mengikuti kelas di sana, aku khawatir orang-orang Dewan Inspeksi akan menyakiti mereka."
  },
  AvgCommunicate_70516_Content_7 = {
    Text = "Aku harus mengawal mereka ke tempat yang aman."
  },
  AvgCommunicate_70516_Content_8 = {
    Text = "Aku baru saja bertarung dengan Clementine, urusan di sini biar aku yang tangani."
  },
  AvgCommunicate_70516_Content_9 = {
    Text = "Gedung pengajaran kuserahkan padamu."
  },
  AvgCommunicate_70516_Option_2 = {
    Text = "Ramona?! Kamu baik-baik saja?"
  },
  AvgCommunicate_70516_Option_8 = {
    Text = "Jaga dirimu baik-baik, Ramona!"
  },
  AvgCommunicate_70517_Content_1 = {
    Text = "Sepi. Kuno. Sama sekali tanpa gairah yang seharusnya dimiliki kehidupan..."
  },
  AvgCommunicate_70517_Content_10 = {
    Text = "Kau ini, sama seperti dulu, masih saja begitu peduli pada aturan."
  },
  AvgCommunicate_70517_Content_11 = {
    Text = "Tidak apa-apa, aula sekolah sudah kusewa."
  },
  AvgCommunicate_70517_Content_12 = {
    Text = "Menyewa aula? Untuk apa?"
  },
  AvgCommunicate_70517_Content_13 = {
    Text = "Karena komite sekolah Misage tidak mengizinkanku membelinya."
  },
  AvgCommunicate_70517_Content_14 = {
    Text = "Sepertinya kau salah memahami pertanyaanku..."
  },
  AvgCommunicate_70517_Content_15 = {
    Text = "Tidak penting. Besok malam, aku akan mengadakan pesta di aula."
  },
  AvgCommunicate_70517_Content_16 = {
    Text = "Sebuah pesta yang meriah, unik, penuh gairah kehidupan yang semestinya, pesta sesungguhnya seperti di kastil kuno."
  },
  AvgCommunicate_70517_Content_17 = {
    Text = "Properti yang perlu disiapkan sudah sepenuhnya siap."
  },
  AvgCommunicate_70517_Content_18 = {
    Text = "Hambatan dari aturan juga sudah kuantisipasi terlebih dahulu. Tidak akan ada yang datang mengganggu kita."
  },
  AvgCommunicate_70517_Content_19 = {
    Text = "Jalan menuju aula, kau bisa menemukannya, bukan, Penjaga Rahasia?"
  },
  AvgCommunicate_70517_Content_2 = {
    Text = "Apa yang kamu bicarakan..."
  },
  AvgCommunicate_70517_Content_3 = {
    Text = "Maksudku, kita sudah lama sekali tidak mengadakan pesta."
  },
  AvgCommunicate_70517_Content_4 = {
    Text = "Bukankah akhir pekan lalu kita baru saja makan bersama di aula?"
  },
  AvgCommunicate_70517_Content_5 = {
    Text = "Sekelompok orang duduk bersama dengan pakaian rapi, menjaga jarak sosial yang sopan, berperilaku santun, setiap saat berusaha menyembunyikan pikiran-pikiran kotor di dalam hati mereka..."
  },
  AvgCommunicate_70517_Content_6 = {
    Text = "Kegiatan sosial yang melelahkan seperti itu tidak bisa disebut pesta."
  },
  AvgCommunicate_70517_Content_7 = {
    Text = "Pesta sesungguhnya di kastil kuno, kau sudah pernah menyaksikannya, bukan?"
  },
  AvgCommunicate_70517_Content_8 = {
    Text = "Nyonya Wanda, ini bagaimanapun juga Londinium, bukan kastilmu..."
  },
  AvgCommunicate_70517_Content_9 = {
    Text = "Beberapa aturan paling dasar, kita tetap harus mematuhinya..."
  },
  AvgCommunicate_70517_Option_12 = {
    Text = "Hm? Untuk apa?"
  },
  AvgCommunicate_70517_Option_14 = {
    Text = "Sepertinya kau salah memahami pertanyaanku..."
  },
  AvgCommunicate_70517_Option_2 = {
    Text = "Apa yang kamu bicarakan..."
  },
  AvgCommunicate_70517_Option_4 = {
    Text = "Bukankah akhir pekan lalu kita baru saja makan bersama di aula?"
  },
  AvgCommunicate_70517_Option_8 = {
    Text = "Ini bagaimanapun juga Londinium, bukan kastilmu..."
  },
  AvgCommunicate_70518_Content_1 = {
    Text = "Hei, ke mana Miriam pergi?"
  },
  AvgCommunicate_70518_Content_10 = {
    Text = "Orang yang ambisius……Aku suka sebutan itu."
  },
  AvgCommunicate_70518_Content_11 = {
    Text = "Tenang saja. Aku sudah menyesuaikan rencanaku."
  },
  AvgCommunicate_70518_Content_12 = {
    Text = "Kebangkitan bangsa Filistin, bukan hanya ada satu jalan yaitu merebut kekuasaan sang Pelintas Lautan."
  },
  AvgCommunicate_70518_Content_13 = {
    Text = "Saya mencarinya karena ingin membahas kerja sama selanjutnya dengannya."
  },
  AvgCommunicate_70518_Content_14 = {
    Text = "Sumber daya dan Kekuatan yang dimiliki oleh Mythag, baik baginya maupun untukku, memiliki manfaat yang sangat besar."
  },
  AvgCommunicate_70518_Content_15 = {
    Text = "Berbisik dengan keras di depanku tentang rencana jahat terhadap Mythag... sepertinya tidak baik, ya?"
  },
  AvgCommunicate_70518_Content_16 = {
    Text = "Itu adalah kerja sama. Lagipula, jika kekuatan Pelaut dan Perishite bisa dimanfaatkan, penyelidikan kalian juga akan berjalan lebih lancar, bukan?"
  },
  AvgCommunicate_70518_Content_17 = {
    Text = "Terdengar... sepertinya memang ada benarnya juga..."
  },
  AvgCommunicate_70518_Content_18 = {
    Text = "Bagus, sangat mengerti, Penjaga."
  },
  AvgCommunicate_70518_Content_19 = {
    Text = "Tenang, setelah semuanya selesai, bagianmu tidak akan berkurang sedikit pun."
  },
  AvgCommunicate_70518_Content_2 = {
    Text = "Goliath, apa yang mau kaulakukan?!"
  },
  AvgCommunicate_70518_Content_20 = {
    Text = "Bagaimanapun juga… dia adalah bocah kecil yang mengikuti saya di dalam Mimpi."
  },
  AvgCommunicate_70518_Content_21 = {
    Text = "Saya Goliath, tidak pernah menyia-nyiakan orang-orang di sekitarku."
  },
  AvgCommunicate_70518_Content_3 = {
    Text = "Aku tahu soal kau dan Miriam, tenanglah sedikit, sekarang bukan saatnya untuk bertindak gegabah!"
  },
  AvgCommunicate_70518_Content_5 = {
    Text = "Di matamu, aku ini cuma orang kasar yang hanya bisa berkelahi?"
  },
  AvgCommunicate_70518_Content_6 = {
    Text = "Memangnya masih ada kemungkinan lain?"
  },
  AvgCommunicate_70518_Content_7 = {
    Text = "Penjaga Rahasia Mizag, bahkan tidak punya kemampuan menilai sesederhana ini. Tempat ini benar-benar tidak punya harapan."
  },
  AvgCommunicate_70518_Content_8 = {
    Text = "Aku tahu, seorang yang ambisius bukanlah orang kasar."
  },
  AvgCommunicate_70518_Content_9 = {
    Text = "Tapi untuk berjaga-jaga, lebih baik bertanya dengan jelas."
  },
  AvgCommunicate_70518_Option_15 = {
    Text = "Berbisik dengan suara keras, sepertinya tidak terlalu baik, ya?"
  },
  AvgCommunicate_70518_Option_17 = {
    Text = "Terdengar cukup masuk akal..."
  },
  AvgCommunicate_70518_Option_2 = {
    Text = "Apa yang mau kaulakukan?!"
  },
  AvgCommunicate_70518_Option_6 = {
    Text = "Memangnya bukan?"
  },
  AvgCommunicate_70518_Option_8 = {
    Text = "Tentu saja bukan!"
  },
  AvgCommunicate_70519_Content_1 = {
    Text = "Arena tinju. Datang lihat."
  },
  AvgCommunicate_70519_Content_10 = {
    Text = "Arena tinju, ada sinar matahari, ada kue, ada rantai, ada darah dan pasir."
  },
  AvgCommunicate_70519_Content_11 = {Text = "Ada aku."},
  AvgCommunicate_70519_Content_2 = {
    Text = "Lagi-lagi... Aku tidak tahu kamu mau menghajar orang atau mau minum darah..."
  },
  AvgCommunicate_70519_Content_3 = {
    Text = "Di Lemvashi, belum puas berkelahi dengan pemandu itu ya?"
  },
  AvgCommunicate_70519_Content_4 = {Text = "?!"},
  AvgCommunicate_70519_Content_5 = {
    Text = "Ternyata, kamu..."
  },
  AvgCommunicate_70519_Content_6 = {Text = "Hah."},
  AvgCommunicate_70519_Content_7 = {
    Text = "Pertarungan itu, layak dikenang."
  },
  AvgCommunicate_70519_Content_8 = {
    Text = "Arena tinju, ayo!"
  },
  AvgCommunicate_70519_Content_9 = {
    Text = "Aku hanya ingin mengobrol denganmu tentang hal-hal yang pernah kamu alami dulu... Aku tidak bermaksud berkelahi denganmu!"
  },
  AvgCommunicate_70519_Option_2 = {
    Text = "Mulai lagi..."
  },
  AvgCommunicate_70519_Option_3 = {
    Text = "Belum puas berkelahi di Lemvashi ya?"
  },
  AvgCommunicate_70519_Option_9 = {
    Text = "Aku tidak bermaksud berkelahi denganmu!"
  },
  AvgCommunicate_70520_Content_1 = {Text = "Meong~"},
  AvgCommunicate_70520_Content_10 = {
    Text = "Badan makin gemuk belakangan ini, tidur juga makin buruk, semua gara-gara dia!"
  },
  AvgCommunicate_70520_Content_11 = {
    Text = "Lelucon Badut 24 cukup bagus, membawa banyak kesenangan bagi kami…"
  },
  AvgCommunicate_70520_Content_12 = {
    Text = "Cuma raja jokes murahan yang cari perhatian, apa bagusnya sih?"
  },
  AvgCommunicate_70520_Content_13 = {
    Text = "Kalau suka nonton badut, lebih baik pergi ke sirkus saja. Atau bercermin juga bisa."
  },
  AvgCommunicate_70520_Content_14 = {
    Text = "Kucing 24 sangat menggemaskan!"
  },
  AvgCommunicate_70520_Content_15 = {
    Text = "Hah, makhluk yang bahkan tidak bisa bicara bahasa manusia, apa bagusnya sih?"
  },
  AvgCommunicate_70520_Content_16 = {
    Text = "Apa karena butuh peliharaan untuk mengisi hidupmu yang kosong dan membosankan?"
  },
  AvgCommunicate_70520_Content_17 = {
    Text = "Aku tahu, kamu pasti bernama 24 si lidah tajam."
  },
  AvgCommunicate_70520_Content_18 = {
    Text = "24 yang cerewet macam apa! Aku adalah"
  },
  AvgCommunicate_70520_Content_2 = {
    Text = "24, kepribadianmu beralih lagi…"
  },
  AvgCommunicate_70520_Content_20 = {
    Text = "Ma... maaf, Penjaga Rahasia!"
  },
  AvgCommunicate_70520_Content_21 = {
    Text = "Belakangan ini pergi ke jalanan bersama Jenkin, terlalu banyak mendengar orang-orang bertengkar, kepribadian baru yang terbentuk jadi tidak sopan begini……"
  },
  AvgCommunicate_70520_Content_22 = {
    Text = "Tenang saja, Penjaga Rahasia! Aku pasti akan mendidik kepribadian ini secepatnya!"
  },
  AvgCommunicate_70520_Content_23 = {
    Text = "Semangat……"
  },
  AvgCommunicate_70520_Content_3 = {
    Text = "Jadi, sekarang saya sedang berbicara dengan 24 yang mana?"
  },
  AvgCommunicate_70520_Content_4 = {
    Text = "Itu tidak perlu kamu urus."
  },
  AvgCommunicate_70520_Content_5 = {
    Text = "Sekarang, beritahu aku, kepribadian mana yang paling kamu sukai?"
  },
  AvgCommunicate_70520_Content_6 = {
    Text = "Eh, biarkan aku berpikir sejenak…"
  },
  AvgCommunicate_70520_Content_7 = {
    Text = "Hmm, scholar 24, terlihat sangat cerdas, dan dua kumis itu juga menarik..."
  },
  AvgCommunicate_70520_Content_8 = {
    Text = "Hmph. Orang yang hanya tahu membaca buku sepanjang hari."
  },
  AvgCommunicate_70520_Content_9 = {
    Text = "Tidak mau keluar rumah, tidak mau olahraga, kerjaannya cuma memikirkan hal-hal yang tidak jelas."
  },
  AvgCommunicate_70520_Option_11 = {Text = "Badut 24"},
  AvgCommunicate_70520_Option_14 = {Text = "Kucing 24"},
  AvgCommunicate_70520_Option_17 = {
    Text = "Aku tahu, kamu adalah 24 si lidah tajam."
  },
  AvgCommunicate_70520_Option_23 = {
    Text = "Semangat……"
  },
  AvgCommunicate_70520_Option_7 = {Text = "Sarjana 24"},
  AvgCommunicate_70521_Content_1 = {
    Text = "Terima kasih, Tuan..."
  },
  AvgCommunicate_70521_Content_10 = {
    Text = "Film yang sudah jadi, mau nonton bareng?"
  },
  AvgCommunicate_70521_Content_11 = {Text = "Benarkah?!"},
  AvgCommunicate_70521_Content_12 = {
    Text = "Terima kasih, Tuan!"
  },
  AvgCommunicate_70521_Content_2 = {
    Text = "Hm? Ada apa?"
  },
  AvgCommunicate_70521_Content_3 = {
    Text = "Cerita yang difilmkan itu, Lily sudah mengerti..."
  },
  AvgCommunicate_70521_Content_4 = {
    Text = "Lily tahu, itu sengaja dibuat untuk Lily tonton..."
  },
  AvgCommunicate_70521_Content_5 = {
    Text = "Kalau begitu, Lily suka?"
  },
  AvgCommunicate_70521_Content_6 = {Text = "Ya!"},
  AvgCommunicate_70521_Content_7 = {
    Text = "Lily suka akhir ceritanya."
  },
  AvgCommunicate_70521_Content_8 = {
    Text = "\"Sejak saat itu, gadis itu hidup bahagia bersama ibunya\"..."
  },
  AvgCommunicate_70521_Content_9 = {
    Text = "Kata Nyonya Daffodil, filmnya sudah selesai diproses."
  },
  AvgCommunicate_70521_Option_2 = {
    Text = "Hm? Ada apa?"
  },
  AvgCommunicate_70521_Option_5 = {
    Text = "Kalau begitu, Lily suka?"
  },
  AvgCommunicate_70521_Option_9 = {
    Text = "Film jadinya sudah selesai, mau nonton bareng?"
  },
  AvgCommunicate_70522_Content_1 = {
    Text = "Beberapa akuisisi tanah di kota Londinium berjalan dengan lancar, dan kontrak-kontrak yang merepotkan itu juga sudah diselesaikan."
  },
  AvgCommunicate_70522_Content_10 = {
    Text = "Kenapa, Penjaga Rahasia Misage, jangan-jangan kau orang yang tidak menepati janji?"
  },
  AvgCommunicate_70522_Content_11 = {
    Text = "Tentu saja tidak! Hanya saja……"
  },
  AvgCommunicate_70522_Content_12 = {
    Text = "Heh... Dasar orang yang kekanakan. Meskipun aku tidak bisa melihatnya, tapi aku yakin, saat kamu memikirkan cara berbohong, wajahmu pasti sudah memerah sampai ke leher, kan?"
  },
  AvgCommunicate_70522_Content_13 = {
    Text = "Begini saja. Barang yang sudah kujanjikan untuk Misage perlu kamu yang menyerahkannya. Alasan ini cukup, kan?"
  },
  AvgCommunicate_70522_Content_14 = {Text = "Tapi..."},
  AvgCommunicate_70522_Content_15 = {
    Text = "Sudah, jangan tapi-tapian lagi, sudah diputuskan."
  },
  AvgCommunicate_70522_Content_16 = {
    Text = "Baiklah, aku setuju... Suatu kehormatan bagi saya, Nyonya Soreil."
  },
  AvgCommunicate_70522_Content_17 = {
    Text = "Nah, begitu dong."
  },
  AvgCommunicate_70522_Content_18 = {
    Text = "Di antara kita, tidak perlu lagi ada basa-basi dan saling menguji."
  },
  AvgCommunicate_70522_Content_19 = {
    Text = "Malam ini pukul delapan, di ruang bawah tanah anggur di mansionku. Tidak akan ada yang menghalangimu."
  },
  AvgCommunicate_70522_Content_2 = {
    Text = "Semua ini berkat bantuanmu, Penjaga Rahasia."
  },
  AvgCommunicate_70522_Content_20 = {
    Text = "Aku menunggumu, ksatria kecilku."
  },
  AvgCommunicate_70522_Content_3 = {
    Text = "Salon bisnis yang melelahkan itu akhirnya akan segera berakhir."
  },
  AvgCommunicate_70522_Content_4 = {
    Text = "Selagi ada waktu luang, mau datang minum segelas denganku?"
  },
  AvgCommunicate_70522_Content_5 = {
    Text = "Siswa Misage dilarang minum alkohol……"
  },
  AvgCommunicate_70522_Content_6 = {
    Text = "Benarkah? Profesor Dexter tidak mengatakan hal itu padaku."
  },
  AvgCommunicate_70522_Content_7 = {
    Text = "Siapa yang membuat aturan ini, sudah saatnya diubah."
  },
  AvgCommunicate_70522_Content_8 = {
    Text = "Ah, ini……"
  },
  AvgCommunicate_70522_Content_9 = {
    Text = "Kau masih berutang segelas padaku. Ingat?"
  },
  AvgCommunicate_70522_Option_11 = {
    Text = "Tentu saja tidak! Hanya saja……"
  },
  AvgCommunicate_70522_Option_16 = {
    Text = "Suatu kehormatan bagi saya, Nyonya Soreil."
  },
  AvgCommunicate_70522_Option_5 = {
    Text = "Siswa Misage dilarang minum alkohol……"
  },
  AvgCommunicate_70523_Content_1 = {
    Text = "Perjalanan tadi terburu-buru, belum sempat memperkenalkan adat istiadat dan budaya setempat kepada kalian semua."
  },
  AvgCommunicate_70523_Content_10 = {
    Text = "Seperti yang telah kukatakan sebelumnya, aku hanyalah seorang utusan yang menyebarkan ajaran Tuhan kami."
  },
  AvgCommunicate_70523_Content_11 = {
    Text = "Dewa kami akan menciptakan masa depan yang lebih indah bagi dunia."
  },
  AvgCommunicate_70523_Content_12 = {
    Text = "Suku primitif seperti Yalan juga merupakan bagian dari masa depan itu, mereka adalah sahabat kami yang paling setia."
  },
  AvgCommunicate_70523_Content_13 = {
    Text = "Tentu saja, aku juga memahami kekhawatiran Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70523_Content_14 = {
    Text = "Aku yakin setelah menghabiskan waktu bersama lebih lama, kekhawatiran itu akan hilang dengan sendirinya."
  },
  AvgCommunicate_70523_Content_15 = {
    Text = "Kalian semua telah menempuh perjalanan panjang, silakan beristirahat dengan baik."
  },
  AvgCommunicate_70523_Content_16 = {
    Text = "Atas nama Lemwahi, aku dengan tulus menyambut kedatanganmu, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70523_Content_2 = {
    Text = "Apakah Penjaga Rahasia {Male=tuan,Female=nyonya} punya pertanyaan yang perlu saya bantu jawab?"
  },
  AvgCommunicate_70523_Content_3 = {
    Text = "Aku agak penasaran dengan adat istiadat di sini."
  },
  AvgCommunicate_70523_Content_4 = {
    Text = "Meskipun orang Yalan turun-temurun hidup dari peternakan dan jauh dari masyarakat industri, tolong jangan menganggap mereka sebagai kelompok liar yang belum beradab."
  },
  AvgCommunicate_70523_Content_5 = {
    Text = "Di sini tidak ada banyak aturan kaku, silakan bergaul dengan mereka secara santai saja."
  },
  AvgCommunicate_70523_Content_6 = {
    Text = "Keramahan orang Yalan, saya yakin kalian semua akan segera merasakannya."
  },
  AvgCommunicate_70523_Content_7 = {
    Text = "Keberadaan seseorang seperti Utusan Yuliette di suku primitif seperti ini adalah hal yang cukup aneh, bukan?"
  },
  AvgCommunicate_70523_Content_8 = {
    Text = "Datang karena panggilan mimpi untuk membimbing Yalan, alasan itu terdengar agak dipaksakan."
  },
  AvgCommunicate_70523_Content_9 = {
    Text = "Penjaga Rahasia {Male=tuan,Female=nyonya} terlalu khawatir."
  },
  AvgCommunicate_70523_Option_3 = {
    Text = "Aku agak penasaran dengan adat istiadat di sini"
  },
  AvgCommunicate_70523_Option_7 = {
    Text = "Aku penasaran soal utusan Lierette"
  },
  AvgCommunicate_70524_Content_1 = {
    Text = "Ngomong-ngomong, sejak insiden museum lilin, kita sudah lama tidak bekerja sama lagi."
  },
  AvgCommunicate_70524_Content_10 = {
    Text = "Semoga kerja sama kali ini berjalan lancar."
  },
  AvgCommunicate_70524_Content_11 = {
    Text = "Dengan bantuan Senior William, pasti akan lancar!"
  },
  AvgCommunicate_70524_Content_2 = {
    Text = "Waktu urusan Stormtreader kemarin, Senior William juga banyak membantu!"
  },
  AvgCommunicate_70524_Content_3 = {
    Text = "……Cuma menyetir saja, itu tidak bisa dibilang membantu."
  },
  AvgCommunicate_70524_Content_4 = {
    Text = "Menempatkan dua kartu as dalam satu misi itu agak mubazir."
  },
  AvgCommunicate_70524_Content_6 = {
    Text = "Kamu juga tidak malu-malu ya mengatakannya."
  },
  AvgCommunicate_70524_Content_7 = {
    Text = "Di museum lilin, kamu pernah menyelamatkanku sekali. Budi itu akan kubalas."
  },
  AvgCommunicate_70524_Content_8 = {
    Text = "Dalam misi kali ini, kamu dan Ramona berada di garis depan, ada beberapa hal yang tidak mudah dilakukan."
  },
  AvgCommunicate_70524_Content_9 = {
    Text = "Penyelidikan dari balik layar biar aku yang menangani."
  },
  AvgCommunicate_70524_Option_11 = {Text = "Pasti!"},
  AvgCommunicate_70524_Option_2 = {
    Text = "Waktu urusan Stormtreader kemarin, Senior William juga banyak membantu"
  },
  AvgCommunicate_70524_Option_4 = {
    Text = "Menempatkan dua kartu as dalam satu misi itu agak mubazir"
  },
  AvgCommunicate_70525_Content_1 = {
    Text = "Dang dang dang!"
  },
  AvgCommunicate_70525_Content_10 = {
    Text = "Oh begitu. Kalau begitu juga boleh."
  },
  AvgCommunicate_70525_Content_11 = {
    Text = "Semoga kali ini kalian bisa lebih menghormati seni pertunjukan, jangan lagi membuat sesuatu seperti\"gadis itu hidup bahagia bersama ibunya selamanya\"atau semacamnya!"
  },
  AvgCommunicate_70525_Content_2 = {
    Text = "Bagaimana, Penjaga Rahasia, terkejut dengan penataan panggung Andy Johnson, kan!"
  },
  AvgCommunicate_70525_Content_3 = {
    Text = "Jadi sutradara besar benar-benar sudah ketagihan ya…"
  },
  AvgCommunicate_70525_Content_4 = {
    Text = "Tapi, panggung yang kamu tata memang sangat bagus."
  },
  AvgCommunicate_70525_Content_5 = {
    Text = "Pengaturan pertunjukannya juga dilakukan dengan baik."
  },
  AvgCommunicate_70525_Content_6 = {
    Text = "Kami sedang mempersiapkan karya berikutnya."
  },
  AvgCommunicate_70525_Content_7 = {
    Text = "Kalau begitu, untuk dekorasi panggung dan penyutradaraan karya berikutnya, sudah diputuskan itu kamu!"
  },
  AvgCommunicate_70525_Content_8 = {
    Text = "Apa, tidak termasuk penulisan naskah?"
  },
  AvgCommunicate_70525_Content_9 = {
    Text = "Eh, Jenkin punya beberapa ide kecil untuk cerita Night Ranger…"
  },
  AvgCommunicate_70525_Option_3 = {
    Text = "Memang sangat bagus!"
  },
  AvgCommunicate_70525_Option_6 = {
    Text = "Karya berikutnya bergantung padamu!"
  },
  AvgCommunicate_70525_Option_9 = {
    Text = "Jenkin punya beberapa ide kecil untuk cerita Night Ranger…"
  },
  AvgCommunicate_70526_Content_1 = {
    Text = "Kerja sama saya dengan Herbert sudah berakhir."
  },
  AvgCommunicate_70526_Content_10 = {
    Text = "Yang jelas, aku ingin melihat dunia yang lebih luas."
  },
  AvgCommunicate_70526_Content_11 = {
    Text = "Rotan mengalahkanku tiga kali. Aku ingin tahu, selain kebencian, apa lagi yang bisa memberi seseorang kekuatan sedahsyat itu."
  },
  AvgCommunicate_70526_Content_12 = {
    Text = "Setelah aku menemukan jawabannya, aku akan kembali."
  },
  AvgCommunicate_70526_Content_13 = {
    Text = "Saat itu tiba, kuharap kau dan Rotan bersedia menjadi lawanku sekali lagi."
  },
  AvgCommunicate_70526_Content_14 = {
    Text = "Selama bukan sebagai musuh, baik sebagai lawan maupun rekan, aku menyambutnya."
  },
  AvgCommunicate_70526_Content_15 = {
    Text = "Akan kusampaikan pada Rotan. Kurasa, dia juga akan sangat menantikan untuk melihat dirimu yang baru."
  },
  AvgCommunicate_70526_Content_16 = {
    Text = "Kapalnya sudah berangkat."
  },
  AvgCommunicate_70526_Content_17 = {
    Text = "Akan ada hari di mana kita bertemu lagi. Sampai jumpa, Shilo."
  },
  AvgCommunicate_70526_Content_2 = {
    Text = "Aku tidak akan memusuhi kalian lagi. Ini janjiku."
  },
  AvgCommunicate_70526_Content_3 = {
    Text = "Setelah pertempuran itu, kau menghilang tanpa jejak..."
  },
  AvgCommunicate_70526_Content_4 = {
    Text = "Herbert adalah musuh bersama kita. Kami sangat bersedia untuk berdamai denganmu."
  },
  AvgCommunicate_70526_Content_5 = {
    Text = "Kalau kau mau datang, Mythage selalu menyambutmu."
  },
  AvgCommunicate_70526_Content_6 = {
    Text = "Terima kasih atas tawarannya. Tapi aku berencana untuk pergi."
  },
  AvgCommunicate_70526_Content_7 = {
    Text = "Pergi? Kau mau ke mana?"
  },
  AvgCommunicate_70526_Content_8 = {
    Text = "Entahlah. Mungkin ke suatu lautan."
  },
  AvgCommunicate_70526_Content_9 = {
    Text = "Mungkin ke suatu gunung. Aku selalu mendengar panggilannya."
  },
  AvgCommunicate_70526_Option_14 = {
    Text = "Akan kusampaikan padanya"
  },
  AvgCommunicate_70526_Option_17 = {
    Text = "Sampai jumpa, Shilo."
  },
  AvgCommunicate_70526_Option_3 = {
    Text = "Kau bisa mempertimbangkan untuk datang ke Mythage"
  },
  AvgCommunicate_70526_Option_7 = {
    Text = "Kau mau ke mana?"
  },
  AvgCommunicate_70527_Content_1 = {
    Text = "Oreta memperlihatkan ubur-ubur peliharaannya kepada Lily."
  },
  AvgCommunicate_70527_Content_10 = {
    Text = "Karena dia telah mewujudkan keinginan terbesarnya — membuat kamu menjalani kehidupan yang bahagia."
  },
  AvgCommunicate_70527_Content_11 = {
    Text = "Lily ingin melihat ibu tersenyum seperti itu."
  },
  AvgCommunicate_70527_Content_12 = {
    Text = "Demi membuat ibu bahagia, Lily juga akan terus bahagia!"
  },
  AvgCommunicate_70527_Content_13 = {
    Text = "Benar sekali!"
  },
  AvgCommunicate_70527_Content_14 = {
    Text = "Lily masih ingin naik kereta bawah tanah? Kalau mau, aku akan mengajakmu sekarang."
  },
  AvgCommunicate_70527_Content_15 = {
    Text = "Benarkah?! Terima kasih, Tuan!"
  },
  AvgCommunicate_70527_Content_2 = {
    Text = "Jenkin mengajak Lily memanjat menara lonceng."
  },
  AvgCommunicate_70527_Content_3 = {
    Text = "Kak Ramona membawakan banyak sekali makanan enak untuk Lily..."
  },
  AvgCommunicate_70527_Content_4 = {
    Text = "Lily, bagaimana perasaanmu sekarang, sudah lebih baik?"
  },
  AvgCommunicate_70527_Content_5 = {Text = "Ya!"},
  AvgCommunicate_70527_Content_6 = {
    Text = "Lily semalam bermimpi, memimpikan ibu……"
  },
  AvgCommunicate_70527_Content_7 = {
    Text = "Ibu bilang, dia sedang mengawasi Lily."
  },
  AvgCommunicate_70527_Content_8 = {
    Text = "Melihat Lily bahagia, ibu juga sangat bahagia."
  },
  AvgCommunicate_70527_Content_9 = {
    Text = "Ibu tersenyum. Lily sudah lama tidak melihat ibu tersenyum seperti itu."
  },
  AvgCommunicate_70527_Option_10 = {
    Text = "Karena dia telah mewujudkan keinginannya"
  },
  AvgCommunicate_70527_Option_14 = {
    Text = "Masih ingin naik kereta bawah tanah?"
  },
  AvgCommunicate_70527_Option_4 = {
    Text = "Lily, bagaimana perasaanmu sekarang?"
  },
  AvgCommunicate_70528_Content_1 = {
    Text = "Setelah kembali, selama waktu ini, aku telah mencoba beberapa kemungkinan baru."
  },
  AvgCommunicate_70528_Content_10 = {
    Text = "Tetaplah hidup, Penjaga Rahasia... Bersama Ramona yang itu, temukan cara untuk melawan Erosi."
  },
  AvgCommunicate_70528_Content_11 = {
    Text = "Jika ada yang perlu kulakukan, jangan ragu untuk memberitahuku."
  },
  AvgCommunicate_70528_Content_12 = {
    Text = "Jangan biarkan dunia itu juga berubah menjadi seperti duniaku ini."
  },
  AvgCommunicate_70528_Content_13 = {
    Text = "Ini satu-satunya harapanku, dan hanya kamu yang bisa melakukannya."
  },
  AvgCommunicate_70528_Content_2 = {
    Text = "Tanpa terkecuali, semua pilihan itu salah."
  },
  AvgCommunicate_70528_Content_3 = {
    Text = "Kalian berjalan di satu-satunya jalan yang benar, Penjaga Rahasia."
  },
  AvgCommunicate_70528_Content_4 = {
    Text = "Kerja keras, Ramona..."
  },
  AvgCommunicate_70528_Content_5 = {
    Text = "Bagaimana situasi di tempatmu, apakah sudah membaik sekarang?"
  },
  AvgCommunicate_70528_Content_6 = {
    Text = "Masih sama seperti sebelumnya... Satu-satunya tempat perlindungan yang tersisa dari segalanya yang tenggelam oleh Erosi."
  },
  AvgCommunicate_70528_Content_7 = {
    Text = "Guru Alistair mempertahankan tempat ini, kondisinya juga sangat buruk..."
  },
  AvgCommunicate_70528_Content_8 = {
    Text = "Ramona... apa yang bisa kulakukan untuk kalian?"
  },
  AvgCommunicate_70528_Content_9 = {
    Text = "Tidak apa-apa, kami sudah lama terbiasa dengan semua ini."
  },
  AvgCommunicate_70528_Option_4 = {
    Text = "Kerja keras, Ramona..."
  },
  AvgCommunicate_70528_Option_8 = {
    Text = "Apa yang bisa kulakukan untuk kalian?"
  },
  AvgCommunicate_70529_Content_1 = {
    Text = "Halo, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70529_Content_10 = {
    Text = "Tentu. Kebetulan, kondisi salah satu pasien tiba-tiba memburuk, saya harus segera menanganinya."
  },
  AvgCommunicate_70529_Content_11 = {
    Text = "Terima kasih sudah mengantar Lily pulang, ruang istirahat dan hidangan teh sudah disiapkan untuk kalian semua."
  },
  AvgCommunicate_70529_Content_12 = {
    Text = "Selamat datang di Sanatorium Rye, Penjaga Rahasia {Male=tuan,Female=nyonya}."
  },
  AvgCommunicate_70529_Content_2 = {
    Text = "Melalui perkenalan dari Nyonya Daffodel, Misage memberikan informasi kontak Anda kepada saya."
  },
  AvgCommunicate_70529_Content_3 = {
    Text = "Boleh saya tahu, kalian dan Lily sudah sampai di mana?"
  },
  AvgCommunicate_70529_Content_4 = {
    Text = "Kami sudah tiba di Jembatan Baja Fowles, sebentar lagi akan sampai di sanatorium."
  },
  AvgCommunicate_70529_Content_5 = {
    Text = "Sepanjang perjalanan, Lily tidak merepotkan kalian, kan?"
  },
  AvgCommunicate_70529_Content_6 = {
    Text = "Tidak perlu khawatir, Lily sangat penurut sepanjang perjalanan."
  },
  AvgCommunicate_70529_Content_7 = {
    Text = "Nona Francis, mengenai sanatorium, saya ingin..."
  },
  AvgCommunicate_70529_Content_8 = {
    Text = "Maaf, Penjaga. Kondisi salah satu pasien tiba-tiba memburuk, aku harus segera menanganinya."
  },
  AvgCommunicate_70529_Content_9 = {
    Text = "Kalau begitu, kita bertemu di sanatorium?"
  },
  AvgCommunicate_70529_Option_4 = {
    Text = "Sebentar lagi sampai"
  },
  AvgCommunicate_70529_Option_6 = {
    Text = "Lily sangat penurut"
  },
  AvgCommunicate_70529_Option_7 = {
    Text = "Tanyakan pada Francis tentang kejanggalan di sanatorium"
  },
  AvgCommunicate_70529_Option_9 = {
    Text = "Tahan dulu, agar tidak membuatnya waspada"
  },
  AvgCommunicate_70530_Content_1 = {
    Text = "Benih berharga ditolak begitu saja... Sungguh menyedihkan, Penjaga Rahasia."
  },
  AvgCommunicate_70530_Content_10 = {
    Text = "Semakin berharga sesuatu, semakin layak disambut dengan upacara yang khidmat."
  },
  AvgCommunicate_70530_Content_11 = {
    Text = "Benih yang paling berharga ini, cepat atau lambat akan menjadi milikmu."
  },
  AvgCommunicate_70530_Content_12 = {
    Text = "Tenang saja, Penjaga Rahasia. Hari itu tidak akan membuatmu menunggu terlalu lama."
  },
  AvgCommunicate_70530_Content_2 = {
    Text = "Taiyi Si, bukan itu maksudku..."
  },
  AvgCommunicate_70530_Content_3 = {
    Text = "Oh? Lalu apa maksud Penjaga Rahasia?"
  },
  AvgCommunicate_70530_Content_4 = {Text = "Aku..."},
  AvgCommunicate_70530_Content_5 = {
    Text = "Maaf, tapi situasi saat itu benar-benar terlalu mendadak, aku tidak punya waktu untuk berpikir..."
  },
  AvgCommunicate_70530_Content_6 = {
    Text = "Kalau begitu, bagaimana kalau situasinya tidak mendadak?"
  },
  AvgCommunicate_70530_Content_7 = {Text = "Aku..."},
  AvgCommunicate_70530_Content_8 = {
    Text = "Baiklah, baiklah, aku tidak menggodamu lagi."
  },
  AvgCommunicate_70530_Content_9 = {
    Text = "Aku mengerti, Penjaga Rahasia."
  },
  AvgCommunicate_70530_Option_2 = {
    Text = "Taiyi Si, bukan itu maksudku..."
  },
  AvgCommunicate_70530_Option_5 = {
    Text = "Maaf, tapi situasi saat itu benar-benar terlalu mendadak..."
  },
  AvgCommunicate_70531_Content_1 = {
    Text = "Keeper, boleh saya bertanya..."
  },
  AvgCommunicate_70531_Content_10 = {
    Text = "Selamat bergabung di Miskatonic."
  },
  AvgCommunicate_70531_Content_11 = {
    Text = "...Tadi Hannah datang menemuiku."
  },
  AvgCommunicate_70531_Content_12 = {
    Text = "Pembuatan tubuh kebangkitan Jenkin telah berhasil diselesaikan."
  },
  AvgCommunicate_70531_Content_13 = {Text = "!!!"},
  AvgCommunicate_70531_Content_14 = {
    Text = "Ayo, mari kita temui pahlawan kecil kita."
  },
  AvgCommunicate_70531_Content_2 = {
    Text = "Bagaimana perkembangan kebangkitan Jenkin?"
  },
  AvgCommunicate_70531_Content_3 = {
    Text = "Gudang material sekolah sudah menyiapkan semua bahan yang dibutuhkan untuk tubuhnya, sekarang sedang dalam proses pembuatan tubuh kebangkitan."
  },
  AvgCommunicate_70531_Content_4 = {
    Text = "Kita akan segera bisa bertemu dengannya lagi!"
  },
  AvgCommunicate_70531_Content_5 = {
    Text = "Syukurlah! Syukurlah..."
  },
  AvgCommunicate_70531_Content_6 = {
    Text = "Terima kasih, Keeper. Terima kasih semuanya..."
  },
  AvgCommunicate_70531_Content_7 = {
    Text = "Kamu dan Jenkin telah menyelamatkan kami."
  },
  AvgCommunicate_70531_Content_8 = {
    Text = "Dia meninggal demi menyelamatkan Miskatonic, semua ini adalah hal yang seharusnya kami lakukan."
  },
  AvgCommunicate_70531_Content_9 = {
    Text = "Dewan sekolah sudah berdiskusi dan menyetujui, kalian berdua tidak perlu lagi khawatir hidup terlantar di luar."
  },
  AvgCommunicate_70531_Option_11 = {
    Text = "Aku menerima sebuah pesan..."
  },
  AvgCommunicate_70531_Option_3 = {
    Text = "Hampir selesai"
  },
  AvgCommunicate_70531_Option_7 = {
    Text = "Kami yang seharusnya berterima kasih padamu, dan juga Jenkin."
  },
  AvgCommunicate_70532_Content_1 = {
    Text = "Penjaga Meo!"
  },
  AvgCommunicate_70532_Content_2 = {
    Text = "Kapan kita syuting film lagi!"
  },
  AvgCommunicate_70532_Content_3 = {
    Text = "Kenapa, sudah ketagihan ya?"
  },
  AvgCommunicate_70532_Content_4 = {
    Text = "Bukan aku yang ketagihan, tapi kota ini membutuhkan kita!"
  },
  AvgCommunicate_70532_Content_5 = {
    Text = "Kota ini penuh dengan kejahatan, membutuhkan Ranger Malam dan asistennya!"
  },
  AvgCommunicate_70532_Content_6 = {
    Text = "Aku akan tanya Doer, lihat bisa pinjam kamera sekali lagi atau tidak."
  },
  AvgCommunicate_70532_Content_7 = {
    Text = "Selain itu, kelas baca tulisnya sudah belajar dengan baik belum? Sudah berapa banyak salah ketik itu!"
  },
  AvgCommunicate_70532_Content_8 = {
    Text = "Jangan ikut campur, orang Distrik Barat!"
  },
  AvgCommunicate_70532_Content_9 = {
    Text = "Kota ini membutuhkan kami, Night Ranger dan asistennya sangat sibuk tahu!"
  },
  AvgCommunicate_70532_Option_3 = {
    Text = "Ketagihan ya?"
  },
  AvgCommunicate_70532_Option_6 = {
    Text = "Aku tanya Dor dulu ya..."
  },
  AvgCommunicate_70533_Content_1 = {
    Text = "Penjaga Rahasia, Penjaga Rahasia!"
  },
  AvgCommunicate_70533_Content_10 = {
    Text = "Tapi, kenapa Aurita tidak ingat mereka?"
  },
  AvgCommunicate_70533_Content_11 = {
    Text = "Anjing kecil, kuda kecil, ubur-ubur kecil... mereka semua pernah menjadi teman Aurita."
  },
  AvgCommunicate_70533_Content_12 = {
    Text = "Kemudian, mereka harus pergi ke tempat yang sangat jauh."
  },
  AvgCommunicate_70533_Content_13 = {
    Text = "Mereka takut Aurita akan sedih, jadi mereka membawa pergi kenangan Aurita tentang mereka."
  },
  AvgCommunicate_70533_Content_14 = {
    Text = "Tapi mereka tetap ingin menemani Aurita, jadi mereka meninggalkan tubuh mereka."
  },
  AvgCommunicate_70533_Content_15 = {
    Text = "Tubuh-tubuh itu berubah menjadi patung tanah liat kecil, dan tinggal di Istana Air milik Aurita."
  },
  AvgCommunicate_70533_Content_16 = {
    Text = "...Mereka selalu peduli dan menemani Aurita, tidak pernah berubah."
  },
  AvgCommunicate_70533_Content_17 = {
    Text = "Sepertinya Aurita mengerti, tapi juga sepertinya belum mengerti..."
  },
  AvgCommunicate_70533_Content_18 = {
    Text = "Tapi, sekarang Aurita tahu! Yang ada di Istana Air itu, semuanya adalah teman baik Aurita."
  },
  AvgCommunicate_70533_Content_19 = {
    Text = "Aurita akan merawat mereka dengan baik, dan setiap hari mengajak mereka bermain bersama!"
  },
  AvgCommunicate_70533_Content_2 = {
    Text = "Kamu tahu apa yang ada di dalam Istana Air Aurita?"
  },
  AvgCommunicate_70533_Content_3 = {
    Text = "Menurutmu itu apa, Aurita?"
  },
  AvgCommunicate_70533_Content_4 = {
    Text = "Hmm... Aurita tidak bisa mengingatnya..."
  },
  AvgCommunicate_70533_Content_5 = {
    Text = "Rasanya sangat familiar, seperti... seperti..."
  },
  AvgCommunicate_70533_Content_6 = {Text = "Teman..."},
  AvgCommunicate_70533_Content_7 = {
    Text = "Aurita paling suka teman, tapi kenapa Aurita tidak ingat mereka?"
  },
  AvgCommunicate_70533_Content_8 = {
    Text = "Mereka semua, adalah teman Aurita."
  },
  AvgCommunicate_70533_Content_9 = {
    Text = "Teman? Aurita paling suka teman!"
  },
  AvgCommunicate_70533_Option_11 = {
    Text = "Ceritakan kisahnya kepada Aurita"
  },
  AvgCommunicate_70533_Option_3 = {
    Text = "Menurutmu bagaimana, Aurita?"
  },
  AvgCommunicate_70533_Option_8 = {
    Text = "Mereka semua adalah teman Aurita."
  },
  AvgCommunicate_72037_Content_1 = {
    Text = "Kemarin aku bermimpi tentang masa kecil, memimpikan banyak orang dari masa lalu Lemuria."
  },
  AvgCommunicate_72037_Content_10 = {
    Text = "Tidak ada yang bisa kausembunyikan dariku."
  },
  AvgCommunicate_72037_Content_11 = {
    Text = "Yang menyelimuti mimpi itu adalah perasaan yang sangat akrab dan familiar. Awalnya aku mengira itu berasal dari Noah."
  },
  AvgCommunicate_72037_Content_12 = {
    Text = "Baru kemudian aku menyadari, dalam perjalanan waktu yang panjang, hal yang paling familiar bagiku bukanlah siapa pun, melainkan sebuah benda mati yang dingin."
  },
  AvgCommunicate_72037_Content_13 = {Text = "Tulu……"},
  AvgCommunicate_72037_Content_14 = {
    Text = "Simpan rasa simpatimu. Sejak saat aku mengenakan mahkota, aku sudah siap menghadapi segalanya."
  },
  AvgCommunicate_72037_Content_15 = {
    Text = "Raja Lemuria tidak membutuhkan siapa pun untuk meneteskan air mata untuknya."
  },
  AvgCommunicate_72037_Content_16 = {
    Text = "Kalau begitu…… Raja Lemuria, apakah Anda berminat untuk mencicipi lagi rasa permen beras itu? Kurasa koki Misagor bisa mereplikasinya sedikit."
  },
  AvgCommunicate_72037_Content_18 = {
    Text = "Hmph, kau memang perhatian juga."
  },
  AvgCommunicate_72037_Content_19 = {
    Text = "Baiklah, anggap saja itu sebagai persembahanmu."
  },
  AvgCommunicate_72037_Content_2 = {
    Text = "Kenangan itu tidak pernah suka kuceritakan kepada orang lain, tapi, dalam mimpi kemarin, kau ada di sana, bukan?"
  },
  AvgCommunicate_72037_Content_3 = {
    Text = "?! Bagaimana kau bisa tahu?"
  },
  AvgCommunicate_72037_Content_4 = {
    Text = "Waktu yang kuhabiskan dalam mimpi jauh lebih banyak daripada di dunia nyata. Kau meragukan persepsi seseorang yang hidup dalam mimpi?"
  },
  AvgCommunicate_72037_Content_5 = {
    Text = "Selain ramalan, terkadang aku juga bermimpi seperti orang biasa, tapi mimpi-mimpi itu tidak pernah senyata dan seberkesinambungan mimpi kemarin..."
  },
  AvgCommunicate_72037_Content_6 = {
    Text = "Seperti ada seseorang yang duduk bersamaku, mengalami kembali semua hal di masa lalu dari awal."
  },
  AvgCommunicate_72037_Content_7 = {
    Text = "Perasaan tidak sendirian ini... tidak buruk."
  },
  AvgCommunicate_72037_Content_8 = {
    Text = "Aku memang selalu menemanimu."
  },
  AvgCommunicate_72037_Content_9 = {
    Text = "Biar kutebak, pasti kau merasuki mahkota itu, kan?"
  },
  AvgCommunicate_72037_Option_10 = {Text = "Ya"},
  AvgCommunicate_72037_Option_13 = {Text = "Tulu……"},
  AvgCommunicate_72037_Option_16 = {
    Text = "Kalau begitu……"
  },
  AvgCommunicate_72037_Option_3 = {Text = "?!"},
  AvgCommunicate_72037_Option_8 = {
    Text = "Aku memang selalu menemanimu."
  },
  AvgCommunicate_80100_Content_1 = {
    Text = "%player%, kalau tidak keberatan, maukah kamu melakukan tes psikologi?"
  },
  AvgCommunicate_80100_Content_10 = {
    Text = "Ramona, Rotten, Ogier…… Saat sendirian, bayangan mereka semua selalu muncul di benakku."
  },
  AvgCommunicate_80100_Content_11 = {
    Text = "Tidak perlu memaksakan diri untuk menanggung semuanya sendirian. Apa pun keresahan dan kebingunganmu, kamu bisa menceritakannya padaku."
  },
  AvgCommunicate_80100_Content_12 = {
    Text = "Aku juga sudah menyiapkan teh hangat dan camilan khusus untukmu. Kita bisa mengobrol pelan-pelan."
  },
  AvgCommunicate_80100_Content_13 = {
    Text = "……Aku akan ke sana sekarang."
  },
  AvgCommunicate_80100_Content_2 = {
    Text = "...Tes psikologi?"
  },
  AvgCommunicate_80100_Content_3 = {
    Text = "Sangat sederhana, kamu hanya perlu menggambar rumah, pohon, dan orang di atas kertas putih."
  },
  AvgCommunicate_80100_Content_4 = {
    Text = "Percayalah, ini tidak akan menyita banyak waktumu."
  },
  AvgCommunicate_80100_Content_5 = {
    Text = "……Tapi menurutku kondisi mentalku sangat sehat."
  },
  AvgCommunicate_80100_Content_6 = {
    Text = "Tujuan akhir dari tes ini bukan untuk menilai sehat atau tidaknya, melainkan untuk mengamati masalah psikologis yang mungkin muncul."
  },
  AvgCommunicate_80100_Content_7 = {
    Text = "%player%, setelah datang ke sini, apakah kamu pernah merasa kesepian? Apakah kamu merindukan teman-teman dari dunia itu?"
  },
  AvgCommunicate_80100_Content_8 = {
    Text = "Rasa kesepian dan kesendirian itu akan tersimpan jauh di dalam hatimu, dan seiring berjalannya waktu akan terus mengendap, menimbulkan dampak yang tak terduga."
  },
  AvgCommunicate_80100_Content_9 = {
    Text = "Mungkin kamu benar, aku memang sangat merindukan mereka……"
  },
  AvgCommunicate_80100_Option_13 = {
    Text = "……Aku akan ke sana sekarang."
  },
  AvgCommunicate_80100_Option_2 = {
    Text = "...Tes psikologi?"
  },
  AvgCommunicate_80100_Option_5 = {
    Text = "……Tapi menurutku kondisi mentalku sangat sehat."
  },
  AvgCommunicate_80101_Content_1 = {
    Text = "Kudengar belakangan ini suasana hatimu sedang tidak baik. Kalau tidak keberatan, kamu bisa datang kepadaku untuk konsultasi."
  },
  AvgCommunicate_80101_Content_10 = {
    Text = "Ah, hanya dengan mendeskripsikannya saja, hati perakku sudah gemetar tak henti-henti……"
  },
  AvgCommunicate_80101_Content_11 = {
    Text = "%player%, aku sudah tidak sabar ingin menyelami hatimu, mencicipi kenanganmu."
  },
  AvgCommunicate_80101_Content_12 = {
    Text = "Kalau begitu kamu akan kecewa. Aku sudah keluar rumah."
  },
  AvgCommunicate_80101_Content_13 = {
    Text = "Aku tahu. Salah satu pasienku sudah mengirim pesan memberitahuku soal ini."
  },
  AvgCommunicate_80101_Content_14 = {
    Text = "Dia bahkan dengan baik hati melampirkan lokasimu saat ini, jadi……"
  },
  AvgCommunicate_80101_Content_15 = {
    Text = "Aku segera tiba."
  },
  AvgCommunicate_80101_Content_2 = {
    Text = "Tidak perlu memaksakan diri, Penjaga Rahasia. Saran dari bidang profesional bisa membantumu mengelola tekanan lebih cepat."
  },
  AvgCommunicate_80101_Content_3 = {
    Text = "Bagaimana kamu bisa tahu semua ini……"
  },
  AvgCommunicate_80101_Content_4 = {Text = "Rahasia~"},
  AvgCommunicate_80101_Content_5 = {
    Text = "Jadi, apa jawabanmu?"
  },
  AvgCommunicate_80101_Content_6 = {
    Text = "Aku jamin kali ini tidak akan melakukan induksi lain lagi."
  },
  AvgCommunicate_80101_Content_7 = {
    Text = "Terakhir kali, dan sebelumnya juga, kamu bilang hal yang sama……"
  },
  AvgCommunicate_80101_Content_8 = {
    Text = "Itu bukan salahku, melainkan karena kesadaranmu dipenuhi oleh kenangan-kenangan yang menyenangkan."
  },
  AvgCommunicate_80101_Content_9 = {
    Text = "Kenangan-kenangan itu jauh melampaui batas rasa sakit yang bisa ditanggung manusia biasa, namun membawa aura keberadaan agung itu, sungguh kenikmatan yang tiada tara."
  },
  AvgCommunicate_80101_Option_12 = {
    Text = "……Kalau begitu kamu akan kecewa"
  },
  AvgCommunicate_80101_Option_3 = {
    Text = "Bagaimana kamu bisa tahu semua ini……"
  },
  AvgCommunicate_80101_Option_7 = {
    Text = "Terakhir kali, dan sebelumnya juga, kamu bilang hal yang sama……"
  },
  AvgCommunicate_80102_Content_1 = {
    Text = "%player%, kalau kamu tidak keberatan, bolehkah aku yang menangani terapi psikologismu?"
  },
  AvgCommunicate_80102_Content_10 = {
    Text = "Tapi aku tidak akan mengambil tindakan yang berlebihan. Percayalah."
  },
  AvgCommunicate_80102_Content_11 = {
    Text = "……Benarkah?"
  },
  AvgCommunicate_80102_Content_12 = {
    Text = "Tentu saja. Lagipula aku hanyalah seorang psikiater biasa."
  },
  AvgCommunicate_80102_Content_2 = {
    Text = "Menurutku kamu membutuhkan seorang psikolog pribadi."
  },
  AvgCommunicate_80102_Content_3 = {
    Text = "...Kurasa itu tidak perlu."
  },
  AvgCommunicate_80102_Content_4 = {
    Text = "Tidak, sebagai satu-satunya Penjaga Rahasia, keberadaanmu sendiri sudah layak mendapat perhatian khusus."
  },
  AvgCommunicate_80102_Content_5 = {
    Text = "Aku hanya ingin menggunakan keahlian profesionalku untuk membantumu, itu saja."
  },
  AvgCommunicate_80102_Content_6 = {
    Text = "Benarkah begitu? Kenapa aku merasa kamu punya tujuan lain..."
  },
  AvgCommunicate_80102_Content_7 = {
    Text = "Misalnya, dengan dalih sebagai psikiater pribadi, mengintip ingatan saya."
  },
  AvgCommunicate_80102_Content_8 = {
    Text = "Ah, ketahuan ya? Kalau begitu, tidak bisa diapa-apakan lagi."
  },
  AvgCommunicate_80102_Content_9 = {
    Text = "Memang benar saya sangat, sangat tertarik dengan ingatanmu. Terutama setelah kamu menceritakan tentang dunia itu."
  },
  AvgCommunicate_80102_Option_11 = {
    Text = "……Benarkah?"
  },
  AvgCommunicate_80102_Option_3 = {
    Text = "...Kurasa itu tidak perlu."
  },
  AvgCommunicate_80102_Option_6 = {
    Text = "...Benarkah begitu?"
  },
  AvgCommunicate_80104_Content_1 = {
    Text = "Terima kasih sudah mengirimkan laporan itu kepadaku."
  },
  AvgCommunicate_80104_Content_10 = {
    Text = "Dan untuk bisa kembali ke dunia itu, hanya dengan kekuatanku dan Meltdown · Dor saja, jelas tidak cukup."
  },
  AvgCommunicate_80104_Content_11 = {
    Text = "Kau membutuhkan kekuatanku…… Aku mengerti."
  },
  AvgCommunicate_80104_Content_12 = {
    Text = "Hadiah ini, akan kuterima. Dan sebagai balasan, adalah satu sesi konsultasi psikologis gratis."
  },
  AvgCommunicate_80104_Content_13 = {
    Text = "%player%, kapan kamu ada waktu luang?"
  },
  AvgCommunicate_80104_Content_14 = {
    Text = "Baik sebagai dokter maupun sebagai teman, aku punya kewajiban untuk memahami isi hatimu lebih dalam."
  },
  AvgCommunicate_80104_Content_15 = {
    Text = "Aku sedang tugas lapangan……sinyalnya jelek……nanti lanjut……"
  },
  AvgCommunicate_80104_Content_16 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_17 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_18 = {
    Text = "Heh, aku tahu kamu masih di sana. Tapi tidak apa-apa, kita masih punya banyak waktu."
  },
  AvgCommunicate_80104_Content_2 = {
    Text = "Itu adalah salinan ringkasan laporan Ras Serangga yang kusalin tangan, tidak melibatkan masalah kebocoran rahasia, simpan saja dengan tenang."
  },
  AvgCommunicate_80104_Content_3 = {
    Text = "Ini \"imbalan\" yang dibayar di muka?"
  },
  AvgCommunicate_80104_Content_4 = {
    Text = "Tapi maaf, aku belum punya informasi orang dalam dari Dewan Peninjauan yang bisa kusampaikan akhir-akhir ini."
  },
  AvgCommunicate_80104_Content_5 = {
    Text = "Ini bukan imbalan, melainkan hadiah."
  },
  AvgCommunicate_80104_Content_6 = {
    Text = "Untuk merayakan kelahiran barumu, dan juga berterima kasih karena kau telah memilihku."
  },
  AvgCommunicate_80104_Content_7 = {
    Text = "Karena aku tidak seperti \"dia\" di dunia itu, yang berdiri di sisi berlawanan darimu?"
  },
  AvgCommunicate_80104_Content_8 = {
    Text = "Kau bisa menganggapnya begitu"
  },
  AvgCommunicate_80104_Content_9 = {
    Text = "Sebagai Penjaga Rahasia, aku selalu percaya bahwa aku dan Awakened adalah teman, bukan musuh."
  },
  AvgCommunicate_80104_Option_15 = {
    Text = "……Sinyalnya jelek"
  },
  AvgCommunicate_80104_Option_2 = {
    Text = "Sepertinya kau sudah menerima suratnya"
  },
  AvgCommunicate_80104_Option_5 = {
    Text = "Bukan, ini adalah hadiah……"
  },
  AvgCommunicate_80104_Option_8 = {
    Text = "Kau bisa menganggapnya begitu"
  },
  AvgCommunicate_81323_Content_1 = {
    Text = "Penyelamat, kapan buku latihan baru akan diberikan kepadaku?"
  },
  AvgCommunicate_81323_Content_10 = {
    Text = "Aku mengerti. Kalau begitu, apakah penyelamatku bisa merekomendasikan guru lain yang menguasai kedua mata pelajaran ini?"
  },
  AvgCommunicate_81323_Content_11 = {
    Text = "Kalau benar-benar tidak bisa, aku juga bisa membaca buku-buku lain dan mencoba belajar sendiri."
  },
  AvgCommunicate_81323_Content_12 = {
    Text = "Ada... memang ada, tapi temperamennya tidak begitu baik."
  },
  AvgCommunicate_81323_Content_13 = {
    Text = "Tidak apa-apa, aku tidak takut."
  },
  AvgCommunicate_81323_Content_14 = {
    Text = "Aku yang takut! Sudahlah, kalau pergi menemui Wenkel... ugh, dia mungkin akan gila duluan."
  },
  AvgCommunicate_81323_Content_15 = {
    Text = "Gila? Apakah Guru Wenkel ini menderita suatu penyakit?"
  },
  AvgCommunicate_81323_Content_16 = {
    Text = "Tidak... juga tidak bisa dibilang tidak, aaargh! Pokoknya, biar kuajarkan dulu satu prinsip utama dalam belajar!"
  },
  AvgCommunicate_81323_Content_17 = {
    Text = "Baik, penyelamatku, aku siap mendengarkan."
  },
  AvgCommunicate_81323_Content_18 = {
    Text = "Yaitu jangan selalu mengorek segala sesuatu sampai ke akarnya!!!"
  },
  AvgCommunicate_81323_Content_19 = {
    Text = "Kenapa begitu? Penyelamatku, aku kurang mengerti. Kalau tidak bertanya sampai jelas, bagaimana bisa belajar secara menyeluruh..."
  },
  AvgCommunicate_81323_Content_2 = {
    Text = "Dan mengenai dua buku yang terakhir, aku sudah selesai membacanya. Aku mencatat total 107 pertanyaan. Mohon Penyelamat berkenan membimbingku di waktu senggang."
  },
  AvgCommunicate_81323_Content_20 = {
    Text = "Kamu tidak capek! Dengan semangat rajin seperti itu menyelami lautan ilmu pengetahuan, kamu pasti akan berhasil dalam apa pun yang kamu lakukan..."
  },
  AvgCommunicate_81323_Content_21 = {
    Text = "Terima kasih, penyelamatku. Bisa dengan bebas mempelajari ilmu yang diminati, sungguh hal yang berharga dan menyenangkan."
  },
  AvgCommunicate_81323_Content_22 = {
    Text = "Saat benar-benar mengantuk, istirahat sebentar saja sudah cukup. Mana mungkin capek?"
  },
  AvgCommunicate_81323_Content_23 = {
    Text = "Jadi, kapan penyelamatku bisa memperkenalkan guru baru untukku? Aku akan berusaha untuk tidak terlalu mengorek segala sesuatu sampai ke akarnya."
  },
  AvgCommunicate_81323_Content_24 = {
    Text = "Hmm... bagaimana kalau hanya bertanya 97 pertanyaan saja?"
  },
  AvgCommunicate_81323_Content_3 = {Text = "Aku salah"},
  AvgCommunicate_81323_Content_4 = {
    Text = "Aku benar-benar salah"
  },
  AvgCommunicate_81323_Content_6 = {
    Text = "Seharusnya aku tidak memberikan tugasku padamu untuk dikerjakan. Urusan sendiri seharusnya dikerjakan sendiri……"
  },
  AvgCommunicate_81323_Content_7 = {
    Text = "Kumohon, jangan tanya aku lagi. Kalau terus begini, aku akan mimpi buruk setiap malam!"
  },
  AvgCommunicate_81323_Content_8 = {
    Text = "Ah... Maaf, tidak kusangka gangguanku membuat penyelamatku begitu terganggu. Aku benar-benar tidak peka."
  },
  AvgCommunicate_81323_Content_9 = {
    Text = "Bukan begitu, tidak juga, mungkin aku saja yang tidak cocok jadi guru..."
  },
  AvgCommunicate_81323_Option_12 = {
    Text = "Ada... memang ada."
  },
  AvgCommunicate_81323_Option_14 = {
    Text = "Aku yang takut!"
  },
  AvgCommunicate_81323_Option_16 = {
    Text = "Tidak... juga tidak bisa dibilang tidak..."
  },
  AvgCommunicate_81323_Option_18 = {
    Text = "Yaitu jangan selalu mengorek segala sesuatu sampai ke akarnya!!!"
  },
  AvgCommunicate_81323_Option_20 = {
    Text = "Kamu tidak capek!"
  },
  AvgCommunicate_81323_Option_3 = {Text = "Aku salah"},
  AvgCommunicate_81323_Option_4 = {
    Text = "Aku benar-benar salah"
  },
  AvgCommunicate_81323_Option_9 = {
    Text = "Bukan begitu, tidak juga, mungkin aku saja yang tidak cocok jadi guru..."
  },
  AvgCommunicate_81324_Content_1 = {
    Text = "Penyelamat, akhir-akhir ini aku punya keraguan baru saat membaca buku."
  },
  AvgCommunicate_81324_Content_10 = {
    Text = "Maksud Penyelamat... harus melihat niat saat melakukan hal tersebut?"
  },
  AvgCommunicate_81324_Content_11 = {
    Text = "Benar sekali. Coba pikirkan, aku menyuruhmu mengerjakan dua tugas itu, apakah aku ingin mengeksploitasimu untuk bekerja gratis untukku, atau berharap kamu mendapat kesempatan belajar?"
  },
  AvgCommunicate_81324_Content_12 = {
    Text = "Aku tidak tahu."
  },
  AvgCommunicate_81324_Content_13 = {
    Text = "Masa tidak tahu? Tentu saja supaya kamu bisa belajar pengetahuan dengan lebih baik!"
  },
  AvgCommunicate_81324_Content_14 = {
    Text = "Oh ternyata begitu, aku salah paham. Kukira Penyelamat hanya ingin aku membantu mengerjakan tugas Anda."
  },
  AvgCommunicate_81324_Content_16 = {
    Text = "Ehem... baiklah, coba pikirkan lagi. Saat kita melakukan sesuatu, jika kita menjadikan orang lain sebagai tujuan dari tindakan itu sendiri dan benar-benar memikirkan kepentingan mereka, itu bisa disebut bermoral."
  },
  AvgCommunicate_81324_Content_17 = {
    Text = "Jika menjadikan orang lain semata-mata sebagai alat, tentu saja itu tidak bermoral."
  },
  AvgCommunicate_81324_Content_18 = {
    Text = "Sepertinya aku mengerti. Seperti Lampbearer yang menjadikan aku dan Pollux sebagai alat persembahan, tanpa benar-benar mempertimbangkan perasaan kami — itu namanya tidak bermoral."
  },
  AvgCommunicate_81324_Content_19 = {
    Text = "Benar sekali, kamu memang cepat paham!"
  },
  AvgCommunicate_81324_Content_2 = {
    Text = "Sebelumnya Anda pernah bilang, tugas itu untuk menguji dan mengasah pengetahuan diri sendiri. Selama pengetahuannya sudah dikuasai, tidak perlu terpaku pada apakah tugasnya selesai atau tidak."
  },
  AvgCommunicate_81324_Content_20 = {
    Text = "Aku mengerti sekarang, Penyelamat benar-benar orang yang sangat bermoral! Kalau begitu, tolong berikan aku beberapa buku tugas lagi. Aku akan mengerjakannya dengan serius lalu datang bertanya!"
  },
  AvgCommunicate_81324_Content_21 = {
    Text = "Penyelamat?"
  },
  AvgCommunicate_81324_Content_22 = {
    Text = "Anu, aku tiba-tiba ada urusan, soal tugas langsung cari Doer saja ya!"
  },
  AvgCommunicate_81324_Content_3 = {
    Text = "Hmm... sepertinya aku memang pernah bilang begitu."
  },
  AvgCommunicate_81324_Content_4 = {
    Text = "Tapi buku yang kubaca baru-baru ini menyebutkan bahwa menyuruh orang lain mengerjakan tugas kita sendiri tampaknya merupakan tindakan yang tidak bermoral."
  },
  AvgCommunicate_81324_Content_6 = {
    Text = "Jadi, bagaimana cara menentukan apakah hal ini bermoral atau tidak?"
  },
  AvgCommunicate_81324_Content_7 = {
    Text = "Eh... soal ini ya, kamu harus melihatnya secara dialektis."
  },
  AvgCommunicate_81324_Content_8 = {
    Text = "Kita tidak bisa bilang mutlak ya, juga tidak bisa bilang mutlak tidak."
  },
  AvgCommunicate_81324_Content_9 = {
    Text = "Menilai suatu hal, tidak bisa hanya dilihat dari hasilnya, tapi lebih penting lagi dari tujuan tindakannya."
  },
  AvgCommunicate_81324_Option_11 = {Text = "Benar."},
  AvgCommunicate_81324_Option_13 = {
    Text = "Masa tidak tahu?"
  },
  AvgCommunicate_81324_Option_19 = {
    Text = "Benar sekali, kamu memang cepat paham!"
  },
  AvgCommunicate_81324_Option_22 = {
    Text = "Anu, aku tiba-tiba ada urusan..."
  },
  AvgCommunicate_81324_Option_3 = {
    Text = "Hmm... sepertinya aku memang pernah bilang begitu."
  },
  AvgCommunicate_81324_Option_7 = {
    Text = "Eh... soal ini ya, kamu harus melihatnya secara dialektis."
  },
  AvgCommunicate_81324_Option_8 = {
    Text = "Kita tidak bisa bilang mutlak ya, juga tidak bisa bilang mutlak tidak."
  },
  AvgCommunicate_81325_Content_1 = {
    Text = "Kotak yang ajaib sekali. Penyelamat, ini benar-benar tidak digerakkan oleh semacam sihir atau lingkaran ritual?"
  },
  AvgCommunicate_81325_Content_10 = {
    Text = "Tidak juga sih, hanya saja kedua bidang ilmu ini masih terus berkembang. Ada banyak sekali peneliti yang memperluas dan memperdalam penelitian ini, menciptakan pengetahuan baru."
  },
  AvgCommunicate_81325_Content_11 = {
    Text = "Kalau kamu menjadikan bidang ilmu yang berkembang pesat seperti ini sebagai tujuan belajar, tentu saja harus belajar seumur hidup!"
  },
  AvgCommunicate_81325_Content_12 = {
    Text = "Begitu rupanya, pengetahuan yang terus berkembang... Sungguh luar biasa."
  },
  AvgCommunicate_81325_Content_13 = {
    Text = "Saat kami mempelajari kitab suci Pembawa Lentera, bahkan tidak boleh mengubah satu huruf pun. Semua isinya ditetapkan, diulang, dan tidak pernah berubah."
  },
  AvgCommunicate_81325_Content_14 = {
    Text = "Tapi, setiap kali mempelajari kitab suci, selalu ada perasaan sesak seperti berada di dalam kotak, di mana ujungnya sudah terlihat jelas."
  },
  AvgCommunicate_81325_Content_15 = {
    Text = "Sudah kuduga, hanya pengetahuan yang terus bertumbuh yang sesuai dengan hakikat kehidupan!"
  },
  AvgCommunicate_81325_Content_16 = {
    Text = "Tiba-tiba jadi mendalam begitu……"
  },
  AvgCommunicate_81325_Content_17 = {
    Text = "Ngomong-ngomong, aku punya kesempatan belajar yang luar biasa yang bisa kuberikan gratis untukmu."
  },
  AvgCommunicate_81325_Content_18 = {
    Text = "Benarkah, Penyelamat! Rasa terima kasihku tak bisa diungkapkan dengan kata-kata."
  },
  AvgCommunicate_81325_Content_19 = {
    Text = "Tentu saja benar. Buku latihan Penggunaan dan Prinsip Perbaikan Teknologi Silver Core ini, dan Buku Wajib Strategi Psikologi Investigator ini, kamu mau menulis duluan……"
  },
  AvgCommunicate_81325_Content_2 = {
    Text = "Bukan, ini adalah teknologi Silver Core murni. Oh ya, satu hal lagi, harga komunikator ini mahal, jadi sebaiknya jangan dibongkar sembarangan ya."
  },
  AvgCommunicate_81325_Content_20 = {
    Text = "Ah bukan, maksudnya mau belajar yang mana dulu?"
  },
  AvgCommunicate_81325_Content_3 = {
    Text = "Ah, sayang sekali…… Bagaimana Penyelamat bisa tahu kalau aku baru saja ingin membongkarnya? Apakah ini telepati?"
  },
  AvgCommunicate_81325_Content_4 = {
    Text = "Juga bukan…… Menebak pikiranmu bahkan tidak perlu menggunakan psikologi!"
  },
  AvgCommunicate_81325_Content_5 = {
    Text = "Pasti psikologi juga merupakan ilmu yang mendalam. Malu rasanya, pengetahuan yang saya miliki sungguh terbatas……"
  },
  AvgCommunicate_81325_Content_6 = {
    Text = "Penyelamat, berapa lama waktu yang dibutuhkan untuk mempelajari teknologi Silver Core dan psikologi ini?"
  },
  AvgCommunicate_81325_Content_7 = {
    Text = "Mempelajari? Hmm……"
  },
  AvgCommunicate_81325_Content_8 = {
    Text = "Untuk dasar-dasarnya butuh empat sampai lima tahun, kalau ingin benar-benar menguasainya mungkin harus mendalaminya seumur hidup."
  },
  AvgCommunicate_81325_Content_9 = {
    Text = "Seumur hidup! Apakah pengetahuan ini sebanyak ribuan gulungan kitab?"
  },
  AvgCommunicate_81325_Option_10 = {
    Text = "Tidak juga sih……"
  },
  AvgCommunicate_81325_Option_16 = {
    Text = "Tiba-tiba jadi mendalam begitu……"
  },
  AvgCommunicate_81325_Option_19 = {
    Text = "Tentu saja benar."
  },
  AvgCommunicate_81325_Option_2 = {Text = "Bukan"},
  AvgCommunicate_81325_Option_4 = {
    Text = "Juga bukan……"
  },
  AvgCommunicate_81325_Option_7 = {
    Text = "Mempelajari? Hmm……"
  },
  AvgCommunicate_84107_Content_1 = {
    Text = "Kapan liburan kali ini berakhir?"
  },
  AvgCommunicate_84107_Content_10 = {
    Text = "Semua faktor ini digabungkan, ditimbang baik-buruknya, barulah bisa direncanakan rute yang paling efisien dan masuk akal."
  },
  AvgCommunicate_84107_Content_11 = {
    Text = "……Aku belajar banyak. Ternyata setiap pekerjaan memiliki maknanya sendiri."
  },
  AvgCommunicate_84107_Content_12 = {
    Text = "Ya, karena aku sudah membuat pilihan, aku harus memikul tanggung jawab ini."
  },
  AvgCommunicate_84107_Content_13 = {
    Text = "Mulai sekarang, aku juga akan berpatroli setiap malam, memastikan selama liburan, akademi tidak mengalami kejadian tak terduga."
  },
  AvgCommunicate_84107_Content_14 = {
    Text = "Penjaga Rahasia, kalau begitu kita ngobrol sampai sini dulu. Aku harus pergi bekerja."
  },
  AvgCommunicate_84107_Content_2 = {
    Text = "……Bukannya liburan baru saja dimulai?"
  },
  AvgCommunicate_84107_Content_4 = {
    Text = "Aku hanya mempersiapkan diri untuk nanti."
  },
  AvgCommunicate_84107_Content_5 = {
    Text = "Peta akademi sudah diperbarui, jam sudah dikalibrasi, bendera dan tiang bendera juga sudah dibersihkan."
  },
  AvgCommunicate_84107_Content_6 = {
    Text = "Setiap hari ke depannya, aku juga akan terus melakukan perawatan, memastikan semuanya siap kapan saja."
  },
  AvgCommunicate_84107_Content_7 = {
    Text = "……Hanya mengatur lalu lintas saat makan siang di akademi, perlu persiapan sebanyak itu?"
  },
  AvgCommunicate_84107_Content_8 = {
    Text = "Tentu saja. Kantin mana yang paling populer, akademi mana yang siswanya paling banyak, siswa mana yang ingin lebih dulu ke kantin, semua itu memengaruhi perencanaan seluruh rute."
  },
  AvgCommunicate_84107_Content_9 = {
    Text = "Juga taman bunga mana yang dijadikan rumah oleh kucing liar baru, area mana yang sudah diinjak-injak siswa hingga menjadi jalan baru, jalan mana yang perlu perbaikan……"
  },
  AvgCommunicate_84107_Option_11 = {
    Text = "……Aku belajar banyak."
  },
  AvgCommunicate_84107_Option_2 = {
    Text = "……Bukannya liburan baru saja dimulai?"
  },
  AvgCommunicate_84107_Option_7 = {
    Text = "Hanya mengatur lalu lintas saat makan siang di akademi……"
  },
  AvgCommunicate_84108_Content_1 = {
    Text = "Penjaga Rahasia, mengenai insiden kemarin, aku merasa sangat menyesal."
  },
  AvgCommunicate_84108_Content_10 = {
    Text = "Tapi karena ini bukan di laut, jadi aku menyesuaikannya berdasarkan situasi yang ada."
  },
  AvgCommunicate_84108_Content_11 = {
    Text = "Yang dimaksud penyesuaian, jangan-jangan memborgol kamu dan aku bersama..."
  },
  AvgCommunicate_84108_Content_12 = {
    Text = "Benar. Dengan begitu, begitu terjadi sesuatu pada saya, Anda bisa langsung menyadari dan mencegahnya."
  },
  AvgCommunicate_84108_Content_13 = {
    Text = "...Bisakah aku menolak?"
  },
  AvgCommunicate_84108_Content_14 = {
    Text = "Tentu saja Anda boleh menolak."
  },
  AvgCommunicate_84108_Content_15 = {
    Text = "Tapi saya sudah ada di depan pintu."
  },
  AvgCommunicate_84108_Content_2 = {
    Text = "……Maksudmu soal Api St. Elmo yang lepas kendali karena insomnia?"
  },
  AvgCommunicate_84108_Content_3 = {
    Text = "Meskipun Meltdown · Dor berhasil membuatku pingsan tepat waktu, aku tetap merasa bersalah."
  },
  AvgCommunicate_84108_Content_4 = {
    Text = "Aku sudah memikirkannya cukup lama, dan merasa bahwa aku perlu menerima hukuman."
  },
  AvgCommunicate_84108_Content_5 = {
    Text = "Tidak perlu sampai seperti itu. Insiden kemarin tidak menimbulkan konsekuensi serius apa pun."
  },
  AvgCommunicate_84108_Content_6 = {
    Text = "Tidak, melakukan kesalahan harus menerima hukuman. Itu sudah aturannya."
  },
  AvgCommunicate_84108_Content_7 = {
    Text = "Aku sudah memborgol satu sisi ke tanganku sendiri, sisi yang lain membutuhkan kerja sama Anda."
  },
  AvgCommunicate_84108_Content_8 = {
    Text = "Kerja samaku?"
  },
  AvgCommunicate_84108_Content_9 = {
    Text = "Biasanya, orang yang melakukan kesalahan di kapal akan diborgol kakinya dan dijemur di dek selama beberapa jam."
  },
  AvgCommunicate_84108_Option_11 = {
    Text = "Yang dimaksud penyesuaian, jangan-jangan..."
  },
  AvgCommunicate_84108_Option_13 = {
    Text = "...Bisakah aku menolak?"
  },
  AvgCommunicate_84108_Option_2 = {
    Text = "Maksudmu..."
  },
  AvgCommunicate_84108_Option_5 = {
    Text = "Tidak perlu sampai seperti itu."
  },
  AvgCommunicate_84108_Option_8 = {
    Text = "Kerja samaku?"
  },
  AvgCommunicate_84109_Content_1 = {
    Text = "Penjaga Rahasia, terima kasih."
  },
  AvgCommunicate_84109_Content_11 = {
    Text = "Sebenarnya……"
  },
  AvgCommunicate_84109_Content_12 = {
    Text = "Sebenarnya? Kenapa tiba-tiba bicara terbata-bata begitu, ini tidak seperti dirimu."
  },
  AvgCommunicate_84109_Content_13 = {
    Text = "Sebenarnya tidak perlu mengunjungi museum maritim, cukup \"bersantai\" saja juga tidak apa-apa."
  },
  AvgCommunicate_84109_Content_14 = {
    Text = "Meskipun saya tidak bisa memahami apa yang Anda sebut sebagai \"bersantai\" yang normal, tapi saat bersama Anda, saya memang merasakan ketenangan."
  },
  AvgCommunicate_84109_Content_15 = {
    Text = "Seperti berada di lautan yang tenang, tanpa badai, dan tidak akan menemui badai. Cukup berlayar mengikuti jalur, maka bisa tiba di tujuan dengan selamat."
  },
  AvgCommunicate_84109_Content_16 = {
    Text = "……Meskipun perumpamaan ini agak sulit dipahami, tapi aku kira-kira mengerti maksudmu."
  },
  AvgCommunicate_84109_Content_17 = {
    Text = "Ke depannya, kita bisa pergi mengunjungi lebih banyak tempat. Dunia ini luas, selain lautan, masih banyak pemandangan indah lainnya."
  },
  AvgCommunicate_84109_Content_18 = {
    Text = "……Saya mengerti. Saya akan mencobanya."
  },
  AvgCommunicate_84109_Content_19 = {
    Text = "Melihat……pemandangan indah yang berbeda dari lautan."
  },
  AvgCommunicate_84109_Content_2 = {
    Text = "Kenapa tiba-tiba berterima kasih?"
  },
  AvgCommunicate_84109_Content_3 = {
    Text = "Kunjungan ke Museum Maritim London kali ini, aku belajar banyak hal."
  },
  AvgCommunicate_84109_Content_4 = {
    Text = "Jam navigasi, peta laut buatan tangan, dan halaman-halaman jurnal pelayaran yang dipamerkan, semuanya sangat membantu meningkatkan kemampuan navigasi."
  },
  AvgCommunicate_84109_Content_5 = {
    Text = "Aku akan menerapkan semua ini dalam pelayaran berikutnya, memastikan semua orang kembali dengan selamat ke pelabuhan."
  },
  AvgCommunicate_84109_Content_6 = {
    Text = "Kalau tidak salah, tujuan kita ke Museum Maritim London hari itu adalah untuk \"bersantai\"……"
  },
  AvgCommunicate_84109_Content_7 = {
    Text = "Sudahlah, yang penting kau senang."
  },
  AvgCommunicate_84109_Content_8 = {
    Text = "Ya, aku juga sangat senang, dan berharap ke depannya bisa sering pergi bersantai dengan Anda."
  },
  AvgCommunicate_84109_Content_9 = {
    Text = "Tidak masalah, aku akan segera mencari museum maritim lain di London yang bisa dikunjungi."
  },
  AvgCommunicate_84109_Option_12 = {
    Text = "Sebenarnya?"
  },
  AvgCommunicate_84109_Option_16 = {
    Text = "……Perumpamaan yang sulit dipahami"
  },
  AvgCommunicate_84109_Option_2 = {
    Text = "Kenapa tiba-tiba berterima kasih?"
  },
  AvgCommunicate_84109_Option_6 = {Text = "...?"},
  AvgCommunicate_84109_Option_9 = {
    Text = "Tidak masalah"
  },
  AvgCommunicate_84110_Content_1 = {
    Text = "Bisakah jatah pasokan kafein yang ketiga dari sekarang diberikan lebih awal kepadaku, Penjaga Rahasia?"
  },
  AvgCommunicate_84110_Content_10 = {
    Text = "Tunggu, kenapa makin lama makin gila!"
  },
  AvgCommunicate_84110_Content_11 = {
    Text = "Winkel sekarang ada di mana?"
  },
  AvgCommunicate_84110_Content_12 = {
    Text = "Ada di sini bersamaku, sedang melakukan eksperimen perangkat konduksi, menguji apakah energi @2<AvgCommunicateConfuseColor.Light> bisa diubah menjadi energi cahaya."
  },
  AvgCommunicate_84110_Content_13 = {
    Text = "Kenapa kamu tidak menolak?"
  },
  AvgCommunicate_84110_Content_14 = {
    Text = "Kenapa harus menolak? Melayani penumpang adalah salah satu pekerjaanku."
  },
  AvgCommunicate_84110_Content_16 = {
    Text = "Aku ke sana sekarang. Tahan Winkel untukku."
  },
  AvgCommunicate_84110_Content_17 = {
    Text = "Diterima, akan kujalankan perintahmu sampai mati."
  },
  AvgCommunicate_84110_Content_2 = {
    Text = "Pasokanmu diambil lagi oleh Winkel?"
  },
  AvgCommunicate_84110_Content_3 = {
    Text = "Tepatnya, bukan \"diambil\", melainkan aku yang memberikannya kepada penumpang itu."
  },
  AvgCommunicate_84110_Content_4 = {
    Text = "……lagi-lagi karena alasan seperti \"lain kali aku akan ikut naik kapal untuk berlayar\"?"
  },
  AvgCommunicate_84110_Content_5 = {
    Text = "Aku hanya menjalankan tugasku. Melayani penumpang juga merupakan salah satu pekerjaanku."
  },
  AvgCommunicate_84110_Content_6 = {
    Text = "……permohonan suplai sudah disetujui. Ini yang terakhir kalinya."
  },
  AvgCommunicate_84110_Content_7 = {
    Text = "Oh ya, apa Winkel masih mencoba mengekstrak @2 di dadamu akhir-akhir ini?"
  },
  AvgCommunicate_84110_Content_8 = {
    Text = "Tidak lagi, penumpang ini sudah mengubah metode penelitiannya."
  },
  AvgCommunicate_84110_Content_9 = {
    Text = "Misalnya menggunakan galvanometer impak untuk menguji kekuatan @2<AvgCommunicateConfuseColor.Light>, menggunakan spektroskop untuk memindai garis spektrum @2<AvgCommunicateConfuseColor.Light>, menggunakan meja uji tubuh manusia untuk memverifikasi cara koneksi @2<AvgCommunicateConfuseColor.Light> dengan serat saraf……"
  },
  AvgCommunicate_84110_Option_10 = {
    Text = "Tunggu, kenapa makin lama makin gila!"
  },
  AvgCommunicate_84110_Option_13 = {
    Text = "Kenapa kamu tidak menolak?"
  },
  AvgCommunicate_84110_Option_2 = {
    Text = "Pasokanmu diambil lagi oleh Winkel?"
  },
  AvgCommunicate_84110_Option_4 = {
    Text = "Lagi-lagi karena……"
  },
  AvgCommunicate_84110_Option_6 = {
    Text = "Permohonan suplai sudah disetujui……"
  },
  AvgCommunicate_94500_Content_1 = {
    Text = "Berkat perkenalan dari Anda, setelah berkenalan dengan Tuan Ogier, beliau memperkenalkan kami kepada lebih banyak teman."
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "Tuan Ogier juga mengatakan bahwa pelatihan ksatria jauh lebih rumit dan berat dari ini. Sepertinya memang benar seperti yang tertulis di buku, setiap ksatria adalah sosok yang sangat patut dihormati."
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "Benar, Augier adalah yang paling rajin berlatih di antara para Kebangkitan!"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "Kami juga menemukan bahwa Instruktur Elvira, meskipun memiliki keterbatasan fisik, ternyata menjalani latihan yang sama dengan kami."
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "Kami awalnya mengira Instruktur Elvira juga seorang ksatria, tetapi beliau mengatakan bahwa dirinya pernah menjadi seorang tentara. Kami tidak tahu profesi seperti apa itu, tetapi pastilah sama terhormatnya dengan ksatria."
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "Tentara adalah orang yang berperang demi negara, bisa dianggap semacam ksatria juga. Namun dibandingkan dengan kode moral ketat seorang ksatria, apa yang dilakukan tentara belum tentu mewakili keadilan."
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "Elvira baru menyadari hal ini setelah meninggalkan militer. Mungkin kehidupannya sekarang terasa lebih menenangkan baginya."
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "Saya mengerti, maksud Anda adalah, ksatria bukan mewakili kekuatan, melainkan semangat keadilan. Orang-orang yang menjunjung keadilan seperti Instruktur Elvira dan juga Anda, semuanya memiliki jiwa seorang ksatria."
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "Meskipun kamu mengatakannya dengan baik, tapi kenapa rasanya jadi malu begini ya..."
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "Itu hal yang bagus, aku turut senang untuk kalian."
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "Kami sudah bertemu dengan banyak Awakened, dan memang seperti yang Anda katakan, kebanyakan dari mereka adalah orang-orang yang baik hati."
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "Mengingat saat baru tiba di sini, saya sering bersikap waspada dan curiga terhadap orang lain, sungguh memalukan."
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "Sebenarnya itu wajar saja, toh memang masih banyak orang yang perlu diwaspadai..."
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "Sekarang saya dan Castor sedang mengikuti kursus pelatihan Instruktur Elva bersama Tuan Ogier."
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "Sosok Tuan Ogier saat bertarung sungguh memukau, tapi beliau sendiri tampaknya tidak terbiasa dipuji, sungguh orang yang rendah hati."
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "Hahaha, Ogier memang mudah malu, kalian bicara saja secara normal dengannya."
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "Begitu rupanya. Saya dan Castor tidak pernah menerima pelatihan tempur di gereja. Latihan seberat ini sungguh melelahkan, namun Tuan Ogier ternyata melakukannya setiap hari. Sungguh keteguhan yang luar biasa."
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "Benar, Augier adalah yang paling rajin berlatih di antara para Kebangkitan!"
  },
  AvgCommunicate_94500_Option_14 = {
    Text = "Bisa dibilang begitu..."
  },
  AvgCommunicate_94500_Option_2 = {
    Text = "Itu hal yang bagus, aku turut senang untuk kalian."
  },
  AvgCommunicate_94500_Option_5 = {
    Text = "Sebenarnya itu wajar saja, toh memang masih banyak orang yang perlu diwaspadai..."
  },
  AvgCommunicate_94500_Option_8 = {
    Text = "Ogier memang mudah malu."
  },
  AvgCommunicate_94501_Content_1 = {
    Text = "Yang Terhormat, terima kasih telah repot-repot menyiapkan tempat tinggal untuk saya dan Castor."
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "Si Castor itu sangat menyukainya sampai ingin mencuci muka lima kali sehari, setelah saya cegah jadi tiga kali sehari."
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "Terlalu sering cuci muka bisa merusak kulit lho!!"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "Tapi kalian belum pernah menggunakan barang-barang ini sebelumnya? Tidak kusangka Gereja Lentera ternyata sepelit itu."
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "Memang belum pernah, tapi bukan karena gereja pelit, melainkan karena kami sebagai Putra Suci selalu diwajibkan untuk menahan nafsu dan berkonsentrasi pada latihan spiritual."
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "Kami hampir tidak pernah menyentuh produk teknologi seperti ini, dan kehidupan sehari-hari serta makanan kami juga memiliki banyak aturan."
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "Meskipun pakaian dan makanan umumnya cukup mewah, tetapi di luar waktu tiga kali makan kami tidak boleh makan, dan setelah waktu bangun tiba, kami harus meninggalkan kamar tidur."
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "Sejak kecil saya sering berkhayal kapan bisa tidak perlu bangun pagi, dan bisa makan apa saja yang diinginkan sepanjang hari."
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "Beberapa hari ini saya sudah berkali-kali melihat seorang gadis membawa makanan melewati koridor pada sore hari. Sepertinya kehidupan impian saya sudah menjadi hal biasa di sini."
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "Ah, itu mungkin Murphy yang pergi mengambil kue kecil... Kehidupan kalian memang cukup berat ya."
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "Saya mendengar Castor berkata bahwa ada tempat tidur tambahan yang sengaja disiapkan di kamar, saya langsung tahu itu pasti berkat Anda."
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "Semuanya sudah berlalu, kesalahan dan penyimpangan itu akan tetap tinggal di masa lalu. Kami akan melangkah di jalan yang benar dengan penampilan baru. Mohon saksikanlah."
  },
  AvgCommunicate_94501_Content_21 = {
    Text = "Terlalu sopan, kalau ada masalah cari saya saja. Sikap kalian ini sudah jauh lebih tidak merepotkan dibanding beberapa Awakened Body lainnya!"
  },
  AvgCommunicate_94501_Content_3 = {
    Text = "Sejak kecil kami sudah terbiasa tinggal bersama di kamar tidur gereja, jadi sedikit khawatir saat mendengar peraturan di sini mengharuskan satu orang satu kamar."
  },
  AvgCommunicate_94501_Content_4 = {
    Text = "Sekarang melihat betapa cermatnya Anda mempertimbangkan kebutuhan kami, saya benar-benar menyadari betapa tepatnya saran Nona Therese waktu itu agar kami bergabung dengan Anda."
  },
  AvgCommunicate_94501_Content_5 = {
    Text = "Haha, hal kecil kok, apakah kalian sudah terbiasa tinggal di sini?"
  },
  AvgCommunicate_94501_Content_6 = {
    Text = "Berkat perhatian Anda, semuanya baik-baik saja. Meskipun kamar tidur di sini kecil seperti kamar pelayan, tetapi perlengkapannya sangat lengkap, dan setelah terbiasa terasa cukup nyaman."
  },
  AvgCommunicate_94501_Content_7 = {
    Text = "Ahaha, begitu ya, syukurlah, syukurlah..."
  },
  AvgCommunicate_94501_Content_8 = {
    Text = "Kami sudah perlahan belajar hidup tanpa pelayan, Anda tidak perlu khawatir tentang kami. Bahkan bisa dibilang ini adalah hal yang kami berdua impikan selama bertahun-tahun."
  },
  AvgCommunicate_94501_Content_9 = {
    Text = "Terutama sabun pembersih wajah yang disediakan di kamar, sungguh menakjubkan. Setelah digunakan sesuai petunjuk, ternyata menghasilkan banyak busa seperti awan. Pasta gigi yang disediakan juga rasanya sangat segar."
  },
  AvgCommunicate_94501_Option_19 = {
    Text = "Ah, itu mungkin Murphy yang pergi mengambil kue kecil..."
  },
  AvgCommunicate_94501_Option_21 = {
    Text = "Terlalu sopan."
  },
  AvgCommunicate_94501_Option_5 = {
    Text = "Hal kecil kok."
  },
  AvgCommunicate_94501_Option_7 = {
    Text = "Ahaha, begitu ya, syukurlah, syukurlah..."
  },
  AvgCommunicate_94502_Content_1 = {
    Text = "Maaf mengganggu, bisakah Anda memperkenalkan kami sedikit..."
  },
  AvgCommunicate_94502_Content_10 = {
    Text = "Oh! Itu pasti Augier dan Rotan."
  },
  AvgCommunicate_94502_Content_11 = {
    Text = "Augier... Saya akan mengingat nama ini. Pemuda itu memiliki sikap yang jujur dan berani, membuat kami sangat terpesona. Saya dan Castor awalnya ingin menghampiri, tapi mereka segera berlalu pergi."
  },
  AvgCommunicate_94502_Content_12 = {
    Text = "Setelah kembali ke kamar, kami gelisah tidak bisa tidur, sangat ingin berkenalan dengan ksatria itu, tapi tidak tahu bagaimana cara memulai pembicaraan. Maka kami datang memohon perkenalan dari Anda, berharap Anda bersedia meluangkan waktu untuk membantu mempertemukan kami."
  },
  AvgCommunicate_94502_Content_13 = {
    Text = "Saya mengerti, sebenarnya kalian tidak perlu sesopan ini. Augier adalah orang yang sangat ramah, selama kalian mau membuka mulut, dia pasti dengan senang hati mau berteman dengan kalian."
  },
  AvgCommunicate_94502_Content_14 = {
    Text = "Memang pantas disebut ksatria sejati, kelapangan hati ini sungguh mengagumkan. Dia bahkan bersedia menerima kami yang asing dan pernah bekerja untuk musuh."
  },
  AvgCommunicate_94502_Content_15 = {
    Text = "Tidak tidak, ini tidak ada hubungannya dengan kelapangan hati! Ini memang cara orang normal berteman!"
  },
  AvgCommunicate_94502_Content_16 = {
    Text = "Memang tidak semua Awakened itu orang normal... Tapi kebanyakan orang di sini cukup ramah, kalian bisa bersosialisasi dengan normal tanpa ragu."
  },
  AvgCommunicate_94502_Content_17 = {
    Text = "Maaf, bolehkah Anda mengajari saya, apa yang dimaksud dengan... bersosialisasi secara normal?"
  },
  AvgCommunicate_94502_Content_19 = {
    Text = "Aku mengerti, biar aku yang memberitahu kalian rahasia berteman!"
  },
  AvgCommunicate_94502_Content_2 = {
    Text = "Sejak Anda menyarankan kami untuk lebih banyak berteman, saya dan Castor sering pergi ke tempat-tempat ramai untuk berkeliling."
  },
  AvgCommunicate_94502_Content_20 = {
    Text = "Yaitu inisiatif! Ketulusan dan inisiatif adalah hal yang paling menyentuh hati orang!"
  },
  AvgCommunicate_94502_Content_21 = {
    Text = "Ingatlah, kalian mungkin akan ditolak, ditipu, tapi itu adalah masalah orang yang menyakiti kalian. Jangan pernah meragukan bahwa ketulusan itu salah."
  },
  AvgCommunicate_94502_Content_22 = {
    Text = "Latihlah hati yang kuat, lalu beranilah untuk merasakan persahabatan!"
  },
  AvgCommunicate_94502_Content_23 = {
    Text = "Kebijaksanaan Anda selalu membuat saya kagum dan terpesona. Saya akan merenungkan ajaran Anda dengan baik. Terima kasih dari lubuk hati, wahai pelita saya."
  },
  AvgCommunicate_94502_Content_3 = {
    Text = "Berkeliling?"
  },
  AvgCommunicate_94502_Content_4 = {
    Text = "Benar, kami sering duduk diam di kantin atau alun-alun, mengamati orang-orang yang berlalu lalang, berusaha tidak mengganggu siapa pun."
  },
  AvgCommunicate_94502_Content_6 = {
    Text = "Eh, meskipun niat kalian baik, tapi duduk diam di tempat saja tidak akan bisa mendapatkan teman!"
  },
  AvgCommunicate_94502_Content_7 = {
    Text = "Oh, ternyata begitu ya, kami terlalu terikat oleh tata krama. Tapi tidak disangka di sini ternyata ada seorang ksatria sejati!"
  },
  AvgCommunicate_94502_Content_8 = {
    Text = "Mungkin Anda sudah pernah mendengar dari Castor, kami berdua selalu sangat mengagumi kisah-kisah para ksatria."
  },
  AvgCommunicate_94502_Content_9 = {
    Text = "Hari itu di alun-alun, kami melihat seorang pemuda memegang tombak panjang, sedang berdiskusi tentang teknik tombak ksatria dengan seorang wanita."
  },
  AvgCommunicate_94502_Option_10 = {
    Text = "Oh! Itu pasti Augier dan Rotan."
  },
  AvgCommunicate_94502_Option_13 = {
    Text = "Sebenarnya kalian tidak perlu sesopan ini."
  },
  AvgCommunicate_94502_Option_15 = {
    Text = "Ini tidak ada hubungannya dengan kelapangan hati!"
  },
  AvgCommunicate_94502_Option_3 = {
    Text = "Berkeliling?"
  },
  AvgCommunicate_95003_Content_1 = {
    Text = "Si kecil, ada waktu?"
  },
  AvgCommunicate_95003_Content_10 = {
    Text = "\"...Saat bintang-bintang berada di posisi yang tepat, Bayi Suci akan lahir dari rahim Ibu Ilahi.\""
  },
  AvgCommunicate_95003_Content_11 = {
    Text = "\"...Meskipun saat ini kami sudah tidak lagi melakukan ritual dan persembahan apa pun, semoga informasi ini bisa memberikan sedikit inspirasi untukmu.\""
  },
  AvgCommunicate_95003_Content_12 = {
    Text = "\"...Jika ada waktu, aku ingin berdiskusi denganmu tentang Raja Muda dan Sang Penyelamat kami...\""
  },
  AvgCommunicate_95003_Content_13 = {
    Text = "...Aku tahu siapa orangnya."
  },
  AvgCommunicate_95003_Content_14 = {
    Text = "...Seharusnya aku sudah menduganya."
  },
  AvgCommunicate_95003_Content_15 = {
    Text = "Sepertinya orang yang si kecil kenal?"
  },
  AvgCommunicate_95003_Content_16 = {
    Text = "Benar... Serahkan padaku untuk mengurusnya."
  },
  AvgCommunicate_95003_Content_17 = {
    Text = "Lain kali kalau melihat surat semacam ini lagi, tolong jangan dibalas, dan segera beritahu aku!"
  },
  AvgCommunicate_95003_Content_2 = {Text = "Ada apa?"},
  AvgCommunicate_95003_Content_3 = {
    Text = "Tidak kusangka, setelah hari itu, ternyata benar ada beberapa surat yang dikirim kemari."
  },
  AvgCommunicate_95003_Content_4 = {
    Text = "Setelah menyingkirkan yang jelas-jelas palsu, ternyata ada beberapa surat asli di dalamnya."
  },
  AvgCommunicate_95003_Content_5 = {
    Text = "Ternyata benar ada orang yang tertipu!"
  },
  AvgCommunicate_95003_Content_6 = {
    Text = "Tapi ada satu surat yang agak aneh, lokasi pengirimannya dari dalam Missaguene."
  },
  AvgCommunicate_95003_Content_7 = {
    Text = "Apa! Harus segera memberitahu bagian keamanan."
  },
  AvgCommunicate_95003_Content_8 = {
    Text = "Jangan terburu-buru, untuk berjaga-jaga, biar kusampaikan dulu poin-poin pentingnya."
  },
  AvgCommunicate_95003_Content_9 = {
    Text = "\"...Sebelumnya kami memilih bayi yang berusia sesuai, untuk menanggung tugas sebagai Ibu Ilahi.\""
  },
  AvgCommunicate_95003_Option_13 = {
    Text = "...Aku tahu siapa orangnya."
  },
  AvgCommunicate_95003_Option_14 = {
    Text = "...Seharusnya aku sudah menduganya."
  },
  AvgCommunicate_95004_Content_1 = {
    Text = "Sudah lama tidak menyapa, penjaga rahasiaku yang kecil."
  },
  AvgCommunicate_95004_Content_10 = {
    Text = "Hal seperti ini tentu saja sangat aneh!!!"
  },
  AvgCommunicate_95004_Content_11 = {
    Text = "Hahaha, sudah kuduga."
  },
  AvgCommunicate_95004_Content_12 = {
    Text = "A, apa yang sudah diduga?"
  },
  AvgCommunicate_95004_Content_13 = {
    Text = "Aku bertaruh dengan Ismail, bilang si kecil pasti akan sangat kaget melihat pesan ini."
  },
  AvgCommunicate_95004_Content_14 = {
    Text = "Sekarang terlihat jelas aku yang menang."
  },
  AvgCommunicate_95004_Content_15 = {
    Text = "...Bisa beritahu aku siapa yang menulis pesan itu?"
  },
  AvgCommunicate_95004_Content_16 = {
    Text = "Meskipun aku bisa menulis sesuatu yang serupa."
  },
  AvgCommunicate_95004_Content_17 = {
    Text = "Tapi pesan di atas memang aku yang minta Ismail menulisnya."
  },
  AvgCommunicate_95004_Content_18 = {
    Text = "...Bagus, ternyata dua-duanya adalah biang keladinya."
  },
  AvgCommunicate_95004_Content_19 = {Text = "Eh, eh..."},
  AvgCommunicate_95004_Content_2 = {
    Text = "Sudah cukup lama sejak terakhir kali kita bertemu, semoga kesehatanmu baik-baik saja."
  },
  AvgCommunicate_95004_Content_20 = {Text = "Si kecil?"},
  AvgCommunicate_95004_Content_21 = {
    Text = "Si kecil? Masih di sana?"
  },
  AvgCommunicate_95004_Content_22 = {
    Text = "Tidak ada, silakan tinggalkan pesan."
  },
  AvgCommunicate_95004_Content_23 = {
    Text = "Maaf maaf, si kecil jangan marah dong."
  },
  AvgCommunicate_95004_Content_24 = {
    Text = "Sebagai kompensasi, semua hasil buruan kali ini akan kuberikan sebagai hadiah untuk si kecil lho."
  },
  AvgCommunicate_95004_Content_25 = {
    Text = "Ayo ke sini, sudah lama tidak bertemu, semua sangat merindukanmu."
  },
  AvgCommunicate_95004_Content_26 = {
    Text = "……Hmph, baiklah, demi hadiah, kali ini kumaafkan kalian!"
  },
  AvgCommunicate_95004_Content_27 = {
    Text = "Aku beres-beres dulu lalu ke sana, tidak ada lain kali!"
  },
  AvgCommunicate_95004_Content_28 = {
    Text = "(Lain kali pakai cara lain saja untuk menggoda si kecil.)"
  },
  AvgCommunicate_95004_Content_29 = {
    Text = "Aku melihatnya! Tidak ada lain kali!"
  },
  AvgCommunicate_95004_Content_3 = {
    Text = "Jika hari ini kau tidak ada urusan, aku ingin mengundangmu untuk berpartisipasi dalam perburuan agung ini."
  },
  AvgCommunicate_95004_Content_4 = {
    Text = "Kami telah menyiapkan tempat terbaik untukmu, semua orang menanti kedatanganmu."
  },
  AvgCommunicate_95004_Content_5 = {
    Text = "Ka, Katigula? Kamu Katigula???"
  },
  AvgCommunicate_95004_Content_6 = {
    Text = "Tentu saja, yang berbicara denganmu adalah Sang Penguasa Kobaran Api yang Tak Pernah Melupakan."
  },
  AvgCommunicate_95004_Content_7 = {
    Text = "Katigula, bersikaplah normal! Aku takut!"
  },
  AvgCommunicate_95004_Content_8 = {
    Text = "Apakah ada yang aneh dari cara bicaraku?"
  },
  AvgCommunicate_95004_Content_9 = {
    Text = "Sangat aneh!!"
  },
  AvgCommunicate_95004_Option_10 = {
    Text = "Hal seperti ini tentu saja sangat aneh!!!"
  },
  AvgCommunicate_95004_Option_9 = {
    Text = "Sangat aneh!!"
  },
  AvgCommunicate_95005_Content_1 = {
    Text = "Teman-teman yang sering melakukan persembahan pasti sudah tahu."
  },
  AvgCommunicate_95005_Content_10 = {
    Text = "Menurutmu, apakah ada orang yang akan tertipu dengan cara seperti ini?"
  },
  AvgCommunicate_95005_Content_11 = {
    Text = "Siapa tahu, lagipula tidak ada yang tahu apa yang dipikirkan para penganut aliran sesat."
  },
  AvgCommunicate_95005_Content_12 = {
    Text = "Mungkin lebih baik memanggil Lake untuk membantumu, ya?"
  },
  AvgCommunicate_95005_Content_13 = {
    Text = "Dengan keberuntungannya, mungkin benar-benar bisa memancing cukup banyak anggota kultus."
  },
  AvgCommunicate_95005_Content_14 = {
    Text = "Tidak perlu, aku hanya ingin melihat si kecil mengucapkan kata-kata itu."
  },
  AvgCommunicate_95005_Content_15 = {
    Text = "?! Ini cara bermain macam apa!"
  },
  AvgCommunicate_95005_Content_16 = {
    Text = "Tanggal operasi akan diinformasikan nanti, si kecil harus datang ya."
  },
  AvgCommunicate_95005_Content_2 = {
    Text = "Persembahan mudah disiapkan, tapi dewa sulit dipanggil."
  },
  AvgCommunicate_95005_Content_3 = {
    Text = "Jadi sebuah persembahan yang berhasil sering kali membutuhkan banyak modifikasi pada sesaji dan penyesuaian lingkaran sihir."
  },
  AvgCommunicate_95005_Content_4 = {
    Text = "Di tempat kami, kami menggunakan darah racikan khusus, ditambah tujuh ratus tujuh puluh tujuh mayat hidup, ditempatkan dalam lingkaran sihir khusus."
  },
  AvgCommunicate_95005_Content_5 = {
    Text = "Dengan cara ini, peluang untuk menyenangkan hati dewa dan berhasil membuatnya turun menjadi paling besar."
  },
  AvgCommunicate_95005_Content_6 = {
    Text = "Bagaimana metode persembahan di tempat kalian?"
  },
  AvgCommunicate_95005_Content_7 = {
    Text = "Bisakah kamu memberitahuku lewat surat?"
  },
  AvgCommunicate_95005_Content_8 = {
    Text = "Tolong bagikan kepada kami melalui surat."
  },
  AvgCommunicate_95005_Content_9 = {
    Text = "Nah, seperti itulah rasanya. Tidak buruk, Nak."
  },
  AvgCommunicate_95005_Option_7 = {
    Text = "Bisakah kamu memberitahuku lewat surat?"
  },
  AvgCommunicate_95005_Option_8 = {
    Text = "Tolong bagikan kepada kami melalui surat."
  },
  AvgCommunicate_96408_Content_1 = {
    Text = "Hai, menerima jasa pengambilan jenazah, harga terjangkau, silakan hubungi. Yang kondisinya masih relatif utuh semasa hidup diprioritaskan, mendukung pengiriman antar wilayah lho~"
  },
  AvgCommunicate_96408_Content_10 = {
    Text = "Ah……ada pelanggan yang menghubungi! Sudah kuduga aku tidak salah menilainya."
  },
  AvgCommunicate_96408_Content_11 = {
    Text = "Peralatan masakku sudah menunggu sejak lama. Nanti kita lanjut ngobrol."
  },
  AvgCommunicate_96408_Content_13 = {
    Text = "Lebih baik aku pura-pura tidak tahu apa yang akan kau lakukan."
  },
  AvgCommunicate_96408_Content_2 = {Text = "?!"},
  AvgCommunicate_96408_Content_3 = {
    Text = "Du…Dulcesine? Hah???"
  },
  AvgCommunicate_96408_Content_4 = {
    Text = "Apakah ini dirasuki???"
  },
  AvgCommunicate_96408_Content_5 = {
    Text = "Ternyata Yang Mulia Penjaga Rahasia, saya sedang mencoba menggunakan komunikator untuk mencari pelanggan."
  },
  AvgCommunicate_96408_Content_6 = {
    Text = "Baru pertama kali pakai sudah bisa mengirim iklan massal……belajar dari mana ini……?"
  },
  AvgCommunicate_96408_Content_7 = {
    Text = "Anak yang bernama Jenkin itu, kemampuan pengamatannya terhadap hati orang-orang di sini sungguh mengesankan."
  },
  AvgCommunicate_96408_Content_8 = {
    Text = "……Sudah kuduga memang dia."
  },
  AvgCommunicate_96408_Content_9 = {
    Text = "Dibandingkan dengan kerja keras mendaki puncak kuliner, memahami teknologi seperti ini tidaklah sulit."
  },
  AvgCommunicate_96408_Option_2 = {Text = "?!"},
  AvgCommunicate_96408_Option_3 = {Text = "Dulcesine?"},
  AvgCommunicate_96408_Option_4 = {Text = "Dirasuki?"},
  AvgCommunicate_96408_Option_6 = {
    Text = "Pelanggan……"
  },
  AvgCommunicate_96408_Option_8 = {Text = "Jenkin!"},
  AvgCommunicate_96409_Content_1 = {
    Text = "Yang Mulia Penjaga Rahasia, apakah saya memiliki kehormatan untuk mengundang Anda makan malam bersama?"
  },
  AvgCommunicate_96409_Content_10 = {
    Text = "Untuk hidangan ini saya menggunakan saus yang baru dibuat."
  },
  AvgCommunicate_96409_Content_11 = {
    Text = "Mau mencobanya? Yang Mulia Penjaga Rahasia."
  },
  AvgCommunicate_96409_Content_12 = {
    Text = "Terima kasih atas kebaikan Anda……"
  },
  AvgCommunicate_96409_Content_13 = {
    Text = "Terima kasih atas kebaikan Anda……"
  },
  AvgCommunicate_96409_Content_14 = {
    Text = "Tapi semalam perut saya bermasalah karena salah makan, sepertinya saya tidak bisa menikmatinya."
  },
  AvgCommunicate_96409_Content_15 = {
    Text = "Begitu ya? Sayang sekali."
  },
  AvgCommunicate_96409_Content_16 = {
    Text = "Ini sudah yang keberapa kali perutmu bermasalah?"
  },
  AvgCommunicate_96409_Content_17 = {Text = "Eh……"},
  AvgCommunicate_96409_Content_18 = {
    Text = "Belum pernah mencicipi kelezatan mayat segar, sungguh disayangkan. Semoga Anda bisa mempertimbangkan undangan saya dengan serius."
  },
  AvgCommunicate_96409_Content_19 = {
    Text = "Lain kali pasti, lain kali pasti."
  },
  AvgCommunicate_96409_Content_2 = {
    Text = "Saya mencoba membuat hidangan tulang belikat dengan bawang putih disertai salad sumsum tulang belakang, empuk dan meresap, masih menyisakan sedikit kehangatan dari trauma masa kecil."
  },
  AvgCommunicate_96409_Content_3 = {
    Text = "Ehh……kedengarannya seperti rasa yang akan meninggalkan trauma psikologis."
  },
  AvgCommunicate_96409_Content_4 = {
    Text = "Tentu saja tidak. Bahan utamanya semasa hidup adalah seorang terapis fisik, bertemperamen lembut, hampir tidak ada sisa kebencian."
  },
  AvgCommunicate_96409_Content_5 = {
